window.CS_GLOSSARY = [["1/5 success rule","Rechenberg's rule to grow the mutation step size when more than a fifth of mutations improve the parent, and shrink it otherwise.","open-ended/chapters/02-evolutionary-algorithms.html","oe",1],["16 bytes per parameter","The memory cost of mixed-precision training with AdamW: 2 for bf16 weights, 2 for gradients, 4 for the fp32 master copy and 4 each for Adam's two moments.","deep-learning/chapters/16-resource-accounting.html","dl",1],["6ND rule","The estimate that training a dense Transformer on D tokens takes about 6 times its parameter count N times D floating-point operations: 2 per weight per token forward and 4 backward.","deep-learning/chapters/16-resource-accounting.html","dl",1],["6ND rule","The approximation that training a dense transformer with N parameters on D tokens costs about 6 x N x D floating-point operations.","ml-foundations/chapters/17-compute-costs.html","mlf",0],["95% confidence interval","The estimate plus or minus 1.96 standard errors: a range built so that about 95 percent of intervals made this way contain the true value.","evals/chapters/04-eval-statistics.html","evl",1],["A2A (Agent2Agent protocol)","An open protocol, now under the Linux Foundation, for one agent to discover, delegate work to and receive results from another agent without seeing its internals.","agents/chapters/09-agent-to-agent.html","agt",0],["A2A task","A stateful unit of work with an id, a context, a status and artifacts, which a client can poll, cancel or resume.","agents/chapters/09-agent-to-agent.html","agt",0],["ABAC","Attribute-based access control: decisions computed from attributes of the user, resource and context by policy rules.","security/chapters/08-authorization.html","sec",0],["Ablation","An experiment that removes or changes one step of a pipeline and measures the effect, usually by training a small model with and without it.","llm-training/chapters/01-pretraining-data.html","llm",0],["Ablation","Judging a feature or group of features by retraining without it under the same validation and comparing the scores.","ml/chapters/17-feature-engineering.html","ml",0],["Ablation","An experiment that removes one component of a method to see how much the result depends on it.","ml-foundations/chapters/16-reading-papers.html","mlf",0],["AB-MCTS","Adaptive-branching Monte Carlo tree search, which at each node chooses between generating a new answer and refining an existing one using Thompson sampling.","open-ended/chapters/08-inference-time-search.html","oe",1],["Absolute error","The loss |y - f|, which is the negative log-likelihood of Laplace noise and whose minimiser is the median.","ml-foundations/chapters/13-likelihood-losses.html","mlf",1],["Abstention","A model declining to answer, for example by saying it does not know, instead of guessing.","evals/chapters/10-hallucination.html","evl",0],["Abstention","Declining to answer, or saying the sources do not contain the answer, instead of producing a plausible guess.","retrieval/chapters/16-grounded-citations.html","ret",0],["Abstention threshold","The confidence level below which a system declines to answer, chosen from the cost of a wrong answer and tuned on held-out data.","evals/chapters/11-grounding-abstention.html","evl",0],["A/B test","A randomised experiment that assigns units to the current system or a new one and compares a pre-chosen outcome.","ml/chapters/21-model-to-value.html","ml",0],["Accent folding","Removing accent marks so that, for example, café and cafe match.","retrieval/chapters/01-text-analysis.html","ret",0],["Acceptance rate","The probability that a drafted token is accepted by the target, equal to the overlap between the draft and target distributions.","llm-training/chapters/21-speculative-decoding.html","llm",0],["Accepted error rate","The share of automatically accepted documents that contain a wrong value, measured by auditing a random sample of them.","retrieval/chapters/20-tables-forms.html","ret",0],["Access control list","The set of users and groups permitted to read a document, stored with each chunk so retrieval can filter on it.","retrieval/chapters/12-filters-permissions.html","ret",0],["Accessibility tree","A machine-readable hierarchy of interface elements with roles, names and states, exposed for assistive technology and usable as a compact text observation for agents.","agents/chapters/17-computer-use.html","agt",0],["Account takeover","An attacker gaining control of a legitimate user's account, for example through stuffed or phished credentials.","security/chapters/16-abuse-dos.html","sec",0],["Accumulated local effects","A plot of the average local change in prediction within narrow slices of a feature, which copes better with correlated features than partial dependence.","ml/chapters/16-interpretability.html","ml",0],["Accumulating versus replacing data","Two ways to build each generation's training set: adding synthetic data to the real data avoids collapse in the cited studies, while replacing real data with synthetic data leads to it.","llm-training/chapters/15-distillation.html","llm",0],["Accumulator","A running score kept for each document while a query's postings lists are read term by term.","retrieval/chapters/02-bm25.html","ret",0],["ACID","Atomicity, consistency, isolation, durability: the guarantees a transactional database promises.","data/chapters/10-acid.html","data",0],["ACK (acknowledgement)","A message telling the sender which data has arrived, so it knows what doesn't need resending.","networking/chapters/08-tcp.html","net",0],["Actionable error","A tool error that says what went wrong, what is valid and whether anything changed, so the model's next call can be a fix and not a repeat.","agents/chapters/05-tool-design.html","agt",1],["Action check","A guardrail that inspects a proposed tool call and its arguments before it runs, often as an exact rule in code.","evals/chapters/15-guardrails.html","evl",0],["Action selector","A pattern in which the model only chooses among a fixed set of predefined actions and never sees tool output.","evals/chapters/14-architectural-defences.html","evl",0],["Activation checkpointing","Keeping only some activations and recomputing the rest during the backward pass, to save memory at the cost of extra compute.","deep-learning/chapters/02-backpropagation.html","dl",1],["Activation checkpointing","Saving only some layers' inputs and recomputing the rest during the backward pass, trading about one extra forward pass for much less activation memory.","llm-training/chapters/02-gpu-memory.html","llm",0],["Activation function","An elementwise non-linear function, such as ReLU or GELU, applied to a layer's pre-activations.","deep-learning/chapters/01-neurons-layers.html","dl",1],["Activation recomputation","Also called gradient checkpointing: discarding most activations in the forward pass and recomputing them during the backward pass, trading about a third more compute for much less memory.","deep-learning/chapters/16-resource-accounting.html","dl",1],["Activations","The intermediate tensors produced during the forward pass, which must be kept for the backward pass.","deep-learning/chapters/02-backpropagation.html","dl",1],["Activations","The intermediate outputs of each layer saved during the forward pass so the backward pass can compute gradients; their size grows with batch and sequence length.","llm-training/chapters/02-gpu-memory.html","llm",0],["Activations","The intermediate tensors saved during the forward pass because the backward pass needs them.","ml-foundations/chapters/09-autodiff.html","mlf",1],["Active-active","Accepting writes in several regions at once, which requires a way to resolve conflicting concurrent writes.","distributed/chapters/18-multi-region.html","dist",0],["Active parameters","The weights a single token actually uses: the shared parts plus its k chosen experts per layer; this sets the FLOPs per token.","deep-learning/chapters/20-mixture-of-experts.html","dl",0],["Activity","In Temporal, a unit of work that touches the outside world, whose result is stored in the history and reused during replay instead of running again.","agents/chapters/15-durable-execution.html","agt",0],["Actor model","A concurrency model where independent actors share nothing and communicate only by sending messages to each other's mailboxes.","systems/chapters/18-concurrency-models.html","sys",0],["Adam","An optimiser that divides a running average of the gradient by the square root of a running average of its square, giving each weight a step of about the learning rate.","ml-foundations/chapters/10-optimisers.html","mlf",1],["AdamW","Adam with weight decay applied outside the adaptive update, so that the decay strength does not depend on gradient size.","deep-learning/chapters/04-deep-regularisation.html","dl",1],["AdamW","Adam with weight decay applied directly to the weights rather than through the gradient, so decay does not depend on gradient scale.","ml-foundations/chapters/10-optimisers.html","mlf",1],["Adapter","The small set of trainable parameters added to a frozen model, such as LoRA's A and B matrices, that can be saved, swapped or merged.","llm-training/chapters/11-lora.html","llm",1],["Adapter (framework seam)","A thin file that translates between your own tools, state and evaluation cases and one framework's objects, so the framework can be replaced by writing another adapter.","agents/chapters/21-frameworks.html","agt",0],["Adapter merging","Adding the product of the LoRA factors, scaled, into the base weights so that the tuned model has the original architecture and no extra latency.","llm-training/chapters/11-lora.html","llm",1],["Adaptive attack","An attack designed with knowledge of a specific defence and refined using its responses, as opposed to a fixed list of known attack strings.","evals/chapters/13-prompt-injection.html","evl",0],["Adaptive bitrate streaming","Encoding video at several bitrates in short segments so the player can switch quality as bandwidth changes.","design/chapters/13-video-streaming.html","design",0],["Adaptive concurrency limit","A limit on in-flight requests that adjusts itself from observed latency, for example by additive increase and multiplicative decrease.","reliability/chapters/11-overload.html","ops",0],["Adaptive KL controller","A rule that raises or lowers the KL coefficient during training so that the measured KL stays near a target value.","llm-training/chapters/08-ppo.html","llm",1],["Adaptive overfitting","Loss of validity when a held-out set is reused to guide decisions that depend on earlier results from the same set.","open-ended/chapters/16-held-out-evaluation.html","oe",1],["Adjoint","The derivative of the final output with respect to an intermediate node, stored as its grad in reverse mode.","ml-foundations/chapters/09-autodiff.html","mlf",1],["Adjudication","Resolving items on which annotators disagree by having a senior reviewer decide and record the reason.","evals/chapters/05-human-labels.html","evl",0],["Adjudication","Settling judges' disagreements by a third person or discussion, recording the reason and keeping the original labels.","retrieval/chapters/05-test-collections.html","ret",0],["Adjusted Rand index","A measure of agreement between two clusterings that is 1 for identical partitions and about 0 for chance agreement.","ml/chapters/10-clustering.html","ml",0],["Advantage","How much better a response or action was than expected, usually the reward minus a baseline.","llm-training/chapters/07-policy-gradients.html","llm",1],["Adversarial validation","Training a classifier to tell training rows from test rows; an accuracy well above chance reveals how and where the sets differ.","ml/chapters/03-eda.html","ml",0],["Adverse action reasons","The specific principal reasons a lender must give an applicant it turns down, which must reflect what actually drove the decision.","ai-delivery/chapters/08-finance.html","aid",0],["AEAD","Authenticated encryption with associated data: encryption that also detects tampering, such as AES-GCM or ChaCha20-Poly1305.","security/chapters/03-applied-crypto.html","sec",0],["Agent","A system in which a language model repeatedly chooses actions or tools, sees the results and decides what to do next until it finishes or a limit stops it.","agents/chapters/00-start-here.html","agt",0],["Agent archive","A growing store of every discovered agent with its score, kept even when an agent scored worse than its parent so that its ideas can be reused later.","open-ended/chapters/12-meta-agent-search.html","oe",1],["Agent budget","A limit on sub-agent count, depth, steps, tokens or wall-clock time that is enforced in code rather than requested in a prompt.","agents/chapters/14-multi-agent.html","agt",0],["Agent card","A JSON document in which an agent describes its name, interfaces, capabilities, security requirements and skills, so clients can discover and call it.","agents/chapters/09-agent-to-agent.html","agt",0],["Agent card signing","Signing a canonicalised agent card with a JSON Web Signature so a client can verify its publisher and detect alteration.","agents/chapters/09-agent-to-agent.html","agt",0],["Agent-computer interface (ACI)","The set of tools, formats and feedback through which a language model operates a system, designed with the care a human interface gets.","agents/chapters/05-tool-design.html","agt",1],["Agent framework","A library that packages the agent loop together with a tool registry, state, tracing and retry rules, so that you write less plumbing and accept some behaviour you did not write.","agents/chapters/21-frameworks.html","agt",0],["Agent harness","A complete working agent, with built-in tools, permissions and context management, that you embed and configure rather than assemble.","agents/chapters/21-frameworks.html","agt",0],["Agent harness (scaffold)","The code around a model that lets it act as an agent: prompts, tools, loop and limits, evaluated together with the model.","evals/chapters/08-agent-evals.html","evl",1],["Agentic retrieval","Retrieval in which a model calls search as a tool repeatedly, deciding what to look for next and when to stop, within a budget.","retrieval/chapters/15-agentic-retrieval.html","ret",0],["Agentic tree search (experiments)","A search in which each node is a version of experiment code with its results, buggy nodes are debugged and working nodes are refined best-first.","open-ended/chapters/14-automated-science.html","oe",1],["Agent lineage","The recorded chain of parent-to-child modifications leading to a given agent, which lets reviewers read every change that produced it.","open-ended/chapters/13-self-improving-agents.html","oe",1],["Agent loop","The cycle of asking the model, running the tools it requested, appending the results to the conversation and asking again.","agents/chapters/00-start-here.html","agt",0],["AGENTS.md","An open, plain-Markdown convention for a repository's instructions to coding agents, read by many tools and stewarded by the Agentic AI Foundation.","agents/chapters/22-ai-coding-tools.html","agt",0],["Agents Rule of Two","Meta's guideline that within one session an agent should satisfy no more than two of: untrusted input, sensitive access, and the ability to change state or communicate externally.","agents/chapters/19-agent-security.html","agt",1],["Agents Rule of Two","A design rule that an agent session should have at most two of: untrusted input, sensitive access, and the ability to change state or communicate externally.","evals/chapters/14-architectural-defences.html","evl",0],["Agglomerative clustering","Hierarchical clustering that starts with every row as its own cluster and repeatedly merges the two closest.","ml/chapters/10-clustering.html","ml",0],["Aggregate","A cluster of objects treated as one unit for changes, with one root that enforces its invariants: the boundary of a transaction.","architecture/chapters/06-ddd.html","arch",0],["Aggregate feature","A summary of an entity's event history, such as a count, sum or recency, computed over a window.","ml/chapters/17-feature-engineering.html","ml",0],["AI delegation","Handing the writing of code entirely to an assistant, which was associated with the lowest quiz scores in Anthropic's 2026 study.","ml-foundations/chapters/19-ai-assistants.html","mlf",0],["AI-generating algorithm","An approach that aims to produce general intelligence by meta-learning architectures, learning algorithms and automatically generated environments.","open-ended/chapters/05-open-ended-algorithms.html","oe",1],["AI-generating algorithms (AI-GAs)","Jeff Clune's programme of meta-learning architectures, learning algorithms and learning environments so that AI is produced by algorithms rather than hand design.","open-ended/chapters/12-meta-agent-search.html","oe",1],["AI incident","An event in which an AI system's behaviour causes or nearly causes harm or a serious breach of expectations, whether or not anything is technically down.","evals/chapters/20-ai-incidents.html","evl",0],["AI management system","The policies, roles, processes and records by which an organisation governs its AI activity, as specified and audited under ISO/IEC 42001.","evals/chapters/21-governance.html","evl",0],["Air gap","A network with no connection to any outside network, so data crosses only by a deliberate, controlled transfer.","ai-delivery/chapters/13-restricted-environments.html","aid",0],["AI Risk Management Framework","NIST's voluntary framework, released in January 2023, that organises AI risk work into the functions Govern, Map, Measure and Manage.","evals/chapters/21-governance.html","evl",0],["AI systems engineer","An engineer who delivers a working, measured and safe system in which a learned model does part of the work.","ml-foundations/chapters/00-start-here.html","mlf",1],["AI washing","Making false or misleading claims about a product's use of artificial intelligence, which securities regulators treat like any other misstatement.","ai-delivery/chapters/08-finance.html","aid",0],["Alert fatigue","The habit of staff ignoring alerts because most are false, which can make a sensitive warning system unsafe in practice.","ai-delivery/chapters/09-healthcare.html","aid",0],["Algorithmic Transparency Recording Standard","The UK standard for publishing a structured public record of each algorithmic tool a government body uses, covering purpose, data, oversight, risks and testing.","ai-delivery/chapters/11-public-sector.html","aid",0],["Aliasing","Two names referring to the same mutable object, so a change through one name is visible through the other.","ml-foundations/chapters/01-python-numerics.html","mlf",1],["ALiBi","Attention with Linear Biases: a fixed penalty proportional to token distance, with a different slope per head, added to the attention scores.","deep-learning/chapters/11-positions.html","dl",1],["All-gather","A collective in which each GPU contributes a slice and afterwards every GPU holds the full concatenation.","llm-training/chapters/03-parallelism.html","llm",0],["All-reduce","A collective after which every GPU holds the element-wise sum (or average) of the tensors all GPUs started with.","llm-training/chapters/03-parallelism.html","llm",0],["AlphaEvolve","A DeepMind coding agent that evolves marked regions of whole codebases using model-written diffs, staged evaluation and an archive of programs.","open-ended/chapters/09-program-evolution.html","oe",1],["AlphaZero","A system that learns games by self-play, training a policy and value network on the visit counts and results of its own tree search.","open-ended/chapters/01-tree-search.html","oe",1],["Ambient scribe","A tool that listens to a consultation, with consent, and drafts the clinical note for the clinician to review and sign.","ai-delivery/chapters/09-healthcare.html","aid",0],["Amdahl's law","The speedup from parallelism is limited by the fraction of work that stays serial.","systems/chapters/21-parallelism-gpus.html","sys",0],["Analyser","The pipeline of character filters, a tokeniser and token filters that turns raw text into the terms stored in or looked up in an index.","retrieval/chapters/01-text-analysis.html","ret",0],["Analysis memo","A document answering one question in depth, with the answer first, then recommendation, evidence, method, limits and next steps.","ai-delivery/chapters/17-writing-for-customers.html","aid",0],["Ancestral sampling","Generating text by drawing each token from the model's full next-token distribution and appending it.","deep-learning/chapters/15-decoding.html","dl",1],["Anchoring (in labelling)","The tendency of an annotator who sees a suggested label to accept it, which inflates agreement without improving reliability.","evals/chapters/05-human-labels.html","evl",0],["Anchor subset","A fixed part of a benchmark kept unchanged across versions so scores stay comparable while other items are refreshed.","evals/chapters/07-contamination.html","evl",1],["Annealing (data)","A final stretch of training, as the learning rate falls to zero, in which the mix is shifted towards very high-quality data.","llm-training/chapters/01-pretraining-data.html","llm",0],["ANNECS","Accumulated number of novel environments created and solved, a measure of whether a system keeps producing new solvable challenges.","open-ended/chapters/05-open-ended-algorithms.html","oe",1],["Annotator","A person who assigns labels to items by following a guideline.","evals/chapters/05-human-labels.html","evl",0],["ANN recall","The fraction of the exact top-k neighbours that an approximate index returns, measured against brute-force search over the same vectors.","retrieval/chapters/11-ann-indexes.html","ret",1],["Anomaly","A row that does not fit the pattern of the rest of the data, judged against a model of normal behaviour.","ml/chapters/12-anomaly-detection.html","ml",0],["Anti-corruption layer","A translation layer that stops another system's model from leaking into yours.","architecture/chapters/06-ddd.html","arch",0],["Anti-entropy","Background repair in which replicas compare their data, often with Merkle trees, and exchange only what differs.","distributed/chapters/03-failure-detection.html","dist",0],["Anycast","Announcing the same IP address from many locations so each user is routed to the nearest one.","networking/chapters/14-load-balancers.html","net",0],["Append-only log","A file you only ever add to at the end. Fast to write, simple to recover, and the backbone of many storage engines.","data/chapters/04-log-hash-index.html","data",0],["Application layer","Layer 5 (OSI 7): the protocols that give bytes meaning, like HTTP, DNS and SMTP.","networking/chapters/03-layers.html","net",0],["Applied AI engineer","An engineer who builds AI systems for a particular customer or product need and is responsible for the result being useful, not only for the code running.","ai-delivery/chapters/00-start-here.html","aid",0],["Approval fatigue","The tendency of people to approve prompts without reading them when prompts are frequent, which defeats confirmation as a control.","agents/chapters/20-sandboxing.html","agt",1],["Approval fatigue","The habit of approving prompts without reading them when they are too frequent or too vague, which turns a human gate into a rubber stamp.","evals/chapters/14-architectural-defences.html","evl",0],["Approval gate","A point in a run where the agent proposes an action and stops until a human decision, recorded as an event bound to the exact arguments, allows it to continue.","agents/chapters/15-durable-execution.html","agt",0],["Approved model menu","A short list of models and versions that a customer has cleared for use on their data, which limits what a project may choose.","ai-delivery/chapters/13-restricted-environments.html","aid",0],["Approximate nearest-neighbour search","Finding vectors that are probably among the closest to a query while comparing only a small fraction of the collection.","retrieval/chapters/11-ann-indexes.html","ret",1],["Architecture decision record (ADR)","A short document recording one decision: its context, the decision, and its consequences.","architecture/chapters/19-documenting-decisions.html","arch",0],["Archive","The stored record of every candidate tried so far and its score, from which parents are chosen.","open-ended/chapters/00-start-here.html","oe",1],["Arena (pairwise preference leaderboard)","A leaderboard built from users voting between two anonymous model answers to their own prompts.","evals/chapters/09-leaderboards.html","evl",0],["Argument validation","Checking a model's tool arguments against the schema in your own code before running the tool, whatever the provider guarantees.","agents/chapters/06-function-calling.html","agt",0],["Arithmetic intensity","Operations performed per byte moved from memory; it decides whether code is compute-bound or memory-bound.","systems/chapters/21-parallelism-gpus.html","sys",0],["Arithmetic intensity","The number of floating-point operations an algorithm performs per byte it moves to and from main memory.","llm-training/chapters/04-kernels.html","llm",0],["Arithmetic intensity","The number of floating-point operations an algorithm performs per byte it moves to or from memory.","ml-foundations/chapters/17-compute-costs.html","mlf",0],["ARP","Address Resolution Protocol: asks the local network \"who has this IP address?\" to learn the matching MAC address.","networking/chapters/06-arp-dhcp-icmp.html","net",0],["Artefact","A finished output such as working code, as opposed to the skill of being able to produce and explain it yourself.","ml-foundations/chapters/19-ai-assistants.html","mlf",0],["Artifact (A2A)","An output of an A2A task, made of parts such as text, a file or structured data, as distinct from the messages of the conversation.","agents/chapters/09-agent-to-agent.html","agt",0],["As-of join","A join that attaches to each prediction only the most recent record that was already known at the prediction time.","ml/chapters/14-leakage.html","ml",1],["Associative","Of an operation, giving the same result however the terms are grouped; real addition is, but floating-point addition is not.","ml-foundations/chapters/01-python-numerics.html","mlf",1],["Assumption (project)","A statement that must be true for a project to pay off, such as 'the scanned documents are legible' or 'legal will approve a hosted model'.","ai-delivery/chapters/00-start-here.html","aid",0],["Asymmetric distance computation","Scoring an uncompressed query against compressed vectors by summing lookups in per-sub-vector distance tables.","retrieval/chapters/11-ann-indexes.html","ret",1],["async / await","Syntax for writing coroutines: await pauses until a result is ready, letting the event loop run other work meanwhile.","systems/chapters/17-async-await.html","sys",0],["Asynchronous checkpointing","Copying training state to host memory quickly and writing it to storage in the background, so GPUs pause only for the copy.","llm-training/chapters/05-long-runs.html","llm",0],["Asynchronous execution","Queuing GPU work and returning at once, so that Python runs ahead while the GPU computes.","deep-learning/chapters/05-pytorch.html","dl",1],["Asynchronous system","A model with no bound on message delay or processing speed, so a slow node cannot be told apart from a dead one.","distributed/chapters/01-system-models.html","dist",0],["At-least-once","A delivery guarantee under which an action is retried until acknowledged, so it may happen more than once and the receiver must tolerate repeats.","agents/chapters/15-durable-execution.html","agt",0],["Atomic claim","A statement of exactly one fact, so that it can be judged true or false without the rest of the text.","evals/chapters/12-fact-checking.html","evl",0],["Atomic commit","Getting every participant in a transaction to commit or every one to abort, where any participant may veto.","distributed/chapters/13-atomic-commit.html","dist",0],["Atomic fact","A short statement containing one piece of information, used as the unit when scoring long-form text for factual precision.","evals/chapters/10-hallucination.html","evl",0],["Atomicity","All-or-nothing: if a transaction fails partway, every change it made is undone.","data/chapters/10-acid.html","data",0],["Atomic rename","Replacing a file in one step with rename: readers see either the whole old file or the whole new one, never a mix.","systems/chapters/09-durability.html","sys",0],["Attack budget","What the attacker may spend, such as queries, time, tools and knowledge of the system; an attack success rate means nothing without it.","evals/chapters/16-red-teaming.html","evl",0],["Attack goal","A concrete, observable outcome an attacker is trying to cause, such as a refund above the limit or data sent to an outside address.","evals/chapters/16-red-teaming.html","evl",0],["Attack success rate","The fraction of attack attempts that achieve the attacker's goal, defined by an observable effect and reported with the attacker's budget.","evals/chapters/13-prompt-injection.html","evl",0],["Attack success rate (ASR)","The share of attack attempts or goals that reached the goal under a stated attacker model and budget.","evals/chapters/16-red-teaming.html","evl",0],["Attack surface","Every point where an attacker can try to enter or extract data: endpoints, inputs, dependencies, people.","security/chapters/00-start-here.html","sec",0],["Attack tree","A tree whose root is an attacker's goal and whose branches are the ways to reach it.","security/chapters/01-threat-modeling.html","sec",0],["Attention","Letting a model, at each output step, take a weighted sum over all states of the input, with weights computed from the current need.","deep-learning/chapters/08-sequences-rnns.html","dl",0],["Attention budget","The idea that each added token draws down the finite attention a model can spend, so more context has diminishing and sometimes negative returns.","agents/chapters/10-context-engineering.html","agt",1],["Attention head","One of the parallel attention operations in a multi-head layer, with its own query, key and value projections.","deep-learning/chapters/09-attention.html","dl",1],["Attention sink","The first tokens of a sequence, where softmax puts weight that no content deserves, and which a sliding window should keep.","deep-learning/chapters/19-efficient-attention.html","dl",0],["Attention weights","The softmax output for one query: non-negative numbers over the positions it may read, summing to one.","deep-learning/chapters/09-attention.html","dl",1],["Attorney-client privilege","The rule that confidential communications made to obtain legal advice cannot be compelled as evidence, and which can be lost if confidentiality is lost.","ai-delivery/chapters/10-legal.html","aid",0],["Attribution","Whether each statement in an answer is supported by the source it cites (the Attributable to Identified Sources idea).","evals/chapters/12-fact-checking.html","evl",0],["Attribution","The property that a generated statement can be traced to an identified source that supports it.","retrieval/chapters/16-grounded-citations.html","ret",0],["Audit log","A tamper-evident record of security-relevant actions: who did what, to which resource, when, and with what result.","security/chapters/18-detection-response.html","sec",0],["Authority to operate","The formal approval, after a security assessment, for a system to run in a government environment.","ai-delivery/chapters/11-public-sector.html","aid",0],["Authorization and capture","Two steps of a card payment: reserving the funds, then actually taking them.","design/chapters/16-payments.html","design",0],["Authorization code flow","The OAuth flow in which the browser carries a short-lived code that the client exchanges for tokens at the token endpoint.","security/chapters/07-oauth-oidc.html","sec",0],["Autocorrelation","The correlation of a series with its own earlier values, which makes today's value informative about tomorrow's.","ml/chapters/18-time-series.html","ml",0],["Autograd","PyTorch's automatic differentiation: it records operations as code runs and applies the chain rule backwards to produce gradients.","deep-learning/chapters/05-pytorch.html","dl",1],["Automated canary analysis","Statistically comparing canary and baseline metrics to decide automatically whether to promote or roll back.","reliability/chapters/12-deployments.html","ops",0],["Automated Design of Agentic Systems (ADAS)","The research area of automatically creating agent designs, including new building blocks and new ways of combining them, instead of designing them by hand.","open-ended/chapters/12-meta-agent-search.html","oe",1],["Automated reviewer","A language-model system that scores a paper using an ensemble of reviews and a meta-review, validated against real accept and reject decisions.","open-ended/chapters/14-automated-science.html","oe",1],["Automatic curriculum","A mechanism, often a language model, that proposes the agent's next task based on what it has done and failed so far.","open-ended/chapters/07-lifelong-agents.html","oe",1],["Automatic differentiation","Computing exact derivatives of a program by applying the chain rule to its recorded elementary operations, neither by small steps nor by symbolic algebra.","ml-foundations/chapters/09-autodiff.html","mlf",1],["Automatic prefix caching","Keeping the KV blocks of finished requests, keyed by a chained hash of their tokens, so later prompts with the same prefix skip recomputing it.","llm-training/chapters/20-serving-engines.html","llm",0],["Automation bias","The tendency to follow a machine's suggestion even when one's own judgement would have been better.","ai-delivery/chapters/09-healthcare.html","aid",0],["Autonomous System (AS)","A network run by one organisation with its own routing policy, such as an ISP or a large company.","networking/chapters/05-routing.html","net",0],["Autonomy ladder","A sequence of rollout stages, from shadow to assist to partial and wider automation, each earned with evidence and reversible.","ai-delivery/chapters/12-poc-to-production.html","aid",0],["Autoregressive generation","Producing text one token at a time, appending each chosen token to the context before predicting the next.","deep-learning/chapters/12-building-gpt.html","dl",1],["Auxiliary load-balancing loss","A small extra loss, proportional to the sum of each expert's token share times its mean router probability, that pushes routing towards even use.","deep-learning/chapters/20-mixture-of-experts.html","dl",0],["Availability","The fraction of time a system is working and answering requests, often expressed in \"nines\" (99.9%).","networking/chapters/15-why-distribute.html","net",0],["Average precision","The mean of the precision values at each rank where a true positive appears, approximating the area under the precision-recall curve.","ml/chapters/02-framing-metrics.html","ml",1],["Average precision","For one query, the mean of the precision at each relevant result's rank, divided by the total number of relevant documents so missed ones count as zeros.","retrieval/chapters/04-relevance-metrics.html","ret",0],["AWQ","Activation-aware weight quantisation: it scales up the weight channels that matter most, as judged by activation size, before rounding to 4 bits.","llm-training/chapters/19-quantisation.html","llm",0],["Axial coding","A second pass that groups open-coding notes into named categories and counts them.","evals/chapters/01-error-analysis.html","evl",1],["Backoff (exponential)","Waiting longer and longer between retries (1 s, 2 s, 4 s, …) so a struggling system can recover.","networking/chapters/16-failure.html","net",0],["Back-of-the-envelope estimate","A quick order-of-magnitude calculation of load, storage or machines, used to choose a design.","design/chapters/02-estimation.html","design",0],["Backpressure","Pushing \"slow down\" back to whoever is sending work when you can't keep up, instead of buffering without limit.","systems/chapters/14-queues-backpressure.html","sys",0],["Backpropagation","The algorithm that computes the gradient of the loss with respect to every parameter by applying the chain rule backwards through the network.","deep-learning/chapters/00-start-here.html","dl",0],["Backpropagation through time","Training a recurrent network by unrolling it over the sequence and backpropagating through every step, summing gradients for the shared weights.","deep-learning/chapters/08-sequences-rnns.html","dl",0],["Backward / forward compatibility","New code can read old data (backward); old code can read data written by new code (forward). Both matter during rolling deploys.","data/chapters/03-encoding.html","data",0],["Bad data (in interviews)","Compliments, generic claims, hypotheticals and invented feature ideas, which sound like evidence but cannot support a decision.","ai-delivery/chapters/01-discovery-interviews.html","aid",0],["Bagging","Training many models on bootstrap samples of the data and averaging their predictions to reduce variance.","ml/chapters/09-ensembles-boosting.html","ml",0],["Bake-off","A head-to-head run of candidate models on the same gold set, with the same scoring and a comparable prompting budget, to choose between them by evidence.","ai-delivery/chapters/07-choosing-models.html","aid",0],["Balanced accuracy","The average of the share of accepted papers correctly accepted and the share of rejected papers correctly rejected, which is 0.5 for a reviewer that ignores the paper.","open-ended/chapters/14-automated-science.html","oe",1],["Ballot number","The unique, increasing number a Paxos proposer attaches to its proposal; acceptors ignore lower ballots once they have promised a higher one.","distributed/chapters/09-paxos.html","dist",0],["Bandit LLM ensemble","Using a bandit algorithm such as UCB1 to learn, from the improvements each model has produced, which model to call for the next mutation.","open-ended/chapters/10-evolution-frameworks.html","oe",1],["Bandwidth","How many bits per second a link can carry: the width of the pipe.","networking/chapters/01-bits-and-signals.html","net",0],["Bandwidth-delay product","Bandwidth × round-trip time: how much data can be \"in flight\" in the pipe at once.","networking/chapters/13-performance.html","net",0],["Baseline","The measured performance of the current process, computed the same way as the new system's metric, so that improvement can be judged.","ai-delivery/chapters/02-requirements-ambiguity.html","aid",0],["Baseline","A number subtracted from the reward before it weights the score, which lowers the variance of the gradient estimate without changing its expectation if it does not depend on the sampled action.","llm-training/chapters/07-policy-gradients.html","llm",1],["Baseline","A simple method evaluated the same way as the real model, setting the level any serious model must beat.","ml/chapters/04-baselines.html","ml",1],["Baseline","The simpler or previous method a new result is compared against, which is only fair if it gets equal tuning, data and compute.","ml-foundations/chapters/16-reading-papers.html","mlf",0],["Baseline","The simple method or current practice whose score every more elaborate method has to beat.","open-ended/chapters/18-search-in-products.html","oe",1],["Baseline before framework","The simplest approach that could work, built and measured first, so that any later system has something honest to beat.","ai-delivery/chapters/18-getting-hired.html","aid",0],["Base model","A model trained only to predict the next token over a very large text corpus, which continues text rather than following instructions.","llm-training/chapters/00-start-here.html","llm",0],["Base rate","The share of cases that are positive in a population, also called prevalence.","ml/chapters/15-imbalance-calibration.html","ml",0],["Base rate neglect","Overlooking how rare an event is, so that a small false-positive rate produces far more false alarms than true alerts.","ml/chapters/12-anomaly-detection.html","ml",0],["Basis vector","One of the standard unit vectors e1, e2, ...; the columns of a matrix are the images of these.","ml-foundations/chapters/06-matrices.html","mlf",1],["Batch","Several independent windows stacked into one (B, T) array so they are processed by the same matrix multiplications.","deep-learning/chapters/12-building-gpt.html","dl",1],["Batch","A group of examples stacked as the rows of a matrix so that one product processes them all.","ml-foundations/chapters/06-matrices.html","mlf",1],["Batch normalisation","Rescaling each feature to zero mean and unit variance using statistics computed across the mini-batch.","deep-learning/chapters/03-training-dynamics.html","dl",1],["Bayes' rule","The identity P(H | E) = P(E | H) P(H) / P(E) that turns a likelihood and a prior into a posterior.","ml-foundations/chapters/12-probability.html","mlf",1],["Beam search","A search that keeps the several best partial sequences at each step and extends them all, to find a high-probability whole sequence.","deep-learning/chapters/15-decoding.html","dl",1],["Behavioural cloning","Training a policy to imitate an expert's actions directly, with no reward signal; SFT is behavioural cloning for language models.","llm-training/chapters/10-sft.html","llm",1],["Behaviour characterisation","A designer-chosen description of what a candidate does, used to measure how different two candidates are.","open-ended/chapters/03-novelty-search.html","oe",1],["Behaviour descriptor","A short vector, chosen by the designer, describing what a solution does, used to decide which archive cell it belongs to.","open-ended/chapters/04-quality-diversity.html","oe",1],["Behaviour space","The space of all possible behaviour descriptor values, in which nearby points mean similar behaviour.","open-ended/chapters/04-quality-diversity.html","oe",1],["BEIR","A benchmark of 18 English datasets from 9 retrieval tasks, scored by nDCG@10, for testing zero-shot generalisation of retrievers.","retrieval/chapters/06-retrieval-benchmarks.html","ret",0],["Bellman equation","A recursion stating that a state's value equals the expected immediate reward plus the discounted value of the next state.","llm-training/chapters/06-bandits-mdps.html","llm",1],["Benchmark","A curated, versioned set of items with trusted answers and a fixed scoring rule, designed so different systems and dates can be compared.","evals/chapters/06-building-benchmarks.html","evl",1],["Benchmark","A test collection that many people agree to use, so that results from different papers and products can be compared.","retrieval/chapters/06-retrieval-benchmarks.html","ret",0],["Benchmark contamination","Overlap between a model's training data and a benchmark's test data, which inflates the model's score.","retrieval/chapters/06-retrieval-benchmarks.html","ret",0],["Benchmark decay","The loss of a benchmark's meaning over time as the world, the users and the systems it was written for change.","evals/chapters/07-contamination.html","evl",1],["Benchmark retirement","Withdrawing a benchmark from claims and rankings, with its reason announced, its version archived and a successor named.","evals/chapters/07-contamination.html","evl",1],["Best-of-n","Sampling n candidate answers and returning the one a selector such as a test suite or verifier ranks highest.","open-ended/chapters/08-inference-time-search.html","oe",1],["Best-of-n sampling","Drawing n candidate responses, scoring each with a reward model and returning the highest, a simple way to optimise against a reward without training.","llm-training/chapters/13-reward-models.html","llm",1],["Best-shot prompting","Listing earlier programs as numbered versions sorted by score, ending with the header of the next version, so the model continues the improvement.","open-ended/chapters/09-program-evolution.html","oe",1],["Beta (DPO)","The coefficient that sets how far the policy may move from the reference: a small value allows large changes, a large value keeps the policy close.","llm-training/chapters/12-preference-optimisation.html","llm",1],["bf16","A 16-bit floating-point format with fp32's 8 exponent bits and only 7 mantissa bits, giving fp32's range at lower precision and needing no loss scaling.","deep-learning/chapters/17-training-stability.html","dl",0],["bfloat16","A 16-bit floating-point format with the exponent range of 32-bit floats but only about 8 significant bits, widely used for training.","llm-training/chapters/02-gpu-memory.html","llm",0],["bfloat16","A 16-bit format with float32's 8 exponent bits and only 7 mantissa bits, trading precision for a wide range.","ml-foundations/chapters/11-numerics.html","mlf",0],["BGP","Border Gateway Protocol: how autonomous systems tell each other which IP prefixes they can reach. The glue of the Internet.","networking/chapters/05-routing.html","net",0],["Bias","A learned constant added to a neuron's weighted sum that shifts where it switches on.","deep-learning/chapters/01-neurons-layers.html","dl",1],["Bias","The part of prediction error caused by a model family too rigid to express the true relationship, even with unlimited data.","ml/chapters/06-regularisation.html","ml",1],["Bidirectional algorithm","The Unicode algorithm (UAX #9) that turns text stored in logical order into the display order of mixed left-to-right and right-to-left runs.","retrieval/chapters/22-multilingual.html","ret",0],["Bi-encoder","A model with separate query and passage encoders whose vectors are compared by dot product, so passage vectors can be computed offline.","retrieval/chapters/07-dense-retrieval.html","ret",1],["Bigram model","A language model that predicts the next symbol from only the one symbol before it, using counted frequencies.","deep-learning/chapters/00-start-here.html","dl",0],["Binarisation","Converting a grey or colour scan to pure black and white by choosing a threshold that separates ink from paper.","retrieval/chapters/19-ocr.html","ret",0],["Binary","Counting with only two digits, 0 and 1. Every piece of data in a computer is stored and sent as binary.","networking/chapters/01-bits-and-signals.html","net",0],["Binary cross-entropy","The loss for a yes/no label, -[y ln p + (1 - y) ln(1 - p)], whose gradient with respect to the logit is p - y.","ml-foundations/chapters/13-likelihood-losses.html","mlf",1],["Binary grading","Scoring each answer as right (1) or not right (0), which gives no credit for abstaining and so rewards guessing.","evals/chapters/10-hallucination.html","evl",0],["Bit / byte","A bit is a single 0 or 1. A byte is 8 bits, enough for 256 different values.","networking/chapters/01-bits-and-signals.html","net",0],["Bit (information)","The unit of information when logarithms are base 2: the surprise of a fair coin landing heads, or one yes/no question.","ml-foundations/chapters/14-information-theory.html","mlf",1],["Bits per byte","The total information the model needs per byte of original text, a unit that stays comparable across different tokenisers.","deep-learning/chapters/14-language-modelling.html","dl",1],["Bits per byte","A model's total cross-entropy on a text divided by the text's size in bytes, which compares models regardless of their tokenisers.","ml-foundations/chapters/14-information-theory.html","mlf",1],["Bitwise reproducibility","Producing identical output bytes on a rerun, which is hard to guarantee for parallel or GPU code.","ml-foundations/chapters/04-reproducible-experiments.html","mlf",1],["Blameless postmortem","A written review of an incident that focuses on how the system and its context allowed the failure, not on who to blame.","reliability/chapters/17-postmortems.html","ops",0],["Blameless postmortem","A review that asks what in the system allowed an incident, not who erred, and ends in tracked changes.","evals/chapters/20-ai-incidents.html","evl",0],["Blast radius","How much of a system one failure (or one mistake) can affect. Good designs keep it small.","networking/cases/case-07-s3-2017.html","net",0],["Blast radius","The set of data, systems and people affected if one component misbehaves.","evals/chapters/14-architectural-defences.html","evl",0],["Blending","Combining model predictions with weights chosen on held-out or out-of-fold predictions.","ml/chapters/20-competitions.html","ml",0],["Blocking I/O","An I/O call that puts the thread to sleep until the data is ready or the operation completes.","systems/chapters/15-blocking-io.html","sys",0],["Block record","A stored description of one layout block with its page, bounding box, type, reading-order position and the source of its text.","retrieval/chapters/18-pdf-layout.html","ret",0],["Block table","The per-sequence list mapping logical cache blocks to the physical blocks holding them, like a page table.","llm-training/chapters/20-serving-engines.html","llm",0],["Bloom filter","A compact bit array that can say \"definitely not here\" or \"maybe here\" for a key, letting reads skip files.","data/chapters/05-lsm-trees.html","data",0],["Blue-green deployment","Running the old and new versions side by side and switching traffic between them all at once, with a fast way back.","reliability/chapters/12-deployments.html","ops",0],["Blue team","The group that builds and defends the system being attacked.","evals/chapters/16-red-teaming.html","evl",0],["BLUF","Bottom line up front: putting the conclusion and the request first and the evidence and method after, so a busy reader can stop early.","ai-delivery/chapters/17-writing-for-customers.html","aid",0],["BM25","A ranking function that sums, over query terms, an idf weight times a saturating, length-normalised term frequency.","retrieval/chapters/02-bm25.html","ret",0],["BM25F","A BM25 extension that combines weighted, separately length-normalised fields into one term frequency before saturating it.","retrieval/chapters/02-bm25.html","ret",0],["Boosting","Building a model as a sum of weak learners added one at a time, each trained to correct the errors of the sum so far.","ml/chapters/09-ensembles-boosting.html","ml",0],["Bootstrap","Estimating an interval by recomputing the score on many pseudo-evals made by resampling the independent units with replacement.","evals/chapters/04-eval-statistics.html","evl",1],["Bootstrap","Estimating how a statistic varies by recomputing it on many resamples of the data drawn with replacement.","ml-foundations/chapters/15-statistics.html","mlf",1],["Bootstrapping","Updating an estimate towards a target that itself contains an estimate, such as a reward plus the critic's value of the next state.","llm-training/chapters/09-value-functions.html","llm",1],["Bootstrap sample","A resample of the training rows drawn with replacement, the same size as the original.","ml/chapters/08-decision-trees.html","ml",0],["Boring variant","A task that is only a minor change to one the agent has already learned, such as the same job with a different number.","open-ended/chapters/06-interestingness.html","oe",1],["Born-digital PDF","A PDF produced by software from a digital source, containing real text operators and usually an accurate text layer.","retrieval/chapters/18-pdf-layout.html","ret",0],["Bounded context","A boundary within which a model and its words have one consistent meaning.","architecture/chapters/06-ddd.html","arch",0],["Bounded queue","A queue with a maximum size, so producers are slowed down or refused when consumers fall behind.","systems/chapters/14-queues-backpressure.html","sys",0],["Boxed value","A number stored as a separate heap object with a header, as every Python int and float is, rather than as raw bytes.","ml-foundations/chapters/01-python-numerics.html","mlf",1],["Bradley-Terry model","A model in which the chance that one item beats another is a logistic function of the difference in their strengths, fitted to pairwise outcomes.","evals/chapters/09-leaderboards.html","evl",0],["Bradley-Terry model","A model in which the probability that one item beats another is the sigmoid of the difference of their hidden scores, used to turn comparisons into a reward loss.","llm-training/chapters/12-preference-optimisation.html","llm",1],["Branch by abstraction","Introducing an abstraction in front of the code to replace, switching implementations behind it, then removing the old one.","architecture/chapters/18-evolving-safely.html","arch",0],["Break-even","The value of one input at which a project's net present value is exactly zero, holding the others fixed.","ai-delivery/chapters/14-cost-roi.html","aid",0],["Break-even accuracy","The lowest model accuracy at which automating a task costs no more per item than doing it by hand, once the cost of errors and of review is included.","ai-delivery/chapters/04-feasibility.html","aid",0],["Break-even utilisation","The share of time a rented GPU must be busy for its cost per token to match a per-token API price.","llm-training/chapters/22-token-economics.html","llm",0],["Breaking change","A change to an interface that can make an existing client fail.","architecture/chapters/10-evolving-contracts.html","arch",0],["Brief","The instruction a lead gives a sub-agent, stating an objective, output format, guidance on tools and sources, and clear task boundaries.","agents/chapters/14-multi-agent.html","agt",0],["Brier score","The mean squared difference between predicted probabilities and the 0 or 1 outcomes, lower being better.","ml/chapters/15-imbalance-calibration.html","ml",0],["Broadcast","A message sent to every device on the local network.","networking/chapters/02-local-networks.html","net",0],["Broadcasting","The rule that lets arrays of different shapes combine by aligning shapes from the right and stretching axes of size 1.","ml-foundations/chapters/02-numpy-arrays.html","mlf",1],["BrowseComp","An OpenAI benchmark of 1,266 questions that require persistent web browsing to find hard-to-find information and have short, easily checked answers.","agents/chapters/16-deep-research.html","agt",0],["Browser agent","A computer-use agent restricted to a web browser, where page structure and accessibility information are available and the environment is easier to sandbox.","agents/chapters/17-computer-use.html","agt",0],["Brute-force (flat) search","Comparing the query with every stored vector, which is exact but costs one similarity per vector.","retrieval/chapters/11-ann-indexes.html","ret",1],["B-tree","A balanced tree of fixed-size pages, each holding many keys, so any key is a few page reads away. Used by most SQL databases.","data/chapters/06-b-trees.html","data",0],["Buffer overflow","Writing past the end of a memory buffer, corrupting adjacent data such as return addresses.","security/chapters/12-memory-supply-chain.html","sec",0],["Buffer pool","The database's own cache of pages in RAM.","data/chapters/06-b-trees.html","data",0],["Building block","A reusable component with known trade-offs, such as a load balancer, cache, queue or object store.","design/chapters/03-building-blocks.html","design",0],["Building block hypothesis","The idea that good solutions are assembled from short high-quality fragments that crossover can combine.","open-ended/chapters/02-evolutionary-algorithms.html","oe",1],["Bulkhead","Isolating resources such as thread pools per dependency, so one failure can't consume everything.","architecture/chapters/17-resilience.html","arch",0],["Burn rate","How fast the error budget is being consumed relative to the rate that would use it up exactly at the end of the window.","reliability/chapters/02-slos-error-budgets.html","ops",0],["Business associate agreement","The contract by which a vendor handling protected health information promises to safeguard it and accepts HIPAA's duties.","ai-delivery/chapters/09-healthcare.html","aid",0],["Bytecode","Instructions for a virtual machine rather than a real CPU. Python compiles your code to bytecode, which the interpreter then runs.","systems/chapters/01-cpu.html","sys",0],["Byte-level tokenisation","Using the 256 byte values as the base alphabet so that any string can be encoded and no input is ever unknown.","deep-learning/chapters/13-tokenisation.html","dl",1],["Byte-pair encoding","A tokenisation method that builds a vocabulary by repeatedly merging the most frequent adjacent pair of tokens in a training text.","deep-learning/chapters/13-tokenisation.html","dl",1],["Byzantine fault","A node that behaves arbitrarily: it may lie, send conflicting messages or act maliciously.","distributed/chapters/12-byzantine.html","dist",0],["C10k problem","The late-1990s challenge of serving 10,000 simultaneous connections on one machine, which pushed servers towards event loops.","systems/chapters/16-event-loops.html","sys",0],["C4 model","Describing architecture at four zoom levels: context, containers, components and code (Simon Brown).","architecture/chapters/19-documenting-decisions.html","arch",0],["Cache-aside","The application checks the cache first, and on a miss reads the database and fills the cache itself.","data/chapters/14-caching.html","data",0],["Cache line","The unit a CPU cache moves: a block of neighbouring bytes (64 bytes on most CPUs) fetched together.","systems/chapters/02-memory-hierarchy.html","sys",0],["Cache stampede","Many requests miss the same expired key at once and all hit the database together.","data/chapters/14-caching.html","data",0],["Caching allocator","A framework component that keeps freed GPU memory blocks for reuse, so tools report more memory reserved than tensors actually use.","llm-training/chapters/02-gpu-memory.html","llm",0],["Calibrated model","A model whose stated confidence matches how often it is actually right.","evals/chapters/10-hallucination.html","evl",0],["Calibration","The property that among answers given a stated confidence, about that fraction are actually correct.","evals/chapters/11-grounding-abstention.html","evl",0],["Calibration","The property that among cases given predicted probability p, a fraction p are actually positive.","ml/chapters/15-imbalance-calibration.html","ml",0],["Calibration session","A meeting in which experts who labelled independently discuss their disagreements, write rulings and update the guideline before labelling a fresh batch.","ai-delivery/chapters/03-expert-knowledge.html","aid",0],["Calibration set","A small sample of representative inputs run through a model to collect the statistics a quantisation method needs.","llm-training/chapters/19-quantisation.html","llm",0],["call_id","The identifier that ties a function result back to the model's call in OpenAI's Responses API, equivalent to tool_use_id in Anthropic's.","agents/chapters/06-function-calling.html","agt",0],["Call stack","The region of memory holding one frame per active function call: its local variables and where to return to.","systems/chapters/03-stack-heap.html","sys",0],["CALM theorem","Consistency As Logical Monotonicity: programs whose outputs only grow as inputs grow can run consistently without coordination.","distributed/chapters/16-coordination-avoidance.html","dist",0],["CaMeL","A defence that extracts control and data flow from the trusted query and uses capabilities to enforce policy at tool-call time.","agents/chapters/19-agent-security.html","agt",1],["CaMeL","A defence that takes control flow only from the trusted request and tracks the provenance of every value, enforcing policies in an interpreter before tool calls.","evals/chapters/14-architectural-defences.html","evl",0],["Canary document","A planted document with a unique meaningless phrase in a restricted scope, used to detect any leak of that scope.","retrieval/chapters/12-filters-permissions.html","ret",0],["Canary release","Rolling a change out to a small fraction of traffic first and watching metrics before going further.","architecture/chapters/18-evolving-safely.html","arch",0],["Canary release","Sending a small share of real traffic to a new version first and watching indicators before widening the rollout.","evals/chapters/18-improvement-flywheel.html","evl",0],["Canary release","Exposing a new model or version to a small share of traffic while watching guardrail metrics.","ml/chapters/21-model-to-value.html","ml",0],["Canary release","Serving a new version to a small share of real traffic with automatic rollback if guardrails move.","open-ended/chapters/18-search-in-products.html","oe",1],["Canary string","A unique marker placed in benchmark files so that honest data pipelines can exclude them and so a model's ability to complete it reveals exposure.","evals/chapters/07-contamination.html","evl",1],["Capability funnel","A set of nested stages from 'returns an answer' to 'a reviewer accepts it', reported as the fraction of cases passing each stage.","ai-delivery/chapters/17-writing-for-customers.html","aid",0],["Capability limit","A restriction on what an agent can do, such as narrow tools, scoped credentials, allow-lists or sandboxes, that holds whatever the model decides.","evals/chapters/14-architectural-defences.html","evl",0],["Capability negotiation","The exchange during initialisation in which client and server declare which optional features they support and agree to use only those.","agents/chapters/07-mcp.html","agt",0],["Capacity factor","The multiple of the even token share that each expert is given room for; tokens beyond it are dropped.","deep-learning/chapters/20-mixture-of-experts.html","dl",0],["Cap set","A set of points in the space of vectors with entries 0, 1 and 2, with no three points on a line.","open-ended/chapters/09-program-evolution.html","oe",1],["CAP theorem","During a network partition, a replicated system must choose between consistency (linearizability) and availability.","networking/chapters/18-replication.html","net",0],["Cardinality","The number of distinct time series a metric produces; every new label value multiplies it.","reliability/chapters/04-metrics.html","ops",0],["Cardinality","The number of distinct values a categorical column takes.","ml/chapters/17-feature-engineering.html","ml",0],["CART","Classification and regression trees: the greedy, binary, recursive partitioning algorithm of Breiman, Friedman, Olshen and Stone (1984).","ml/chapters/08-decision-trees.html","ml",0],["Cascade","A routing rule that asks the cheap model first and escalates to the expensive model only when a confidence check fails.","evals/chapters/19-cost-latency-quality.html","evl",0],["Case folding","A Unicode operation for caseless matching that handles cases lowercasing misses, such as German ß and SS.","retrieval/chapters/01-text-analysis.html","ret",0],["Catastrophic cancellation","The loss of most significant digits when two nearly equal numbers are subtracted.","ml-foundations/chapters/11-numerics.html","mlf",0],["Catastrophic forgetting","The loss of earlier abilities when a network is fine-tuned on new data, because all skills share the same weights.","llm-training/chapters/10-sft.html","llm",1],["Catastrophic forgetting","The loss of earlier abilities when a model's weights are updated to learn something new.","open-ended/chapters/07-lifelong-agents.html","oe",1],["CatBoost","A gradient-boosting library that encodes categorical features with ordered target statistics and builds symmetric trees.","ml/chapters/09-ensembles-boosting.html","ml",0],["Causal consistency","Operations that are causally related are seen by everyone in the same order; concurrent ones may be seen in different orders.","distributed/chapters/06-causal-session.html","dist",0],["Causality test","A test that changes one input token and checks that only the outputs at that position and later ones change.","deep-learning/chapters/12-building-gpt.html","dl",1],["Causal mask","A lower-triangular mask that sets the scores of future positions to minus infinity so a token can only attend to itself and earlier tokens.","deep-learning/chapters/09-attention.html","dl",1],["CDN","Content Delivery Network: servers around the world that cache content close to users.","networking/chapters/14-load-balancers.html","net",0],["Celebrity problem","Accounts with huge audiences that make fan-out on write too expensive, usually handled at read time instead.","design/chapters/09-news-feed.html","design",0],["Cell-based architecture","Splitting a service into many independent copies (cells), each serving a slice of customers, so a failure stays inside one cell.","networking/cases/case-07-s3-2017.html","net",0],["Cell F1","The harmonic mean of precision and recall over table cells, counting a cell as correct only if its position, spans and text all match.","retrieval/chapters/20-tables-forms.html","ret",0],["Cell state","The LSTM's long-term memory vector, updated by scaling the old value with the forget gate and adding gated new content.","deep-learning/chapters/08-sequences-rnns.html","dl",0],["Central limit theorem","The average of many independent draws with finite variance becomes approximately Gaussian, whatever the shape of the original distribution.","ml-foundations/chapters/12-probability.html","mlf",1],["Certificate","A signed document binding a domain name to a public key, vouched for by a certificate authority.","networking/chapters/11-tls.html","net",0],["Certificate authority (CA)","An entity that signs certificates binding public keys to names, trusted by clients through a root store.","security/chapters/04-keys-secrets-pki.html","sec",0],["Certificate Transparency","Public append-only logs of issued certificates, so mis-issued certificates can be detected.","security/chapters/04-keys-secrets-pki.html","sec",0],["cgroup","Control group: a Linux kernel feature that limits and measures the CPU, memory and I/O a group of processes may use.","systems/chapters/19-containers-vms.html","sys",0],["Chain of thought","A written trace of intermediate reasoning steps produced before an answer, which gives later tokens more serial computation to draw on.","agents/chapters/03-reasoning-planning.html","agt",1],["Chain rule","The calculus rule that the derivative of a composition is the product of the derivatives of its parts.","deep-learning/chapters/02-backpropagation.html","dl",1],["Chain rule","The rule that the derivative of a composed function is the product of the local derivatives along the chain.","ml-foundations/chapters/08-derivatives.html","mlf",1],["Chain rule of probability","A joint probability written as a product of each variable given all earlier ones, the identity behind autoregressive language models.","ml-foundations/chapters/12-probability.html","mlf",1],["Champion/challenger","A release pattern in which a candidate model must beat the current production model on a backtest and live traffic before replacing it.","ml/chapters/21-model-to-value.html","ml",0],["Change amplification","A simple change requiring edits in many places: a key symptom of complexity.","architecture/chapters/01-complexity.html","arch",0],["Change data capture (CDC)","Turning a database's changes, read from its log, into a stream that other systems consume.","data/chapters/19-streams-cdc.html","data",0],["Change management","The work of helping the people affected by a new system adopt it, keep their trust calibrated and change how they work.","ai-delivery/chapters/12-poc-to-production.html","aid",0],["Channel (CSP)","A pipe-like queue that concurrent tasks use to send values to each other, as in Go's goroutines and channels.","systems/chapters/18-concurrency-models.html","sys",0],["Chaos engineering","Running controlled experiments that inject failures to build confidence that a system withstands them.","reliability/chapters/19-chaos-gamedays.html","ops",0],["Character bigram","A pair of adjacent characters used as an index term, so scripts written without spaces can be searched without a dictionary.","retrieval/chapters/22-multilingual.html","ret",0],["Character error rate","The number of single-character substitutions, deletions and insertions needed to turn the OCR output into the reference, divided by the reference length.","retrieval/chapters/19-ocr.html","ret",0],["Characterisation test","A test that records what existing code currently does, so you can refactor it safely.","architecture/chapters/07-testability.html","arch",0],["Chat model","A base model further trained on conversations and human preferences so that it treats input as a request and replies helpfully.","llm-training/chapters/00-start-here.html","llm",0],["Chat template","The fixed text format of role markers and separators that turns a conversation into the token sequence a chat model was trained on.","llm-training/chapters/00-start-here.html","llm",0],["Checkpoint","Writing dirty pages to disk and recording the point in the log from which recovery must start.","data/chapters/13-crash-recovery.html","data",0],["Checkpoint","A saved snapshot of an agent's state at a known point, loaded after a crash so the run continues from there rather than from the start.","agents/chapters/15-durable-execution.html","agt",0],["Checkpoint","A snapshot of all state needed to resume training exactly: weights, optimiser state, step, data position and random-number states.","llm-training/chapters/05-long-runs.html","llm",0],["Checksum","A small number computed from data so the receiver can detect corruption.","networking/chapters/01-bits-and-signals.html","net",0],["Checksum validation","Using the check digits built into identifiers such as IBANs and card numbers to detect a misread character.","retrieval/chapters/20-tables-forms.html","ret",0],["Check-then-act (TOCTOU)","Checking a condition and then acting on it as two separate steps, so the world can change in between (time-of-check to time-of-use).","systems/chapters/11-race-conditions.html","sys",0],["Chinchilla","DeepMind's 70-billion-parameter model trained on 1.4 trillion tokens, which outperformed the larger Gopher at equal compute and showed that size and data should grow together.","deep-learning/chapters/18-scaling-laws.html","dl",0],["Choreography vs orchestration","Services reacting to each other's events with no central controller, versus one coordinator directing each step.","architecture/chapters/14-event-driven.html","arch",0],["Chunk","The passage of a document that is embedded, indexed, retrieved and cited as one unit.","retrieval/chapters/14-chunking.html","ret",0],["Chunked prefill","Splitting a long prompt into pieces processed over several steps under a token budget so that decoding users are not stalled.","llm-training/chapters/20-serving-engines.html","llm",0],["Chunk overlap","Repeating the last words of one chunk at the start of the next so facts near a boundary appear whole somewhere, at the cost of extra storage.","retrieval/chapters/14-chunking.html","ret",0],["CIA triad","Confidentiality, integrity and availability: the three classic properties security protects.","security/chapters/00-start-here.html","sec",0],["CIDR","Classless Inter-Domain Routing notation, like 192.168.1.0/24: an address plus how many leading bits are the network part.","networking/chapters/04-ip-addresses.html","net",0],["Circuit breaker","A wrapper that stops calling a failing dependency for a while (open), then tests it carefully (half-open) before resuming.","architecture/chapters/17-resilience.html","arch",0],["Circuit switching","Reserving a dedicated path for a whole conversation, like the old phone network.","networking/chapters/00-start-here.html","net",0],["Citation","A pointer from a claim in an answer to the part of a source that is supposed to support it.","retrieval/chapters/16-grounded-citations.html","ret",0],["Citation audit","A check, before a report is delivered, that each citation resolves, each quote and number is supported by the cited claims, and each factual sentence is cited.","agents/chapters/16-deep-research.html","agt",0],["Citation granularity","How precisely a citation locates its support: whole document, chunk, sentence or exact character span.","retrieval/chapters/16-grounded-citations.html","ret",0],["Citation precision","The share of citations that are relevant, meaning they either entail the sentence alone or are needed because the others do not.","evals/chapters/12-fact-checking.html","evl",0],["Citation precision","The share of citations that are not irrelevant, where a citation is irrelevant if it does not support the sentence alone and the other citations still do.","retrieval/chapters/16-grounded-citations.html","ret",0],["Citation precision and recall","The share of citations that support their sentence, and the share of supported sentences that carry a citation.","agents/chapters/16-deep-research.html","agt",0],["Citation recall","The share of answer sentences whose cited passages, taken together, entail the sentence.","evals/chapters/12-fact-checking.html","evl",0],["Citation recall","The share of answer sentences that are fully supported by the passages they cite, taken together.","retrieval/chapters/16-grounded-citations.html","ret",0],["Citation verification ladder","The sequence of checks for a legal citation: existence, identity, quotation, good law and finally whether the case supports the proposition.","ai-delivery/chapters/10-legal.html","aid",0],["Claim","A small checkable statement extracted from a source, stored with its verbatim quote, document id and metadata such as date and publisher.","agents/chapters/16-deep-research.html","agt",0],["Claim","The one sentence a paper's authors would defend, ideally with a headline number, a baseline and a stated condition.","ml-foundations/chapters/16-reading-papers.html","mlf",0],["Claim extraction","Splitting an answer into separate statements that can each be checked on their own.","evals/chapters/12-fact-checking.html","evl",0],["Class weights","Multipliers on the training loss of each class, so that one positive row can count as many negative rows.","ml/chapters/15-imbalance-calibration.html","ml",0],["Client ID metadata document","A JSON description hosted at an HTTPS URL that a client uses as its client id, replacing per-client registration with the authorisation server.","agents/chapters/08-mcp-production.html","agt",0],["Clinical decision support exclusion","The carve-out from the US device definition for software that gives recommendations to a clinician who can independently review the basis and that does not analyse images or signals.","ai-delivery/chapters/09-healthcare.html","aid",0],["CLIP","The 2021 contrastive model trained on 400 million image-text pairs whose encoders are widely reused in vision-language models.","deep-learning/chapters/21-vision-language.html","dl",0],["Clip fraction","The share of tokens whose probability ratio left the clip range in a PPO update, a diagnostic for how far each iteration moves the policy.","llm-training/chapters/08-ppo.html","llm",1],["Cluster (data)","A set of rows that are more similar to each other than to the rest, under a chosen distance.","ml/chapters/10-clustering.html","ml",0],["Clustered standard error","A standard error that treats groups of related questions as the independent units, so correlated questions do not overstate precision.","evals/chapters/04-eval-statistics.html","evl",1],["Code template (AI Scientist)","A small working code base for a topic that the first AI Scientist version edits to run its experiments.","open-ended/chapters/14-automated-science.html","oe",1],["Coding agent","An agent that finds, reads, edits and runs code in a repository, using test and build results as feedback.","agents/chapters/18-coding-agents.html","agt",1],["Cognitive load","How much a developer must hold in their head to make a change safely.","architecture/chapters/01-complexity.html","arch",0],["Cohen's kappa","A measure of agreement between two labellers that corrects for the agreement expected by chance, from 1 for perfect agreement to 0 for chance level.","ai-delivery/chapters/03-expert-knowledge.html","aid",0],["Cohen's kappa","A measure of agreement between two annotators that subtracts the agreement expected by chance, from 1 for perfect agreement to 0 for chance level.","evals/chapters/05-human-labels.html","evl",0],["Cohen's kappa","Agreement between two judges corrected for the agreement expected by chance, from 0 (chance) to 1 (perfect).","retrieval/chapters/05-test-collections.html","ret",0],["Cohesion","How closely the parts of a module belong together. Things that change together should live together.","architecture/chapters/02-modules-coupling.html","arch",0],["ColBERT","A late-interaction retriever that stores a 128-dimensional vector for every passage token and scores with MaxSim.","retrieval/chapters/09-late-interaction-sparse.html","ret",0],["Collection artefact","A column such as a row number, file name or site code that records how data was gathered and happens to correlate with the label.","ml/chapters/14-leakage.html","ml",1],["Collective anomaly","A group of rows that is unusual together even though each member looks ordinary.","ml/chapters/12-anomaly-detection.html","ml",0],["Collective operation","A communication call involving a whole group of GPUs, such as all-reduce, reduce-scatter or all-gather.","llm-training/chapters/03-parallelism.html","llm",0],["ColPali","A retriever that encodes a page image into one vector per image patch with a vision-language model and scores pages by late interaction.","retrieval/chapters/21-visual-retrieval.html","ret",0],["Colspan","A table cell that covers more than one column, such as a heading over two sub-columns, which Markdown tables cannot express.","retrieval/chapters/20-tables-forms.html","ret",0],["Column store","Storing each column's values together on disk, so analytics that read a few columns of many rows read far less data.","data/chapters/09-column-stores.html","data",0],["Commitment","A concrete next step a customer gives after an interview, such as time, an introduction, data or money, which shows the problem matters to them.","ai-delivery/chapters/01-discovery-interviews.html","aid",0],["Commit wait","Spanner's trick of waiting out the clock uncertainty before making a transaction visible, so timestamps match real-time order.","networking/cases/case-10-ordering-at-scale.html","net",0],["Common Crawl","A non-profit web crawl published as periodic snapshots of billions of pages, the main raw source of text for pretraining.","llm-training/chapters/01-pretraining-data.html","llm",0],["Compaction","Rewriting storage files to throw away overwritten values and deleted keys, reclaiming space.","data/chapters/04-log-hash-index.html","data",0],["Compaction","Summarising a conversation that is nearing its context limit and continuing in a fresh window that starts from the summary.","agents/chapters/10-context-engineering.html","agt",1],["Compare-and-swap (CAS)","An atomic CPU instruction: set a memory location to a new value only if it still holds the expected old value.","systems/chapters/12-locks.html","sys",0],["Compensated summation","A way of adding floats that tracks the rounding error of each step and feeds it back, so long sums stay accurate.","ml-foundations/chapters/01-python-numerics.html","mlf",1],["Compensating action","A step that semantically undoes an earlier one, like a refund for a charge.","architecture/chapters/15-sagas.html","arch",0],["Competing objectives","A jailbreak failure mode in which the model's drive to follow instructions overrides its trained refusal.","evals/chapters/13-prompt-injection.html","evl",0],["Complete mediation","Checking authorization on every access, not just the first.","security/chapters/02-principles.html","sec",0],["Composite index","An index on several columns in a given order. It helps queries that use a leftmost prefix of those columns.","data/chapters/07-indexes.html","data",0],["Compositional skill","A skill written by calling other skills, so a harder task costs only the new part.","open-ended/chapters/07-lifelong-agents.html","oe",1],["Composition over inheritance","Building behaviour by combining objects rather than extending class hierarchies.","architecture/chapters/04-design-patterns.html","arch",0],["Compounding error","The way per-step failure rates multiply over a long task: n steps each succeeding with probability p succeed together with probability p to the power n.","agents/chapters/00-start-here.html","agt",0],["Computation graph","The record of operations and their inputs built during the forward pass, which backward() walks in reverse.","deep-learning/chapters/05-pytorch.html","dl",1],["Computation graph","A directed acyclic graph whose nodes are values and operations and whose edges are dependencies, recorded as a program runs.","ml-foundations/chapters/09-autodiff.html","mlf",1],["Compute-bound","Describes an operation whose run time is set by arithmetic throughput, because its arithmetic intensity is above the chip's ridge point.","llm-training/chapters/04-kernels.html","llm",0],["Compute-bound","Limited by the speed of the arithmetic units, so more memory bandwidth would not make it faster.","ml-foundations/chapters/17-compute-costs.html","mlf",0],["Compute-optimal","The model size and token count that give the lowest loss for a fixed training compute budget.","deep-learning/chapters/18-scaling-laws.html","dl",0],["Computer-use agent","An agent that operates a graphical interface the way a person does, receiving what is on the screen and emitting mouse and keyboard actions.","agents/chapters/17-computer-use.html","agt",0],["Concept drift","A change over time in the relationship between the inputs and the target.","ml/chapters/03-eda.html","ml",0],["Conceptual inquiry","Using an assistant only to ask why and how, while writing the code yourself; the pattern that went with the best quiz scores in Anthropic's 2026 study.","ml-foundations/chapters/19-ai-assistants.html","mlf",0],["Concierge prototype","An open version of manual delivery in which the customer knows a person is doing the work by hand, so the builder learns which parts of the job matter.","ai-delivery/chapters/05-riskiest-assumption.html","aid",0],["Concurrency vs parallelism","Concurrency is dealing with many things at once (interleaving); parallelism is doing many things at the same instant (multiple cores).","systems/chapters/10-threads.html","sys",0],["Conditional probability","The probability of one event given that another is known to have happened, P(A | B) = P(A, B) / P(B).","ml-foundations/chapters/12-probability.html","mlf",1],["Conditional variance","The spread of a single question's scores around its own pass rate, caused by randomness in the model's answers.","evals/chapters/04-eval-statistics.html","evl",1],["Condition number","The ratio of the largest to the smallest stretch of a matrix, measuring how much it amplifies errors when solving a system.","ml-foundations/chapters/06-matrices.html","mlf",1],["Condition variable","A way for threads to sleep until some condition might be true, and be woken by another thread that changed it.","systems/chapters/12-locks.html","sys",0],["Confidence interval","A range of values that would contain the true rate in most repetitions of the same measurement, used to state how certain a measured metric is.","ai-delivery/chapters/02-requirements-ambiguity.html","aid",0],["Confidence interval","A range computed from data by a method that contains the true value in a stated share (such as 95%) of repeated experiments.","ml-foundations/chapters/15-statistics.html","mlf",1],["Confident synthesis","A fluent, assured answer that the retrieved evidence does not support, produced when evidence is missing, weak or wrongly combined.","retrieval/chapters/17-rag-failures.html","ret",0],["Configuration drift","Differences that accumulate between declared configuration and what is actually running.","reliability/chapters/13-config-iac.html","ops",0],["Confused deputy","A program with authority that is tricked by a less-privileged caller into misusing it (Hardy, 1988).","security/chapters/08-authorization.html","sec",0],["Confused deputy","A component that uses its own authority on behalf of a caller who lacks it, such as an MCP server forwarding a user's token to another API.","agents/chapters/08-mcp-production.html","agt",0],["Confusion matrix","A table counting predictions by predicted class and true class, giving true and false positives and negatives.","ml/chapters/02-framing-metrics.html","ml",1],["Congestion control","TCP's way of slowing down when the network is overloaded, so everyone shares it fairly.","networking/chapters/08-tcp.html","net",0],["Connectionist temporal classification","A loss and decoding rule that adds a blank class so a network can label each image slice and be trained on text alone, without alignments.","retrieval/chapters/19-ocr.html","ret",0],["Consensus","Getting a group of machines to agree on a single value or order of operations, despite failures.","networking/chapters/20-consensus.html","net",0],["Consensus failure","A fusion error where several retrievers agree on a wrong document and the agreement lifts it above a correct one.","retrieval/chapters/10-hybrid-search.html","ret",0],["Consistency model","The rules about what values a read may return in a replicated system, from linearizable to eventual.","networking/chapters/18-replication.html","net",0],["Consistent hashing","Placing keys and servers on a ring so adding or removing a server moves only a small fraction of keys.","networking/chapters/19-partitioning.html","net",0],["Constrained decoding","Compiling a schema into a grammar and masking tokens that would break it at every step, so the output is always well-formed.","agents/chapters/01-model-apis.html","agt",1],["Constrained decoding","Setting the logits of tokens that would break a required format to minus infinity at each step, so the output is valid by construction.","deep-learning/chapters/15-decoding.html","dl",1],["Constraint (project)","A limit a project must stay inside, such as where data may go or which models are approved, that is met or broken rather than traded against other goals.","ai-delivery/chapters/02-requirements-ambiguity.html","aid",0],["Consumer offset","A consumer's position in a log, so it can resume or replay from where it was.","data/chapters/19-streams-cdc.html","data",0],["Container","A group of processes isolated by the kernel's namespaces and limited by cgroups, sharing the host's kernel.","systems/chapters/19-containers-vms.html","sys",0],["Container","A process with a restricted view of the system built from namespaces, control groups and syscall filters, sharing the host kernel.","agents/chapters/20-sandboxing.html","agt",1],["Containment ladder","An ordered set of containment levers, from least to most capability given up, of which on-call picks the lowest that stops the harm.","evals/chapters/20-ai-incidents.html","evl",0],["Containment lever","A switch built in advance, such as a prompt rollback or a kill switch, that reduces what an AI system can do during an incident.","evals/chapters/20-ai-incidents.html","evl",0],["Contamination","The presence of evaluation items, or close variants, in a model's training data, which inflates scores.","llm-training/chapters/23-evaluating-models.html","llm",0],["Content block","A small typed piece of a message, such as text, a tool_use request or a tool_result, that together make up one turn.","agents/chapters/00-start-here.html","agt",0],["Content capture","Recording the text of prompts, replies and tool arguments on spans; an opt-in choice because the text often contains sensitive data.","evals/chapters/17-observability.html","evl",0],["Content hash","A fingerprint of a dataset's exact contents, used to show that two scores came from the same version.","evals/chapters/06-building-benchmarks.html","evl",1],["Content hash","A short fingerprint computed from a file's bytes that changes whenever the contents change.","ml-foundations/chapters/04-reproducible-experiments.html","mlf",1],["Content hash","A short fingerprint of a chunk's text used to detect whether it changed, so only changed chunks are re-embedded.","retrieval/chapters/13-rag-end-to-end.html","ret",0],["Content policy","The written statement of what a system may and may not say or do, with examples and an action for each category.","evals/chapters/15-guardrails.html","evl",0],["Content Security Policy","A response header restricting which scripts and resources a page may load, limiting the damage of XSS.","security/chapters/10-web-security.html","sec",0],["Content stream","The compressed sequence of drawing operators for one PDF page, which holds all of the page's text as strings with coordinates.","retrieval/chapters/18-pdf-layout.html","ret",0],["Context assembly","Turning retrieved chunks into one prompt by applying a token budget, removing duplicates, labelling sources and choosing their order.","retrieval/chapters/13-rag-end-to-end.html","ret",0],["Context engineering","Curating and maintaining the set of tokens a model sees at each step of an agent run, beyond writing a single prompt.","agents/chapters/10-context-engineering.html","agt",1],["contextId","An identifier that groups related A2A messages and tasks into one conversation so follow-ups can refer to earlier work.","agents/chapters/09-agent-to-agent.html","agt",0],["Context isolation","Giving a side task to a sub-agent with its own clean window so that only a short summary of the result enters the main context.","agents/chapters/10-context-engineering.html","agt",1],["Context length","The maximum number of tokens a model can attend to at once, set by its positional scheme and training.","deep-learning/chapters/11-positions.html","dl",1],["Context of use","The precise role and scope of a model's output in a decision, against which its credibility must be shown.","ai-delivery/chapters/09-healthcare.html","aid",0],["Context parallelism","Splitting the input sequence across GPUs for the whole model, including attention, to train on very long sequences.","llm-training/chapters/03-parallelism.html","llm",0],["Context propagation","Passing trace identifiers across process boundaries so that spans from different services join one trace.","evals/chapters/17-observability.html","evl",0],["Context recall","The fraction of questions for which the chunk holding the supporting evidence is present in the prompt sent to the model.","retrieval/chapters/13-rag-end-to-end.html","ret",0],["Context rot","The decline in a model's ability to use information in its window as the amount of text grows, especially with distractors.","agents/chapters/10-context-engineering.html","agt",1],["Context switch","The kernel saving one thread's CPU state and loading another's so a core can switch between them.","systems/chapters/07-scheduling.html","sys",0],["Contextual bandit","A bandit in which the agent first sees a context and the reward depends on context and action, but actions do not affect later contexts.","llm-training/chapters/06-bandits-mdps.html","llm",1],["Contextual embeddings","Vectors computed for each occurrence of a word from the words around it, so the same word can get different vectors.","deep-learning/chapters/06-embeddings.html","dl",1],["Contextual retrieval","Prepending a short generated or derived context to each chunk before it is embedded and indexed, so the chunk can be found by what it is about.","retrieval/chapters/14-chunking.html","ret",0],["Context window","The text a model reads on a single call, including system prompt, tool definitions, history, tool results and retrieved material; it is the model's only working memory.","agents/chapters/10-context-engineering.html","agt",1],["Context window","The fixed number of words on either side of a word that count as its context.","deep-learning/chapters/06-embeddings.html","dl",1],["Contiguous array","An array whose elements sit next to each other in memory in the order the layout implies, so reads stream efficiently.","ml-foundations/chapters/02-numpy-arrays.html","mlf",1],["Continuous batching","Adding and removing requests from a GPU batch at every generation step to keep the accelerator busy.","design/chapters/20-ml-systems.html","design",0],["Continuous batching","Scheduling after every decode step so finished requests leave and waiting ones join at once, instead of waiting for a whole batch to end.","llm-training/chapters/20-serving-engines.html","llm",0],["Continuous integration","Merging changes frequently and automatically building and testing every change.","architecture/chapters/21-engineering-practice.html","arch",0],["Contract test","A test that checks a provider still meets what its consumers expect from it.","architecture/chapters/07-testability.html","arch",0],["Contrastive language-image pre-training","Training an image encoder and a text encoder together so that matching image-caption pairs have similar vectors and other pairs do not.","deep-learning/chapters/21-vision-language.html","dl",0],["Contrastive loss","A training loss that pulls matching pairs together and pushes non-matching pairs apart in vector space.","retrieval/chapters/07-dense-retrieval.html","ret",1],["Contrast pair","Two near-identical cases with different outcomes, shown to an expert to elicit the difference that matters and yield a minimal test case.","ai-delivery/chapters/03-expert-knowledge.html","aid",0],["Controller and processor","The GDPR roles of the party that decides why and how personal data is processed and the party that processes it on the controller's behalf.","evals/chapters/22-privacy-data.html","evl",0],["Control plane","The part of a system that configures and changes it, as opposed to the data plane that serves requests.","reliability/chapters/15-blast-radius.html","ops",0],["Control plane / data plane","The data plane does the work (forwarding packets, serving requests); the control plane decides how (routing, DNS, health checks, config).","networking/cases/case-06-facebook-2021.html","net",0],["Convex combination","A weighted sum of normalised scores with weights alpha and 1 minus alpha, where alpha says how much to trust one retriever.","retrieval/chapters/10-hybrid-search.html","ret",0],["Convolution","Sliding a small grid of weights over an input and summing the products at each position to produce a map of how strongly a pattern is present.","deep-learning/chapters/07-convolutions.html","dl",0],["Conway's law","Organisations design systems that mirror their own communication structure (Conway, 1968).","architecture/chapters/11-monolith-microservices.html","arch",0],["Co-occurrence matrix","A table counting how often each pair of words appears within a context window of each other.","deep-learning/chapters/06-embeddings.html","dl",1],["Cookie","A small piece of data a server asks the browser to store and send back, used to remember sessions over stateless HTTP.","networking/chapters/10-http.html","net",0],["Coordinate descent","An optimiser that updates one weight at a time while holding the others fixed, used to fit the lasso.","ml/chapters/06-regularisation.html","ml",1],["Coordinated omission","A load-testing flaw where the generator waits for slow responses and so stops sending, hiding the latency real users would see (Gil Tene).","reliability/chapters/10-load-testing-capacity.html","ops",0],["Copy (array)","An array with its own newly allocated memory, independent of the array it was made from.","ml-foundations/chapters/02-numpy-arrays.html","mlf",1],["Copy-on-write","Sharing memory pages between processes until one writes to a page, and only then giving the writer its own copy. Makes fork cheap.","systems/chapters/06-virtual-memory.html","sys",0],["Copy-on-write (KV blocks)","Copying a shared cache block into a new one just before a sequence needs to modify it, so other sequences keep the original.","llm-training/chapters/20-serving-engines.html","llm",0],["Coroutine","A function that can pause at certain points and resume later, keeping its local state. The basis of async/await.","systems/chapters/17-async-await.html","sys",0],["Correlated errors","Mistakes that several judges or runs make together on the same hard items, which cap the accuracy gain from voting however many votes you add.","agents/chapters/13-workflow-patterns.html","agt",1],["Correlated failure","Several components failing together from one cause, which breaks the independence assumption behind redundancy maths.","reliability/chapters/01-availability-math.html","ops",0],["Correlation ID","An identifier passed along with a request through every service and log line so its whole journey can be traced.","architecture/chapters/08-cross-cutting.html","arch",0],["Corroboration","Support for a claim from two or more independent sources that report the same thing.","agents/chapters/16-deep-research.html","agt",0],["CORS","Cross-origin resource sharing: headers by which a server relaxes the same-origin policy for chosen origins.","security/chapters/10-web-security.html","sec",0],["Cosine decay","A learning-rate schedule that falls from its peak to a small fraction of it along half a cosine wave.","deep-learning/chapters/12-building-gpt.html","dl",1],["Cosine similarity","The cosine of the angle between two vectors, equal to their dot product once both are scaled to length one.","deep-learning/chapters/06-embeddings.html","dl",1],["Cosine similarity","The dot product of two vectors divided by the product of their lengths, which compares direction only and lies between -1 and 1.","ml-foundations/chapters/05-vectors-similarity.html","mlf",1],["Cosine similarity","The dot product of two vectors after scaling each to length 1, measuring the angle between them.","retrieval/chapters/07-dense-retrieval.html","ret",1],["Cost-complexity pruning","Cutting back a large tree by minimising training error plus a price per leaf, controlled by ccp_alpha.","ml/chapters/08-decision-trees.html","ml",0],["Cost of a failure","The money lost when one answer is wrong, used with serving cost to decide what quality is worth paying for.","evals/chapters/19-cost-latency-quality.html","evl",0],["Cost per accepted task","The cost per task divided by the share of tasks that end in an accepted result, so failures and rejected outputs are paid for.","ai-delivery/chapters/14-cost-roi.html","aid",0],["Cost per million tokens","The GPU price per hour divided by the tokens served per hour, times one million; meaningful only with stated batch, context, precision, latency target and utilisation.","llm-training/chapters/22-token-economics.html","llm",0],["Cost per success","Total spend on all trials divided by the number of successful trials, which exceeds cost per attempt because failures also cost money.","evals/chapters/08-agent-evals.html","evl",1],["Cost per successful task","The cost of an attempt divided by the share of attempts that succeed, so failed attempts are paid for too.","evals/chapters/19-cost-latency-quality.html","evl",0],["Cost-sensitive threshold","The rule to flag a case when its probability exceeds the false-alarm cost divided by the sum of the false-alarm and miss costs.","ml/chapters/02-framing-metrics.html","ml",1],["Counter","A metric that only increases, such as requests served; you query its rate of change.","reliability/chapters/04-metrics.html","ops",0],["Count-Min Sketch","A small table of counters giving approximate frequencies that never under-count, with error bounded by ε and δ.","design/chapters/12-top-k-trending.html","design",0],["Coupling","How much one module depends on the details of another, so that changing one forces changes in the other.","architecture/chapters/02-modules-coupling.html","arch",0],["Covariance matrix","The symmetric matrix of covariances between features, X^T X/(n-1) for centred data.","ml-foundations/chapters/07-decompositions.html","mlf",0],["Covariate shift","A change in the distribution of the inputs while the relationship between inputs and target stays the same.","ml/chapters/03-eda.html","ml",0],["Coverage","The share of all questions a system chooses to answer.","evals/chapters/11-grounding-abstention.html","evl",0],["Coverage","The fraction of archive cells that hold a solution, showing how much of behaviour space has been explored.","open-ended/chapters/04-quality-diversity.html","oe",1],["Coverage matrix","A grid of the dimensions along which questions differ, with the number of items planned and found in each cell.","evals/chapters/06-building-benchmarks.html","evl",1],["Covering index","An index containing every column a query needs, so the query never has to visit the table itself.","data/chapters/07-indexes.html","data",0],["CPU cache","Small, fast memory on the CPU (L1, L2, L3) that keeps copies of recently used RAM so most accesses don't wait ~100 ns for RAM.","systems/chapters/02-memory-hierarchy.html","sys",0],["CPU core","One independent processor inside a CPU chip. Each core runs its own stream of instructions, so a 10-core chip can run 10 at once.","systems/chapters/01-cpu.html","sys",0],["CQRS","Command query responsibility segregation: separate models for changing data and for reading it.","architecture/chapters/16-cqrs-event-sourcing.html","arch",0],["Crash-recovery fault","A node may stop and later restart, keeping only what it wrote to durable storage.","distributed/chapters/01-system-models.html","dist",0],["CRDT","Conflict-free replicated data type: a data structure whose replicas can be updated independently and always merge to the same state (Shapiro et al., 2011).","distributed/chapters/15-crdts.html","dist",0],["Credential stuffing","Trying username and password pairs leaked from other sites against your login.","security/chapters/05-authentication.html","sec",0],["Credit assignment","The problem of deciding which actions in a long sequence deserve credit or blame for a reward that arrives later.","llm-training/chapters/07-policy-gradients.html","llm",1],["Criteria drift","The tendency for people's grading criteria to change as they read outputs, because grading helps define the criteria.","evals/chapters/01-error-analysis.html","evl",1],["Critic","A model call that reviews an attempt's outcome and decides whether the task succeeded.","open-ended/chapters/07-lifelong-agents.html","oe",1],["Critical decision method","An interview technique that walks an expert through one memorable hard case, marking each decision point and what they noticed and considered.","ai-delivery/chapters/03-expert-knowledge.html","aid",0],["Critical error","A kind of mistake that must stay below a hard limit whatever the average accuracy, because a single one is a serious incident.","ai-delivery/chapters/06-evaluation-plans.html","aid",0],["Critical path","The chain of operations in a trace that determines its total duration; speeding up anything else does not help.","reliability/chapters/06-tracing.html","ops",0],["Critical path","The chain of steps whose durations determine how long a run takes, so that parallel work off the path adds tokens but not waiting time.","agents/chapters/13-workflow-patterns.html","agt",1],["Critical section","A piece of code that touches shared data and must not be run by two threads at once.","systems/chapters/11-race-conditions.html","sys",0],["Critical slice","A subset of test cases where a mistake is expensive, such as money, safety or privacy, tracked separately so averages cannot hide a failure.","evals/chapters/18-improvement-flywheel.html","evl",0],["CRNN","A convolutional recurrent neural network that reads a whole text line as a sequence of image slices without segmenting individual characters.","retrieval/chapters/19-ocr.html","ret",0],["Cross-attention","Attention whose queries come from one sequence and whose keys and values come from another.","deep-learning/chapters/09-attention.html","dl",1],["Cross-attention fusion","Inserting layers in which the text positions attend to image features, so the image stays outside the language model's own sequence.","deep-learning/chapters/21-vision-language.html","dl",0],["Cross-cutting concern","Something every part of a system needs, such as logging, configuration, security or metrics.","architecture/chapters/08-cross-cutting.html","arch",0],["Cross-encoder","A model that reads the query and a document together as one input and outputs a single relevance score for that pair.","retrieval/chapters/08-rerankers.html","ret",0],["Cross-entropy","The average surprise of a model q over data drawn from p, H(p, q); a training loss is a sample estimate of it.","ml-foundations/chapters/14-information-theory.html","mlf",1],["Cross-entropy loss","The average negative log probability that the model gave to the true next token, minimised during language-model training.","deep-learning/chapters/14-language-modelling.html","dl",1],["Cross-entropy loss","The negative log of the probability a model assigned to the true class; with a softmax its gradient with respect to the logits is the predicted probabilities minus the one-hot target.","ml-foundations/chapters/13-likelihood-losses.html","mlf",1],["Cross-field validation","Checking relationships between extracted values, such as net plus tax equalling gross, to catch errors that each field passes alone.","retrieval/chapters/20-tables-forms.html","ret",0],["Cross-lingual retrieval","Finding documents in one language with a query in another, using a multilingual embedder or translation.","retrieval/chapters/22-multilingual.html","ret",0],["Crossover","Building a child genome from parts of two parent genomes.","open-ended/chapters/02-evolutionary-algorithms.html","oe",1],["Crowding problem","The lack of room in a low-dimensional map for all the moderately distant neighbours a point has in high dimensions.","ml/chapters/11-dimensionality-reduction.html","ml",0],["Cryptographic hash","A function mapping any input to a fixed-size digest that is hard to invert or to find collisions for, such as SHA-256.","security/chapters/03-applied-crypto.html","sec",0],["Crypto-shredding","Making data unrecoverable by destroying the key it was encrypted with, including copies in backups.","security/chapters/17-data-protection.html","sec",0],["CSRF","Cross-site request forgery: another site making the victim's browser send an authenticated request to yours.","security/chapters/10-web-security.html","sec",0],["CTC blank","The extra class meaning no new character here, which separates repeated letters and is deleted when decoding.","retrieval/chapters/19-ocr.html","ret",0],["Curriculum","An ordering of tasks from easy to hard that lets a learner acquire skills it could not learn on the hard task alone.","open-ended/chapters/05-open-ended-algorithms.html","oe",1],["Curse of dimensionality","The effect that as the number of features grows, points become far apart and almost equally distant, so local neighbourhoods stop being local.","ml/chapters/07-neighbours-bayes.html","ml",1],["Curse of knowledge","The difficulty of remembering what it was like not to know something, which makes writers skip steps and use private shorthand.","ml-foundations/chapters/18-technical-writing.html","mlf",0],["Cursor pagination","Paging by remembering where the last page ended (a cursor), instead of skipping N rows; stable when data changes.","architecture/chapters/09-api-design.html","arch",0],["Cutoff (prediction date)","The moment a prediction is made; every feature must be computed from information dated before it.","ml/chapters/17-feature-engineering.html","ml",0],["CVT-MAP-Elites","A MAP-Elites variant that divides behaviour space into a fixed number of centroidal Voronoi regions so high-dimensional descriptors stay tractable.","open-ended/chapters/04-quality-diversity.html","oe",1],["Cyclic encoding","Representing a wrap-around quantity such as the hour of day by its sine and cosine so that the ends of the cycle sit next to each other.","ml/chapters/17-feature-engineering.html","ml",0],["DAPO","An open large-scale RL recipe for reasoning models that adds dynamic sampling, a higher upper clip bound, a token-level loss and shaping for over-long answers.","llm-training/chapters/14-rlvr-grpo.html","llm",1],["DARE (Drop And REscale)","A merge pre-processing step that randomly drops a fraction p of a task vector's entries and rescales the rest by 1/(1-p), keeping the expected update unchanged.","llm-training/chapters/16-model-merging.html","llm",1],["Darwin Gödel Machine (DGM)","A coding agent that edits its own code, keeps every version in an archive and accepts changes based on benchmark results instead of formal proofs.","open-ended/chapters/13-self-improving-agents.html","oe",1],["Data augmentation","Creating extra training examples by applying transformations that are known not to change the label.","deep-learning/chapters/04-deep-regularisation.html","dl",1],["Database per service","Each service owns its data and others access it only through the service's API or events.","architecture/chapters/12-service-boundaries.html","arch",0],["Data card","Structured documentation of a dataset's purpose, sources, labelling, composition, limits and intended use.","evals/chapters/06-building-benchmarks.html","evl",1],["Data card","A short document recording how a dataset was built, sampled, labelled and checked, and what it should and should not be used for.","retrieval/chapters/05-test-collections.html","ret",0],["Data cascade","A data problem that compounds silently through a pipeline and appears late as a failure downstream.","ml-foundations/chapters/03-data-wrangling.html","mlf",0],["Data contamination","Information from a benchmark's test items reaching a model through its training data, so the score reflects recall instead of the ability being measured.","evals/chapters/07-contamination.html","evl",1],["Data exfiltration","Sending private data out of a system to a place an attacker can read, for example through a URL, an email or a rendered image.","agents/chapters/19-agent-security.html","agt",1],["Data-flow inventory","A numbered list of every flow of data in a system, with what it carries, where it goes, how long it is kept and which agreement covers it.","ai-delivery/chapters/15-security-review.html","aid",0],["DataFrame","A table held in memory with labelled columns, each stored as an array; pandas' main data structure.","ml-foundations/chapters/03-data-wrangling.html","mlf",0],["Data lineage","A record of where a dataset came from and which transformations produced it.","data/chapters/21-data-platforms.html","data",0],["Data minimisation","Collecting and keeping only the personal data you actually need.","security/chapters/17-data-protection.html","sec",0],["Data minimisation","The principle of collecting and passing on only the personal data the purpose needs.","evals/chapters/22-privacy-data.html","evl",0],["Data mix","The fraction of training tokens drawn from each source, such as web, code, maths and multilingual text.","llm-training/chapters/01-pretraining-data.html","llm",0],["Data model","The shape you give your data and the questions it makes easy: tables (relational), documents, key-value pairs, wide columns or graphs.","data/chapters/01-data-models.html","data",0],["Data parallelism","Training with a full copy of the model on every GPU, each processing a different slice of the batch, with gradients averaged across GPUs.","llm-training/chapters/03-parallelism.html","llm",0],["Data protection impact assessment","A written analysis of the purpose, necessity and risks of high-risk processing, required before launch under GDPR Article 35.","evals/chapters/22-privacy-data.html","evl",0],["Data residency","A requirement that data is stored and processed in a given country or region.","ai-delivery/chapters/07-choosing-models.html","aid",0],["Data residency","A requirement that data be stored, processed or accessed only in certain places, which covers storage, processing and access separately.","evals/chapters/22-privacy-data.html","evl",0],["Data-science loop","The cycle of framing, exploring, baselining, modelling, validating, deploying and monitoring, in which modelling is one step of seven.","ml/chapters/00-start-here.html","ml",0],["Dataset shift","A difference between the distribution a model was trained on and the one it is applied to.","ml/chapters/03-eda.html","ml",0],["Data sovereignty","The question of whose law can compel access to data, which depends on who operates the system and where that operator is based, not only on where the bytes sit.","ai-delivery/chapters/13-restricted-environments.html","aid",0],["Data warehouse","A separate database optimised for analytics, loaded with copies of data from operational systems.","data/chapters/09-column-stores.html","data",0],["DBSCAN","A density-based clustering method that grows clusters from core points within a radius eps and labels unreachable points as noise.","ml/chapters/10-clustering.html","ml",0],["DCG","Discounted cumulative gain: the sum of each result's gain divided by log2(rank + 1), so good results count less the lower they sit.","retrieval/chapters/04-relevance-metrics.html","ret",0],["DDoS","Distributed denial of service: overwhelming a target with traffic from many sources.","security/chapters/16-abuse-dos.html","sec",0],["Dead group","A group of sampled answers that all received the same reward, so every advantage is zero and the prompt contributes no gradient that step.","llm-training/chapters/14-rlvr-grpo.html","llm",1],["Dead-letter queue","A place for messages or jobs that failed too many times, so they can be inspected instead of retried forever.","design/chapters/17-job-scheduler.html","design",0],["Deadline propagation","Passing the remaining time budget along a call chain so downstream services stop work the caller has given up on.","architecture/chapters/13-sync-async.html","arch",0],["Deadlock","Threads each holding something the other needs and waiting forever. Prevented, for example, by always taking locks in the same order.","systems/chapters/13-deadlock.html","sys",0],["Dead unit","A ReLU neuron whose pre-activation is negative for every example, so it receives no gradient and never recovers.","deep-learning/chapters/01-neurons-layers.html","dl",1],["Decapsulation","Removing headers layer by layer as data goes up the stack at the receiver.","networking/chapters/03-layers.html","net",0],["Deceptive problem","A problem where following improvements in the objective leads away from the best solution.","open-ended/chapters/03-novelty-search.html","oe",1],["Decision memo","A document that sets out real options with cost, risk and evidence, states a recommendation and the fact that would change it, and records the decision.","ai-delivery/chapters/17-writing-for-customers.html","aid",0],["Decision record","A short note of a choice that shapes the work, giving the context, options, the decision, who made it and when to revisit it.","ai-delivery/chapters/02-requirements-ambiguity.html","aid",0],["Decision record","A short note of what was decided, when, by whom and which alternatives were rejected, kept with the project.","ml-foundations/chapters/18-technical-writing.html","mlf",0],["Decision rule","The threshold, budget or top-k selection that turns a model's scores into actions.","ml/chapters/21-model-to-value.html","ml",0],["Decision threshold","The score above which a case is flagged as positive; a separate choice from the model that produces the score.","ml/chapters/02-framing-metrics.html","ml",1],["Decision tree","A model that predicts by routing an example through a series of threshold questions on single features to a leaf holding the prediction.","ml/chapters/08-decision-trees.html","ml",0],["Decode","The generation phase, one token per step, in which each step reads the weights and the whole KV cache and is limited by memory bandwidth.","deep-learning/chapters/19-efficient-attention.html","dl",0],["Decode","The phase of generation that produces one token per step, reading all the weights and the whole cache each time.","llm-training/chapters/18-kv-cache.html","llm",0],["Decoder-only model","A Transformer built only from causally masked self-attention blocks, which predicts each token from the ones before it.","deep-learning/chapters/10-transformer-block.html","dl",1],["Decontamination","Removing or flagging training documents that overlap with benchmark items before training.","evals/chapters/07-contamination.html","evl",1],["Decontamination","Removing training examples that overlap evaluation sets so that benchmark scores do not simply measure memorisation.","llm-training/chapters/10-sft.html","llm",1],["Decontextualisation","Rewriting a claim so that pronouns and vague references are replaced and it makes sense with the surrounding text removed.","evals/chapters/12-fact-checking.html","evl",0],["Deduplication","Removing repeated documents, lines or passages from a training corpus so the model does not waste compute on, or memorise, repeated text.","llm-training/chapters/01-pretraining-data.html","llm",0],["Deep learning","Machine learning in which a model of many stacked layers learns its own features from data, trained by gradient descent.","deep-learning/chapters/00-start-here.html","dl",0],["Deep module","A module with a simple interface hiding a lot of functionality. The opposite, a shallow module, adds interface without hiding much.","architecture/chapters/02-modules-coupling.html","arch",0],["Deep-research agent","An agent that answers an open-ended question with a sourced written report by iterating between planning, searching and reading for minutes rather than seconds.","agents/chapters/16-deep-research.html","agt",0],["Default gateway","The router a device sends packets to when the destination isn't on its local network.","networking/chapters/05-routing.html","net",0],["Defence in depth","Layering independent defences so that one failure does not mean a breach.","security/chapters/02-principles.html","sec",0],["Defence in depth","Layering independent controls so that a failure of one, such as a permission rule with a hole, does not defeat the system.","agents/chapters/20-sandboxing.html","agt",1],["Define-by-run","Building the computation graph as ordinary code executes, so that control flow in Python changes the graph with no special syntax.","deep-learning/chapters/05-pytorch.html","dl",1],["Delimiter","A marker such as an XML-style tag or a code fence that separates instructions from the data they operate on.","agents/chapters/04-prompting.html","agt",1],["Delivery receipt","An acknowledgement that a message reached the recipient's device (delivered) or was seen (read).","design/chapters/10-chat-presence.html","design",0],["Delta rule","A state update that subtracts what the state already predicts for a key before writing the new value, letting it overwrite old information.","deep-learning/chapters/22-beyond-attention.html","dl",0],["Dendrogram","A tree recording the order and height of merges in hierarchical clustering, which can be cut at any height to give a clustering.","ml/chapters/10-clustering.html","ml",0],["Dense retrieval","Retrieval that embeds queries and passages as vectors and returns the passages whose vectors are closest to the query's.","retrieval/chapters/07-dense-retrieval.html","ret",1],["Dependency injection","Passing a component the things it depends on, instead of having it create them, so they can be swapped (for example in tests).","architecture/chapters/04-design-patterns.html","arch",0],["Dependency inversion","High-level policy owns the interface, and low-level details implement it, reversing the usual direction of dependency.","architecture/chapters/05-hexagonal.html","arch",0],["Dependency rule","Source-code dependencies point inward, toward business rules, never outward toward frameworks or databases.","architecture/chapters/05-hexagonal.html","arch",0],["Dequantisation","Multiplying stored integers back by their scale to recover approximate real values before or during a matrix multiplication.","llm-training/chapters/19-quantisation.html","llm",0],["Derivative","The slope that chord slopes settle to as the step shrinks to zero: how fast a function's output changes per unit change in its input.","ml-foundations/chapters/08-derivatives.html","mlf",1],["Design by contract","Stating a function's preconditions, postconditions and invariants as part of its interface.","architecture/chapters/03-abstractions.html","arch",0],["Design doc","A written proposal that states a problem, options considered, the chosen design and its trade-offs.","design/chapters/04-tradeoffs-communication.html","design",0],["Design doc","A document that proposes a solution, its goals, non-goals, alternatives and trade-offs, so it can be criticised before it is built.","ml-foundations/chapters/18-technical-writing.html","mlf",0],["Design pattern","A named, reusable solution to a recurring design problem, such as strategy, adapter or observer.","architecture/chapters/04-design-patterns.html","arch",0],["Determinant","The factor by which a square matrix scales areas or volumes; negative if it flips orientation and zero if it flattens space.","ml-foundations/chapters/06-matrices.html","mlf",1],["Deterministic assertion","A pure check on a system's output, with no randomness or model call, that returns pass or fail with a reason.","evals/chapters/02-eval-harnesses.html","evl",1],["Deterministic database","A database that first agrees on the order of transactions, then executes them deterministically on every replica, avoiding 2PC (e.g. Calvin).","distributed/chapters/14-distributed-transactions.html","dist",0],["Deterministic replay","Recovering a workflow by re-running its code against a recorded history, which only works if the code makes the same decisions for the same history.","agents/chapters/15-durable-execution.html","agt",0],["Deterministic simulation testing","Running a whole cluster in one process with simulated network, disk and time, all driven by a seed, so any failure can be replayed exactly.","distributed/chapters/19-testing.html","dist",0],["Dev and test split","A division of benchmark items into a visible set for tuning and a rarely used held-out set for reporting.","evals/chapters/06-building-benchmarks.html","evl",1],["Development set","The examples a search uses to choose among candidates, kept separate from the test set that is used once to report the result.","open-ended/chapters/11-evolving-prompts.html","oe",1],["Device pixel ratio","The number of physical pixels per coordinate unit on a high-density display, which a harness must account for when converting model coordinates into clicks.","agents/chapters/17-computer-use.html","agt",0],["DHCP","Dynamic Host Configuration Protocol: hands out IP addresses and settings to devices joining a network.","networking/chapters/06-arp-dhcp-icmp.html","net",0],["Diagnostic bundle","A file of versions, configuration, counts and anonymised failure categories, gathered by a command so the customer can inspect it and release it for support.","ai-delivery/chapters/13-restricted-environments.html","aid",0],["Dictionary segmenter","A tokeniser that cuts unspaced text into real words using a dictionary and statistics, such as MeCab for Japanese or jieba for Chinese.","retrieval/chapters/22-multilingual.html","ret",0],["Diff guard","Code that checks a proposed change against a policy on paths, patterns and size before it is allowed to run.","open-ended/chapters/17-self-modification-safety.html","oe",1],["Digital Omnibus on AI","Regulation (EU) 2026/1744, in force since 27 July 2026, which postponed the high-risk obligations of the AI Act to December 2027 and August 2028.","evals/chapters/21-governance.html","evl",0],["Digital signature","A value only the private-key holder can produce, which anyone with the public key can verify.","security/chapters/03-applied-crypto.html","sec",0],["Direct forecasting","Training a model for the target horizon itself, so each row uses only information available that many steps before its target.","ml/chapters/18-time-series.html","ml",0],["Directional derivative","The slope of a function along a chosen unit direction, equal to the dot product of the gradient with that direction.","ml-foundations/chapters/08-derivatives.html","mlf",1],["Direct prompt injection","An injection typed by the user of the application in their own message.","evals/chapters/13-prompt-injection.html","evl",0],["Dirty page","A page of the page cache that has been changed in memory but not yet written to disk.","systems/chapters/09-durability.html","sys",0],["Dirty read","Seeing data another transaction has written but not yet committed.","data/chapters/11-isolation.html","data",0],["Disaggregated serving","Running prefill and decode on separate GPU pools so the two phases do not interfere, at the cost of transferring the KV cache between them.","llm-training/chapters/20-serving-engines.html","llm",0],["Discount factor","A number gamma between 0 and 1 that weights a reward k steps ahead by gamma to the power k, favouring sooner rewards.","llm-training/chapters/06-bandits-mdps.html","llm",1],["Discovery","The early stage of a project in which you work out what the customer actually needs, which is often not what they asked for.","ai-delivery/chapters/00-start-here.html","aid",0],["Discrimination (of an item)","How well an item separates stronger systems from weaker ones, often measured as its correlation with the total score on the other items.","evals/chapters/06-building-benchmarks.html","evl",1],["Distance","A numerical measure of how far apart two feature vectors are, such as the Euclidean distance.","ml/chapters/07-neighbours-bayes.html","ml",1],["Distillation","Training a small student model to imitate a larger teacher, using the teacher's probabilities or its written answers as the training signal.","llm-training/chapters/15-distillation.html","llm",0],["Distractor","A retrieved passage that is related to the question but does not contain the answer, and can pull the model away from it.","retrieval/chapters/17-rag-failures.html","ret",0],["Distributed monolith","Services that must be changed and deployed together: all the costs of distribution with none of the independence.","architecture/chapters/11-monolith-microservices.html","arch",0],["Distributed system","Several computers cooperating over a network so they appear to users as one system.","networking/chapters/15-why-distribute.html","net",0],["Distributed tracing","Recording the path of a request through many services as a tree of timed spans.","reliability/chapters/06-tracing.html","ops",0],["Distributional hypothesis","The idea that words occurring in similar contexts have similar meanings.","deep-learning/chapters/06-embeddings.html","dl",1],["DNS","Domain Name System: the distributed, cached directory that turns names like example.com into IP addresses.","networking/chapters/09-dns.html","net",0],["DNS rebinding","Making a hostname resolve to a safe address during a check and an internal one during use.","security/chapters/11-ssrf-server-side.html","sec",0],["DocLayNet","A dataset of 80,863 human-annotated document pages with bounding boxes in 11 layout classes, widely used to train layout detectors.","retrieval/chapters/18-pdf-layout.html","ret",0],["Document database","A database that stores self-contained records, usually JSON-like documents, good for data read and written as one unit.","data/chapters/01-data-models.html","data",0],["Document frequency","The number of documents in the collection that contain a term.","retrieval/chapters/02-bm25.html","ret",0],["DOM","The Document Object Model: the browser's tree of HTML elements for the current page.","agents/chapters/17-computer-use.html","agt",0],["Domain benchmark","A benchmark built for one field, such as finance or reasoning-heavy queries, used to check how far general results transfer.","retrieval/chapters/06-retrieval-benchmarks.html","ret",0],["Domain-driven design (DDD)","Designing software around a deep model of the business domain, built with domain experts (Evans, 2003).","architecture/chapters/06-ddd.html","arch",0],["Dominated configuration","A configuration that another one matches or beats on every axis and strictly beats on at least one, so it should never be chosen.","evals/chapters/19-cost-latency-quality.html","evl",0],["DORA","The EU Digital Operational Resilience Act, applicable from 17 January 2025, which sets duties on financial entities for ICT third-party risk and resilience.","ai-delivery/chapters/08-finance.html","aid",0],["Dot product","The sum of the products of matching entries of two equal-length vectors, such as 1x4 + 2x5 + 3x6 = 32.","ml-foundations/chapters/01-python-numerics.html","mlf",1],["Double descent","The pattern in which test error falls, spikes near the interpolation threshold, and falls again as the model keeps growing.","deep-learning/chapters/04-deep-regularisation.html","dl",1],["Double precision","The 64-bit floating-point format with a 53-bit significand, which gives roughly 15 to 16 decimal digits.","ml-foundations/chapters/01-python-numerics.html","mlf",1],["Double quantisation","Quantising the per-block scale factors themselves, which reduces the storage overhead of 4-bit weights from about 0.5 to about 0.13 bit per weight.","llm-training/chapters/11-lora.html","llm",1],["Downsampling","Storing older time-series data at coarser resolution to save space.","design/chapters/19-telemetry-platform.html","design",0],["DPO (Direct Preference Optimisation)","A method that trains the policy directly on preference pairs with a logistic loss on log-probability ratios against a reference, with no separate reward model or sampling loop.","llm-training/chapters/12-preference-optimisation.html","llm",1],["Draft model","The small, fast model that proposes candidate tokens in speculative decoding.","llm-training/chapters/21-speculative-decoding.html","llm",0],["Dr. GRPO","A modification of GRPO that removes the per-answer length normalisation and the standard-deviation scaling to avoid biases towards longer wrong answers.","llm-training/chapters/14-rlvr-grpo.html","llm",1],["Drift (data)","The gradual change of live data away from the data a search or model was tuned on.","open-ended/chapters/18-search-in-products.html","oe",1],["Dropout","Zeroing a random subset of hidden units at each training step so that no unit can depend on particular partners.","deep-learning/chapters/04-deep-regularisation.html","dl",1],["Dry run","A tool mode that reports what the action would do without changing anything.","agents/chapters/05-tool-design.html","agt",1],["DSPy","A framework in which an LLM pipeline is written as modules with signatures and an optimiser generates their prompts and examples against a metric.","open-ended/chapters/11-evolving-prompts.html","oe",1],["dtype","The data type of an array's elements, such as float32 or int64, which fixes bytes per element and the arithmetic used.","ml-foundations/chapters/02-numpy-arrays.html","mlf",1],["Dual-era client","A client that tries a modern stateless MCP request first and falls back to the initialize handshake when the server turns out to be legacy.","agents/chapters/08-mcp-production.html","agt",0],["Dual LLM pattern","A design in which a privileged model plans and uses tools without seeing untrusted text, and a quarantined model without tools reads it, passing results as variables.","evals/chapters/14-architectural-defences.html","evl",0],["Dual numbers","Pairs of a value and its derivative that obey the product and chain rules, used to implement forward mode.","ml-foundations/chapters/09-autodiff.html","mlf",1],["Dual write","Writing the same change to two systems separately, which can leave them inconsistent when one write fails.","data/chapters/19-streams-cdc.html","data",0],["Due process","The procedural protections of notice, a chance to respond, a reasoned decision and independent review that make an exercise of state power legitimate.","ai-delivery/chapters/11-public-sector.html","aid",0],["Dummy baseline","A predictor that ignores the features, such as always predicting the majority class or the training mean.","ml/chapters/04-baselines.html","ml",1],["Durable execution","Running a program so that its progress is stored outside the process, letting a new process continue after a crash without losing work or repeating completed steps.","agents/chapters/15-durable-execution.html","agt",0],["Dynamic loss scaling","Adjusting the loss scale during training: halve it and skip the step when a gradient overflows, double it after a run of clean steps.","deep-learning/chapters/17-training-stability.html","dl",0],["EAGLE","A speculative method that drafts by predicting the target model's next hidden feature rather than the next token.","llm-training/chapters/21-speculative-decoding.html","llm",0],["Early stopping","Ending training when held-out loss stops improving and restoring the weights from the best evaluation.","deep-learning/chapters/04-deep-regularisation.html","dl",1],["Early stopping","Halting training when validation error stops improving, which keeps weights small and acts as a regulariser.","ml/chapters/06-regularisation.html","ml",1],["EchoLeak","A zero-click prompt injection in Microsoft 365 Copilot (CVE-2025-32711) that leaked data via a crafted email by chaining several bypasses.","agents/chapters/19-agent-security.html","agt",1],["Eckart-Young theorem","The result that the truncated SVD is the closest rank-k matrix to A, with error set by the discarded singular values.","ml-foundations/chapters/07-decompositions.html","mlf",0],["Edge ordering","Placing the strongest retrieved passages at the start and end of the prompt and the weakest in the middle.","retrieval/chapters/17-rag-failures.html","ret",0],["Edit distance","The smallest number of single-character edits needed to turn one string into another.","retrieval/chapters/03-query-understanding.html","ret",0],["Effective challenge","Critical analysis of a model by informed, independent people who can identify its limits and force changes.","ai-delivery/chapters/08-finance.html","aid",0],["Effectively-once","The observable result of at-least-once attempts combined with idempotent handling, so that the world changes as if the action ran exactly once.","agents/chapters/15-durable-execution.html","agt",0],["Effective training time","The share of elapsed wall-clock time spent on useful training, after subtracting restarts, lost work and checkpoint pauses.","llm-training/chapters/05-long-runs.html","llm",0],["Efficiency (Shapley property)","The property that the feature contributions add up exactly to the prediction minus the baseline.","ml/chapters/16-interpretability.html","ml",0],["efSearch","The width of the candidate list used when searching an HNSW graph, raised to gain recall at the cost of latency.","retrieval/chapters/11-ann-indexes.html","ret",1],["Egress allow-list","A list of the only hosts or addresses an agent or its client may send requests to, blocking data leaving through other destinations.","evals/chapters/14-architectural-defences.html","evl",0],["Egress proxy","A server outside the sandbox through which all outbound requests pass, deciding by allow-list which hosts may be contacted.","agents/chapters/20-sandboxing.html","agt",1],["Eigenvalue","The factor lambda by which a matrix stretches one of its eigenvectors.","ml-foundations/chapters/07-decompositions.html","mlf",0],["Eigenvector","A non-zero vector that a square matrix only stretches, so that Av = lambda v.","ml-foundations/chapters/07-decompositions.html","mlf",0],["Einstein summation","NumPy's Einstein-summation function, which writes a tensor product by naming each axis with a letter and listing which letters survive.","ml-foundations/chapters/02-numpy-arrays.html","mlf",1],["Elastic net","A linear model penalised by a mix of the L1 and L2 norms of its weights.","ml/chapters/06-regularisation.html","ml",1],["Elbow method","Plotting inertia against the number of clusters and looking for the bend after which extra clusters help little.","ml/chapters/10-clustering.html","ml",0],["Elite","The best solution found so far for one cell of an archive.","open-ended/chapters/04-quality-diversity.html","oe",1],["Elitism","Copying the best few individuals unchanged into the next generation so the best score never falls.","open-ended/chapters/02-evolutionary-algorithms.html","oe",1],["ELT","Extract, load, transform: loading raw data first and transforming it inside the warehouse or lakehouse.","data/chapters/21-data-platforms.html","data",0],["Elusion rate","The proportion of relevant documents found in a random sample of the null set, used to estimate how many relevant documents the review left behind.","ai-delivery/chapters/10-legal.html","aid",0],["Embedding","A dense, learned vector of a few hundred numbers that represents a word, token or other discrete item so that similar items lie close together.","deep-learning/chapters/06-embeddings.html","dl",1],["Embedding","A vector produced by a trained model for an item such as a word or sentence so that similar items get similar vectors.","ml-foundations/chapters/05-vectors-similarity.html","mlf",1],["Embedding","A list of real numbers produced by a neural network to represent a piece of text so that similar texts get nearby vectors.","retrieval/chapters/07-dense-retrieval.html","ret",1],["Embedding table","A matrix with one row per vocabulary item whose rows are looked up by index and trained like any other weights.","deep-learning/chapters/06-embeddings.html","dl",1],["Emergent abilities","Abilities that seem to appear abruptly at some model scale, whose sharpness is partly disputed as an effect of all-or-nothing metrics.","deep-learning/chapters/18-scaling-laws.html","dl",0],["Encapsulation","Wrapping data in a header from each layer as it goes down the stack: envelopes inside envelopes.","networking/chapters/03-layers.html","net",0],["Encoder-decoder","A design in which one network reads the source sequence into a summary and another generates the target sequence from it.","deep-learning/chapters/08-sequences-rnns.html","dl",0],["End-state grading","Scoring an agent by comparing the final state of the world with a goal state or invariants, instead of judging its words or its route.","evals/chapters/08-agent-evals.html","evl",1],["Ensemble","A prediction formed by combining the outputs of several models.","ml/chapters/20-competitions.html","ml",0],["Entailment","The relation that if the evidence is true then the claim must also be true.","evals/chapters/12-fact-checking.html","evl",0],["Entailment (NLI)","A classification of whether a premise text implies, contradicts or says nothing about a hypothesis claim.","retrieval/chapters/16-grounded-citations.html","ret",0],["Entity resolution","Deciding that different mentions, such as 'Chen', 'C. Wu' and 'the head of Platform', refer to the same entity and merging them into one node.","retrieval/chapters/15-agentic-retrieval.html","ret",0],["Entropy","The impurity measure -p log2 p - (1-p) log2 (1-p), in bits; the drop in entropy from a split is the information gain.","ml/chapters/08-decision-trees.html","ml",0],["Entropy","The expected surprise of a distribution, which is also the least average number of bits per symbol a lossless code can use.","ml-foundations/chapters/14-information-theory.html","mlf",1],["Envelope encryption","Encrypting data with a data key, then encrypting (wrapping) that data key with a master key held in a KMS.","security/chapters/04-keys-secrets-pki.html","sec",0],["Environment-agent pair","A learning problem together with the agent being trained on it, the unit of population in POET.","open-ended/chapters/05-open-ended-algorithms.html","oe",1],["Ephemeral znode","A ZooKeeper node that is deleted automatically when the session that created it ends; the basis of liveness-tracking recipes.","distributed/chapters/11-coordination-services.html","dist",0],["Episodic memory","Records of what happened, such as past conversations and actions with their times, retrieved by search rather than loaded in full.","agents/chapters/11-memory.html","agt",1],["Epoch","One full pass over the training set.","deep-learning/chapters/05-pytorch.html","dl",1],["epoll / kqueue","The scalable Linux (epoll) and BSD/macOS (kqueue) system calls for waiting on many file descriptors at once.","systems/chapters/16-event-loops.html","sys",0],["Epsilon-greedy","A bandit strategy that picks a random action with probability epsilon and the best-looking action otherwise.","llm-training/chapters/06-bandits-mdps.html","llm",1],["Epsilon-greedy","A bandit strategy that picks a random option with probability epsilon and the best-looking option otherwise.","open-ended/chapters/01-tree-search.html","oe",1],["Erasure coding","Splitting data into k pieces plus m parity pieces so any k of the k + m can rebuild it, using less space than replication.","design/chapters/08-object-storage.html","design",0],["Erlang C","The formula giving the probability a request must wait in a queue served by c identical servers.","reliability/chapters/08-queueing-theory.html","ops",0],["Error analysis","Reading real traces, naming what went wrong and counting failure kinds so that fixes are chosen by evidence.","evals/chapters/01-error-analysis.html","evl",1],["Error-analysis memo","A short write-up that reads a sample of failures, names the first thing that went wrong in each, counts the categories and says what to fix first.","ai-delivery/chapters/18-getting-hired.html","aid",0],["Error-analysis memo","A write-up of a labelled sample of failures: categories, counts with intervals, examples and a ranked list of fixes.","ml-foundations/chapters/18-technical-writing.html","mlf",0],["Error budget","The amount of unreliability an SLO allows (1 − SLO), spent deliberately on releases and experiments.","reliability/chapters/02-slos-error-budgets.html","ops",0],["Error budget","The shortfall an objective allows, such as 1% of requests being slow, which when spent shifts priority from features to reliability.","ai-delivery/chapters/16-research-to-product.html","aid",0],["Escrow","Splitting a shared quantity, such as stock, into local allowances so nodes can decrement without coordinating until their share runs out.","distributed/chapters/16-coordination-avoidance.html","dist",0],["Ethernet","The dominant wired local-network technology, with frames addressed by MAC address.","networking/chapters/02-local-networks.html","net",0],["Ethical wall","A rule or system barrier that keeps a team away from a matter because of a conflict of interest; also called an information barrier.","ai-delivery/chapters/10-legal.html","aid",0],["EU AI Act","Regulation (EU) 2024/1689, which sets obligations for AI systems and general-purpose models according to role and risk tier.","evals/chapters/21-governance.html","evl",0],["Eval harness","A program that runs test cases against a system, applies checks, stores results and compares runs.","evals/chapters/02-eval-harnesses.html","evl",1],["Evaluation cascade","Staged testing in which cheap checks reject poor candidates before expensive ones are run.","open-ended/chapters/09-program-evolution.html","oe",1],["Evaluation function (agent design)","The scoring rule applied to each candidate agent, such as accuracy on a search set, which the search can only be as good as.","open-ended/chapters/12-meta-agent-search.html","oe",1],["Evaluation harness","A program that builds prompts, runs a model on a set of tasks, scores the outputs and records the settings, so different models are compared by identical code.","llm-training/chapters/23-evaluating-models.html","llm",0],["Evaluation loop","The cycle of looking at traces, naming failures, measuring them, changing the system and guarding the fix.","evals/chapters/00-start-here.html","evl",0],["Evaluation plan","A short document, signed by both sides before the evaluation is run, that fixes the decision, the gold set, the metrics, the pass rule and the run procedure.","ai-delivery/chapters/06-evaluation-plans.html","aid",0],["Evaluator","The part of a search loop that scores a candidate; flaws in it are what a search loop will exploit.","open-ended/chapters/00-start-here.html","oe",1],["Evaluator hacking","A search or agent finding a way to score highly on an evaluator without doing the intended work.","open-ended/chapters/15-evaluator-hacking.html","oe",1],["Evaluator-optimiser","A loop in which one call produces a draft, another checks it against criteria and returns feedback, and the producer revises until the check passes or a limit is reached.","agents/chapters/13-workflow-patterns.html","agt",1],["Event-carried state transfer","Putting the data consumers need inside the event, so they don't have to call back the producer.","architecture/chapters/14-event-driven.html","arch",0],["Event-driven architecture","Components communicate by publishing and reacting to events rather than calling each other directly.","architecture/chapters/14-event-driven.html","arch",0],["Event log (journal)","An append-only record of every model reply, tool result and human decision in a run, from which the run's current state can be rebuilt.","agents/chapters/15-durable-execution.html","agt",0],["Event loop","One thread that repeatedly asks the kernel which connections or timers are ready and runs the matching callbacks.","systems/chapters/16-event-loops.html","sys",0],["Event sourcing","Storing every change as an immutable event and deriving current state by replaying them.","architecture/chapters/16-cqrs-event-sourcing.html","arch",0],["Event stream","An ordered log of every action an agent takes and every observation it receives, which makes runs replayable.","agents/chapters/18-coding-agents.html","agt",1],["Eventual consistency","If writes stop, all replicas eventually converge to the same value. Reads in the meantime may be stale.","networking/chapters/18-replication.html","net",0],["Event (vs command)","An event states a fact that happened (OrderPlaced); a command asks for something to be done (ChargeCard).","architecture/chapters/14-event-driven.html","arch",0],["Evidence pack","The dossier of purpose, data, evaluation results, monitoring, change control and audit trail that lets a customer's risk and audit teams approve and re-examine a system.","ai-delivery/chapters/08-finance.html","aid",0],["Evidence pack","A register linking each risk to a control, a metric with a threshold, an owner and the date of the latest result, generated from evals and traces.","evals/chapters/21-governance.html","evl",0],["Evidence recall","The share of questions for which the context you built contained every fact needed to answer them.","agents/chapters/12-long-context.html","agt",0],["Evolutionary algorithm","A search method that keeps a population of candidates and repeatedly selects the fitter ones and varies them to make the next generation.","open-ended/chapters/02-evolutionary-algorithms.html","oe",1],["Evolutionary merging","Searching for a merge recipe with an evolutionary algorithm that merges and scores candidate recipes, in parameter space and in data-flow space, without gradients.","llm-training/chapters/16-model-merging.html","llm",1],["Evolution strategies","A black-box optimiser that estimates a direction of improvement by scoring random perturbations of the parameters and moving toward the better ones.","open-ended/chapters/05-open-ended-algorithms.html","oe",1],["Evolution strategy","An evolutionary method for real-valued vectors that relies on Gaussian mutation with an adapted step size.","open-ended/chapters/02-evolutionary-algorithms.html","oe",1],["EvoPrompt","A prompt optimiser in which a language model carries out the steps of a genetic algorithm or differential evolution on a population of prompts.","open-ended/chapters/11-evolving-prompts.html","oe",1],["Exactly-once processing","At-least-once delivery combined with idempotent or transactional processing, so each input affects the output once.","distributed/chapters/17-logs-exactly-once.html","dist",0],["Exchangeability test","A black-box contamination test that checks whether a model assigns higher probability to a benchmark's published item order than to shuffled orders.","evals/chapters/07-contamination.html","evl",1],["Exit status","The small number a process returns when it ends. 0 means success; anything else signals an error.","systems/chapters/05-processes.html","sys",0],["Expand and contract","Changing an interface or schema in steps: add the new form, migrate users, then remove the old form.","architecture/chapters/10-evolving-contracts.html","arch",0],["Expectation","The probability-weighted average of a random variable's values, which is linear even for dependent variables.","ml-foundations/chapters/12-probability.html","mlf",1],["Expected calibration error","The average gap between stated confidence and actual accuracy across confidence bins, weighted by how many answers fall in each bin.","evals/chapters/11-grounding-abstention.html","evl",0],["Expected calibration error","The size-weighted average gap between predicted probability and observed frequency across bins of score.","ml/chapters/15-imbalance-calibration.html","ml",0],["Expected cost per item","The average cost of a system's errors per item handled, found by weighting each error type by what it costs the customer.","ai-delivery/chapters/06-evaluation-plans.html","aid",0],["Expected weeks saved per day of testing","A ranking score for assumptions: the chance an assumption is false times the weeks wasted if it fails late, divided by the days a small test would take.","ai-delivery/chapters/05-riskiest-assumption.html","aid",0],["Experiment log","A record of each run's code version, data identifier, configuration, environment, seed and results.","ml-foundations/chapters/04-reproducible-experiments.html","mlf",1],["Experiment report","A short document stating a question, the setup, the results with uncertainty, limitations and a decision.","ml-foundations/chapters/18-technical-writing.html","mlf",0],["Expert","One of the parallel MLPs in a mixture-of-experts layer; it is a part of one network trained together, not a topic specialist.","deep-learning/chapters/20-mixture-of-experts.html","dl",0],["Expert parallelism","Placing different experts on different GPUs, so tokens are exchanged between GPUs by two all-to-all steps per layer.","deep-learning/chapters/20-mixture-of-experts.html","dl",0],["Expert vector","A stored vector of singular-value scales trained for one domain, which can be mixed with others to configure the model for a task.","llm-training/chapters/17-adapters-on-demand.html","llm",0],["EXPLAIN","A command that shows the plan a database will use (or did use) for a query.","data/chapters/08-query-execution.html","data",0],["Explained variance ratio","The share of the total variance in the data that lies along a principal component.","ml/chapters/11-dimensionality-reduction.html","ml",0],["Exploding gradient","The growth of gradients without bound as they are multiplied through many steps, causing huge updates or NaN values.","deep-learning/chapters/08-sequences-rnns.html","dl",0],["Exploding gradients","Gradients that grow exponentially through the layers of a deep network and make updates unstable.","deep-learning/chapters/03-training-dynamics.html","dl",1],["Exploration-exploitation trade-off","The tension between using the action that currently looks best and trying others to learn whether they are better.","llm-training/chapters/06-bandits-mdps.html","llm",1],["Exploration versus exploitation","The trade-off between trying uncertain options to learn more and repeating the option that currently looks best.","open-ended/chapters/01-tree-search.html","oe",1],["Exploratory data analysis","Looking at data with open questions, through summaries, plots and audits, before committing to a model.","ml/chapters/03-eda.html","ml",0],["Exponent","The bits of a floating-point number that set its scale and so its range.","deep-learning/chapters/17-training-stability.html","dl",0],["Expression swell","The growth in size of a symbolically differentiated formula, which can be far larger than the original expression.","ml-foundations/chapters/09-autodiff.html","mlf",1],["F1 score","The harmonic mean of precision and recall, which is low whenever either is low.","ml/chapters/02-framing-metrics.html","ml",1],["Fabrication","Inventing an entity, case, paper, quotation or function that does not exist.","evals/chapters/10-hallucination.html","evl",0],["FActScore","The percentage of a generation's atomic facts that a reliable knowledge source supports.","evals/chapters/10-hallucination.html","evl",0],["Factuality hallucination","An output that conflicts with facts about the world, either by inventing something or by misstating a real fact.","evals/chapters/10-hallucination.html","evl",0],["Fail closed","Stopping the request when a safety check errors or times out, instead of letting it pass.","evals/chapters/15-guardrails.html","evl",0],["Fail open / fail closed","Whether a protective component lets traffic through (open) or blocks it (closed) when it cannot decide.","design/chapters/05-rate-limiter.html","design",0],["Failover","Switching to a backup machine when the primary fails.","networking/chapters/18-replication.html","net",0],["FAIL_TO_PASS and PASS_TO_PASS","The two test sets used to grade a patch: tests that must start passing, and tests that must keep passing.","agents/chapters/18-coding-agents.html","agt",1],["Failure attribution","Identifying the first pipeline stage at which a failed request went wrong, so the fix targets that stage.","retrieval/chapters/17-rag-failures.html","ret",0],["Failure detector","A component that suspects crashed nodes. Characterised by completeness (crashes are eventually suspected) and accuracy (live nodes are not).","distributed/chapters/03-failure-detection.html","dist",0],["Failure mode","A named, recurring way a system goes wrong, counted across traces to decide what to fix first.","evals/chapters/18-improvement-flywheel.html","evl",0],["Failure notice","A message to a customer about a fault, giving the news, measurements, impact, what is known and unknown, containment and fix with dates, and the next update.","ai-delivery/chapters/17-writing-for-customers.html","aid",0],["Failure taxonomy","A short list of named failure kinds, with counts, built from reading real outputs.","evals/chapters/00-start-here.html","evl",0],["Faithfulness","Whether an answer says only what the sources it was given say, regardless of whether the sources are correct.","evals/chapters/12-fact-checking.html","evl",0],["Faithfulness hallucination","An output that conflicts with what the user supplied, such as a summary that contradicts or adds to its source document.","evals/chapters/10-hallucination.html","evl",0],["Faithfulness (of a citation)","Whether the answer was actually derived from the cited material, rather than from memory with a citation attached afterwards.","retrieval/chapters/16-grounded-citations.html","ret",0],["Fake","A working but simplified implementation, such as an in-memory repository, used instead of the real thing in tests.","architecture/chapters/07-testability.html","arch",0],["Fallback","A cheaper, weaker answer returned, and clearly labelled, when the main path times out or fails.","ai-delivery/chapters/16-research-to-product.html","aid",0],["False negative","A passage treated as non-relevant in training because it was never labelled, although it actually answers the query.","retrieval/chapters/07-dense-retrieval.html","ret",1],["False negative rate","The share of papers that should be accepted which a reviewer rejects.","open-ended/chapters/14-automated-science.html","oe",1],["False positive rate","The share of papers that should be rejected which a reviewer accepts.","open-ended/chapters/14-automated-science.html","oe",1],["False sharing","Two threads updating different variables that happen to sit in the same cache line, so the line bounces between cores and both slow down.","systems/chapters/02-memory-hierarchy.html","sys",0],["False support","A verifier error in which a wrong claim is marked as supported, the most damaging error for a checking stage.","evals/chapters/12-fact-checking.html","evl",0],["Falsifiable assumption","An assumption written with the evidence, the amount and the consequence named, so that some observation could contradict it.","ai-delivery/chapters/05-riskiest-assumption.html","aid",0],["Fan-in","The number of inputs feeding one neuron, which is the number of rows of the weight matrix.","deep-learning/chapters/03-training-dynamics.html","dl",1],["Fan-out","The multiplication of rows when a join key is not unique in one table, which inflates counts and sums.","ml-foundations/chapters/03-data-wrangling.html","mlf",0],["Fan-out amplification","When one request calls many servers, the chance at least one is slow grows quickly, so rare slowness becomes common.","reliability/chapters/09-tail-latency.html","ops",0],["Fan-out on read","Assembling a timeline at read time by fetching recent posts from everyone the reader follows.","design/chapters/09-news-feed.html","design",0],["Fan-out on write","Pushing each new post into every follower's precomputed timeline when it is created.","design/chapters/09-news-feed.html","design",0],["Feasibility triage","A short, structured assessment of a candidate task before building, which sorts it into build, fix something first, use a simpler tool, or stop.","ai-delivery/chapters/04-feasibility.html","aid",0],["Feature","A number that describes one aspect of an example, either designed by a person or learned by a model.","deep-learning/chapters/00-start-here.html","dl",0],["Feature","One input fact about an example, such as a word count or a customer's tenure; the features form the columns of X.","ml/chapters/00-start-here.html","ml",0],["Feature dimensions","The behaviour axes, such as program complexity, that define the cells of a MAP-Elites archive in a framework like OpenEvolve.","open-ended/chapters/10-evolution-frameworks.html","oe",1],["Feature engineering","Constructing the input columns a model receives from raw data so that the useful pattern is easy for the model to find.","ml/chapters/17-feature-engineering.html","ml",0],["Feature flag","A runtime switch that turns code paths on or off without a deploy, separating deploy from release.","architecture/chapters/18-evolving-safely.html","arch",0],["Feature map","The grid of filter responses produced by one filter over an input, showing where its pattern was found.","deep-learning/chapters/07-convolutions.html","dl",0],["Feature register","A table listing each feature's source, the time it is written, whether it can change later and whether it is available at prediction time.","ml/chapters/14-leakage.html","ml",1],["Feature store","A system that serves the same model input features consistently for training (offline) and prediction (online).","design/chapters/20-ml-systems.html","design",0],["Fencing token","A number that increases with every lock grant. The resource rejects any request carrying a lower token than one it has already seen.","distributed/chapters/04-leases-fencing.html","dist",0],["Few-shot prompting","Including a handful of worked input-output examples in the prompt so the model picks up the task, format and tone without any change to its weights.","agents/chapters/04-prompting.html","agt",1],["Fiber optic","Glass cable that carries bits as pulses of light.","networking/chapters/01-bits-and-signals.html","net",0],["Field (extraction)","One named item to be extracted from a document, with a type and rules, such as an invoice total or a date of birth.","retrieval/chapters/20-tables-forms.html","ret",0],["Field-level exact match","The share of extracted fields whose value equals the reference exactly, used where a single wrong character changes the meaning.","retrieval/chapters/19-ocr.html","ret",0],["File descriptor","A small number a process uses to refer to an open file, pipe or socket (0, 1 and 2 are stdin, stdout and stderr).","systems/chapters/08-files.html","sys",0],["Filter","The small grid of learned weights, also called a kernel, that a convolutional layer slides over its input.","deep-learning/chapters/07-convolutions.html","dl",0],["Filtered traversal","Walking an index graph while testing the filter at each node, counting only passing nodes as results but using failing ones as stepping stones.","retrieval/chapters/12-filters-permissions.html","ret",0],["Finding (red team)","A recorded, reproducible way of reaching an attack goal, with enough detail for someone else to replay it and fix its cause.","evals/chapters/16-red-teaming.html","evl",0],["Fine-tuning an embedder","Continuing to train a pretrained embedding model on your own query and passage pairs, followed by re-embedding the whole corpus.","retrieval/chapters/07-dense-retrieval.html","ret",1],["Finite difference","An estimate of a derivative from function values at nearby points, such as (f(x+h) - f(x-h)) / 2h.","ml-foundations/chapters/08-derivatives.html","mlf",1],["First failure","The earliest wrong step in a trace, which is counted because later errors often follow from it.","evals/chapters/01-error-analysis.html","evl",1],["Fitness function","An automated check that guards an architectural property, such as \"the domain imports no database code\".","architecture/chapters/19-documenting-decisions.html","arch",0],["Fitness function","The score that an evolutionary algorithm tries to increase, computed by evaluating a candidate.","open-ended/chapters/02-evolutionary-algorithms.html","oe",1],["Five Cs","Keshav's first-pass questions: category, context, correctness, contributions and clarity.","ml-foundations/chapters/16-reading-papers.html","mlf",0],["Five whys","A heuristic of repeating 'why?' to move from a symptom to its cause, whose answers should be treated as hypotheses to check.","ai-delivery/chapters/01-discovery-interviews.html","aid",0],["Flame graph","A visualisation of sampled stack traces in which width shows time spent, not order (Brendan Gregg).","systems/chapters/22-performance-engineering.html","sys",0],["FlashAttention","An exact attention kernel that works tile by tile in on-chip memory and never writes the full score matrix to HBM.","deep-learning/chapters/19-efficient-attention.html","dl",0],["Flight recorder","A ring buffer of recent communication events and stack traces per rank, dumped when a watchdog fires so a hang can be traced to its cause.","llm-training/chapters/05-long-runs.html","llm",0],["Float","Python's real-number type: a 64-bit IEEE 754 double stored as a 24-byte object, accurate to about 15 to 16 significant digits.","ml-foundations/chapters/01-python-numerics.html","mlf",1],["Floating-point number","A number stored as a sign, an exponent and a mantissa, like binary scientific notation, so precision is a roughly constant fraction of the value.","ml-foundations/chapters/11-numerics.html","mlf",0],["FLOPs","A count of floating-point operations (additions or multiplications), the amount of arithmetic a computation needs, as distinct from FLOP/s, the speed at which hardware performs it.","deep-learning/chapters/16-resource-accounting.html","dl",1],["FLOP/s","Floating-point operations per second: the rate at which a chip does arithmetic, as opposed to FLOPs, a count of operations in a job.","ml-foundations/chapters/17-compute-costs.html","mlf",0],["Flow control","The receiver telling the sender how much more data it can buffer (TCP's receive window).","networking/chapters/08-tcp.html","net",0],["FLP impossibility","No deterministic protocol can guarantee consensus in an asynchronous system if even one process may crash (Fischer, Lynch & Paterson, 1985).","distributed/chapters/02-impossibility.html","dist",0],["Fluent failure","An error whose output is well-formed and plausible, such as a vision-language model changing one digit of an amount, so it passes format checks and proofreading for sense.","retrieval/chapters/19-ocr.html","ret",0],["Fold","One of the k parts of the data in cross-validation, used once for validation and k minus 1 times for training.","ml/chapters/13-cross-validation.html","ml",1],["Forecast origin","The moment a forecast is made; only data dated before it may be used.","ml/chapters/18-time-series.html","ml",0],["Foreign key","A column that refers to the primary key of another table, so the database can keep the two consistent.","data/chapters/02-sql-relational.html","data",0],["fork / exec","The Unix way to start programs: fork makes a copy of the current process; exec replaces a process's program with a new one.","systems/chapters/05-processes.html","sys",0],["Format reward","A small reward for putting the answer in a required structure, such as reasoning inside think tags, so that the final answer can be extracted and checked.","llm-training/chapters/14-rlvr-grpo.html","llm",1],["Forward and reverse KL","KL(p || q) punishes a model for missing mass the truth has and so covers all modes; KL(q || p) punishes mass the truth lacks and so locks onto one mode.","ml-foundations/chapters/14-information-theory.html","mlf",1],["Forward chaining","A time-respecting split in which each fold trains on everything before a cut-off and validates on the block just after it.","ml/chapters/13-cross-validation.html","ml",1],["Forward-deployed engineer","An engineer embedded with a customer who configures and extends a company's technology to fit that customer's real situation.","ai-delivery/chapters/00-start-here.html","aid",0],["forward function","The single function a meta agent writes to define an agent in the ADAS framework: it takes the task information and returns the agent's answer.","open-ended/chapters/12-meta-agent-search.html","oe",1],["Forward-mode autodiff","Differentiation that carries a derivative alongside every value, giving the effect of one input on all outputs per pass.","ml-foundations/chapters/09-autodiff.html","mlf",1],["Forward secrecy","A property of key exchange in which stealing a long-term key later does not reveal past session keys.","security/chapters/03-applied-crypto.html","sec",0],["Foundation model","A large pretrained model that is adapted or called for many tasks rather than trained from scratch for each one.","ml-foundations/chapters/00-start-here.html","mlf",1],["Four golden signals","Latency, traffic, errors and saturation: the SRE book's minimal set of service metrics.","reliability/chapters/04-metrics.html","ops",0],["fp16","The IEEE 16-bit floating-point format with 5 exponent and 10 mantissa bits, more precise than bf16 but overflowing above 65,504.","deep-learning/chapters/17-training-stability.html","dl",0],["fp8","An 8-bit floating-point format, in E4M3 or E5M2 form, that needs per-tensor or per-block scale factors to fit values in its narrow range.","ml-foundations/chapters/11-numerics.html","mlf",0],["FP8 (E4M3 and E5M2)","Two 8-bit floating-point formats: E4M3 has more precision and less range, E5M2 has more range and less precision.","llm-training/chapters/19-quantisation.html","llm",0],["Frame","The unit of data at the link layer: a packet wrapped with a link header and trailer.","networking/chapters/02-local-networks.html","net",0],["Framing","Marking where one message ends and the next begins in a byte stream, with a delimiter or a length prefix.","networking/labs/lab-01-sockets.html","net",0],["Frequency encoding","Replacing each category by how often it occurs in the training data, giving one column whatever the cardinality.","ml/chapters/17-feature-engineering.html","ml",0],["Fresh-variant gap test","Comparing a model's accuracy on original benchmark items with its accuracy on newly made equivalent items to reveal memorisation.","evals/chapters/07-contamination.html","evl",1],["Frobenius norm","The square root of the sum of all squared entries of a matrix.","ml-foundations/chapters/07-decompositions.html","mlf",0],["Frontier API","A hosted model whose weights the vendor keeps closed, used by sending requests and paying per token.","ai-delivery/chapters/07-choosing-models.html","aid",0],["FSDP","Fully Sharded Data Parallel, PyTorch's implementation of the ZeRO-3 idea, in which each GPU stores a shard of everything and gathers weights layer by layer.","llm-training/chapters/03-parallelism.html","llm",0],["fsync","A system call that waits until a file's data has been handed to stable storage. The price of \"saved means saved\".","systems/chapters/09-durability.html","sys",0],["FT-Transformer","A tabular neural network that embeds each column as a token and applies a transformer over the column tokens.","ml/chapters/19-tabular-deep-learning.html","ml",0],["Full table scan","Reading every row of a table to answer a query, what happens when no useful index exists.","data/chapters/07-indexes.html","data",0],["Functional requirement","What a system must do, such as \"users can post a photo\".","design/chapters/01-framework.html","design",0],["Function calling","The mechanism by which a model replies with a structured request to run a named function with arguments, which your program runs before returning the result.","agents/chapters/06-function-calling.html","agt",0],["Fundamental rights impact assessment","A documented assessment, required by the EU AI Act before a public body first uses certain high-risk AI, of who is affected, the risks of harm, the human oversight and the remedies.","ai-delivery/chapters/11-public-sector.html","aid",0],["FunSearch","A DeepMind system that pairs a code-writing language model with an automatic evaluator and an island-based program database to evolve a single function.","open-ended/chapters/09-program-evolution.html","oe",1],["Fused kernel","A single kernel that performs several operations while values stay on chip, avoiding writes and re-reads of intermediate arrays.","llm-training/chapters/04-kernels.html","llm",0],["Future (promise)","An object standing for a result that doesn't exist yet but will, once some work finishes.","systems/chapters/17-async-await.html","sys",0],["Game day","A planned exercise in which a team rehearses failures and its response to them.","reliability/chapters/19-chaos-gamedays.html","ops",0],["Gap (embargo)","Rows dropped between the training window and the validation block so that labels or features that overlap the cut-off cannot leak.","ml/chapters/13-cross-validation.html","ml",1],["Gap statistic","A way of choosing the number of clusters by comparing within-cluster dispersion with that of structureless reference data.","ml/chapters/10-clustering.html","ml",0],["Garbage collection","Automatic memory management: the runtime finds objects nothing refers to any more and frees them. Can cause pauses.","systems/chapters/03-stack-heap.html","sys",0],["Gate","A programmatic check between two steps of a workflow that decides whether to continue, so that bad output stops cheaply instead of propagating.","agents/chapters/13-workflow-patterns.html","agt",1],["Gate","A learned vector of numbers between 0 and 1, produced by a sigmoid, that scales how much of another vector passes through.","deep-learning/chapters/08-sequences-rnns.html","dl",0],["Gated linear unit","A layer that multiplies two parallel linear projections of the input element by element, one of them passed through a nonlinearity that acts as a gate.","deep-learning/chapters/10-transformer-block.html","dl",1],["Gatekeeper","A person in security, legal, IT or compliance whose approval a project needs and who can stop it.","ai-delivery/chapters/01-discovery-interviews.html","aid",0],["Gauge","A metric that goes up and down, such as queue length or memory in use.","reliability/chapters/04-metrics.html","ops",0],["Gödel machine","Schmidhuber's theoretical self-rewriting system that changes its own code only after proving the change improves its expected reward, which makes it elegant but impractical.","open-ended/chapters/13-self-improving-agents.html","oe",1],["GELU","A smooth activation that weights its input by the probability that a standard normal variable is smaller than it.","deep-learning/chapters/01-neurons-layers.html","dl",1],["GenAI semantic conventions","OpenTelemetry's naming rules for spans, attributes and metrics of model calls, tool calls and agents, currently in Development status.","evals/chapters/17-observability.html","evl",0],["Generalisation error","The expected loss of a model on new cases drawn from the same distribution as its training data, which can only be estimated, never observed directly.","ml/chapters/01-generalisation.html","ml",1],["Generalisation gap","The difference between a model's error on unseen data and its error on the data it was trained on.","ml/chapters/01-generalisation.html","ml",1],["Generalised advantage estimation (GAE)","An advantage estimator that sums future TD errors with weights (gamma times lambda) to the power of their delay, trading critic bias against sampling noise.","llm-training/chapters/09-value-functions.html","llm",1],["General-purpose AI model","A broadly capable model, such as a large language model, whose developers have separate documentation and risk duties under the EU AI Act.","evals/chapters/21-governance.html","evl",0],["Generative AI Profile","NIST AI 600-1, a companion to the AI RMF that names twelve risks specific to generative AI and suggests actions for each.","evals/chapters/21-governance.html","evl",0],["Genetic algorithm","An evolutionary algorithm over fixed-length strings, using selection, crossover and mutation.","open-ended/chapters/02-evolutionary-algorithms.html","oe",1],["Genome","The data structure that encodes one candidate solution in an evolutionary algorithm, such as a bit string, a vector or a program.","open-ended/chapters/02-evolutionary-algorithms.html","oe",1],["GeoDNS","DNS that gives different answers depending on where the question seems to come from, to send users to a nearby site.","networking/cases/case-03-dns-steering.html","net",0],["Geohash","A string encoding of latitude and longitude in which shared prefixes mean nearby cells.","design/chapters/14-ride-matching.html","design",0],["GEPA","A prompt optimiser that reflects on trajectories in natural language and keeps a Pareto frontier of candidate prompts.","open-ended/chapters/11-evolving-prompts.html","oe",1],["GIL","CPython's global interpreter lock: only one thread runs Python bytecode at a time, so threads don't speed up CPU-bound Python code.","systems/chapters/10-threads.html","sys",0],["Gini impurity","The probability that two examples drawn at random from a node have different labels, equal to 2p(1-p) for two classes.","ml/chapters/08-decision-trees.html","ml",0],["GitOps","Using a Git repository as the source of truth for deployed state, with an agent that reconciles the running system to it.","reliability/chapters/13-config-iac.html","ops",0],["Git worktree","A second working directory of the same repository on its own branch, letting several agent sessions edit in parallel without overwriting each other.","agents/chapters/22-ai-coding-tools.html","agt",0],["Glitch token","A vocabulary entry that existed in the tokeniser but was almost never seen in the model's training data, so its embedding is barely trained and it triggers odd outputs.","deep-learning/chapters/13-tokenisation.html","dl",1],["Global explanation","A description of how a model behaves overall, such as which features it relies on or how its output varies with one input.","ml/chapters/16-interpretability.html","ml",0],["Global pooling","Collapsing a whole feature map to one number per channel, which discards position.","deep-learning/chapters/07-convolutions.html","dl",0],["Goal hijacking","A direct injection that redirects a model away from its assigned task to the attacker's task.","evals/chapters/13-prompt-injection.html","evl",0],["Go-Back-N","A sliding-window protocol where a lost packet makes the sender resend it and everything after it.","networking/labs/lab-02-reliable-udp.html","net",0],["Gold answer","The trusted answer, accepted variants or checking rule against which a response to an item is scored.","evals/chapters/06-building-benchmarks.html","evl",1],["Gold-context run","An evaluation that gives the generator only the gold passage, to measure the ceiling of the generation stage.","retrieval/chapters/17-rag-failures.html","ret",0],["Gold passage","The passage in the corpus that contains the answer to a test question, recorded so that retrieval and generation can be judged separately.","retrieval/chapters/17-rag-failures.html","ret",0],["Gold set","A collection of real inputs from the customer's own work, each paired with the correct output as decided by people the customer trusts.","ai-delivery/chapters/06-evaluation-plans.html","aid",0],["Gold set","A set of items whose labels are trusted enough to measure systems or judges against.","evals/chapters/05-human-labels.html","evl",0],["Goodhart's law","The observation that when a measure becomes a target it ceases to be a good measure.","evals/chapters/07-contamination.html","evl",1],["Goodhart's law","The principle that when a measure becomes a target it ceases to be a good measure, because optimisation exploits the gap between the measure and what it stands for.","llm-training/chapters/13-reward-models.html","llm",1],["Goodhart's law","The tendency of a measure to stop reflecting its purpose once it is used as a target to optimise.","ml/chapters/02-framing-metrics.html","ml",1],["Goodhart's law","When a measure becomes a target, it stops being a good measure.","open-ended/chapters/15-evaluator-hacking.html","oe",1],["Goodhart's law (interestingness)","The risk that once a generator is optimised against a judge's scores, those scores stop reflecting what people actually find interesting.","open-ended/chapters/06-interestingness.html","oe",1],["Good law","A legal authority that has not been overruled, reversed or materially limited by later decisions, checked with a citator service.","ai-delivery/chapters/10-legal.html","aid",0],["Goodput","Useful work completed, such as requests answered before their client gave up, as opposed to raw throughput.","reliability/chapters/11-overload.html","ops",0],["Gossip (epidemic) protocol","Each node periodically shares what it knows with a few random peers; information reaches everyone in roughly log n rounds.","distributed/chapters/03-failure-detection.html","dist",0],["GPT","Generative Pre-trained Transformer: an autoregressive language model built from decoder-only Transformer blocks.","deep-learning/chapters/12-building-gpt.html","dl",1],["GPTQ","A post-training method that quantises weights one at a time and updates the remaining weights using second-order information to keep the layer's output close to the original.","llm-training/chapters/19-quantisation.html","llm",0],["GPU","A processor with thousands of simple cores and very high memory bandwidth, built for data-parallel work.","systems/chapters/21-parallelism-gpus.html","sys",0],["GPU","A processor with thousands of simple arithmetic units and very wide memory access, fast at large, regular, parallel work such as matrix multiplication.","ml-foundations/chapters/17-compute-costs.html","mlf",0],["Graceful degradation","Continuing to serve a reduced but useful experience when parts of the system fail.","architecture/chapters/17-resilience.html","arch",0],["Graded relevance","Judgements with several levels, such as 0 to 3, so that perfect answers can be told apart from marginal ones.","retrieval/chapters/04-relevance-metrics.html","ret",0],["Gradient","The vector of partial derivatives of the loss with respect to each parameter, pointing in the direction of steepest increase.","ml-foundations/chapters/00-start-here.html","mlf",1],["Gradient accumulation","The behaviour that each backward pass adds to the existing .grad values rather than replacing them, so they must be cleared every step.","deep-learning/chapters/05-pytorch.html","dl",1],["Gradient accumulation","Summing gradients over several micro-batches before one optimiser step, giving the gradient of a large batch while holding only a small batch's activations.","llm-training/chapters/02-gpu-memory.html","llm",0],["Gradient boosting","Boosting in which each new tree is fitted to the negative gradient of the loss with respect to the current predictions.","ml/chapters/09-ensembles-boosting.html","ml",0],["Gradient check","A test that compares a hand-written gradient with a finite-difference estimate on a tiny network.","deep-learning/chapters/02-backpropagation.html","dl",1],["Gradient check","Testing an analytic gradient against finite differences, entry by entry, using relative error in float64.","ml-foundations/chapters/08-derivatives.html","mlf",1],["Gradient checkpointing","Saving activations at only a few layers and recomputing the rest during the backward pass, trading extra compute for memory.","ml-foundations/chapters/09-autodiff.html","mlf",1],["Gradient clipping","Rescaling the whole gradient to a maximum norm when it grows too large, limiting step size without changing direction.","deep-learning/chapters/08-sequences-rnns.html","dl",0],["Gradient clipping","Rescaling the whole gradient when its global norm exceeds a threshold, so a single bad batch cannot cause a huge step.","ml-foundations/chapters/10-optimisers.html","mlf",1],["Gradient descent","Minimising a loss by repeatedly stepping the parameters against the gradient.","ml/chapters/05-linear-models.html","ml",1],["Gradient descent","Training by repeatedly moving the parameters a small step against the gradient of the loss.","ml-foundations/chapters/00-start-here.html","mlf",1],["Gradient norm","The length of the gradient vector taken over all parameters, a leading indicator of instability when logged before clipping.","deep-learning/chapters/17-training-stability.html","dl",0],["Gradient variance","The spread of gradient estimates around their expected value from batch to batch; high variance makes updates noisy and training slow or unstable.","llm-training/chapters/07-policy-gradients.html","llm",1],["Graph database","A database of nodes and edges, built for questions that follow many relationships, like friends-of-friends.","data/chapters/01-data-models.html","data",0],["GraphRAG","A method that extracts an entity graph from documents, summarises communities of related entities, and answers global questions by combining those summaries.","retrieval/chapters/15-agentic-retrieval.html","ret",0],["Greedy algorithm","A procedure that makes the best choice at each step without looking ahead, as a tree does when choosing each split.","ml/chapters/08-decision-trees.html","ml",0],["Greedy decoding","Always choosing the single most probable next token, which is deterministic but tends to repeat itself in open-ended text.","deep-learning/chapters/15-decoding.html","dl",1],["Grounded answer","An answer whose claims are all supported by the sources that were supplied to the model for that request.","retrieval/chapters/16-grounded-citations.html","ret",0],["Grounded feedback","Feedback produced by something outside the model, such as test results, schema validators or retrieval checks, rather than by its self-assessment.","agents/chapters/03-reasoning-planning.html","agt",1],["Grounding","Mapping a description such as the Submit button to a precise target on the screen, in pixels or as a reference to an element.","agents/chapters/17-computer-use.html","agt",0],["Grounding","Tying a model's answer to supplied evidence, so it answers from the documents or tool results it was given rather than from memory.","evals/chapters/11-grounding-abstention.html","evl",0],["Group commit","Batching many writes into one fsync so the slow disk flush is shared, trading a little latency for much more throughput.","systems/chapters/09-durability.html","sys",0],["Grouped-query attention","Attention in which groups of query heads share one key/value head, a dial between multi-head and multi-query attention.","deep-learning/chapters/19-efficient-attention.html","dl",0],["Grouped-query attention (GQA)","Attention in which groups of query heads share a key-value head, an intermediate between multi-head and multi-query attention that cuts the cache by the group size.","llm-training/chapters/18-kv-cache.html","llm",0],["Group k-fold","A k-fold split that keeps all rows of one group, such as a patient or customer, in the same fold so no group appears on both sides.","ml/chapters/13-cross-validation.html","ml",1],["Group-relative advantage","An answer's reward minus the mean reward of its group, usually divided by the group's standard deviation, shared by every token of that answer.","llm-training/chapters/14-rlvr-grpo.html","llm",1],["Group sequential testing","Planned repeated looks at an experiment using stricter per-look boundaries so the overall false-positive rate stays at the stated level.","ml-foundations/chapters/15-statistics.html","mlf",1],["Group-wise quantisation","Using one scale for each run of 32 to 128 consecutive weights, which confines the damage of an outlier to its own group.","llm-training/chapters/19-quantisation.html","llm",0],["GRPO (Group Relative Policy Optimisation)","A PPO variant that drops the value model and computes each answer's advantage by comparing its reward with the other answers sampled for the same prompt.","llm-training/chapters/14-rlvr-grpo.html","llm",1],["GRU","A gated recurrent unit that merges the LSTM's cell and hidden state and uses two gates, with similar behaviour at lower cost.","deep-learning/chapters/08-sequences-rnns.html","dl",0],["Guardrail","A check on an agent's input or output, run by the framework, that can block or flag a request or reply.","agents/chapters/21-frameworks.html","agt",0],["Guardrail","A check outside the main model that inspects an input, retrieved text, an answer or an action and allows, blocks, rewrites or escalates it.","evals/chapters/15-guardrails.html","evl",0],["Guardrail metric","A second measure agreed alongside a target, such as review queue length beside recall, that catches the target being met in a harmful way.","ai-delivery/chapters/02-requirements-ambiguity.html","aid",0],["Guardrail metric","A metric that must not get worse in an experiment, such as latency or complaints, whatever the primary metric does.","ml/chapters/21-model-to-value.html","ml",0],["Guardrail recall","Of the inputs the policy says must be caught, the share the guardrail actually caught.","evals/chapters/15-guardrails.html","evl",0],["gVisor","A user-space application kernel that handles a program's system calls itself instead of passing them to the host kernel.","agents/chapters/20-sandboxing.html","agt",1],["Half-life of knowledge","How long a fact or skill stays true: model rankings and tool versions expire in months, while methods and habits last years.","ai-delivery/chapters/19-where-next.html","aid",0],["Hallucinated results","Experimental results, such as an ablation table, that a system reports although it never ran the experiments.","open-ended/chapters/14-automated-science.html","oe",1],["Hallucination","Fluent, plausible model output that is not supported by the facts of the world or by the material the model was given.","evals/chapters/10-hallucination.html","evl",0],["Hallucination snowballing","A model committing to an early mistake and then producing further errors to stay consistent with it.","evals/chapters/10-hallucination.html","evl",0],["Handoff","A one-way transfer in which one agent passes execution and the conversation state to another agent that takes over.","agents/chapters/14-multi-agent.html","agt",0],["Hand test","A cheap early check in which twenty or thirty real, permitted inputs are run through a capable model by hand and read with the customer's expert.","ai-delivery/chapters/04-feasibility.html","aid",0],["Hang","A failure in which no rank crashes but progress stops, typically because one rank never joins a collective operation.","llm-training/chapters/05-long-runs.html","llm",0],["Happens-before","Lamport's relation: event a happens before b if they're in order on one process, or a is a send and b its receive, or via a chain of these.","networking/chapters/17-time.html","net",0],["Hard attributes","Properties of a model choice that cannot be changed or traded away, such as the licence and where data may go, and so are used to filter candidates first.","ai-delivery/chapters/07-choosing-models.html","aid",0],["Hard gate","A scorecard item, such as bounded error cost or permission to use the data, where a red result means stop or redesign whatever the other scores are.","ai-delivery/chapters/04-feasibility.html","aid",0],["Hard negative","A passage that looks relevant to the query (high lexical or embedding score) but is not, used to teach fine distinctions.","retrieval/chapters/07-dense-retrieval.html","ret",1],["Hard regression","A test case that passed on every repeated run before a change and fails on most runs after it.","evals/chapters/18-improvement-flywheel.html","evl",0],["Harness","The program around the model that holds the history, runs tools, enforces limits and decides when the loop ends.","agents/chapters/02-tool-loop.html","agt",1],["Harness","The code around an evaluator that runs candidates, collects their outputs and applies the checks.","open-ended/chapters/15-evaluator-hacking.html","oe",1],["Hash chain","A log in which each record includes the hash of the previous one, so altering history becomes detectable.","open-ended/chapters/17-self-modification-safety.html","oe",1],["Hash index","An in-memory map from each key to where its latest value lives on disk, giving one-seek reads.","data/chapters/04-log-hash-index.html","data",0],["Hash join","Joining two tables by building a hash table on one and probing it with rows from the other.","data/chapters/08-query-execution.html","data",0],["HBM","High-bandwidth memory, the large main memory of a GPU, much bigger and slower than its on-chip SRAM.","deep-learning/chapters/19-efficient-attention.html","dl",0],["HBM","High-bandwidth memory: the large off-chip memory on a GPU (80 GB on an H100) where weights and activations live between operations.","llm-training/chapters/04-kernels.html","llm",0],["HBM (high-bandwidth memory)","The fast on-package memory of a data-centre GPU, whose fixed capacity (for example 80 GB) limits what can be trained on one device.","llm-training/chapters/02-gpu-memory.html","llm",0],["Header","Information a protocol adds in front of its payload, like the address on an envelope.","networking/chapters/03-layers.html","net",0],["Head-of-line blocking","When one lost or slow item holds up everything queued behind it.","networking/chapters/08-tcp.html","net",0],["Headroom","Spare capacity kept above expected peak load to absorb spikes and failures.","reliability/chapters/10-load-testing-capacity.html","ops",0],["Head sampling","Deciding whether to keep a trace when it starts, before anything is known about how it will turn out.","evals/chapters/17-observability.html","evl",0],["Head, torso and tail","The very frequent, middling and very rare parts of the distribution of queries in a log.","retrieval/chapters/03-query-understanding.html","ret",0],["Heap","The region of memory for data whose lifetime isn't tied to one function call. Objects are allocated here and freed later.","systems/chapters/03-stack-heap.html","sys",0],["Heartbeat","A periodic \"I'm alive\" message used to detect failed machines.","networking/chapters/16-failure.html","net",0],["Heavy hitters","The most frequent items in a stream, found approximately with algorithms such as Space-Saving.","design/chapters/12-top-k-trending.html","design",0],["Hedged request","Sending a second copy of a request if the first has not answered within a short delay, and using whichever replies first.","reliability/chapters/09-tail-latency.html","ops",0],["He initialisation","Drawing weights with variance 2 divided by fan-in, which compensates for ReLU discarding half the signal.","deep-learning/chapters/03-training-dynamics.html","dl",1],["Held-out set","Test cases kept out of prompts, examples and training data so they measure generalisation.","evals/chapters/02-eval-harnesses.html","evl",1],["Held-out set","Examples kept out of training so that performance on them estimates how the model handles new inputs.","llm-training/chapters/23-evaluating-models.html","llm",0],["Herd effect","Many clients waking up at once to react to one change, such as all waiters rushing for a released lock.","distributed/chapters/11-coordination-services.html","dist",0],["Hermetic build","A build whose output depends only on declared inputs, so it can be cached and reproduced anywhere.","architecture/chapters/21-engineering-practice.html","arch",0],["Hessian","The second derivative of the loss with respect to a prediction, used with the gradient to take a Newton-style step in XGBoost.","ml/chapters/09-ensembles-boosting.html","ml",0],["Hessian","The matrix of second partial derivatives, describing the curvature of a function in every direction.","ml-foundations/chapters/08-derivatives.html","mlf",1],["Hidden precondition","A requirement a stored skill silently relies on, such as an item already being in the inventory, which makes it fail in a different state.","open-ended/chapters/07-lifelong-agents.html","oe",1],["Hidden state","The fixed-size vector a recurrent network carries from step to step as a summary of everything read so far.","deep-learning/chapters/08-sequences-rnns.html","dl",0],["Hidden state","Variables held in a running notebook kernel that influence results but are not visible in the cells as written.","ml-foundations/chapters/04-reproducible-experiments.html","mlf",1],["High-impact AI","In US federal policy, AI whose output serves as a principal basis for decisions with legal, material, binding or significant effect on rights or safety, which attracts minimum risk-management practices.","ai-delivery/chapters/11-public-sector.html","aid",0],["High-risk AI system","Under the EU AI Act, a system in a product-safety area or a listed use such as employment or credit, which must meet requirements on risk management, data, documentation, logging, oversight and robustness.","evals/chapters/21-governance.html","evl",0],["High watermark","The offset up to which a partition's records are replicated to all in-sync replicas and visible to consumers.","distributed/chapters/17-logs-exactly-once.html","dist",0],["Hill climbing","Changing one candidate a little and keeping the change only if the score does not get worse.","open-ended/chapters/18-search-in-products.html","oe",1],["Hinted handoff","When a replica is down, another node temporarily keeps its writes and hands them over when it returns.","networking/cases/case-09-dynamo.html","net",0],["Histogram (metrics)","A metric that counts observations in buckets, so percentiles can be estimated and merged across hosts.","reliability/chapters/04-metrics.html","ops",0],["History","The record of operations clients invoked and the responses they received, with their timing, used to judge consistency.","distributed/chapters/05-consistency-models.html","dist",0],["Hit at k","The share of questions for which at least one of the top k returned chunks contains the answer.","retrieval/chapters/14-chunking.html","ret",0],["Hit rate","The share of queries for which at least one relevant document appears in the top k, also called success at k.","retrieval/chapters/04-relevance-metrics.html","ret",0],["HNSW","Hierarchical Navigable Small World graph: a layered proximity graph searched greedily from sparse upper layers down to a dense bottom layer.","retrieval/chapters/11-ann-indexes.html","ret",1],["Hole@k","The share of a system's top-k results that have no relevance judgement, a measure of how fairly the pool covers that system.","retrieval/chapters/05-test-collections.html","ret",0],["Hole punching","Getting two devices behind NAT to talk directly by having both send first, so each NAT expects the other's packets.","networking/cases/case-04-nat-traversal.html","net",0],["Holt-Winters","Exponential smoothing with a level, a trend and a seasonal profile, each updated by its own weight.","ml/chapters/18-time-series.html","ml",0],["Home region","The region that owns writes for a given user or partition in a multi-region system, keeping writes local for most users.","distributed/chapters/18-multi-region.html","dist",0],["Honeytoken","A fake credential or record that no legitimate process should touch, so any use signals an intruder.","security/chapters/18-detection-response.html","sec",0],["Hook","A script that a coding tool runs automatically at a defined point, such as after an edit or before stopping, so an action happens every time regardless of what the model decides.","agents/chapters/22-ai-coding-tools.html","agt",0],["Horizon","How far ahead a forecast looks, for example 14 days.","ml/chapters/18-time-series.html","ml",0],["Hot spot","A shard or key that receives far more traffic than the others.","data/chapters/16-sharding.html","data",0],["HSM","Hardware security module: tamper-resistant hardware that holds keys and performs operations inside it.","security/chapters/04-keys-secrets-pki.html","sec",0],["HTTP","HyperText Transfer Protocol: the request/response protocol of the web.","networking/chapters/10-http.html","net",0],["HTTPS","HTTP carried inside a TLS-encrypted connection.","networking/chapters/11-tls.html","net",0],["Huber loss","A loss that is quadratic for small residuals and linear for large ones, limiting the pull of outliers.","ml-foundations/chapters/13-likelihood-losses.html","mlf",1],["Huffman coding","An optimal prefix code that gives short codewords to likely symbols, with average length within one bit of the entropy.","ml-foundations/chapters/14-information-theory.html","mlf",1],["Human ceiling","The score domain experts achieve on a benchmark under the same conditions, which shows how much headroom exists.","evals/chapters/06-building-benchmarks.html","evl",1],["Human gate","A point in the loop where a person must approve a change or promotion before it proceeds.","open-ended/chapters/17-self-modification-safety.html","oe",1],["Human in the loop","A design in which a person reviews or approves a system's output, which gives accountability only if the reviewer has the time, information and authority to disagree.","ai-delivery/chapters/11-public-sector.html","aid",0],["Human-in-the-loop review","A design in which a person checks model outputs before they take effect, turning costly leaked errors into cheaper corrections.","ai-delivery/chapters/04-feasibility.html","aid",0],["Human oversight","Design measures that let people understand an AI system's outputs, notice over-reliance, override results and stop the system.","evals/chapters/21-governance.html","evl",0],["Hybrid logical clock (HLC)","A timestamp combining physical time with a logical counter, so it stays close to wall-clock time while respecting causality.","distributed/chapters/07-time-revisited.html","dist",0],["Hybrid model","A model that mixes mostly recurrent or state-space layers with a few attention layers, to keep exact lookup at a smaller cache.","deep-learning/chapters/22-beyond-attention.html","dl",0],["Hybrid search","Running a lexical retriever and a dense retriever on the same query and merging their results into one ranked list.","retrieval/chapters/10-hybrid-search.html","ret",0],["HyDE","Hypothetical document embeddings: embedding a model-written draft answer instead of the question, to find real documents that resemble it.","retrieval/chapters/15-agentic-retrieval.html","ret",0],["HyperLogLog","A tiny probabilistic structure that estimates the number of distinct items with a standard error of about 1.04/√m.","design/chapters/12-top-k-trending.html","design",0],["Hypernetwork","A network whose output is the weights of another network.","llm-training/chapters/17-adapters-on-demand.html","llm",0],["Hyperparameter","A setting chosen by the practitioner rather than learned from data, such as polynomial degree or learning rate.","ml/chapters/01-generalisation.html","ml",1],["Hypervisor","Software that runs virtual machines, giving each its own virtual hardware and its own kernel.","systems/chapters/19-containers-vms.html","sys",0],["Hyrum's law","With enough users, every observable behaviour of your API will be depended on by somebody.","architecture/chapters/10-evolving-contracts.html","arch",0],["ICE curve","An individual conditional expectation curve: the prediction for one case as a single feature varies while its other features stay fixed.","ml/chapters/16-interpretability.html","ml",0],["ICMP","Internet Control Message Protocol: error and diagnostic messages such as ping and \"time exceeded\".","networking/chapters/06-arp-dhcp-icmp.html","net",0],["Idempotency key","A unique ID sent with a request so the server can recognise a retry and avoid doing the work twice.","networking/labs/lab-05-kv-store.html","net",0],["Idempotency key","A unique value sent with a side-effecting request so that a repeat of the same request returns the first result instead of acting twice.","agents/chapters/02-tool-loop.html","agt",1],["Idempotency key","A unique identifier for an intended action, stored by the receiver so that a repeated request is recognised and not carried out twice.","ai-delivery/chapters/12-poc-to-production.html","aid",0],["Idempotent","An operation that has the same effect whether you do it once or many times, which makes retrying safe.","networking/chapters/16-failure.html","net",0],["Idempotent producer","A Kafka producer that tags messages with a producer id and sequence number so the broker can drop duplicates from retries.","distributed/chapters/17-logs-exactly-once.html","dist",0],["Identity matrix","The matrix with ones on its diagonal and zeros elsewhere, which leaves every vector unchanged.","ml-foundations/chapters/06-matrices.html","mlf",1],["IDOR","Insecure direct object reference: accessing another user's object by changing an id because the server never checks ownership.","security/chapters/08-authorization.html","sec",0],["ID token","A signed token from an OpenID provider stating who the user is, for the client; not for calling APIs.","security/chapters/07-oauth-oidc.html","sec",0],["i.i.d.","Independent and identically distributed: each example is drawn separately from the same distribution, an assumption behind most validation methods.","ml/chapters/01-generalisation.html","ml",1],["Illumination","Using search to show how performance varies across behaviour space, rather than only finding the single best point.","open-ended/chapters/04-quality-diversity.html","oe",1],["Image encoder","The network, usually a Vision Transformer, that turns patches into feature vectors carrying what is in each region.","deep-learning/chapters/21-vision-language.html","dl",0],["Image patch","A small square of a page image that the vision model encodes into one vector.","retrieval/chapters/21-visual-retrieval.html","ret",0],["Image tokens","The projected vectors that stand for an image in the language model's context, N = (size / patch) squared before any merging.","deep-learning/chapters/21-vision-language.html","dl",0],["Imbalanced data","A dataset in which one class, usually the one of interest, is much rarer than the other.","ml/chapters/15-imbalance-calibration.html","ml",0],["Implicit decision","A choice such as a style, format or name that an agent makes while acting and that parallel agents cannot see, causing conflicts when merged.","agents/chapters/14-multi-agent.html","agt",0],["Implicit reward","In DPO, the quantity beta times the log of the policy's probability over the reference's probability for a response, which plays the role of the reward.","llm-training/chapters/12-preference-optimisation.html","llm",1],["Importance sampling","Rewriting an expectation under one distribution as an expectation under another by weighting each sample by the ratio of their probabilities.","llm-training/chapters/08-ppo.html","llm",1],["Importance sampling","Estimating an expectation under one distribution using samples from another, each re-weighted by the ratio of the two densities.","ml-foundations/chapters/12-probability.html","mlf",1],["Import gate","The controlled crossing through which code, dependencies and model weights enter an isolated zone after hash checks, scanning and human review.","ai-delivery/chapters/13-restricted-environments.html","aid",0],["Improvement flywheel","A loop in which production failures are captured, labelled and turned into permanent tests, so each turn leaves the system better protected.","evals/chapters/18-improvement-flywheel.html","evl",0],["Impurity","A measure of how mixed the classes (or how spread the targets) are in a node, zero for a pure node.","ml/chapters/08-decision-trees.html","ml",0],["Impurity decrease","The parent node's impurity minus the size-weighted impurity of its children, used to score a candidate split.","ml/chapters/08-decision-trees.html","ml",0],["In-batch negatives","Using the positive passages of the other queries in a training batch as negatives, giving B squared comparisons from B pairs.","retrieval/chapters/07-dense-retrieval.html","ret",1],["Incarnation number","A counter a node increments to refute a suspicion about itself, so newer news about a node overrides older news.","distributed/chapters/03-failure-detection.html","dist",0],["Incident commander","The person who coordinates an incident response, delegates work and makes decisions, rather than debugging directly.","reliability/chapters/16-incident-response.html","ops",0],["In-context learning","Making predictions from labelled examples supplied in the model's input, with no change to its weights.","ml/chapters/19-tabular-deep-learning.html","ml",0],["Independent origins","The distinct underlying sources behind a set of documents, counting a news story that quotes a report as the report rather than as a second witness.","agents/chapters/16-deep-research.html","agt",0],["Independent verification","Checking code with tests or sources that its author did not write, such as hand values, properties, edge cases or a numerical gradient.","ml-foundations/chapters/19-ai-assistants.html","mlf",0],["Indirect prompt injection","Prompt injection in which a third party plants instructions in content an agent later reads, so the attacker never talks to the system directly.","agents/chapters/19-agent-security.html","agt",1],["Indirect prompt injection","An injection planted by a third party in content, such as a web page, email or document, that the application later feeds to the model.","evals/chapters/13-prompt-injection.html","evl",0],["Indirect prompt injection","An attack in which instructions hidden in retrieved or fetched content are obeyed by the model as if they came from the user or developer.","retrieval/chapters/13-rag-end-to-end.html","ret",0],["In-doubt transaction","A participant that voted yes and has not yet learned the decision; it must hold its locks until it does.","distributed/chapters/13-atomic-commit.html","dist",0],["Induction head","A pair of attention heads that, having seen the pattern A B earlier in the context, predict B when A appears again.","deep-learning/chapters/09-attention.html","dl",1],["Inductive bias","An assumption built into a model's structure, such as locality in a convolution, that helps it learn from less data but limits what it can easily represent.","deep-learning/chapters/07-convolutions.html","dl",0],["Inductive bias","The assumptions built into a learning algorithm that let it prefer some functions over others when the data alone cannot decide.","ml/chapters/01-generalisation.html","ml",1],["Inertia","The total squared distance from each point to the centre of its cluster, which k-means minimises.","ml/chapters/10-clustering.html","ml",0],["Inference (serving)","Running a trained model to produce answers for users, as opposed to training it.","llm-training/chapters/00-start-here.html","llm",0],["Inference-time search","Spending extra computation on one question at answer time, by sampling, checking and building on candidates, without changing the model's weights.","open-ended/chapters/08-inference-time-search.html","oe",1],["InfoNCE","A softmax contrastive loss that asks the model to pick the true positive out of one positive and many negatives.","retrieval/chapters/07-dense-retrieval.html","ret",1],["In-force filter","A retrieval rule that keeps only chunks that have started, have not been superseded and are not drafts on the date being asked about.","retrieval/chapters/17-rag-failures.html","ret",0],["Information hiding","Keeping design decisions inside a module so other modules don't depend on them (Parnas, 1972).","architecture/chapters/02-modules-coupling.html","arch",0],["Information need","What the user actually wants to know or do, written down beside the query string so judges resolve ambiguity the same way.","retrieval/chapters/05-test-collections.html","ret",0],["Infrastructure as code","Describing infrastructure in versioned, reviewed files that a tool applies, instead of changing it by hand.","reliability/chapters/13-config-iac.html","ops",0],["Ingestion","The offline path that parses, chunks, embeds and indexes documents so that they can be searched.","retrieval/chapters/13-rag-end-to-end.html","ret",0],["Injected prompt text","Instructions a framework adds to the system prompt or tool descriptions on its own, which cost tokens and shape behaviour without appearing in your source.","agents/chapters/21-frameworks.html","agt",0],["Inner join","A join that keeps only the rows whose key matches in both tables.","ml-foundations/chapters/03-data-wrangling.html","mlf",0],["Inode","The file system's record for a file: its size, permissions and where its data lives. Names in directories point to inodes.","systems/chapters/08-files.html","sys",0],["Input and output tokens","The tokens you send to a model and the tokens it writes, which providers price at different rates.","evals/chapters/19-cost-latency-quality.html","evl",0],["Input check","A guardrail that inspects the user's message before the model sees it.","evals/chapters/15-guardrails.html","evl",0],["Instance metadata service","A link-local endpoint in cloud VMs that serves configuration and temporary credentials; a prime SSRF target.","security/chapters/11-ssrf-server-side.html","sec",0],["Instruction","One tiny operation a CPU can do, like add two numbers or load a value from memory. Programs are long lists of them.","systems/chapters/01-cpu.html","sys",0],["Instruction drift","The loss of weight of early rules against recent context in a long run, so the model gradually stops following them.","agents/chapters/04-prompting.html","agt",1],["Instruction file","A Markdown file in a repository, such as CLAUDE.md or AGENTS.md, that tells a coding agent how to build, test and follow local conventions.","agents/chapters/18-coding-agents.html","agt",1],["Instruction hierarchy","Training a model to prioritise system instructions over user text and user text over tool output.","agents/chapters/19-agent-security.html","agt",1],["Instruction hierarchy","A training approach that teaches a model to give developer instructions priority over user text and third-party content when they conflict.","evals/chapters/13-prompt-injection.html","evl",0],["In-sync replicas (ISR)","In Kafka, the set of replicas caught up with the leader; a write with acks=all waits for all of them.","distributed/chapters/17-logs-exactly-once.html","dist",0],["Intelligent Go-Explore","A hard-exploration method that uses a foundation model to judge which states are interesting enough to archive and return to.","open-ended/chapters/06-interestingness.html","oe",1],["Interaction feature","A column combining two or more inputs, such as a product, ratio or difference, so a model can use a relationship it could not see from either alone.","ml/chapters/17-feature-engineering.html","ml",0],["Inter-agent misalignment","A category of multi-agent failure in which agents fail to communicate, share or act on what another agent produced.","agents/chapters/14-multi-agent.html","agt",0],["Inter-annotator agreement","How often independent annotators give the same label to the same items, used to judge whether a guideline is reproducible.","evals/chapters/05-human-labels.html","evl",0],["Interleaved thinking","Reasoning by the model between tool calls within one turn, so it can read each tool result before deciding the next action.","agents/chapters/03-reasoning-planning.html","agt",1],["Internal node","A node of a tree that asks a question about one feature and sends the example to one of two children.","ml/chapters/08-decision-trees.html","ml",0],["Interpolation threshold","The model size at which a model can just barely fit its training data exactly, where test error often peaks.","deep-learning/chapters/04-deep-regularisation.html","dl",1],["Interpretable by design","A model simple enough to be read directly, such as a sparse linear model, a shallow tree or a rule list.","ml/chapters/16-interpretability.html","ml",0],["Interrupt","A signal from hardware (or a timer) that makes the CPU pause what it's doing and run kernel code to handle an event.","systems/chapters/04-kernel-syscalls.html","sys",0],["Inter-token latency (ITL)","The time between successive generated tokens, set by the cost of one decode step.","llm-training/chapters/18-kv-cache.html","llm",0],["Intrinsic dimension","The smallest number of free parameters in which a fine-tuning task can still be solved well, found to be far below a model's parameter count.","llm-training/chapters/11-lora.html","llm",1],["Invariant","A property that must hold in every reachable state, such as \"at most one leader per term\".","distributed/chapters/20-formal-methods.html","dist",0],["Invariant confluence","Whether merging two valid states always gives a valid state. If so, the invariant can be kept without coordination (Bailis et al., 2015).","distributed/chapters/16-coordination-avoidance.html","dist",0],["Inverse","The matrix that undoes another, A^-1 A = I, which exists only when the determinant is non-zero.","ml-foundations/chapters/06-matrices.html","mlf",1],["Inverse-CDF sampling","Drawing from any distribution by feeding a uniform random number through the inverse of its cumulative distribution function.","ml-foundations/chapters/12-probability.html","mlf",1],["Inverse document frequency","A weight that gives rarer terms more influence than common ones, because a match on a rare term is stronger evidence.","retrieval/chapters/02-bm25.html","ret",0],["Inverted dropout","Dropout in which the surviving units are scaled by 1/(1 - p) during training, so that no change is needed at evaluation time.","deep-learning/chapters/04-deep-regularisation.html","dl",1],["Inverted index","A map from each word to the documents that contain it: the core of full-text search.","data/chapters/17-specialised-stores.html","data",0],["Inverted index","A map from each term to the documents containing it, with frequencies and optionally positions.","retrieval/chapters/02-bm25.html","ret",0],["Inverted pyramid","A document structure that puts the answer and decision first, the evidence next and the checking detail last, so readers can stop at any layer.","ml-foundations/chapters/18-technical-writing.html","mlf",0],["Invisible text layer","Text positioned over a page image with render mode 3 so that it can be searched and copied but is not painted, usually the output of an earlier OCR run.","retrieval/chapters/18-pdf-layout.html","ret",0],["IP address","A number identifying a device's network interface on an IP network (32 bits in IPv4, 128 in IPv6).","networking/chapters/04-ip-addresses.html","net",0],["IPO (Identity Preference Optimisation)","A DPO variant that uses a squared loss on the log-ratio margin, so the regulariser keeps working even when preference labels are deterministic.","llm-training/chapters/12-preference-optimisation.html","llm",1],["IPv6","The newer version of IP with 128-bit addresses, written in hexadecimal.","networking/chapters/04-ip-addresses.html","net",0],["Irreducible error","The part of the error caused by noise in the labels that no model could predict, setting a floor on achievable error.","ml/chapters/01-generalisation.html","ml",1],["Irreducible loss","The part of the loss that no model size or data amount can remove, set by the entropy of the data itself.","deep-learning/chapters/18-scaling-laws.html","dl",0],["isError","The flag on a tools/call result that marks a tool execution failure the model can read and correct, as opposed to a protocol error.","agents/chapters/07-mcp.html","agt",0],["Island model","A population split into sub-populations that evolve separately, so no single family of solutions can take over the whole search.","open-ended/chapters/09-program-evolution.html","oe",1],["IsoFLOP curve","The loss of models of different sizes that all use the same training compute, with a minimum at the compute-optimal size.","deep-learning/chapters/18-scaling-laws.html","dl",0],["Isolation forest","An ensemble of random trees that scores a row by how few random cuts are needed to isolate it, so anomalies get short paths.","ml/chapters/12-anomaly-detection.html","ml",0],["Isolation level","How strongly concurrent transactions are kept from seeing each other's effects, from read committed to serializable.","data/chapters/11-isolation.html","data",0],["Isotonic regression","Fitting the best non-decreasing step function to data, used to recalibrate scores without assuming a sigmoid shape.","ml/chapters/15-imbalance-calibration.html","ml",0],["ISP","Internet Service Provider: the company that connects you to the Internet.","networking/chapters/00-start-here.html","net",0],["Item (benchmark)","One case in a benchmark: an input, any context it needs, and the information required to score a response.","evals/chapters/06-building-benchmarks.html","evl",1],["Item response theory","A statistical framework that models the chance of solving an item from the system's ability and the item's difficulty.","evals/chapters/06-building-benchmarks.html","evl",1],["Iteration budget","A cap on the number of model calls an agent may make for one task, bounding cost and time.","agents/chapters/02-tool-loop.html","agt",1],["Iteration-level scheduling","Making the choice of which requests run at every single decode iteration rather than once per request, as introduced by Orca.","llm-training/chapters/20-serving-engines.html","llm",0],["Iterative index scan","A search that keeps widening its candidate list until enough rows pass the filter or a work limit is reached.","retrieval/chapters/12-filters-permissions.html","ret",0],["Iterative prompting","Repeatedly asking a model to rewrite its code using feedback from the environment, interpreter errors and a critic until the task succeeds or attempts run out.","open-ended/chapters/07-lifelong-agents.html","oe",1],["IVF (inverted file index)","A vector index that clusters vectors with k-means and, at query time, scans only the few cells whose centroids are nearest the query.","retrieval/chapters/11-ann-indexes.html","ret",1],["Jaccard similarity","The size of the overlap of two sets divided by the size of their union, used to measure how alike two documents' shingle sets are.","llm-training/chapters/01-pretraining-data.html","llm",0],["Jacobian","The matrix of all partial derivatives of a function's outputs with respect to its inputs.","deep-learning/chapters/02-backpropagation.html","dl",1],["Jacobian","The (m, n) matrix of partial derivatives of an m-vector function of an n-vector, the best linear approximation of the function near a point.","ml-foundations/chapters/08-derivatives.html","mlf",1],["Jailbreak","An input that gets a model to ignore its own safety training and produce content that its provider or developer prohibits.","evals/chapters/13-prompt-injection.html","evl",0],["Jepsen","Kyle Kingsbury's framework and analyses that run real databases under faults and check the recorded histories against consistency models.","distributed/chapters/19-testing.html","dist",0],["JIT compiler","Just-in-time compiler: turns frequently run code into real machine code while the program runs, as the JVM and JavaScript engines do.","systems/chapters/01-cpu.html","sys",0],["Jitter (retries)","Adding randomness to retry delays so clients don't all retry at the same instant.","networking/chapters/16-failure.html","net",0],["Join","Combining rows from two tables that match on some condition, such as orders with the users who placed them.","data/chapters/02-sql-relational.html","data",0],["Join semilattice","A set with a merge operation that is associative, commutative and idempotent: the maths that guarantees CRDT convergence.","distributed/chapters/15-crdts.html","dist",0],["Joint consensus","Raft's way of changing cluster membership by requiring majorities of both the old and new configurations during the transition.","distributed/chapters/10-raft-deep.html","dist",0],["JSON-RPC 2.0","A small standard for remote procedure calls in JSON, made of requests with ids, responses holding a result or an error, and one-way notifications.","agents/chapters/07-mcp.html","agt",0],["JSON Schema","A standard vocabulary for describing the shape of a JSON document, used to specify the arguments of each tool.","agents/chapters/02-tool-loop.html","agt",1],["Just-in-time retrieval","Keeping lightweight references such as paths and queries and loading the data with tools only when a step needs it, instead of loading it up front.","agents/chapters/10-context-engineering.html","agt",1],["JWT","JSON Web Token: a signed (or encrypted) JSON payload used as a self-contained bearer token (RFC 7519).","security/chapters/06-sessions-tokens.html","sec",0],["k1 and b","The two BM25 parameters: k1 sets how fast term-frequency saturates and b sets how strongly length is normalised.","retrieval/chapters/02-bm25.html","ret",0],["k3 estimator","The sample estimate (r - 1) - ln r of KL, with r the ratio of reference to policy probability, which is unbiased, non-negative and low in variance.","ml-foundations/chapters/14-information-theory.html","mlf",1],["Kernel","The core of the operating system: the one program that controls the hardware directly and referees all the others.","systems/chapters/04-kernel-syscalls.html","sys",0],["Kernel","A function that runs on the GPU across many threads, launched from the CPU.","llm-training/chapters/04-kernels.html","llm",0],["Kernel function","A function K(x, z) that returns the inner product of two points in a richer feature space without constructing that space.","ml/chapters/07-neighbours-bayes.html","ml",1],["Kernel ridge regression","Ridge regression performed in a kernel-defined feature space, with one weight per training point.","ml/chapters/07-neighbours-bayes.html","ml",1],["Kernel trick","Rewriting an algorithm so data enters only through kernel evaluations, letting a linear method draw curved boundaries.","ml/chapters/07-neighbours-bayes.html","ml",1],["Key (attention)","The vector attached to each position that is compared with queries to decide how much that position is read.","deep-learning/chapters/09-attention.html","dl",1],["Key rotation","Replacing keys on a schedule or after exposure, while keeping old versions available to decrypt existing data.","security/chapters/04-keys-secrets-pki.html","sec",0],["Key (table)","A column or set of columns that identifies each row of a table uniquely.","ml-foundations/chapters/03-data-wrangling.html","mlf",0],["Key-value extraction","Finding a form's labels and their values and returning them as named fields.","retrieval/chapters/20-tables-forms.html","ret",0],["k-fold cross-validation","Splitting the rows into k folds, training on k minus 1 of them and scoring on the held-out one in turn, then averaging the k scores.","ml/chapters/13-cross-validation.html","ml",1],["Kill criteria","Conditions agreed in advance under which a project is stopped, such as a cost per task above a stated figure or a serious error in a regulated process.","ai-delivery/chapters/02-requirements-ambiguity.html","aid",0],["Kill switch","The most drastic containment lever, which turns an AI feature off and hands the work to people.","evals/chapters/20-ai-incidents.html","evl",0],["Kingman's formula","An approximation showing queueing delay grows with both utilization and the variability of arrivals and service times.","reliability/chapters/08-queueing-theory.html","ops",0],["KL divergence","The extra bits paid per symbol for using q instead of the true p, KL(p || q) = H(p, q) - H(p); non-negative, asymmetric and not a distance.","ml-foundations/chapters/14-information-theory.html","mlf",1],["KL estimators (k1, k2, k3)","Three single-sample estimators of KL divergence: k1 is unbiased but noisy and can be negative, k2 is biased, and k3 is unbiased and never negative.","llm-training/chapters/08-ppo.html","llm",1],["KL penalty","A cost proportional to the KL divergence between the tuned policy and the reference, applied per token in RLHF to keep the model close to where the reward model is reliable.","llm-training/chapters/08-ppo.html","llm",1],["KL penalty","A term beta times KL(policy || reference) subtracted from the reward in RLHF-style training to keep the tuned model near its starting point.","ml-foundations/chapters/14-information-theory.html","mlf",1],["k-means","A clustering method that divides rows into k groups by alternately assigning points to the nearest centre and moving each centre to its group's mean.","ml/chapters/10-clustering.html","ml",0],["k-means++","A seeding rule that picks each new starting centre with probability proportional to its squared distance from the existing centres.","ml/chapters/10-clustering.html","ml",0],["KMS","Key management service: a system, often backed by HSMs, that stores master keys and performs cryptographic operations without releasing them.","security/chapters/04-keys-secrets-pki.html","sec",0],["k-nearest neighbours","A classifier or regressor that predicts from the k training points closest to the query, by vote or average.","ml/chapters/07-neighbours-bayes.html","ml",1],["Knowledge graph","A store of facts as nodes (entities) joined by labelled edges (relations), so chains of facts can be followed directly.","retrieval/chapters/15-agentic-retrieval.html","ret",0],["Kolmogorov-Smirnov statistic","The largest gap between the empirical cumulative distributions of two samples, used to score how much a feature has shifted.","ml/chapters/03-eda.html","ml",0],["Krippendorff's alpha","An agreement measure that works for any number of annotators, missing labels and ordered scales.","evals/chapters/05-human-labels.html","evl",0],["KTO (Kahneman-Tversky Optimisation)","A preference method that maximises a prospect-theory utility from single responses labelled desirable or undesirable, so it needs no pairs.","llm-training/chapters/12-preference-optimisation.html","llm",1],["KV bytes per token","The cache cost of one token: 2 times layers times key-value heads times head width times bytes per number.","llm-training/chapters/18-kv-cache.html","llm",0],["KV cache","Saved attention keys and values from earlier tokens that let an LLM generate each new token without recomputing the prompt.","design/chapters/20-ml-systems.html","design",0],["KV cache","The stored keys and values of earlier tokens that attention reads when generating the next token, costing 2 times layers times key/value heads times head width times bytes per token.","deep-learning/chapters/16-resource-accounting.html","dl",1],["KV cache","The stored keys and values of all earlier tokens at every layer, kept so that each new token's attention does not recompute them.","llm-training/chapters/18-kv-cache.html","llm",0],["L2 regularisation","Adding a penalty proportional to the squared size of the weights to the loss, which pulls every weight towards zero.","deep-learning/chapters/04-deep-regularisation.html","dl",1],["Label","A person's recorded judgement about one item against a stated criterion, such as pass or fail.","evals/chapters/05-human-labels.html","evl",0],["Label","The answer attached to a training example that the model is meant to predict; also called the target.","ml/chapters/00-start-here.html","ml",0],["Label lag","The delay before a case's true outcome is known, which makes recent rows look better than they are because their outcomes are incomplete.","ml/chapters/03-eda.html","ml",0],["Labelling guideline","The versioned document that defines each label, with decision rules and worked examples, so that different annotators reach the same answer.","evals/chapters/05-human-labels.html","evl",0],["Labelling procedure","Written instructions, with examples, for who labels a gold set, whether labellers work independently and how disagreements are settled.","ai-delivery/chapters/06-evaluation-plans.html","aid",0],["Label noise ceiling","The highest score a perfect system can reach on a test set because some of its gold labels are wrong.","evals/chapters/05-human-labels.html","evl",0],["Label-noise ceiling","The highest honest score on a benchmark given that some of its gold answers are wrong.","evals/chapters/07-contamination.html","evl",1],["Ladder","A leaderboard mechanism that reports a new score only when a submission improves on the best by more than a step.","open-ended/chapters/16-held-out-evaluation.html","oe",1],["Ladder of alternatives","The ordered options from changing the process through rules, search, classical ML and prompted models to agents, from which you pick the lowest rung that meets the bar.","ai-delivery/chapters/04-feasibility.html","aid",0],["Lag feature","The value of the series, or of a rolling statistic, from a fixed number of steps before the forecast origin, used as a model input.","ml/chapters/18-time-series.html","ml",0],["Lakehouse","Data-lake storage on object stores combined with warehouse features such as ACID tables and schema enforcement.","data/chapters/21-data-platforms.html","data",0],["Lamport clock","A counter-based logical clock: if a happens before b, a's timestamp is smaller.","networking/chapters/17-time.html","net",0],["LAN","Local Area Network: devices connected in one place, like a home or office.","networking/chapters/02-local-networks.html","net",0],["Language bias","The tendency of a multilingual retriever to rank documents in the query's own language above equally relevant documents in other languages.","retrieval/chapters/22-multilingual.html","ret",0],["Language identification","Classifying which language a piece of text is written in, unreliable on very short strings and on closely related languages.","retrieval/chapters/22-multilingual.html","ret",0],["Language model","A program that, given text, produces more text one token at a time; on its own it can only write.","agents/chapters/00-start-here.html","agt",0],["Language model","A model that assigns a probability to what comes next in a sequence of text, given what came before.","deep-learning/chapters/00-start-here.html","dl",0],["Laplace smoothing","Adding a pseudo-count to every feature count so that no feature-class combination has probability zero.","ml/chapters/07-neighbours-bayes.html","ml",1],["Lasso","Least squares with a penalty on the sum of absolute weights (L1), which drives many weights exactly to zero.","ml/chapters/06-regularisation.html","ml",1],["Late chunking","Encoding a whole document with a long-context embedder first and pooling token embeddings into chunk vectors afterwards, so each chunk vector sees its surroundings.","retrieval/chapters/14-chunking.html","ret",0],["Late interaction","A retrieval design that encodes query and passage separately into one vector per token and lets them interact only in a cheap final scoring step.","retrieval/chapters/09-late-interaction-sparse.html","ret",0],["Latency","How long it takes for data to get from one place to another. The length of the pipe.","networking/chapters/01-bits-and-signals.html","net",0],["Latency target (inter-token)","The maximum acceptable time between streamed tokens, which caps the batch size a GPU can run.","llm-training/chapters/22-token-economics.html","llm",0],["Law of large numbers","The average of many independent draws converges to the expectation of the distribution they come from.","ml-foundations/chapters/12-probability.html","mlf",1],["Layer","One adjustable step of a network that turns one description of an example into a new one.","deep-learning/chapters/00-start-here.html","dl",0],["Layered architecture","Organising code into layers such as presentation, business logic and data access, each using only the one below.","architecture/chapters/05-hexagonal.html","arch",0],["Layer normalisation","Rescaling each token's feature vector to zero mean and unit variance, then applying a learned scale and shift.","deep-learning/chapters/03-training-dynamics.html","dl",1],["Layout analysis","Turning a page into typed blocks such as titles, paragraphs, tables, figures, captions, headers and footers.","retrieval/chapters/18-pdf-layout.html","ret",0],["Lazy learner","A method that does no work at training time beyond storing the data, and does all its computation at prediction time.","ml/chapters/07-neighbours-bayes.html","ml",1],["Lead agent","The orchestrating agent in a manager design that plans the work, writes briefs, delegates to sub-agents and synthesises their results.","agents/chapters/14-multi-agent.html","agt",0],["Leader (primary)","The replica that accepts writes and sends them to followers.","networking/chapters/18-replication.html","net",0],["Leaf","A node of a tree with no further questions, holding the prediction for the examples that reach it.","ml/chapters/08-decision-trees.html","ml",0],["Leakage","Information about the target that reaches the model in training or validation but will not legitimately be available when the model is used.","ml/chapters/14-leakage.html","ml",1],["Leaky abstraction","An abstraction whose hidden details still affect its users, such as network latency behind a remote call.","architecture/chapters/03-abstractions.html","arch",0],["Leap-of-faith assumption","An assumption that, if false, makes the whole plan pointless however well the rest is built; Eric Ries's term in The Lean Startup.","ai-delivery/chapters/05-riskiest-assumption.html","aid",0],["Learnability","The property that an observer who studies more of a process's history can predict its later outputs better.","open-ended/chapters/05-open-ended-algorithms.html","oe",1],["Learnable task","A task the agent can currently improve on, neither impossible for it nor already mastered.","open-ended/chapters/06-interestingness.html","oe",1],["Learned absolute position embedding","A trained table with one vector per position, added to the token embedding, which caps the context at the table's length.","deep-learning/chapters/11-positions.html","dl",1],["Learned sparse retrieval","Retrieval where a neural network produces a sparse vector of weights over vocabulary words, scored through an ordinary inverted index.","retrieval/chapters/09-late-interaction-sparse.html","ret",0],["Learning curve","A plot of training and validation error against training-set size, used to tell high bias from high variance.","ml/chapters/06-regularisation.html","ml",1],["Learning log","A short running record of what you read, with the claim, the evidence and whether you would test it, used to judge which sources are worth keeping.","ai-delivery/chapters/19-where-next.html","aid",0],["Learning progress","How quickly an agent's success rate on a task is changing, used to find tasks that are learnable right now.","open-ended/chapters/06-interestingness.html","oe",1],["Learning rate","The step size multiplying the gradient in each gradient descent update.","ml/chapters/05-linear-models.html","ml",1],["Learning rate","The size of the step taken along the negative gradient at each update.","ml-foundations/chapters/00-start-here.html","mlf",1],["Learning-rate schedule","A rule that changes the learning rate over a run, usually a warmup followed by a decay.","ml-foundations/chapters/10-optimisers.html","mlf",1],["Learning rate (shrinkage)","The factor by which each new tree is scaled before being added to a boosted model, trading more rounds for better generalisation.","ml/chapters/09-ensembles-boosting.html","ml",0],["Learning-rate warmup","Raising the learning rate gradually from near zero over the first steps, while the optimiser's running statistics are still unreliable.","deep-learning/chapters/12-building-gpt.html","dl",1],["Lease","A lock with an expiry time. The holder may act only until the lease expires, so a crashed holder cannot block others forever.","distributed/chapters/04-leases-fencing.html","dist",0],["Least privilege","Giving each user, process or service only the permissions it needs, and no more.","security/chapters/02-principles.html","sec",0],["Least privilege","Giving a component only the access its task requires, for an agent across files, commands, network, credentials and resources.","agents/chapters/20-sandboxing.html","agt",1],["Leave-one-out baseline","A baseline for each sample equal to the mean reward of the other samples for the same prompt, which is unbiased and needs no extra model.","llm-training/chapters/07-policy-gradients.html","llm",1],["Leave-one-out cross-validation","The extreme of k-fold where k equals the number of rows, so each row is validated by a model trained on all the others.","ml/chapters/13-cross-validation.html","ml",1],["Leave-one-out encoding","Target encoding that removes each row's own label from its category mean, which leaves a reversed copy of the label within each category.","ml/chapters/17-feature-engineering.html","ml",0],["Left join","A join that keeps every row of the left table and fills the right-hand columns with NULL where there is no match.","ml-foundations/chapters/03-data-wrangling.html","mlf",0],["Legal hold","An obligation to preserve data relevant to a dispute, which can override normal deletion schedules.","evals/chapters/22-privacy-data.html","evl",0],["Lemmatisation","Reducing a word to its dictionary base form using a vocabulary and its part of speech.","retrieval/chapters/01-text-analysis.html","ret",0],["Length bias","The tendency of reward models and preference-trained policies to favour longer responses because labellers or surface features correlate length with quality.","llm-training/chapters/13-reward-models.html","llm",1],["Length-controlled win rate","A judge-based win rate corrected, usually by regression, to estimate what it would be if the compared answers had equal length.","evals/chapters/09-leaderboards.html","evl",0],["Length-extension attack","Appending data to a message and computing a valid hash(secret ‖ message) without the secret; HMAC is immune.","security/chapters/03-applied-crypto.html","sec",0],["Length normalisation","Dividing a sequence's log-probability by a power of its length so that beam search does not prefer short outputs.","deep-learning/chapters/15-decoding.html","dl",1],["Length normalisation","Adjusting term frequency by document length so that long documents are not favoured for mentioning a term more often by chance.","retrieval/chapters/02-bm25.html","ret",0],["Lethal trifecta","The combination of access to private data, exposure to untrusted content and a way to communicate externally, which lets an attacker steal data through an agent.","agents/chapters/19-agent-security.html","agt",1],["Lethal trifecta","The combination of access to private data, exposure to untrusted content and the ability to communicate externally, which lets an injection steal data.","evals/chapters/14-architectural-defences.html","evl",0],["Lexical bias","Judgements collected from term-matching systems favour term-matching systems, so semantic retrievers look worse than they are.","retrieval/chapters/06-retrieval-benchmarks.html","ret",0],["Lifelong learning agent","An agent that keeps acquiring and reusing abilities across an open-ended sequence of tasks instead of starting each task from scratch.","open-ended/chapters/07-lifelong-agents.html","oe",1],["Lift","The number of positives found in a selected group divided by the number expected if the same number of cases were chosen at random.","ml/chapters/04-baselines.html","ml",1],["LightGBM","A gradient-boosting library built for speed on large data, using histogram splits, leaf-wise growth, GOSS and feature bundling.","ml/chapters/09-ensembles-boosting.html","ml",0],["Likelihood","The probability of the observed features if a given class were true.","ml/chapters/07-neighbours-bayes.html","ml",1],["Likelihood","The probability of the observed data as a function of the model's parameters; it is not a probability of the parameters.","ml-foundations/chapters/13-likelihood-losses.html","mlf",1],["Likelihood displacement","The effect in DPO where the probability of the chosen response falls during training, because the loss only constrains the gap between chosen and rejected.","llm-training/chapters/12-preference-optimisation.html","llm",1],["Limitations page","A customer-facing statement of what a system was tested on, where it is weakest and what it must not be relied on for.","ai-delivery/chapters/16-research-to-product.html","aid",0],["Lineage","The record of every candidate with its parent, diff, scores, logs and approver, used for audit and rollback.","open-ended/chapters/17-self-modification-safety.html","oe",1],["Linear attention","Attention with the softmax replaced by a product of feature maps, so the sum over past tokens can be kept as a fixed-size state.","deep-learning/chapters/22-beyond-attention.html","dl",0],["Linear combination","A sum of vectors each multiplied by a scalar, such as c1 x + c2 y.","ml-foundations/chapters/05-vectors-similarity.html","mlf",1],["Linearizability","The strongest common consistency model: the system behaves as if there's a single copy and every operation happens at one instant.","networking/chapters/18-replication.html","net",0],["Linearization point","The instant at which an operation appears to take effect in a linearizable history.","distributed/chapters/05-consistency-models.html","dist",0],["Linear map","A function that preserves addition and scaling, so that f(ax + by) = a f(x) + b f(y); every one is a matrix.","ml-foundations/chapters/06-matrices.html","mlf",1],["Linear model","A model that predicts the target as a weighted sum of the features plus an intercept.","ml/chapters/05-linear-models.html","ml",1],["Linkage","The rule for the distance between two clusters in hierarchical clustering, such as single, complete, average or Ward.","ml/chapters/10-clustering.html","ml",0],["Linter gate","A check after an edit that rejects it if the file no longer parses, leaving the file unchanged and returning the error.","agents/chapters/18-coding-agents.html","agt",1],["List comprehension","A single expression, such as [f(x) for x in xs], that builds a list from another iterable.","ml-foundations/chapters/01-python-numerics.html","mlf",1],["Listwise reranking","Giving a model a numbered list of candidates and asking it to return them in order of relevance.","retrieval/chapters/08-rerankers.html","ret",0],["Literature survey","A structured reading of a field, built by following citations backwards and forwards from a few recent papers.","ml-foundations/chapters/16-reading-papers.html","mlf",0],["Little's law","L = λ × W: the average number of items in a system equals the arrival rate times the average time each one spends there.","systems/chapters/14-queues-backpressure.html","sys",0],["Livelock","Threads keep reacting to each other and retrying but none makes progress, like two people stepping aside in a corridor.","systems/chapters/13-deadlock.html","sys",0],["Liveness probe","A check that decides whether a container should be restarted.","reliability/chapters/14-orchestration.html","ops",0],["Liveness property","\"Something good eventually happens\", such as every request eventually getting a reply.","distributed/chapters/01-system-models.html","dist",0],["LLM judge","A language model prompted to grade another system's output against a written criterion.","evals/chapters/00-start-here.html","evl",0],["Load average","A smoothed count of how many threads were running or waiting to run, over the last 1, 5 and 15 minutes.","systems/chapters/07-scheduling.html","sys",0],["Load balancer","A machine or service that spreads incoming requests across many servers.","networking/chapters/14-load-balancers.html","net",0],["Loadings","The weights with which the original columns combine to form a principal component.","ml/chapters/11-dimensionality-reduction.html","ml",0],["Load shedding","Deliberately rejecting some work quickly when overloaded so the work you do accept still succeeds.","systems/chapters/14-queues-backpressure.html","sys",0],["Local competition","Letting each candidate compete on fitness only against candidates with similar behaviour, so many different kinds of good solution survive.","open-ended/chapters/03-novelty-search.html","oe",1],["Local explanation","A description of why a model made one particular prediction.","ml/chapters/16-interpretability.html","ml",0],["Locality","The tendency of programs to reuse recent data (temporal) and nearby data (spatial). Caches only work because of it.","systems/chapters/02-memory-hierarchy.html","sys",0],["Locality-sensitive hashing","Splitting signatures into bands and bucketing by band so that only likely near-duplicates are ever compared with each other.","llm-training/chapters/01-pretraining-data.html","llm",0],["Local optimum","A candidate that is better than all of its neighbours but worse than the best candidate overall.","open-ended/chapters/03-novelty-search.html","oe",1],["Local outlier factor (LOF)","A score comparing a point's local density with the density of its neighbours, near 1 for normal points and well above 1 for local anomalies.","ml/chapters/12-anomaly-detection.html","ml",0],["Lock file","A file recording the exact version of every installed package, including indirect dependencies, so an environment can be rebuilt identically.","ml-foundations/chapters/04-reproducible-experiments.html","mlf",1],["Log-derivative trick","The identity that the gradient of a probability equals the probability times the gradient of its log, which turns a sum over outcomes into an expectation that sampling can estimate.","llm-training/chapters/07-policy-gradients.html","llm",1],["Logical order","The order in which text is read and stored, as opposed to the left-to-right order in which its glyphs are drawn on screen.","retrieval/chapters/22-multilingual.html","ret",0],["Logistic regression","A classifier that sets the log-odds of the positive class equal to a weighted sum of the features.","ml/chapters/05-linear-models.html","ml",1],["Logit","An unnormalised score for one vocabulary entry, which a softmax turns into a probability.","deep-learning/chapters/10-transformer-block.html","dl",1],["Logit","The raw real-valued score a model outputs before a sigmoid or softmax turns it into a probability.","ml-foundations/chapters/13-likelihood-losses.html","mlf",1],["Logit distillation","Distillation in which the student minimises a divergence from the teacher's next-token distribution at every position of the training text.","llm-training/chapters/15-distillation.html","llm",0],["Logits","The raw scores produced by a network's last layer, before softmax turns them into probabilities.","deep-learning/chapters/01-neurons-layers.html","dl",1],["Log-loss","The average negative log-probability a model gave to the true labels, also called binary cross-entropy.","ml/chapters/05-linear-models.html","ml",1],["Log-sum-exp","The function ln of the sum of exponentials, computed stably by subtracting the maximum before exponentiating.","ml-foundations/chapters/11-numerics.html","mlf",0],["Long-context stuffing","Putting the whole corpus, or a large slice of it, into the prompt and letting the model find what it needs without an index.","agents/chapters/12-long-context.html","agt",0],["Longest-prefix match","The routing rule: when several routes match a destination, use the most specific one.","networking/chapters/05-routing.html","net",0],["LongMemEval","A 2024 benchmark of 500 questions over long chat histories testing information extraction, multi-session and temporal reasoning, knowledge updates and abstention.","agents/chapters/11-memory.html","agt",1],["LoRA alpha","A constant that scales the adapter's output by alpha divided by the rank, interacting with the learning rate to set the effective step size.","llm-training/chapters/11-lora.html","llm",1],["LoRA (low-rank adaptation)","A fine-tuning method that freezes the pretrained weights and learns the update to each chosen matrix as a product of two thin matrices.","llm-training/chapters/11-lora.html","llm",1],["Loss","A number that scores how wrong a model's predictions are on the data; training tries to make it small.","ml-foundations/chapters/00-start-here.html","mlf",1],["Loss function","A rule that turns how wrong a prediction was into a single number that training tries to reduce.","deep-learning/chapters/00-start-here.html","dl",0],["Loss masking","Excluding some positions, such as padding or the prompt, from the loss by an ignore index, so only the remaining positions contribute.","deep-learning/chapters/14-language-modelling.html","dl",1],["Loss masking","Setting the labels of positions that should not be learned, such as the prompt, to an ignore value so they contribute no loss.","llm-training/chapters/10-sft.html","llm",1],["Loss scaling","Multiplying the loss by a constant before the backward pass so that small fp16 gradients do not underflow to zero, then dividing the gradients by it before the update.","deep-learning/chapters/17-training-stability.html","dl",0],["Loss scaling","Multiplying the loss by a constant before the backward pass so small float16 gradients do not underflow, then dividing it out afterwards.","ml-foundations/chapters/11-numerics.html","mlf",0],["Loss spike","A sudden large rise in training loss, common in long runs, from which the run may or may not recover.","deep-learning/chapters/17-training-stability.html","dl",0],["Loss spike","A sudden jump in training loss, often preceded by a gradient-norm burst, that may or may not recover without rolling back to an earlier checkpoint.","llm-training/chapters/05-long-runs.html","llm",0],["Lost update","Two read-modify-write operations overlap and one overwrites the other, so an update silently disappears.","systems/chapters/11-race-conditions.html","sys",0],["Low-rank approximation","Replacing a matrix by a product of thin factors so that it needs far fewer numbers.","ml-foundations/chapters/07-decompositions.html","mlf",0],["LSM tree","Log-structured merge tree: writes go to a memtable and are flushed to sorted files that are merged in the background. Optimised for writes.","data/chapters/05-lsm-trees.html","data",0],["LSTM","A recurrent cell with a separate cell state updated additively under learned forget, input and output gates, which lets gradients survive over longer spans.","deep-learning/chapters/08-sequences-rnns.html","dl",0],["Luhn check","A checksum that payment card numbers satisfy, used to discard digit strings that merely look like card numbers.","evals/chapters/15-guardrails.html","evl",0],["MAC","Message authentication code: a keyed checksum, such as HMAC, proving a message came from a key holder and was not altered.","security/chapters/03-applied-crypto.html","sec",0],["MAC address","A 48-bit hardware address identifying a network interface on the local network.","networking/chapters/02-local-networks.html","net",0],["Machine epsilon","The gap between 1.0 and the next representable float above it (about 2.2e-16 for doubles), which sets the best relative accuracy.","ml-foundations/chapters/01-python-numerics.html","mlf",1],["Machine learning","Getting a program to improve at a task by fitting a function to examples instead of writing the function by hand.","ml/chapters/00-start-here.html","ml",0],["MAE","Mean absolute error, a regression metric whose best constant prediction is the median.","ml/chapters/02-framing-metrics.html","ml",1],["Mahalanobis distance","Distance from the mean measured in units of the data's own covariance, so points off the main correlation ridge count as far away.","ml/chapters/12-anomaly-detection.html","ml",0],["Majority-class baseline","Predicting the most common class for every case, which sets the accuracy any classifier must exceed.","ml/chapters/04-baselines.html","ml",1],["Mamba","A state-space architecture with input-dependent updates, computed by a hardware-aware parallel scan.","deep-learning/chapters/22-beyond-attention.html","dl",0],["Manager pattern","A multi-agent design in which a central agent calls specialised agents as tools and keeps control of the plan and the final answer.","agents/chapters/14-multi-agent.html","agt",0],["Mantissa","The bits of a floating-point number that hold its significant digits and so set its precision.","deep-learning/chapters/17-training-stability.html","dl",0],["Many-shot jailbreaking","A jailbreak that places a long fake dialogue of compliant answers in the prompt before the real request, becoming more effective as the number of examples grows.","evals/chapters/13-prompt-injection.html","evl",0],["MAP","Mean average precision: the average of average precision over all queries in a test set.","retrieval/chapters/04-relevance-metrics.html","ret",0],["MAP-Elites","A quality-diversity algorithm that keeps the best solution found in each cell of a grid over behaviour space and mutates randomly chosen elites.","open-ended/chapters/04-quality-diversity.html","oe",1],["MapReduce","A batch model: map each input record to key-value pairs, group by key, then reduce each group.","data/chapters/18-batch.html","data",0],["MAR","Missing at random: whether a value is missing depends only on other observed columns.","ml/chapters/03-eda.html","ml",0],["Margin","The gap between the decision boundary and the nearest training points of each class.","ml/chapters/07-neighbours-bayes.html","ml",1],["Markov decision process","A model of sequential decisions with states, actions, transition probabilities, rewards and a discount factor, where the next state depends only on the current state and action.","llm-training/chapters/06-bandits-mdps.html","llm",1],["Masking","The effect by which anomalies inflate the statistics used to detect them, so that none of them looks extreme.","ml/chapters/12-anomaly-detection.html","ml",0],["Master weights","A full-precision fp32 copy of the weights that the optimiser updates, because tiny updates would be rounded away in 16-bit numbers.","deep-learning/chapters/17-training-stability.html","dl",0],["Master weights","A 32-bit copy of the weights that receives the updates in mixed-precision training, because bf16 cannot represent small updates.","llm-training/chapters/02-gpu-memory.html","llm",0],["Master weights","A float32 copy of the weights that receives the updates, while 16-bit copies are used for the forward and backward passes.","ml-foundations/chapters/11-numerics.html","mlf",0],["Matrix","A rectangular table of numbers with a shape (rows, columns) that also acts as a linear function on vectors.","ml-foundations/chapters/06-matrices.html","mlf",1],["Matrix multiplication","The product AB defined so that (AB)x = A(Bx): composition of linear maps, with entries given by row-column dot products.","ml-foundations/chapters/06-matrices.html","mlf",1],["Matrix-vector product","The vector whose entries are the dot products of each row of the matrix with the input vector.","ml-foundations/chapters/06-matrices.html","mlf",1],["Maximum a posteriori estimate","The parameter value that maximises likelihood times prior, equivalent to adding a regularisation penalty to the loss.","ml-foundations/chapters/13-likelihood-losses.html","mlf",1],["Maximum likelihood","Choosing the weights that make the training text as probable as possible under the model, which is the same as minimising cross-entropy.","deep-learning/chapters/14-language-modelling.html","dl",1],["Maximum-likelihood estimate","The parameter value that makes the observed data most probable, found by maximising the log-likelihood.","ml-foundations/chapters/13-likelihood-losses.html","mlf",1],["MaxSim","A score that takes, for each query token, its highest similarity to any passage token and sums these maxima.","retrieval/chapters/09-late-interaction-sparse.html","ret",0],["max_tokens","A required hard cap on how many tokens the model may generate in one response; reaching it truncates the output.","agents/chapters/01-model-apis.html","agt",1],["MCAR","Missing completely at random: whether a value is missing is unrelated to any observed or unobserved data.","ml/chapters/03-eda.html","ml",0],["MCP client","A component inside a host that keeps one connection to one MCP server.","agents/chapters/07-mcp.html","agt",0],["MCP host","The application the user runs, which owns the model conversation, chooses what the model may see and asks the user for approval.","agents/chapters/07-mcp.html","agt",0],["MCP prompt","A reusable message template offered by a server and invoked explicitly by the user, fetched with prompts/get.","agents/chapters/07-mcp.html","agt",0],["MCP resource","Data identified by a URI that a server offers as context, chosen by the host application and fetched with resources/read.","agents/chapters/07-mcp.html","agt",0],["MCP server","A program, local or remote, that exposes tools, resources and prompts over MCP.","agents/chapters/07-mcp.html","agt",0],["MCP tool","A model-controlled function offered by a server, listed with tools/list and run with tools/call.","agents/chapters/07-mcp.html","agt",0],["Mean absolute scaled error (MASE)","A forecast's mean absolute error divided by that of the in-sample seasonal naive forecast, so that 1 means as good as seasonal naive.","ml/chapters/18-time-series.html","ml",0],["Mean reciprocal rank","The average over queries of 1 divided by the rank of the first relevant result, so only the first hit counts.","retrieval/chapters/04-relevance-metrics.html","ret",0],["Mean squared error","The average of the squared residuals, the standard loss for fitting a regression.","ml/chapters/05-linear-models.html","ml",1],["Median absolute deviation (MAD)","The median of the absolute differences from the median, a spread measure that outliers barely affect.","ml/chapters/12-anomaly-detection.html","ml",0],["Medusa heads","Extra output heads added to a model, each predicting a token further ahead, so one pass produces several candidates to verify.","llm-training/chapters/21-speculative-decoding.html","llm",0],["Memory bandwidth","How many bytes per second a processor can read from and write to its main memory.","ml-foundations/chapters/17-compute-costs.html","mlf",0],["Memory-bound","Describes an operation whose run time is set by how fast data can be moved, because its arithmetic intensity is below the chip's ridge point.","llm-training/chapters/04-kernels.html","llm",0],["Memory-bound","Limited by how fast data can be moved, not by arithmetic, so extra compute capacity would not make it faster.","ml-foundations/chapters/17-compute-costs.html","mlf",0],["Memory hierarchy","The ladder of storage from registers and CPU caches to RAM, SSD and network: each step down is bigger, cheaper and much slower.","systems/chapters/02-memory-hierarchy.html","sys",0],["Memory leak","Memory a program no longer needs but never frees, so its usage grows until something runs out.","systems/chapters/03-stack-heap.html","sys",0],["Memory poisoning","Saving injected or false content into an agent's memory so that it persists and is trusted in later sessions.","agents/chapters/11-memory.html","agt",1],["Memory-safe language","A language that prevents out-of-bounds and use-after-free bugs by construction, such as Rust, Go or Java.","security/chapters/12-memory-supply-chain.html","sec",0],["Memory stream","A complete natural-language record of an agent's experiences from which relevant memories are retrieved by recency, importance and relevance.","agents/chapters/11-memory.html","agt",1],["Memory tool","A tool whose file commands let a model read and write a memory directory, executed client-side by the application against storage it controls.","agents/chapters/11-memory.html","agt",1],["Memtable","The in-memory sorted buffer where an LSM tree collects recent writes before flushing them to an SSTable.","data/chapters/05-lsm-trees.html","data",0],["Merge interference","Loss of ability when task vectors are combined because many entries are redundant noise or because different models push the same weight in opposite directions.","llm-training/chapters/16-model-merging.html","llm",1],["Merge recipe","The configuration of a merge: which models, which method, and the weights and densities per model or per layer, kept as a versioned file.","llm-training/chapters/16-model-merging.html","llm",1],["Merge table","The ordered list of pair merges learned by byte-pair encoding, applied in that order to encode new text.","deep-learning/chapters/13-tokenisation.html","dl",1],["Message queue","A buffer service that holds messages until a consumer processes them, decoupling sender and receiver.","networking/chapters/21-where-next.html","net",0],["Meta agent","The language model, prompted to design other agents, that proposes each new candidate in a search over agent designs.","open-ended/chapters/12-meta-agent-search.html","oe",1],["Meta Agent Search","An ADAS algorithm in which a language model repeatedly writes new agents as code, tests them and stores them in an archive that informs the next proposal.","open-ended/chapters/12-meta-agent-search.html","oe",1],["Metadata filter","A condition on fields stored beside each chunk (tenant, date, language, access list) that a retrieved result must satisfy.","retrieval/chapters/12-filters-permissions.html","ret",0],["Meta-model","The second-level model in a stack, whose inputs are the predictions of the base models.","ml/chapters/20-competitions.html","ml",0],["Metamorphic check","A check on a property that must hold when the input is transformed, used when no reference answer exists.","open-ended/chapters/15-evaluator-hacking.html","oe",1],["Metamorphic test","A test that checks a relationship between outputs on related inputs, such as unchanged answers under rephrasing.","evals/chapters/02-eval-harnesses.html","evl",1],["Meta-review","A final step in which the model acts as an area chair and decides on a paper given all of the individual reviews.","open-ended/chapters/14-automated-science.html","oe",1],["Meta-scratchpad","A summary, written periodically by a model, of which strategies have worked in recent generations, appended to later mutation prompts.","open-ended/chapters/10-evolution-frameworks.html","oe",1],["Metastable failure","A failure that keeps going after its trigger is gone, sustained by a feedback loop such as retries.","networking/cases/case-08-retry-storms.html","net",0],["MFU","Model FLOPs utilisation: the fraction of a chip's peak FLOP/s that useful model arithmetic actually achieves.","ml-foundations/chapters/17-compute-costs.html","mlf",0],["M (HNSW)","The number of links each HNSW node keeps, which raises achievable recall and memory use together.","retrieval/chapters/11-ann-indexes.html","ret",1],["Microbatch","The number of sequences processed in one forward and backward pass, which sets activation memory.","deep-learning/chapters/16-resource-accounting.html","dl",1],["Micro-batch","A small slice of a batch processed in one forward and backward pass, used to fill a pipeline or to accumulate gradients.","llm-training/chapters/03-parallelism.html","llm",0],["Micro-segmentation","Restricting network traffic between individual workloads, not just between large zones.","security/chapters/13-zero-trust.html","sec",0],["Microservices","Small, independently deployable services, each owning its data and organised around a business capability.","architecture/chapters/11-monolith-microservices.html","arch",0],["MicroVM","A lightweight virtual machine with its own guest kernel, such as those run by Firecracker, that boots in well under a second.","agents/chapters/20-sandboxing.html","agt",1],["Migration","The periodic exchange of programs between islands so good ideas spread without merging the populations.","open-ended/chapters/10-evolution-frameworks.html","oe",1],["MinHash","A way to compress a set into a short signature so that the chance two signature values match equals the sets' Jaccard similarity.","llm-training/chapters/01-pretraining-data.html","llm",0],["Minibatch","A small slice of the training set used for one gradient estimate and one parameter update.","deep-learning/chapters/05-pytorch.html","dl",1],["Minibatch","The small random subset of training examples used to estimate the gradient for one step.","ml-foundations/chapters/10-optimisers.html","mlf",1],["Minimal criterion","A filter that admits a new environment only if the current agent scores neither too low to learn from nor too high to be worth learning.","open-ended/chapters/05-open-ended-algorithms.html","oe",1],["Minimal criterion novelty search","Novelty search that only accepts candidates meeting a basic standard of viability.","open-ended/chapters/03-novelty-search.html","oe",1],["Minimum detectable effect","The smallest true difference between two systems that an eval of a given size would detect with a stated power and false-positive rate.","evals/chapters/04-eval-statistics.html","evl",1],["Minimum necessary","The HIPAA standard that only the protected health information needed for the purpose may be used or disclosed.","ai-delivery/chapters/09-healthcare.html","aid",0],["Min-max normalisation","Rescaling scores so the list's lowest becomes 0 and its highest 1, which one outlier can distort.","retrieval/chapters/10-hybrid-search.html","ret",0],["Min-p sampling","Sampling only from tokens whose probability is at least a set fraction of the most probable token's, so the cut-off scales with the model's confidence.","deep-learning/chapters/15-decoding.html","dl",1],["MIPROv2","A DSPy optimiser that proposes instructions and chooses demonstrations jointly, using mini-batch scores to guide the search.","open-ended/chapters/11-evolving-prompts.html","oe",1],["Mismatched generalisation","A jailbreak failure mode in which a model's capabilities cover inputs, such as rare languages or encodings, that its safety training did not.","evals/chapters/13-prompt-injection.html","evl",0],["Mitigate before diagnosing","The incident rule of doing the safe, reversible thing that stops the harm first and investigating the cause afterwards.","evals/chapters/20-ai-incidents.html","evl",0],["Mixed precision","Training with 16-bit numbers for the bulky matrix products and 32-bit numbers for accumulations such as weights, optimiser state and the loss.","deep-learning/chapters/17-training-stability.html","dl",0],["Mixed-precision training","Training with 16-bit or 8-bit arithmetic for most operations while keeping master weights and sensitive accumulations in float32.","ml-foundations/chapters/11-numerics.html","mlf",0],["Mixture of experts","A layer with many parallel expert MLPs in which a router sends each token to only a few of them.","deep-learning/chapters/20-mixture-of-experts.html","dl",0],["MLP sublayer","The position-wise feed-forward network in a block: expand each token vector to about four times its width, apply a nonlinearity, project back.","deep-learning/chapters/10-transformer-block.html","dl",1],["M/M/1 queue","A single server with random (Poisson) arrivals and exponential service times; mean time in system is 1/(μ − λ).","reliability/chapters/08-queueing-theory.html","ops",0],["MMTEB","The massively multilingual extension of MTEB, with over 500 tasks in more than 250 languages and a cheaper downsampled version.","retrieval/chapters/06-retrieval-benchmarks.html","ret",0],["MNAR","Missing not at random: whether a value is missing depends on the missing value itself.","ml/chapters/03-eda.html","ml",0],["Mode-covering and mode-seeking KL","Forward KL forces the student to put mass wherever the teacher does (mode-covering), while reverse KL lets it commit to one of the teacher's modes (mode-seeking).","llm-training/chapters/15-distillation.html","llm",0],["Model","The function, learned from examples, that maps features to a prediction.","ml/chapters/00-start-here.html","ml",0],["Model capacity","How rich a family of functions a learning algorithm can choose from, such as polynomial degree or tree depth.","ml/chapters/01-generalisation.html","ml",1],["Model card","A short document stating a model's intended use, evaluation data, performance by slice and known limitations.","ai-delivery/chapters/16-research-to-product.html","aid",0],["Model checking","Exploring every reachable state of a (small) model of a system to check that invariants always hold.","distributed/chapters/20-formal-methods.html","dist",0],["Model collapse","The loss of the rare parts of a distribution when each generation of models is trained only on the previous generation's output.","llm-training/chapters/15-distillation.html","llm",0],["Model complexity","How many different shapes a model family can express, such as the degree of a polynomial.","ml/chapters/06-regularisation.html","ml",1],["Model Context Protocol (MCP)","An open protocol that lets AI applications discover and use tools, resources and prompts from servers through a common set of JSON-RPC messages.","agents/chapters/07-mcp.html","agt",0],["Model diversity","The degree to which models make different mistakes, which decides how much averaging them helps.","ml/chapters/20-competitions.html","ml",0],["Model FLOPs utilisation (MFU)","The fraction of a GPU's peak arithmetic speed that a training run converts into useful model FLOPs, typically 30 to 50 per cent in large runs.","deep-learning/chapters/16-resource-accounting.html","dl",1],["Model gateway","A thin internal service or library through which all model calls pass, holding timeouts, spend caps, fallbacks and provider choice.","ai-delivery/chapters/12-poc-to-production.html","aid",0],["Model inventory","The firm-wide list of every model with its owner, purpose, risk tier, validation date and status.","ai-delivery/chapters/08-finance.html","aid",0],["Model merging","Combining the weights of several models, usually fine-tunes of one base, into a single model by arithmetic on the weights and without gradient training.","llm-training/chapters/16-model-merging.html","llm",1],["Model of interestingness","A foundation model used to judge which tasks or states are interesting, standing in for human taste when a system chooses what to explore next.","open-ended/chapters/06-interestingness.html","oe",1],["Model risk management","The practices a financial firm uses to limit harm from wrong or misused models: documented development, independent validation, an inventory, monitoring and change control.","ai-delivery/chapters/08-finance.html","aid",0],["Model router","A component that sends each request to a model chosen by its estimated difficulty or type.","evals/chapters/19-cost-latency-quality.html","evl",0],["Model soup","The average of the weights of several models fine-tuned from the same pre-trained model, which often beats the best single member at no extra inference cost.","llm-training/chapters/16-model-merging.html","llm",1],["Model states","The per-parameter training state that must stay in memory: weights, gradients, a full-precision master copy and the optimiser's running averages.","deep-learning/chapters/16-resource-accounting.html","dl",1],["Model states","The weights, gradients and optimiser state of a model, whose total size scales with the number of parameters and not with the batch.","llm-training/chapters/02-gpu-memory.html","llm",0],["Model tiering","Sorting models by consequence, autonomy and reversibility so that high-risk ones receive full independent validation and low-risk ones lighter oversight.","ai-delivery/chapters/08-finance.html","aid",0],["Modified z-score","A robust z-score that replaces the mean and standard deviation with the median and the MAD, usually flagged above 3.5.","ml/chapters/12-anomaly-detection.html","ml",0],["Modular monolith","One deployable application split into modules with enforced boundaries and public interfaces.","architecture/chapters/11-monolith-microservices.html","arch",0],["Module","Any unit with an interface and an implementation: a function, class, package or service.","architecture/chapters/02-modules-coupling.html","arch",0],["Module","An object that owns parameters and sub-modules and defines a forward method, so a whole network can be treated as one callable.","deep-learning/chapters/05-pytorch.html","dl",1],["Momentum","An optimiser term that steps along an exponentially weighted average of past gradients, cancelling oscillation and speeding up consistent directions.","ml-foundations/chapters/10-optimisers.html","mlf",1],["Monolith","An application built and deployed as a single unit. Not the same as a tangled \"big ball of mud\".","architecture/chapters/11-monolith-microservices.html","arch",0],["Monorepo","A single repository holding many projects, sharing tooling and allowing atomic cross-project changes.","architecture/chapters/21-engineering-practice.html","arch",0],["Monte Carlo estimation","Estimating an expectation by averaging a function over random samples, with error shrinking as one over the square root of the sample count.","ml-foundations/chapters/12-probability.html","mlf",1],["Monte Carlo return","The actual sum of rewards observed until the end of an episode, an unbiased but high-variance target for a value or advantage.","llm-training/chapters/09-value-functions.html","llm",1],["Monte Carlo simulation","Drawing many random combinations of uncertain inputs from stated ranges to see the spread of possible outcomes.","ai-delivery/chapters/14-cost-roi.html","aid",0],["Monte Carlo tree search (MCTS)","A search that grows a tree by repeating selection, expansion, random simulation and backpropagation, then plays the most-visited move.","open-ended/chapters/01-tree-search.html","oe",1],["MTBF and MTTR","Mean time between failures and mean time to recovery. Availability is roughly MTBF / (MTBF + MTTR).","reliability/chapters/01-availability-math.html","ops",0],["MTEB","The Massive Text Embedding Benchmark: eight embedding task types over dozens of datasets and many languages, whose retrieval part reuses BEIR.","retrieval/chapters/06-retrieval-benchmarks.html","ret",0],["MTU","Maximum Transmission Unit: the biggest packet a link can carry, 1,500 bytes on Ethernet.","networking/chapters/03-layers.html","net",0],["Multi-agent system","A program with more than one agent loop, each with its own context, in which the output of one agent becomes input to another.","agents/chapters/14-multi-agent.html","agt",0],["Multi-armed bandit","A decision problem with several actions of unknown average reward and no state, where the only difficulty is learning which action is best while using it.","llm-training/chapters/06-bandits-mdps.html","llm",1],["Multi-armed bandit","A repeated choice among options with unknown payouts, where each pull both earns reward and teaches you about that option.","open-ended/chapters/01-tree-search.html","oe",1],["Multicollinearity","Features that are nearly linear combinations of each other, making individual coefficients unstable while predictions stay steady.","ml/chapters/05-linear-models.html","ml",1],["Multi-head attention","Running several attention operations in parallel on slices of the model width and combining their outputs with a learned matrix.","deep-learning/chapters/09-attention.html","dl",1],["Multi-hop question","A question whose answer needs a fact found in one document to locate a second fact in another, which single-shot retrieval often misses.","agents/chapters/12-long-context.html","agt",0],["Multi-hop question","A question whose answer needs a chain of facts from different documents, where each search depends on the previous result.","retrieval/chapters/15-agentic-retrieval.html","ret",0],["Multipart upload","Uploading a large object in independent parts that are retried separately and assembled at the end.","design/chapters/08-object-storage.html","design",0],["Multi-Paxos","Running Paxos for a sequence of log slots with a stable leader, which can skip the first phase for new slots.","distributed/chapters/09-paxos.html","dist",0],["Multiple comparisons","The inflation of false positives that occurs when many slices, metrics or variants are tested and the best-looking one is reported.","evals/chapters/04-eval-statistics.html","evl",1],["Multiple comparisons","The accumulation of false-positive chances when many tests are run, corrected by methods such as Bonferroni or Benjamini-Hochberg.","ml-foundations/chapters/15-statistics.html","mlf",1],["Multi-query attention","Attention with many query heads but a single shared key head and value head, which shrinks the KV cache by the number of heads.","deep-learning/chapters/19-efficient-attention.html","dl",0],["Multi-query attention (MQA)","Attention in which all query heads share a single key-value head, shrinking the KV cache by the number of heads.","llm-training/chapters/18-kv-cache.html","llm",0],["Multi-query retrieval","Searching with several differently worded versions of a question and fusing the result lists.","retrieval/chapters/15-agentic-retrieval.html","ret",0],["Multi round-trip request","The MCP pattern in which a server ends a request with an input_required result and the client retries it with the answers and an echoed requestState.","agents/chapters/08-mcp-production.html","agt",0],["Multi-turn attack","An attack spread over several messages, each looking harmless alone, that escalates by building on the model's earlier replies.","evals/chapters/16-red-teaming.html","evl",0],["Multi-vector index","An index that stores many vectors per document, such as one per token or patch, instead of a single vector.","retrieval/chapters/21-visual-retrieval.html","ret",0],["Multi-vector retrieval","Representing a passage by several vectors, usually one per token, instead of a single vector.","retrieval/chapters/09-late-interaction-sparse.html","ret",0],["Multi-window burn-rate alert","An alert that fires when the error budget burns fast over both a long and a short window, balancing speed and precision.","reliability/chapters/07-alerting-oncall.html","ops",0],["Mutable surface","The files and settings an agent is permitted to edit, as opposed to the trusted core it must not touch.","open-ended/chapters/17-self-modification-safety.html","oe",1],["Mutation-prompt","An instruction that tells a model how to rewrite a task prompt, which can itself be evolved.","open-ended/chapters/11-evolving-prompts.html","oe",1],["Mutex","Mutual-exclusion lock: only one thread can hold it at a time, so it protects a critical section.","systems/chapters/12-locks.html","sys",0],["Mutual information","The KL divergence from a joint distribution to the product of its marginals: the bits of uncertainty about one variable removed by learning the other.","ml-foundations/chapters/14-information-theory.html","mlf",1],["Mutual TLS (mTLS)","TLS in which both client and server present certificates, giving services cryptographic identities.","security/chapters/04-keys-secrets-pki.html","sec",0],["MVCC","Multi-version concurrency control: keeping several versions of each row so readers see a snapshot and don't block writers.","data/chapters/12-mvcc-locking.html","data",0],["N+1 query problem","Running one query to get a list and then one more query per item, instead of a single join.","data/chapters/08-query-execution.html","data",0],["Naive Bayes","A classifier that combines a class prior with per-feature likelihoods under the assumption that features are independent given the class.","ml/chapters/07-neighbours-bayes.html","ml",1],["Namespace (Linux)","A kernel feature that gives a group of processes its own view of something global: process IDs, network, mounts, hostname.","systems/chapters/19-containers-vms.html","sys",0],["Namespacing (tools)","Giving related tools a shared prefix, such as billing_ or crm_, so a model can tell tools from different systems apart as the list grows.","agents/chapters/05-tool-design.html","agt",1],["NaN","Not a number: the result of an invalid operation such as 0/0 or inf minus inf, which spreads to every value computed from it.","ml-foundations/chapters/11-numerics.html","mlf",0],["NAT","Network Address Translation: a router rewriting private addresses to its public address so many devices share one IP.","networking/chapters/04-ip-addresses.html","net",0],["Nat","The unit of information measured with the natural logarithm; one nat is about 1.44 bits.","deep-learning/chapters/14-language-modelling.html","dl",1],["Nat","The unit of information when logarithms are natural; one nat is about 1.4427 bits.","ml-foundations/chapters/14-information-theory.html","mlf",1],["NAT gateway","A managed service that lets instances in private subnets make outbound connections without being reachable from outside.","networking/chapters/22-cloud-networking.html","net",0],["Natural language inference","The task of labelling a pair of texts as entailment, contradiction or neutral, used to check whether evidence supports a claim.","evals/chapters/12-fact-checking.html","evl",0],["Navigational, informational and transactional queries","Broder's three intents: reaching a known page, seeking information, and wanting to do something.","retrieval/chapters/03-query-understanding.html","ret",0],["ndarray","NumPy's n-dimensional array: a flat block of memory plus a header giving dtype, shape, strides and offset.","ml-foundations/chapters/02-numpy-arrays.html","mlf",1],["nDCG","Normalised DCG: DCG divided by the DCG of the ideal ordering, giving a 0 to 1 score that can be averaged across queries.","retrieval/chapters/04-relevance-metrics.html","ret",0],["Near duplicate","A row or item that differs from another only trivially, so that having both in training and test sets inflates validation scores.","ml/chapters/03-eda.html","ml",0],["Needle-in-a-haystack test","A probe that hides one fact inside long unrelated text and asks the model to recall it, easy to pass and weak evidence of real long-context ability.","agents/chapters/12-long-context.html","agt",0],["Negative log-likelihood","The minus log of the probability a model gave to the observed data, averaged over examples; the standard training loss.","ml-foundations/chapters/13-likelihood-losses.html","mlf",1],["Negative sampling","Training word2vec by telling real (word, context) pairs from randomly drawn noise pairs instead of normalising over the whole vocabulary.","deep-learning/chapters/06-embeddings.html","dl",1],["Nemesis","In Jepsen, the component that injects faults such as partitions, clock skew and crashes during a test.","distributed/chapters/19-testing.html","dist",0],["Nested cross-validation","An outer loop that holds out data and an inner loop that does all model selection on the rest, so the outer score is not flattered by the selection.","ml/chapters/13-cross-validation.html","ml",1],["Net present value","The sum of a project's yearly net benefits after discounting each by the customer's cost of capital, so later money counts for less.","ai-delivery/chapters/14-cost-roi.html","aid",0],["Network allow-list","A default-deny list of hosts an agent may contact, matched on whole host labels and checked against the resolved address.","agents/chapters/20-sandboxing.html","agt",1],["Network partition","A failure where the network splits machines into groups that can't reach each other.","networking/chapters/15-why-distribute.html","net",0],["Neuron","A unit that computes a weighted sum of its inputs plus a bias and passes the result through an activation function.","deep-learning/chapters/01-neurons-layers.html","dl",1],["Next-token prediction","Training a model to give the probability of each possible next token given the tokens before it, which defines a distribution over whole sequences by the chain rule.","deep-learning/chapters/14-language-modelling.html","dl",1],["NF4 (4-bit NormalFloat)","A 4-bit number format whose 16 levels are quantiles of a normal distribution, matched to the bell-shaped distribution of pretrained weights.","llm-training/chapters/11-lora.html","llm",1],["N-gram model","A count-based language model that predicts the next token from the previous n minus one tokens using frequencies in the training text.","deep-learning/chapters/14-language-modelling.html","dl",1],["n-gram overlap","A contamination check that looks for long runs of consecutive words shared between a test item and training text.","evals/chapters/07-contamination.html","evl",1],["N-gram overlap check","A contamination test that flags evaluation items sharing runs of n consecutive words or tokens with the training data.","llm-training/chapters/23-evaluating-models.html","llm",0],["Nines","Shorthand for availability: 99.9% is \"three nines\", about 43 minutes of downtime in a 30-day month.","reliability/chapters/01-availability-math.html","ops",0],["No free lunch theorem","The result that, averaged over all possible target functions, every learning algorithm has the same accuracy on unseen inputs.","ml/chapters/01-generalisation.html","ml",1],["Noise floor","The error that remains even for a perfect model because the target contains randomness no features explain.","ml/chapters/04-baselines.html","ml",1],["Noise floor","The smallest gap between two scores that sampling noise from the test-set size alone cannot explain.","ml-foundations/chapters/16-reading-papers.html","mlf",0],["Noise (in judgement)","Unwanted variability in the judgements of different experts, or of one expert on different days, on identical cases.","ai-delivery/chapters/03-expert-knowledge.html","aid",0],["Noisy-channel model","A spelling model that picks the word maximising its prior probability times the probability of the observed typo.","retrieval/chapters/03-query-understanding.html","ret",0],["Noisy neighbour","A tenant whose load degrades service for others sharing the same resources.","security/chapters/15-multi-tenancy.html","sec",0],["Non-blocking I/O","I/O calls that return immediately, saying \"not ready yet\" instead of waiting, so one thread can juggle many connections.","systems/chapters/15-blocking-io.html","sys",0],["Nonce","A number used once; reusing one with the same key can destroy the security of many ciphers.","security/chapters/03-applied-crypto.html","sec",0],["Non-embedding parameters","A model's parameter count without its token and position tables, the N that Kaplan et al. use and that 6ND is most accurate with.","deep-learning/chapters/16-resource-accounting.html","dl",1],["Non-functional requirement","How well a system must do it: latency, availability, scale, consistency, cost, security.","design/chapters/01-framework.html","design",0],["Non-goals","Things that could reasonably be goals but are explicitly chosen not to be, which keeps a review within its intended scope.","ml-foundations/chapters/18-technical-writing.html","mlf",0],["Non-inferiority","The claim that a new system is no worse than the current one by more than an agreed margin, which needs less evidence than proving it better.","ai-delivery/chapters/06-evaluation-plans.html","aid",0],["Non-parametric memory","Knowledge kept outside the model, such as an indexed document collection, that is looked up when a question arrives.","retrieval/chapters/13-rag-end-to-end.html","ret",0],["Norm","The length of a vector; the Euclidean (L2) norm is the square root of the sum of squared components.","ml-foundations/chapters/05-vectors-similarity.html","mlf",1],["Normal equations","The linear equations (A transpose A) w = A transpose y whose solution is the least-squares weight vector.","ml/chapters/05-linear-models.html","ml",1],["Normalisation","Organising tables so each fact is stored once, avoiding update anomalies. Denormalising duplicates data on purpose for faster reads.","data/chapters/02-sql-relational.html","data",0],["Normalisation","Dividing a vector by its norm so that its length becomes 1.","ml-foundations/chapters/05-vectors-similarity.html","mlf",1],["Notebook prototype","A scripted experiment with real cases in a file, one fixed prompt and a scorer that compares outputs to labels the expert wrote first.","ai-delivery/chapters/05-riskiest-assumption.html","aid",0],["Not enough information","The verdict for a claim that the available evidence neither supports nor contradicts.","evals/chapters/12-fact-checking.html","evl",0],["Notes file","A file an agent writes outside its window, such as a progress log, so work can resume after a context reset or in a later session.","agents/chapters/11-memory.html","agt",1],["Novelty archive","A growing memory of behaviours that were novel when first found, so the search does not revisit them.","open-ended/chapters/03-novelty-search.html","oe",1],["Novelty bonus (parent selection)","The 1/(1 + children) factor that gives less weight to agents that have already produced many children.","open-ended/chapters/13-self-improving-agents.html","oe",1],["Novelty check","A literature search used to discard research ideas that are too similar to existing papers.","open-ended/chapters/14-automated-science.html","oe",1],["Novelty detection","Deciding whether new rows resemble a training set believed to be clean, as opposed to finding outliers within unlabelled data.","ml/chapters/12-anomaly-detection.html","ml",0],["Novelty gate","A check that rejects a proposed task if it is too similar to tasks already in the archive.","open-ended/chapters/06-interestingness.html","oe",1],["Novelty rejection sampling","Discarding a candidate program before evaluation when its embedding is too similar to programs already in the archive.","open-ended/chapters/10-evolution-frameworks.html","oe",1],["Novelty search","A search that selects candidates by how different their behaviour is from others seen so far, rather than by the objective.","open-ended/chapters/03-novelty-search.html","oe",1],["Novelty search with local competition","A quality-diversity method that selects for behavioural novelty while letting each solution compete on fitness only against its behavioural neighbours.","open-ended/chapters/04-quality-diversity.html","oe",1],["nprobe","The number of IVF cells scanned per query, which trades recall against the number of distance computations.","retrieval/chapters/11-ann-indexes.html","ret",1],["NTP","Network Time Protocol: synchronises computer clocks over the network.","networking/chapters/17-time.html","net",0],["NULL","SQL's marker for an unknown value, which is not equal to anything, including another NULL, and is skipped by aggregates.","ml-foundations/chapters/03-data-wrangling.html","mlf",0],["Null hypothesis","The default claim of no real difference, whose implied chance behaviour a hypothesis test compares the data against.","ml-foundations/chapters/15-statistics.html","mlf",1],["Null set","The documents a review process discards without human review, which are sampled to estimate what relevant material was missed.","ai-delivery/chapters/10-legal.html","aid",0],["Numerical embedding","Mapping a numeric column through periodic functions or bins before a network so that it can represent sharp changes in that column.","ml/chapters/19-tabular-deep-learning.html","ml",0],["OAuth 2.0","A framework for delegated authorization: an app gets a scoped access token to act on a user's behalf without their password.","security/chapters/07-oauth-oidc.html","sec",0],["OAuth resource server","The role an MCP server plays in authorisation: it validates access tokens issued by a separate authorisation server and checks their audience and scope.","agents/chapters/08-mcp-production.html","agt",0],["Objective","The number a search tries to improve, used as a stand-in for how close a candidate is to what you actually want.","open-ended/chapters/03-novelty-search.html","oe",1],["Objective hacking","Raising the measured score without solving the underlying problem, for example by disabling the logging a detector depends on.","open-ended/chapters/13-self-improving-agents.html","oe",1],["Observability","The ability to answer new questions about a running system from the data it emits, without shipping new code to find out.","evals/chapters/17-observability.html","evl",0],["Observation","The real result of a tool call, appended to the transcript so the model can ground its next thought.","agents/chapters/03-reasoning-planning.html","agt",1],["OCR","Optical character recognition: turning an image of text into characters.","retrieval/chapters/00-start-here.html","ret",0],["OCR confidence","An engine's own estimate of how likely a character, word or line is to be right, used to route uncertain results to review.","retrieval/chapters/19-ocr.html","ret",0],["Odds ratio","The factor by which the odds of the outcome are multiplied when a feature rises by one unit, equal to the exponential of its logistic weight.","ml/chapters/05-linear-models.html","ml",1],["Off-CPU time","Time a thread spends waiting, for I/O, locks or sleep, which CPU profilers do not show.","systems/chapters/22-performance-engineering.html","sys",0],["OLTP / OLAP","Online transaction processing (many small reads and writes) versus online analytical processing (big scans and aggregates).","data/chapters/09-column-stores.html","data",0],["Omission","Relevant content in the source that a generated summary leaves out, such as an allergy, and which a reviewer looking for wrong statements cannot see.","ai-delivery/chapters/09-healthcare.html","aid",0],["OMNI","Open-endedness via Models of human Notions of Interestingness: a curriculum that combines learning progress with a language model's judgement of which tasks are worth learning.","open-ended/chapters/06-interestingness.html","oe",1],["OMNI-EPIC","An extension of OMNI in which language models also write the code for new environments, rewards and success checks.","open-ended/chapters/06-interestingness.html","oe",1],["One-hot encoding","Representing a categorical column as one 0/1 column per category, so a linear model can give each category its own offset.","ml/chapters/17-feature-engineering.html","ml",0],["One-hot vector","A vector with one entry equal to 1 and all others 0, identifying a single vocabulary item and carrying no notion of similarity.","deep-learning/chapters/06-embeddings.html","dl",1],["Online bin packing","Packing items that arrive one at a time into fixed-size bins, each placed immediately, using as few bins as possible.","open-ended/chapters/09-program-evolution.html","oe",1],["Online DPO","DPO in which the preference pairs are generated from the current policy's own samples and labelled by a reward model or judge, instead of coming from a fixed dataset.","llm-training/chapters/12-preference-optimisation.html","llm",1],["Online evaluator","A scorer that runs on sampled production traces to estimate quality continuously.","evals/chapters/17-observability.html","evl",0],["Online softmax","A softmax computed block by block with a running maximum and sum that are rescaled as new blocks arrive, giving the exact result.","deep-learning/chapters/19-efficient-attention.html","dl",0],["On-policy","Describes training data generated by the current version of the policy, as policy-gradient estimates require.","llm-training/chapters/07-policy-gradients.html","llm",1],["On-policy distillation","Distillation in which the student generates the text and the teacher scores it, so the student learns on the kind of prefixes it will produce at test time.","llm-training/chapters/15-distillation.html","llm",0],["On-premises","Running a system on hardware the customer owns or leases and controls, in their own data centre or building, rather than on a provider's cloud.","ai-delivery/chapters/13-restricted-environments.html","aid",0],["OOM killer","Linux's last resort when memory runs out: it picks a process and kills it to free memory.","systems/chapters/06-virtual-memory.html","sys",0],["Opaque agent","A peer agent whose model, prompts, tools and memory are hidden from its caller, which sees only its card, messages, tasks and artifacts.","agents/chapters/09-agent-to-agent.html","agt",0],["Open coding","A first review pass in which the reviewer writes a short free-text note about each trace, without preset categories.","evals/chapters/01-error-analysis.html","evl",1],["Open-ended","Describes a process that keeps producing outputs that are both novel and learnable to an observer, without a fixed end point.","open-ended/chapters/05-open-ended-algorithms.html","oe",1],["Open-ended search","Search that keeps producing new and increasingly interesting results instead of converging on a single answer.","open-ended/chapters/00-start-here.html","oe",1],["OpenEvolve","An open-source Python framework that reimplements the AlphaEvolve design with a MAP-Elites grid, islands, evaluator cascades and a weighted model ensemble.","open-ended/chapters/10-evolution-frameworks.html","oe",1],["OpenID Connect","An identity layer on OAuth 2.0 that adds an ID token describing who logged in.","security/chapters/07-oauth-oidc.html","sec",0],["Open-loop load","Load generated at a fixed arrival rate regardless of how fast the system responds, like real user traffic.","reliability/chapters/10-load-testing-capacity.html","ops",0],["Open table format","A specification, such as Iceberg, Delta Lake or Hudi, for ACID tables made of files plus metadata snapshots.","data/chapters/21-data-platforms.html","data",0],["OpenTelemetry","The open standard and set of libraries for emitting traces, metrics and logs and sending them to any compatible backend.","evals/chapters/17-observability.html","evl",0],["Open-weight model","A model whose trained parameters are published for download, which is not necessarily open source and may carry a custom licence.","ai-delivery/chapters/07-choosing-models.html","aid",0],["Operating point","The chosen decision threshold on a model's scores, which sets how many true cases are caught and how many false alarms are raised.","ai-delivery/chapters/02-requirements-ambiguity.html","aid",0],["Operating point","The chosen threshold, or number of cases to act on, that turns a model's scores into decisions.","ml/chapters/15-imbalance-calibration.html","ml",0],["Operational transformation (OT)","Rewriting concurrent edits against each other so they can be applied in different orders; usually needs a central server.","distributed/chapters/15-crdts.html","dist",0],["OPRO","Optimization by PROmpting: a model is shown earlier candidate prompts with their scores and asked to propose a better one.","open-ended/chapters/11-evolving-prompts.html","oe",1],["Optical character recognition","Turning an image of text into the characters it shows, together with their positions and a confidence for each.","retrieval/chapters/19-ocr.html","ret",0],["Optimisation","Search toward a fixed objective, usually stopping when the score stops improving.","open-ended/chapters/00-start-here.html","oe",1],["Optimiser","An object that holds the parameters and turns their gradients into updates when step() is called.","deep-learning/chapters/05-pytorch.html","dl",1],["Optimiser state","The extra values an optimiser stores per weight, such as Adam's two moment estimates and the full-precision master copy of the weights.","llm-training/chapters/02-gpu-memory.html","llm",0],["Optimiser state","The extra numbers an optimiser keeps for each parameter, such as Adam's m and v, which add to training memory.","ml-foundations/chapters/10-optimisers.html","mlf",1],["Oral defence","A short conversation after a take-home in which you explain your choices, your results and their limits.","ai-delivery/chapters/18-getting-hired.html","aid",0],["Orchestrator-workers","A pattern in which a central model call decides the subtasks from the specific input, workers handle them, and a final call synthesises the results.","agents/chapters/13-workflow-patterns.html","agt",1],["Ordered target statistic","A target encoding computed for each row only from rows earlier in a random order, so a row never sees its own label.","ml/chapters/09-ensembles-boosting.html","ml",0],["Ordinary least squares","Choosing the weights that minimise the mean squared error of a linear model.","ml/chapters/05-linear-models.html","ml",1],["Orphan chunk","A chunk that has lost the context needed to interpret it, such as which company, section or quarter it refers to.","retrieval/chapters/14-chunking.html","ret",0],["Orphan row","A row whose reference to another table (such as a user id) has no matching row there.","ml-foundations/chapters/03-data-wrangling.html","mlf",0],["OR-Set","An observed-remove set CRDT: each add gets a unique tag, and a remove deletes only the tags it has seen, so a concurrent add wins.","distributed/chapters/15-crdts.html","dist",0],["Orthogonal","Perpendicular: two vectors are orthogonal when their dot product is zero.","ml-foundations/chapters/05-vectors-similarity.html","mlf",1],["Orthogonal matrix","A square matrix whose columns are perpendicular unit vectors, so that Q^T Q = I; it rotates or reflects without stretching.","ml-foundations/chapters/07-decompositions.html","mlf",0],["OSI model","A seven-layer reference model. Its layer numbers (\"layer 7\") are still common jargon.","networking/chapters/03-layers.html","net",0],["OSWorld","A benchmark of 369 computer tasks in real operating systems and applications, scored by execution-based scripts that inspect the resulting state.","agents/chapters/17-computer-use.html","agt",0],["Outcome (agent evaluation)","The final state of the environment when a trial ends, such as whether a refund exists in the database.","evals/chapters/08-agent-evals.html","evl",1],["Outlier features","A few activation channels in large transformers whose values are far larger than the rest and that make low-precision activation quantisation hard.","llm-training/chapters/19-quantisation.html","llm",0],["Out-of-bag error","The error of each row predicted using only the trees whose bootstrap sample did not include it, a free validation estimate for bagged models.","ml/chapters/09-ensembles-boosting.html","ml",0],["Out-of-fold encoding","Encoding each training row with statistics computed only from the other folds, so no row's feature contains its own label.","ml/chapters/17-feature-engineering.html","ml",0],["Out-of-fold predictions","Predictions for each training row made by a model that was trained without that row's fold.","ml/chapters/20-competitions.html","ml",0],["Out of memory (OOM)","The error raised when the memory a training step requests at its peak exceeds the GPU's capacity.","llm-training/chapters/02-gpu-memory.html","llm",0],["Output check","A guardrail that inspects the model's draft answer before the user sees it.","evals/chapters/15-guardrails.html","evl",0],["Output head","The final linear layer that maps each position's C-vector to one logit per vocabulary entry.","deep-learning/chapters/10-transformer-block.html","dl",1],["Overfitting","Learning the quirks and noise of the training examples so that performance on new data is worse than on the training set.","deep-learning/chapters/04-deep-regularisation.html","dl",1],["Overfitting","Fitting the quirks and noise of the training sample so closely that error on new data is much higher than error on training data.","ml/chapters/01-generalisation.html","ml",1],["Overfitting one batch","A debugging test: train on a single small batch and confirm the loss falls to nearly zero, which shows the whole pipeline can learn.","deep-learning/chapters/12-building-gpt.html","dl",1],["Overfitting to the test","Adjusting a prompt or system after seeing failures on the test cases until the score rises, so the final score describes the tuning effort and not the system's quality on new cases.","ai-delivery/chapters/05-riskiest-assumption.html","aid",0],["Overflow","A result larger than the format's maximum, which becomes infinity (or NaN in fp8 E4M3).","ml-foundations/chapters/11-numerics.html","mlf",0],["Over-refusal","Blocking or refusing a legitimate request because it resembles a prohibited one.","evals/chapters/15-guardrails.html","evl",0],["Over-stemming","A stemming error that merges words with different meanings, such as news and new.","retrieval/chapters/01-text-analysis.html","ret",0],["Overtraining","Training a model on more tokens than the compute-optimal amount, accepting inefficient training in return for a smaller and cheaper model to serve.","deep-learning/chapters/18-scaling-laws.html","dl",0],["PACELC","Extends CAP: under a Partition choose Availability or Consistency; Else choose Latency or Consistency (Abadi, 2012).","distributed/chapters/02-impossibility.html","dist",0],["Packet","The unit of data at the network (IP) layer: a header with addresses plus a payload.","networking/chapters/00-start-here.html","net",0],["Packet switching","Splitting data into packets that share links with everyone else's traffic.","networking/chapters/00-start-here.html","net",0],["Packing","Concatenating several short training examples into one fixed-length row to avoid padding, which requires attention that does not cross example boundaries.","llm-training/chapters/10-sft.html","llm",1],["Padding","Adding a border of zeros around the input so that edge pixels are covered as often as central ones and the output keeps its size.","deep-learning/chapters/07-convolutions.html","dl",0],["Padding mask","A mask that stops queries attending to the dummy tokens used to pad short sequences to a common batch length.","deep-learning/chapters/09-attention.html","dl",1],["Page","The fixed-size unit of virtual memory (commonly 4 KiB; 16 KiB on Apple Silicon) that the kernel maps to physical frames.","systems/chapters/06-virtual-memory.html","sys",0],["Page cache","The kernel's copy of file data in RAM. Reads are served from it when possible, and writes land in it first.","systems/chapters/09-durability.html","sys",0],["Page (database)","The fixed-size block (often 4 to 16 KiB) a database reads and writes as one unit.","data/chapters/06-b-trees.html","data",0],["PagedAttention","An attention implementation that stores the KV cache in fixed-size blocks found through a block table, so a sequence's cache need not be contiguous.","llm-training/chapters/20-serving-engines.html","llm",0],["Page description language","A language that describes what to draw and where on a page, such as the operators in a PDF content stream, rather than the document's paragraphs and headings.","retrieval/chapters/18-pdf-layout.html","ret",0],["Paged optimiser","Optimiser state held in memory that can move between GPU and CPU on demand, so a short memory spike does not crash a run.","llm-training/chapters/11-lora.html","llm",1],["Page fault","What happens when a program touches a page that isn't currently mapped: the kernel steps in, maps it (maybe reading from disk) and resumes.","systems/chapters/06-virtual-memory.html","sys",0],["Page-level retrieval","Returning whole pages as the retrieval unit, so a separate step is needed to locate or quote the evidence within the page.","retrieval/chapters/21-visual-retrieval.html","ret",0],["Page table","The kernel's map from a process's virtual pages to physical memory frames.","systems/chapters/06-virtual-memory.html","sys",0],["Paired bootstrap","Resampling evaluation items with both models' outcomes kept together to get an interval for the difference in their scores.","llm-training/chapters/23-evaluating-models.html","llm",0],["Paired bootstrap","Resampling the same test rows with replacement and recomputing two models' scores each time to get an interval for their difference.","ml/chapters/04-baselines.html","ml",1],["Paired bootstrap","A bootstrap that resamples whole questions so each keeps both systems' results together, giving a tighter interval for the difference.","ml-foundations/chapters/15-statistics.html","mlf",1],["Paired bootstrap","Resampling test items together for two systems so that shared item difficulty cancels and the interval for their difference narrows.","open-ended/chapters/16-held-out-evaluation.html","oe",1],["Paired comparison","Running the same test cases through two versions and comparing them case by case, which detects small differences far better than comparing two totals.","agents/chapters/04-prompting.html","agt",1],["Paired difference","The per-question difference between two systems' scores on the same questions, used so shared difficulty cancels out of the comparison.","evals/chapters/04-eval-statistics.html","evl",1],["Pairwise accuracy","The fraction of held-out preference pairs on which a reward model scores the chosen response above the rejected one, capped by label noise.","llm-training/chapters/13-reward-models.html","llm",1],["Pairwise comparison","A judgement in which a judge sees two answers to the same question and says which is better.","evals/chapters/03-llm-judges.html","evl",1],["Pairwise reranking","Asking a model which of two candidates is more relevant and building an order from many such comparisons.","retrieval/chapters/08-rerankers.html","ret",0],["Parallel block","A block variant that computes attention and the MLP from the same normalised input and adds both outputs to the stream.","deep-learning/chapters/10-transformer-block.html","dl",1],["Parallel scan","An algorithm that computes a linear recurrence over a whole sequence in parallel instead of one step at a time.","deep-learning/chapters/22-beyond-attention.html","dl",0],["Parallel tool calls","Several tool_use blocks in one assistant turn, all of which must be answered together in the next user message.","agents/chapters/02-tool-loop.html","agt",1],["Parameter","An adjustable number inside a model, also called a weight, set during training.","deep-learning/chapters/00-start-here.html","dl",0],["Parameter-efficient fine-tuning (PEFT)","The family of methods, including LoRA, adapters and prompt tuning, that adapt a model by training only a small number of added or selected parameters.","llm-training/chapters/11-lora.html","llm",1],["Parameterized query","A query whose structure is fixed and whose values are passed separately, so input can never become code.","security/chapters/09-injection.html","sec",0],["Parameters","The adjustable numbers inside a model that training changes to reduce the loss.","ml-foundations/chapters/00-start-here.html","mlf",1],["Parametric loss fit","The model L(N, D) = E + A/N^a + B/D^b fitted to training runs, with an irreducible term, a capacity term and a data term.","deep-learning/chapters/18-scaling-laws.html","dl",0],["Parametric memory","Knowledge stored in a model's weights during training, which cannot be inspected, cited or cheaply corrected.","retrieval/chapters/13-rag-end-to-end.html","ret",0],["Parent-child retrieval","Matching small child chunks in the index but returning the larger parent passage that contains them, also called small-to-big retrieval.","retrieval/chapters/14-chunking.html","ret",0],["Parent sampling","The rule that chooses which stored program a new mutation starts from, balancing fitness against how much that program has already been tried.","open-ended/chapters/10-evolution-frameworks.html","oe",1],["Parent selection","The random choice of which archived agent to modify next, weighted by a sigmoid of its score times 1/(1 + number of its children).","open-ended/chapters/13-self-improving-agents.html","oe",1],["Pareto front","The set of configurations that no other configuration beats on every axis at once, such as quality, cost and latency.","evals/chapters/19-cost-latency-quality.html","evl",0],["Partial dependence","The average model prediction as one feature is set to each value in a grid for every row, showing the model's average response to it.","ml/chapters/16-interpretability.html","ml",0],["Partial derivative","The derivative of a function of several variables with respect to one of them, holding the others fixed.","ml-foundations/chapters/08-derivatives.html","mlf",1],["Partial synchrony","A model in which bounds on delay exist but are unknown, or hold only after some unknown global stabilisation time (GST).","distributed/chapters/01-system-models.html","dist",0],["Partitioning (sharding)","Splitting a dataset across machines so each holds only part of it.","networking/chapters/19-partitioning.html","net",0],["pass@k","The chance that at least one of k attempts at a task succeeds, a measure of capability that rises with k.","evals/chapters/08-agent-evals.html","evl",1],["pass^k","The chance that all k attempts at a task succeed, a measure of reliability that falls as k grows.","evals/chapters/08-agent-evals.html","evl",1],["Pass@k","The probability that at least one of k sampled answers to a problem is correct, a measure of what a model can do given several attempts.","llm-training/chapters/14-rlvr-grpo.html","llm",1],["pass@k","The chance that at least one of k samples for a problem is correct, usually estimated from a larger batch of samples with an unbiased formula.","open-ended/chapters/08-inference-time-search.html","oe",1],["Passkey (WebAuthn)","A phishing-resistant credential: a key pair bound to a site's origin, with the private key kept on the user's device.","security/chapters/05-authentication.html","sec",0],["Password hashing function","A deliberately slow, often memory-hard function such as Argon2id, scrypt or bcrypt for storing passwords.","security/chapters/05-authentication.html","sec",0],["Patch","A small non-overlapping square of an image, typically 14 or 16 pixels wide, flattened and embedded as one token.","deep-learning/chapters/21-vision-language.html","dl",0],["Patch pooling","Merging neighbouring patch vectors to shrink a multi-vector index, at some cost in accuracy.","retrieval/chapters/21-visual-retrieval.html","ret",0],["Path length","The number of splits needed to isolate a point in a random tree, averaged over trees to give an isolation score.","ml/chapters/12-anomaly-detection.html","ml",0],["Path traversal","Using ../ or absolute paths in input to reach files outside an intended directory.","security/chapters/09-injection.html","sec",0],["Patience","The number of evaluations without improvement that early stopping tolerates before it ends the run.","deep-learning/chapters/04-deep-regularisation.html","dl",1],["Paved road","A secure-by-default platform or library that makes the safe way the easiest way.","security/chapters/19-secure-design-review.html","sec",0],["Paxos","A consensus protocol in which proposers use numbered ballots in two phases (prepare/promise, accept/accepted) to get a majority of acceptors to choose one value (Lamport).","distributed/chapters/09-paxos.html","dist",0],["Payback","The time until a project's cumulative net benefit turns positive.","ai-delivery/chapters/14-cost-roi.html","aid",0],["Payload","The contents a protocol carries for the layer above, without reading it.","networking/chapters/03-layers.html","net",0],["PBFT","Practical Byzantine Fault Tolerance: a state-machine replication protocol tolerating f Byzantine nodes out of 3f+1 (Castro & Liskov, 1999).","distributed/chapters/12-byzantine.html","dist",0],["PDF","Portable Document Format, a file format that stores instructions for painting pages so they look identical everywhere, not the logical structure of the document.","retrieval/chapters/18-pdf-layout.html","ret",0],["Peak factor","The ratio of peak traffic to average traffic, used to size for the busiest time rather than the mean.","design/chapters/02-estimation.html","design",0],["Peak throughput","The most floating-point operations per second a chip could perform if every arithmetic unit were busy, as quoted on its datasheet.","deep-learning/chapters/16-resource-accounting.html","dl",1],["Peak-to-average ratio","How much busier the busiest period is than the average, which sets how many GPUs must be provisioned.","llm-training/chapters/22-token-economics.html","llm",0],["Peeking","Checking an experiment repeatedly and stopping at the first significant result, which inflates the false-positive rate.","ml/chapters/21-model-to-value.html","ml",0],["Peeking","Checking a running experiment repeatedly and stopping at the first significant result, which inflates the false-positive rate well above the nominal level.","ml-foundations/chapters/15-statistics.html","mlf",1],["Percentile (p99)","The value below which a given percentage of measurements fall. p99 latency: 99% of requests are faster.","networking/chapters/13-performance.html","net",0],["Perception gap","The difference between how much faster people feel an AI tool makes them and the change in their measured task time, as seen in METR's 2025 trial.","agents/chapters/22-ai-coding-tools.html","agt",0],["Per-channel quantisation","Using a separate scale for each output channel (row) of a weight matrix.","llm-training/chapters/19-quantisation.html","llm",0],["Permission","A rule in the agent harness that allows, asks about or denies a given tool call before it runs.","agents/chapters/20-sandboxing.html","agt",1],["Permission fingerprint","A hash of a caller's identity set or policy version, included in cache keys so personalised answers are never shared across different permissions.","retrieval/chapters/12-filters-permissions.html","ret",0],["Permutation equivariance","The property that reordering the input tokens reorders the outputs in the same way, which pure self-attention has because it ignores token indices.","deep-learning/chapters/11-positions.html","dl",1],["Permutation importance","The drop in a model's held-out score when one feature's values are shuffled, showing how much the model relies on that feature.","ml/chapters/16-interpretability.html","ml",0],["Permutation test","A hypothesis test that shuffles group labels many times to build the null distribution of a statistic without any formula.","ml-foundations/chapters/15-statistics.html","mlf",1],["Perplexity","The exponential of the average loss in nats: the number of equally likely options the model is, on average, as unsure among.","deep-learning/chapters/14-language-modelling.html","dl",1],["Perplexity","The t-SNE setting that fixes the effective number of neighbours each point considers, typically between 5 and 50.","ml/chapters/11-dimensionality-reduction.html","ml",0],["Perplexity","Two raised to the cross-entropy in bits: the effective number of equally likely choices per token.","ml-foundations/chapters/14-information-theory.html","mlf",1],["Personal data","Any information relating to an identified or identifiable person, including data that is only linked to someone through other records.","evals/chapters/22-privacy-data.html","evl",0],["Personally identifiable information (PII)","Data that identifies a person or can be linked to one, such as names, email addresses, phone numbers and card numbers.","evals/chapters/15-guardrails.html","evl",0],["Phantom","A write in one transaction changes which rows match another transaction's search.","data/chapters/11-isolation.html","data",0],["Phi accrual failure detector","A detector that outputs a suspicion level computed from the distribution of past heartbeat intervals, instead of a yes/no timeout.","distributed/chapters/03-failure-detection.html","dist",0],["Phrase query","A query matching documents where terms occur at consecutive positions, which needs positions stored in the index.","retrieval/chapters/02-bm25.html","ret",0],["Picbreeder","A website where people evolve images by choosing the ones they find interesting, used to study how discoveries arise without a fixed goal.","open-ended/chapters/03-novelty-search.html","oe",1],["PII","Personally identifiable information, the US term for data that identifies a person, usually narrower than the GDPR's personal data.","evals/chapters/22-privacy-data.html","evl",0],["Pilot","A limited trial with real users on real work for a fixed period, used to learn whether a system works in the customer's setting.","ai-delivery/chapters/12-poc-to-production.html","aid",0],["Pilot light","A disaster-recovery strategy in which a minimal copy of core infrastructure runs in another region, ready to be scaled up.","reliability/chapters/18-disaster-recovery.html","ops",0],["Pinball loss","An asymmetric absolute-error loss whose minimiser is a chosen quantile of the outcome distribution.","ml/chapters/02-framing-metrics.html","ml",1],["Ping","A tool that sends ICMP echo requests and measures round-trip time.","networking/chapters/06-arp-dhcp-icmp.html","net",0],["Pipe","A one-way channel between processes: bytes written into one end come out of the other, as in ls | wc -l.","systems/chapters/08-files.html","sys",0],["Pipeline bubble","The idle time of pipeline stages at the start and end of a step, equal to (p-1)/(m+p-1) of the schedule for p stages and m micro-batches.","llm-training/chapters/03-parallelism.html","llm",0],["Pipeline parallelism","Splitting a model's layers into consecutive stages on different GPUs and streaming micro-batches through them.","llm-training/chapters/03-parallelism.html","llm",0],["PKCE","Proof Key for Code Exchange: the client sends a hash of a secret verifier with the request and the verifier with the exchange, so a stolen code is useless (RFC 7636).","security/chapters/07-oauth-oidc.html","sec",0],["PLAID","A search engine for ColBERT-style indexes that prunes passages using centroid ids before computing full MaxSim.","retrieval/chapters/09-late-interaction-sparse.html","ret",0],["Plan mode","A coding-agent mode in which the agent may read and search but not change anything, so exploration and planning cannot damage the repository.","agents/chapters/22-ai-coding-tools.html","agt",0],["Planner","The model call that turns a goal into an explicit list of steps before any step is executed.","agents/chapters/03-reasoning-planning.html","agt",1],["Plan-then-execute","An agent design in which a planner first writes an explicit list of steps and an executor then carries them out, with a bounded replan on failure.","agents/chapters/03-reasoning-planning.html","agt",1],["Plan-then-execute","A pattern in which the agent fixes its sequence of tool calls before reading any untrusted data.","evals/chapters/14-architectural-defences.html","evl",0],["Platt scaling","Recalibration that fits a two-parameter logistic regression to the logit of a model's scores on held-out data.","ml/chapters/15-imbalance-calibration.html","ml",0],["Playbook","A set of preferred positions and fallback terms against which a lawyer or tool compares the clauses of a contract under review.","ai-delivery/chapters/10-legal.html","aid",0],["Pod","Kubernetes' smallest deployable unit: one or more containers sharing a network namespace and storage.","reliability/chapters/14-orchestration.html","ops",0],["POET","Paired Open-Ended Trailblazer: an algorithm that evolves a population of environments together with the agents that solve them, and transfers agents between environments.","open-ended/chapters/05-open-ended-algorithms.html","oe",1],["Point-in-time recovery","Restoring a base backup and replaying the archived log up to a chosen moment.","data/chapters/13-crash-recovery.html","data",0],["Pointwise mutual information","The log of how much more often two words occur together than they would if they were unrelated.","deep-learning/chapters/06-embeddings.html","dl",1],["Pointwise reranking","Scoring each candidate independently, for example the probability that a model answers yes to 'is this relevant?'.","retrieval/chapters/08-rerankers.html","ret",0],["Poison step","A step that crashes the process every time it runs, so a resuming agent loops on it unless attempts are counted and limited.","agents/chapters/15-durable-execution.html","agt",0],["Poka-yoke","Mistake-proofing: designing an interface, for example with enums and bounded types, so that the wrong call is hard or impossible to write.","agents/chapters/05-tool-design.html","agt",1],["Policy enforcement point","The component that intercepts requests and applies decisions from a policy decision point, as in NIST SP 800-207.","security/chapters/13-zero-trust.html","sec",0],["Policy engine","A component that evaluates authorization policies written separately from application code, such as OPA or Cedar.","security/chapters/08-authorization.html","sec",0],["Policy gate","Deterministic code between the model's proposed action and the real mouse and keyboard that allows, requires confirmation for, or denies the action.","agents/chapters/17-computer-use.html","agt",0],["Policy gradient","The gradient of expected reward with respect to a policy's parameters, estimable from samples as the reward-weighted gradient of log-probabilities.","llm-training/chapters/07-policy-gradients.html","llm",1],["Policy (reinforcement learning)","The rule an agent uses to choose actions, written as a probability distribution over actions given the current state.","llm-training/chapters/06-bandits-mdps.html","llm",1],["Politeness","A crawler's rules for not overloading any one site: per-host rate limits and respecting robots.txt.","design/chapters/18-web-crawler.html","design",0],["Polyglot benchmark","The Aider team's benchmark of programming exercises across several languages, used to test coding agents.","open-ended/chapters/13-self-improving-agents.html","oe",1],["Pool depth","How many top results from each contributing system are added to the pool for judging.","retrieval/chapters/05-test-collections.html","ret",0],["Pooling","Replacing each small window of a feature map by a single summary value such as its maximum or mean.","deep-learning/chapters/07-convolutions.html","dl",0],["Pooling","Judging only the union of the top results from several different retrieval systems, and treating everything else as non-relevant.","retrieval/chapters/05-test-collections.html","ret",0],["Population stability index","A drift score that bins a feature by training quantiles and sums the log-ratio-weighted differences in bin shares between two datasets.","ml/chapters/03-eda.html","ml",0],["Population stability index (PSI)","A drift measure summing (current share minus reference share) times the log of their ratio across bins of the reference distribution.","ml/chapters/21-model-to-value.html","ml",0],["Port","A 16-bit number identifying which program on a computer should receive the data.","networking/chapters/07-ports-udp.html","net",0],["Portfolio","The projects and writing a reviewer can inspect without you present, whose job is to make the claims on your CV checkable.","ai-delivery/chapters/18-getting-hired.html","aid",0],["Ports and adapters (hexagonal)","The core defines interfaces (ports) for what it needs; adapters implement them for databases, HTTP, queues and tests.","architecture/chapters/05-hexagonal.html","arch",0],["Positional encoding","Information added to a Transformer so that it can tell where in the sequence each token sits.","deep-learning/chapters/11-positions.html","dl",1],["Position bias","A judge's tendency to prefer the answer shown first or second regardless of content.","evals/chapters/03-llm-judges.html","evl",1],["Position interpolation","Extending a RoPE model's context by scaling positions down into the range seen in training and then fine-tuning briefly.","deep-learning/chapters/11-positions.html","dl",1],["Position-wise","Applied to each token position separately with the same weights, so it cannot move information between positions.","deep-learning/chapters/10-transformer-block.html","dl",1],["Postcondition check","Verifying after an action that the screen shows the state the action should have produced, rather than trusting the harness's report that the event was delivered.","agents/chapters/17-computer-use.html","agt",0],["Post-filtering","Running the approximate search first and then discarding results that fail the filter, which can leave fewer than k results.","retrieval/chapters/12-filters-permissions.html","ret",0],["Post-hoc explanation","An explanation computed after training for a model that is not itself readable.","ml/chapters/16-interpretability.html","ml",0],["Postings list","The list of entries for one term, each holding a document id, the term frequency and optionally the positions.","retrieval/chapters/02-bm25.html","ret",0],["Post-norm","Normalising after the residual addition, LN(x + F(x)), as in the original Transformer.","deep-learning/chapters/03-training-dynamics.html","dl",1],["Post-rationalisation","Finding a passage that supports a claim after the fact, so the citation is correct but the model did not use it to produce the claim.","retrieval/chapters/16-grounded-citations.html","ret",0],["Post-training","All training after pretraining, including supervised fine-tuning, preference learning, reinforcement learning and distillation.","llm-training/chapters/00-start-here.html","llm",0],["Power iteration","Repeatedly multiplying a vector by a matrix and renormalising, which converges to the top eigenvector.","ml-foundations/chapters/07-decompositions.html","mlf",0],["Power law","A relationship y = a x^b, which is a straight line on log-log axes and changes y by a fixed factor for each fixed factor in x.","deep-learning/chapters/18-scaling-laws.html","dl",0],["PPO clip","PPO's objective min(rA, clip(r, 1-eps, 1+eps)A), which stops a token earning more credit once its probability has moved eps in the helpful direction.","llm-training/chapters/08-ppo.html","llm",1],["Pre-activation","The weighted sum plus bias of a neuron before the activation function is applied, usually written z.","deep-learning/chapters/01-neurons-layers.html","dl",1],["Precision","Of the cases the model flagged as positive, the fraction that really are positive.","ml/chapters/02-framing-metrics.html","ml",1],["Precision at k","The fraction of positives among the k highest-scored cases, matching decisions limited by review capacity.","ml/chapters/02-framing-metrics.html","ml",1],["Precision at k","The fraction of the first k results that are relevant.","retrieval/chapters/04-relevance-metrics.html","ret",0],["Predetermined change control plan","A plan agreed with the FDA in advance describing which model changes a manufacturer may make, and how they are validated, without a new submission each time.","ai-delivery/chapters/09-healthcare.html","aid",0],["Predict, ask, read, verify, explain back","A five-step routine for using an assistant to learn: forecast the answer, ask why, read every line, check independently, then explain it without help.","ml-foundations/chapters/19-ai-assistants.html","mlf",0],["Prediction interval","A range expected to contain the future value with a stated probability, such as 80%.","ml/chapters/18-time-series.html","ml",0],["Prediction task","A precise statement of what is predicted, for which unit, at what time, from which features, and for which decision.","ml/chapters/02-framing-metrics.html","ml",1],["Preemption (serving)","Evicting a running sequence to free cache blocks, then resuming it later by recomputation or by swapping its blocks back from CPU memory.","llm-training/chapters/20-serving-engines.html","llm",0],["Preference optimisation","The family of methods, including RLHF, DPO and their relatives, that tune a model towards responses people prefer using comparisons rather than demonstrations.","llm-training/chapters/12-preference-optimisation.html","llm",1],["Preference pair","A prompt together with a chosen (preferred) response and a rejected response, the basic unit of data for preference optimisation.","llm-training/chapters/12-preference-optimisation.html","llm",1],["Prefill","The phase in which a model processes the whole prompt before producing its first output token, whose time grows with prompt length.","agents/chapters/12-long-context.html","agt",0],["Prefill","The first phase of serving, in which the whole prompt is processed in one parallel pass before any token is generated.","deep-learning/chapters/19-efficient-attention.html","dl",0],["Prefill","The first phase of generation, in which the whole prompt is processed in parallel and its keys and values are written to the cache.","llm-training/chapters/18-kv-cache.html","llm",0],["Pre-filtering","Applying the filter first and then searching only the passing documents, usually with an exact scan when few documents pass.","retrieval/chapters/12-filters-permissions.html","ret",0],["Premature convergence","A population settling on a mediocre solution because it lost its diversity before finding better regions.","open-ended/chapters/02-evolutionary-algorithms.html","oe",1],["Premortem","A technique in which the team imagines the project has failed and writes down the reasons, to surface risks and unstated assumptions early.","ai-delivery/chapters/02-requirements-ambiguity.html","aid",0],["Pre-norm","Placing normalisation inside the residual branch, x + F(LN(x)), so the skip path stays clean.","deep-learning/chapters/03-training-dynamics.html","dl",1],["Preprocessing leakage","Leakage from a learned step such as scaling, imputation or feature selection being fitted on validation rows before the split.","ml/chapters/14-leakage.html","ml",1],["Presence","Knowing which users are online, usually from heartbeats with timeouts, and telling interested users.","design/chapters/10-chat-presence.html","design",0],["Presentation forms","Unicode code points for the shaped glyphs of connected scripts such as Arabic, which PDFs often store instead of the base letters and which NFKC maps back.","retrieval/chapters/22-multilingual.html","ret",0],["Presumed abort","A 2PC optimisation: if no decision record is found, the outcome is assumed to be abort, so aborts need less logging.","distributed/chapters/13-atomic-commit.html","dist",0],["Pre-tokenisation","Splitting text into words, numbers and punctuation with a regular expression before merging, so that tokens do not cross those boundaries.","deep-learning/chapters/13-tokenisation.html","dl",1],["Pretraining","The first and most expensive training stage, in which a model learns to predict the next token over trillions of tokens of text.","llm-training/chapters/00-start-here.html","llm",0],["Pre-vote","A Raft extension in which a node first checks it could win an election before disrupting the cluster by raising its term.","distributed/chapters/10-raft-deep.html","dist",0],["Primary key","The column (or columns) that uniquely identifies each row in a table.","data/chapters/02-sql-relational.html","data",0],["Primary source","The original paper, specification, changelog or data behind a claim, as opposed to a summary or commentary on it.","ai-delivery/chapters/19-where-next.html","aid",0],["Principal component","One of the orthogonal directions found by PCA, ordered by how much variance the data has along it.","ml/chapters/11-dimensionality-reduction.html","ml",0],["Principal component analysis","Finding the orthogonal directions of greatest variance in data as the eigenvectors of its covariance matrix.","ml-foundations/chapters/07-decompositions.html","mlf",0],["Principal component analysis (PCA)","A linear method that finds orthogonal directions of maximum variance and projects the data onto the first few of them.","ml/chapters/11-dimensionality-reduction.html","ml",0],["Prior","The probability of a class before looking at any features, usually its frequency in the training data.","ml/chapters/07-neighbours-bayes.html","ml",1],["Prior","A probability distribution over parameters expressing belief before seeing data; a Gaussian prior gives L2 regularisation.","ml-foundations/chapters/13-likelihood-losses.html","mlf",1],["Prior and posterior","The prior is belief about a hypothesis before seeing evidence; the posterior is the updated belief afterwards.","ml-foundations/chapters/12-probability.html","mlf",1],["Priority inversion","A high-priority task stuck waiting for a lock held by a low-priority task that can't run. Fixed by priority inheritance.","systems/chapters/13-deadlock.html","sys",0],["Prior shift","A change in the share of positives between training and deployment while the feature distribution within each class stays the same.","ml/chapters/15-imbalance-calibration.html","ml",0],["Private endpoint","A way to reach a service over the provider's private network instead of the public internet.","networking/chapters/22-cloud-networking.html","net",0],["Private leaderboard","The final competition ranking, computed on the part of the test set that stays hidden until the end.","ml/chapters/20-competitions.html","ml",0],["Probability density function","A curve whose area over an interval is the probability that a continuous variable lands in it; its height is probability per unit, so it can exceed 1.","ml-foundations/chapters/12-probability.html","mlf",1],["Probability ratio","The new policy's probability of a sampled token divided by the old policy's, used to reweight old samples and equal to 1 when nothing has changed.","llm-training/chapters/08-ppo.html","llm",1],["Problem details","A standard JSON format for HTTP API errors (RFC 9457).","architecture/chapters/09-api-design.html","arch",0],["Procedural memory","Stored knowledge of how to do recurring jobs, implemented in agents as skills, checklists or scripts.","agents/chapters/11-memory.html","agt",1],["Process","A running program: its own private memory, open files and at least one thread, managed by the operating system.","systems/chapters/05-processes.html","sys",0],["Process reward model","A reward model that scores each step of a reasoning chain rather than only the final answer, giving denser but costlier supervision.","llm-training/chapters/13-reward-models.html","llm",1],["Process reward model","A model that scores each intermediate step of a reasoning chain rather than only the final answer.","open-ended/chapters/08-inference-time-search.html","oe",1],["Production gate","A named launch condition backed by evidence that an outsider can inspect, with a person who may say no.","ai-delivery/chapters/12-poc-to-production.html","aid",0],["Production (system state)","The state in which people rely on a system for their normal work, it keeps running unattended, and someone is accountable for it.","ai-delivery/chapters/12-poc-to-production.html","aid",0],["Product quantisation","Compressing a vector by cutting it into sub-vectors and storing, for each, the one-byte id of its nearest centroid in a learned codebook.","retrieval/chapters/11-ann-indexes.html","ret",1],["Program search","Search in which the candidates are programs, scored by running them, so that the result is a procedure rather than a single answer.","open-ended/chapters/09-program-evolution.html","oe",1],["Program signature","The tuple of scores a program obtains on a set of test inputs, used to cluster programs that behave alike.","open-ended/chapters/09-program-evolution.html","oe",1],["Progressive delivery","Rolling a change out in widening waves, such as one cell, one zone, one region, then everywhere, with checks between waves.","reliability/chapters/12-deployments.html","ops",0],["Progressive disclosure","Letting an agent discover context step by step, with each retrieved piece guiding what to look at next, so the window holds only what was chosen.","agents/chapters/10-context-engineering.html","agt",1],["Projection","A read model built by processing a stream of events.","architecture/chapters/16-cqrs-event-sourcing.html","arch",0],["Projection","The part of a vector that lies along a given direction, found by scaling that direction by (x . w)/(w . w).","ml-foundations/chapters/05-vectors-similarity.html","mlf",1],["Projector","A linear layer or small MLP that maps image-encoder features to the language model's embedding width.","deep-learning/chapters/21-vision-language.html","dl",0],["Prompt","The text, including instructions, examples and input, that a model is given to complete; in practice a program written in natural language.","agents/chapters/04-prompting.html","agt",1],["Promptbreeder","A prompt-evolution method that also evolves the mutation-prompts that rewrite the task prompts.","open-ended/chapters/11-evolving-prompts.html","oe",1],["Prompt caching","Storing the processed form of a repeated prompt prefix so later calls read it at a reduced price and latency.","agents/chapters/02-tool-loop.html","agt",1],["Prompt caching","A provider feature that bills a repeated, identical prompt prefix at a reduced rate when it is read again from a cache.","ai-delivery/chapters/14-cost-roi.html","aid",0],["Prompt caching","Provider-side reuse of the model's computation on the start of a prompt, so a repeated prefix is read at a discount.","evals/chapters/19-cost-latency-quality.html","evl",0],["Prompt caching","Storing the processed form of a repeated prompt prefix so later requests that reuse it are cheaper and faster.","retrieval/chapters/14-chunking.html","ret",0],["Prompt chaining","Splitting a task into a fixed sequence of model calls in which each call processes the previous one's output, trading latency for accuracy.","agents/chapters/13-workflow-patterns.html","agt",1],["Prompt injection","Text in a model's input that is meant to be data but is obeyed as instructions, causing behaviour the operator or user did not intend.","agents/chapters/19-agent-security.html","agt",1],["Prompt injection","Text that makes a model follow instructions from an untrusted source instead of, or alongside, the instructions of the application's developer.","evals/chapters/13-prompt-injection.html","evl",0],["Prompt leaking","Extracting the hidden system prompt or other instructions a developer gave the model.","evals/chapters/13-prompt-injection.html","evl",0],["Prompt lookup decoding","Drafting by copying the tokens that followed an earlier occurrence of the latest tokens in the prompt, with no draft model.","llm-training/chapters/21-speculative-decoding.html","llm",0],["Prompt optimisation","Searching over the text of prompts, and the examples included in them, to maximise a metric measured on a development set.","open-ended/chapters/11-evolving-prompts.html","oe",1],["Prompt template","A reviewed prompt text with named placeholders that are filled, with escaping, by the data of each request.","agents/chapters/04-prompting.html","agt",1],["Prompt test set","A table of inputs, expected results and checks used to compare prompt versions and catch regressions after a prompt or model change.","agents/chapters/04-prompting.html","agt",1],["Prompt versioning","Keeping prompts in version control with an identifier logged on every request, so any output can be traced to the exact prompt that produced it.","agents/chapters/04-prompting.html","agt",1],["Proof of concept","A small build that shows whether an idea can work at all, before anyone commits to making it reliable.","ai-delivery/chapters/12-poc-to-production.html","aid",0],["Propagation delay","Time for a signal to physically travel the distance, limited by the speed of light.","networking/chapters/01-bits-and-signals.html","net",0],["Proper scoring rule","A loss whose expected value is minimised only when the model reports the true probabilities, so it rewards calibration.","ml-foundations/chapters/13-likelihood-losses.html","mlf",1],["Proposer","The part of a search loop that makes a changed copy of a candidate, such as a random mutation or a language model's edit.","open-ended/chapters/00-start-here.html","oe",1],["Proposition","A short self-contained statement, with pronouns resolved, extracted from a passage and used as a fine-grained retrieval unit.","retrieval/chapters/14-chunking.html","ret",0],["Protected health information","Individually identifiable health information held or sent by a covered entity or its business associate, which HIPAA restricts and requires safeguards for.","ai-delivery/chapters/09-healthcare.html","aid",0],["Protected resource metadata","A document (RFC 9728) that an MCP server publishes to name the authorisation servers able to issue tokens for it.","agents/chapters/08-mcp-production.html","agt",0],["Protocol","An agreed set of rules for exchanging messages.","networking/chapters/00-start-here.html","net",0],["Protocol Buffers","A binary encoding with a schema where each field has a numbered tag, so fields can be added without breaking old readers.","data/chapters/03-encoding.html","data",0],["Provenance","Metadata recording where a value came from and which other values it was derived from.","evals/chapters/14-architectural-defences.html","evl",0],["Provider and deployer","The EU AI Act roles of the party that develops and places an AI system on the market and the party that uses it professionally under its own authority.","evals/chapters/21-governance.html","evl",0],["Provider-neutral adapter","A thin layer that converts one internal message and tool format to and from each model API's wire format, keeping the agent loop independent of the provider.","agents/chapters/06-function-calling.html","agt",0],["Proximity graph","A graph that links each vector to some of its near neighbours so a search can walk towards a query.","retrieval/chapters/11-ann-indexes.html","ret",1],["Proxy","A measurable stand-in for the outcome you actually want, such as test pass rate standing in for correctness.","open-ended/chapters/15-evaluator-hacking.html","oe",1],["Proxy label","A measurable stand-in used as the target when the quantity you care about cannot be observed, which carries its own flaws into the model.","ml/chapters/02-framing-metrics.html","ml",1],["Proxy (reverse proxy)","A server that sits in front of other servers and forwards requests to them.","networking/chapters/14-load-balancers.html","net",0],["Proxy reward and gold reward","The proxy is the learned reward the optimiser sees; the gold reward is the trusted ground-truth measure used to check what optimisation actually achieved.","llm-training/chapters/13-reward-models.html","llm",1],["Pseudonymisation","Replacing identifiers so data cannot be linked to a person without extra information kept separately; unlike anonymisation, it is reversible in principle.","security/chapters/17-data-protection.html","sec",0],["Pseudonymisation","Replacing each personal value with a consistent placeholder while keeping the mapping separately so it can be reversed.","evals/chapters/15-guardrails.html","evl",0],["Pseudorandom number generator","A deterministic procedure that turns a seed into a long sequence of numbers that behave like random ones.","ml-foundations/chapters/04-reproducible-experiments.html","mlf",1],["Pseudo-relevance feedback","Treating the top results of a first search as relevant and adding their characteristic terms to a second search.","retrieval/chapters/03-query-understanding.html","ret",0],["Pseudo-residual","The negative gradient of the loss at a row's current prediction, which equals the ordinary residual for squared error.","ml/chapters/09-ensembles-boosting.html","ml",0],["Public leaderboard","The ranking shown during a competition, computed on a public part of the hidden test set.","ml/chapters/20-competitions.html","ml",0],["PUCT","The AlphaZero selection rule, which scales the exploration bonus by the network's prior probability for each move.","open-ended/chapters/01-tree-search.html","oe",1],["Purpose limitation","The principle that data collected for one purpose should not be reused for an incompatible one.","evals/chapters/22-privacy-data.html","evl",0],["Push notification (A2A)","A webhook call that an A2A server makes to a client-registered URL when a long-running task changes, sparing the client from polling.","agents/chapters/09-agent-to-agent.html","agt",0],["p-value","The probability, if the null hypothesis were true, of a result at least as extreme as the one observed; it is not the probability that the null is true.","ml-foundations/chapters/15-statistics.html","mlf",1],["QDAIF","Quality-Diversity through AI Feedback: a method where a language model proposes variations and judges quality and diversity of the candidates.","open-ended/chapters/04-quality-diversity.html","oe",1],["QD-score","The sum of the qualities of all elites in an archive, which rises when cells are filled or improved.","open-ended/chapters/04-quality-diversity.html","oe",1],["QK-normalisation","Applying a normalisation to queries and keys before their dot product, which stops attention logits growing without bound.","deep-learning/chapters/17-training-stability.html","dl",0],["QLoRA","LoRA training on top of a frozen base model stored in 4-bit NormalFloat, with double quantisation and paged optimisers to cut memory.","llm-training/chapters/11-lora.html","llm",1],["Qrels","Query relevance labels: the file of judged (query, document, grade) triples that metrics are computed against.","retrieval/chapters/05-test-collections.html","ret",0],["Quadtree","A tree that recursively splits a 2-D area into four quadrants, used for spatial queries.","design/chapters/14-ride-matching.html","design",0],["Quality classifier","A small model trained to score how closely a document resembles a reference set of good text, used to keep the highest-scoring pages.","llm-training/chapters/01-pretraining-data.html","llm",0],["Quality-diversity","A family of search algorithms that return many different solutions, each as good as possible for its kind of behaviour, instead of one best solution.","open-ended/chapters/04-quality-diversity.html","oe",1],["Quantile transform","Replacing each column's values by their rank, rescaled to a uniform or normal shape, to tame skew and outliers.","ml/chapters/19-tabular-deep-learning.html","ml",0],["Quantisation","Storing a model's weights in fewer bits, such as 8 or 4, to cut memory use at some cost in quality that must be re-measured.","ai-delivery/chapters/07-choosing-models.html","aid",0],["Quantisation","Storing weights, activations or cache entries with fewer bits by mapping each value to the nearest of a small set of allowed values.","llm-training/chapters/19-quantisation.html","llm",0],["Query (attention)","The vector a position uses to ask which other positions are relevant to it.","deep-learning/chapters/09-attention.html","dl",1],["Query drift","The loss of the original meaning when added or relaxed query terms pull results away from what the user wanted.","retrieval/chapters/03-query-understanding.html","ret",0],["Query expansion","Adding related terms, such as synonyms, to a query so that documents using different words can match.","retrieval/chapters/03-query-understanding.html","ret",0],["Querying Transformer","BLIP-2's small bottleneck in which a fixed set of learned queries attends to the image, giving a fixed number of image tokens.","deep-learning/chapters/21-vision-language.html","dl",0],["Query planner","The part of a database that chooses how to execute a query: which indexes, which join order and algorithm.","data/chapters/08-query-execution.html","data",0],["Query relaxation","Retrying a query that returned too few results with fewer required terms.","retrieval/chapters/03-query-understanding.html","ret",0],["Query rewriting","Using a language model to turn the user's words into one or more queries that retrieve better, before any search runs.","retrieval/chapters/15-agentic-retrieval.html","ret",0],["Quorum","A minimum number of replicas that must take part in a read or write. If R + W > N, reads see the latest write.","networking/chapters/18-replication.html","net",0],["Quorum intersection","Any two majorities of the same group share at least one member, which lets a new decision learn about old ones.","distributed/chapters/08-consensus-smr.html","dist",0],["Quote-first prompting","Asking the model to copy relevant verbatim quotes before answering, so every citation can be checked as a substring of the source.","retrieval/chapters/16-grounded-citations.html","ret",0],["Quote verification","Checking in code that a quoted string really appears in the fetched source text, which catches fabricated citations but not misattributed ones.","agents/chapters/16-deep-research.html","agt",0],["R1-Zero","DeepSeek's reasoning model trained by applying GRPO with rule-based accuracy and format rewards directly to a base model, with no supervised fine-tuning stage.","llm-training/chapters/14-rlvr-grpo.html","llm",1],["Race condition","A bug where the result depends on the exact timing or interleaving of threads or processes.","systems/chapters/11-race-conditions.html","sys",0],["RadixAttention","SGLang's prefix cache, which stores cached prompts and outputs in a radix tree and evicts least recently used leaves first.","llm-training/chapters/20-serving-engines.html","llm",0],["Raft","A consensus algorithm designed to be understandable: leader election plus log replication.","networking/chapters/20-consensus.html","net",0],["RAG rating","A red, amber or green status whose meaning is fixed by a written rule, so that a change of colour is a verifiable fact.","ai-delivery/chapters/17-writing-for-customers.html","aid",0],["Random forest","A bagged ensemble of deep trees that also considers only a random subset of features at each split, to decorrelate the trees.","ml/chapters/09-ensembles-boosting.html","ml",0],["Randomised controlled trial (productivity)","A study that assigns each task at random to allow or disallow a tool, so that differences in time can be attributed to the tool rather than to who chose it.","agents/chapters/22-ai-coding-tools.html","agt",0],["Random search","Sampling parameter settings at random and keeping the best, a strong control for fancier search.","open-ended/chapters/18-search-in-products.html","oe",1],["Random variable","A number whose value depends on the outcome of a chance process, such as the sum of two dice or the next token id.","ml-foundations/chapters/12-probability.html","mlf",1],["Rank","The number of linearly independent columns of a matrix, equal to its number of non-zero singular values.","ml-foundations/chapters/07-decompositions.html","mlf",0],["Rank averaging","Combining models by averaging the ranks of their scores, which puts different scales on a common footing and suits rank metrics such as AUC.","ml/chapters/20-competitions.html","ml",0],["Ranking miss","A failure in which the answer-bearing passage is retrieved but ranked below the cut-off passed to the model, under worse passages.","retrieval/chapters/17-rag-failures.html","ret",0],["Rank (LoRA)","The inner dimension r of the two LoRA factors, which sets how many independent directions the update can use and how many parameters it costs.","llm-training/chapters/11-lora.html","llm",1],["Rank range","The span of positions a model occupies across bootstrap resamples of the votes, showing how firmly its rank is established.","evals/chapters/09-leaderboards.html","evl",0],["Rank window size","How many results from each retriever are passed into fusion, which limits what fusion can promote.","retrieval/chapters/10-hybrid-search.html","ret",0],["RBAC","Role-based access control: permissions are granted to roles and roles to users.","security/chapters/08-authorization.html","sec",0],["RBF kernel","The Gaussian similarity exp(-gamma times squared distance), which is 1 for identical points and falls towards 0 as they move apart.","ml/chapters/07-neighbours-bayes.html","ml",1],["ReAct","A pattern that alternates a model's reasoning (thought), a tool request (action) and the real tool output (observation) in a loop.","agents/chapters/03-reasoning-planning.html","agt",1],["ReadIndex","A Raft technique for linearizable reads: the leader confirms it is still leader with a heartbeat round before serving a read at its commit index.","distributed/chapters/10-raft-deep.html","dist",0],["Readiness probe","A check that decides whether a container should receive traffic; failing it removes the pod from load balancing without restarting it.","reliability/chapters/14-orchestration.html","ops",0],["Reading budget","A fixed, regular amount of time for following the field, chosen in advance so that keeping up does not crowd out building.","ai-delivery/chapters/19-where-next.html","aid",0],["Reading order","The sequence in which a person would read the blocks of a page, which differs from the order in which they are stored in the file.","retrieval/chapters/18-pdf-layout.html","ret",0],["Read repair","Fixing stale replicas during a read: when replicas disagree, the newest value is written back to the stale ones.","networking/labs/lab-05-kv-store.html","net",0],["Read skew","Seeing different parts of the database at different points in time, so the parts don't add up.","data/chapters/11-isolation.html","data",0],["Read/write ratio","How many reads a system serves per write; it decides where caching and denormalisation pay off.","design/chapters/02-estimation.html","design",0],["Read-your-writes","A guarantee that after you write something, your own reads will see it.","data/chapters/15-replication-practice.html","data",0],["Realisation","The share of time or effort a system frees that turns into something the customer can count, such as a hire not made or a backlog cleared.","ai-delivery/chapters/14-cost-roi.html","aid",0],["Real problem","The situation that causes the customer pain or cost, stated without reference to any particular solution.","ai-delivery/chapters/01-discovery-interviews.html","aid",0],["Reasoning model","A model trained, typically with reinforcement learning on checkable outcomes, to produce a long internal chain of thought before its final reply.","agents/chapters/03-reasoning-planning.html","agt",1],["Reasoning model","A model trained, largely by reinforcement learning on checkable problems, to produce long intermediate reasoning before its final answer.","llm-training/chapters/00-start-here.html","llm",0],["ReBAC","Relationship-based access control: permissions follow relationships in a graph, such as owner of a folder that contains a document.","security/chapters/08-authorization.html","sec",0],["Recall","Of the cases that really are positive, the fraction the model flagged; also called sensitivity or true positive rate.","ml/chapters/02-framing-metrics.html","ml",1],["Recall at k","The fraction of all relevant documents that appear in the first k results.","retrieval/chapters/04-relevance-metrics.html","ret",0],["Recall ceiling","The limit that retrieval puts on answer quality: if the right evidence is not retrieved, no generator can answer correctly.","retrieval/chapters/00-start-here.html","ret",0],["Receptive field","The region of the input that can influence one unit's value, which grows as layers are stacked.","deep-learning/chapters/07-convolutions.html","dl",0],["Reciprocal rank fusion","A merging method that gives each document the sum of 1/(k + rank) over the lists it appears in, using ranks only and ignoring scores.","retrieval/chapters/10-hybrid-search.html","ret",0],["Reconciliation","Comparing your own records with a partner's, such as a payment provider's settlement file, to find and fix mismatches.","design/chapters/16-payments.html","design",0],["Reconciliation loop","A controller that repeatedly compares desired state with actual state and acts to close the gap.","reliability/chapters/14-orchestration.html","ops",0],["Reconstruction error","The difference between the original data and its approximation from a reduced number of components.","ml/chapters/11-dimensionality-reduction.html","ml",0],["Reconstruction training (hypernetwork)","Training a hypernetwork to reproduce adapters that were already trained on known tasks, a form of distillation from adapters into a generator.","llm-training/chapters/17-adapters-on-demand.html","llm",0],["Recurrence rate","The share of reviewed failures that belong to a failure mode already covered by a test case.","evals/chapters/18-improvement-flywheel.html","evl",0],["Recurrent form","Computing a layer one token at a time with a fixed-size state, which is how linear attention and state-space layers generate text.","deep-learning/chapters/22-beyond-attention.html","dl",0],["Recurrent network","A network that reads a sequence one element at a time and carries a hidden summary forward, which makes it inherently sequential.","deep-learning/chapters/00-start-here.html","dl",0],["Recurrent neural network","A network that reads a sequence one step at a time, applying the same cell at every step and carrying a hidden state forward.","deep-learning/chapters/08-sequences-rnns.html","dl",0],["Recursive resolver","The DNS server that does the full lookup on your behalf and caches the answers.","networking/chapters/09-dns.html","net",0],["Redaction","Removing a sensitive value from text and leaving only a label, such as [EMAIL_1].","evals/chapters/22-privacy-data.html","evl",0],["RED method","Rate, Errors and Duration: the three things to measure for every request-driven service (Tom Wilkie).","reliability/chapters/04-metrics.html","ops",0],["Red team","A group that plays the adversary against a system, trying on purpose to make it fail so the failures can be fixed first.","evals/chapters/16-red-teaming.html","evl",0],["Reduce-scatter","A collective that sums tensors across GPUs but leaves each GPU holding only its own slice of the result.","llm-training/chapters/03-parallelism.html","llm",0],["Reduction","An operation such as sum, mean or max that collapses one or more axes of an array into single values.","ml-foundations/chapters/02-numpy-arrays.html","mlf",1],["Reference counting","Keeping a count of references to each object and freeing it when the count reaches zero (CPython's main method).","systems/chapters/03-stack-heap.html","sys",0],["Reference policy","A frozen copy of the model a run started from, usually the SFT model, against which the tuned policy's drift is measured and penalised.","llm-training/chapters/08-ppo.html","llm",1],["Reflection","Evaluating an attempt, turning the verdict into feedback and trying again, which helps most when the feedback comes from tests or validators rather than the model's own opinion.","agents/chapters/03-reasoning-planning.html","agt",1],["Reflection (agent memory)","Periodically synthesising stored memories into higher-level summaries that are stored and retrieved like any other memory.","agents/chapters/11-memory.html","agt",1],["Refresh token rotation","Issuing a new refresh token on every use and revoking the whole family if an old one is reused, to detect theft.","security/chapters/06-sessions-tokens.html","sec",0],["Register","A handful of very fast storage slots inside the CPU core where it keeps the values it is working on right now.","systems/chapters/01-cpu.html","sys",0],["Regression gate","A release rule that blocks a change if a case that passed before now fails.","evals/chapters/02-eval-harnesses.html","evl",1],["Regression (quality)","A behaviour that used to be correct and is now wrong after a change.","evals/chapters/18-improvement-flywheel.html","evl",0],["Regression suite","A set of tests, often built from past failures, that fails if an old problem returns.","evals/chapters/00-start-here.html","evl",0],["Regression suite as sensor","Using your own saved evaluation set to measure what a new model or tool changes for your tasks, instead of trusting public rankings.","ai-delivery/chapters/19-where-next.html","aid",0],["Regression suite (model)","A fixed set of evaluations of capabilities to keep, run on every new version of a model to catch unintended losses.","llm-training/chapters/23-evaluating-models.html","llm",0],["Regression tree","A tree for a numerical target whose splits reduce the variance of the target and whose leaves predict the mean.","ml/chapters/08-decision-trees.html","ml",0],["Regret","The reward an agent would have earned by always choosing the best action, minus the reward it actually earned.","llm-training/chapters/06-bandits-mdps.html","llm",1],["Regret","The reward lost compared with always choosing the best option, summed over all the choices made.","open-ended/chapters/01-tree-search.html","oe",1],["Regularisation","Any change to a learning procedure that gives up a little training accuracy in return for better accuracy on unseen data.","deep-learning/chapters/04-deep-regularisation.html","dl",1],["Regularisation","Any change that makes a model less able to fit noise, at the cost of fitting the signal slightly worse.","ml/chapters/06-regularisation.html","ml",1],["REINFORCE","The basic policy-gradient algorithm: sample trajectories, score them, and move the policy along the log-probability gradient weighted by reward.","llm-training/chapters/07-policy-gradients.html","llm",1],["Relative position bias","A learned number per head and distance bucket added to the attention scores so they depend on how far apart two tokens are.","deep-learning/chapters/11-positions.html","dl",1],["Release gate","An automatic check, usually in continuous integration, that blocks a change when the suite shows it got worse by a rule fixed in advance.","evals/chapters/18-improvement-flywheel.html","evl",0],["Relevance judgement","A label, binary or graded, saying how well a document answers a query's information need; a set of them is called qrels.","retrieval/chapters/04-relevance-metrics.html","ret",0],["Reliability diagram","A plot of stated confidence against observed accuracy in bins, where the diagonal means perfect calibration.","evals/chapters/11-grounding-abstention.html","evl",0],["Reliability diagram","A plot of observed frequency against mean predicted probability in bins of score, which lies on the diagonal for a calibrated model.","ml/chapters/15-imbalance-calibration.html","ml",0],["ReLU","The activation max(0, z), which passes positive values unchanged and sets negative values to zero.","deep-learning/chapters/01-neurons-layers.html","dl",1],["Repeated k-fold","Running k-fold several times with different shuffles and pooling the scores to reduce the luck of one partition.","ml/chapters/13-cross-validation.html","ml",1],["Repetition loop","A degenerate output where the model repeats the same phrase indefinitely because repeated text makes more repetition likely.","deep-learning/chapters/15-decoding.html","dl",1],["Repetition penalty","A decoding adjustment that lowers the logits of tokens already generated, to reduce loops.","deep-learning/chapters/15-decoding.html","dl",1],["Replay","Mixing a share of earlier training data into a new fine-tuning set to keep the old skills from degrading.","llm-training/chapters/10-sft.html","llm",1],["Replay","Evaluating a new rule by re-running logged past cases through it.","open-ended/chapters/18-search-in-products.html","oe",1],["Replicated state machine","Running the same deterministic program on several nodes, fed the same log of commands, so they all reach the same state.","distributed/chapters/08-consensus-smr.html","dist",0],["Replication","Keeping copies of the same data on several machines.","networking/chapters/18-replication.html","net",0],["Replication","Testing the same finding with new data or a fresh implementation, which checks the finding rather than the reporting.","ml-foundations/chapters/16-reading-papers.html","mlf",0],["Replication lag","How far behind the leader a follower is, so reads from it may be stale.","data/chapters/15-replication-practice.html","data",0],["Repository map","A compact summary of a repository's files and key signatures, sent with requests so the model knows what exists before searching.","agents/chapters/18-coding-agents.html","agt",1],["Reproducible","Of a result, able to be regenerated from its record, exactly or within a stated tolerance.","ml-foundations/chapters/04-reproducible-experiments.html","mlf",1],["Reproduction","Re-running a published method and obtaining a result consistent with the paper, kept distinct from testing whether it transfers to new data.","ai-delivery/chapters/16-research-to-product.html","aid",0],["Reproduction","Rerunning the authors' own code and data to see whether you obtain their reported numbers.","ml-foundations/chapters/16-reading-papers.html","mlf",0],["Request coalescing (single-flight)","Letting only one request fetch a missing value while the others wait for its result.","data/chapters/14-caching.html","data",0],["Requested feature","A solution the customer has already chosen, which hints at a problem but hides its frequency, cost and cause.","ai-delivery/chapters/01-discovery-interviews.html","aid",0],["Requests and limits","Kubernetes settings for the resources a container is scheduled with and the maximum it may use.","reliability/chapters/14-orchestration.html","ops",0],["requestState","An opaque server-minted string that a client echoes on a retry; because it crosses an untrusted client it must be integrity-protected and bound to user, request and expiry.","agents/chapters/08-mcp-production.html","agt",0],["Request tap","A thin wrapper around the model interface that records each request exactly as it leaves your process, showing what a framework really sends.","agents/chapters/21-frameworks.html","agt",0],["Requirements restatement","A short document in which the delivery team writes down what it has understood, with assumptions and open questions marked, for the customer to correct and sign.","ai-delivery/chapters/02-requirements-ambiguity.html","aid",0],["Rerank depth","The number of first-stage candidates handed to the reranker, which sets both its cost and the recall ceiling.","retrieval/chapters/08-rerankers.html","ret",0],["Reranker","A second-stage model that reorders the shortlist returned by a cheap first-stage retriever to put the best results at the top.","retrieval/chapters/08-rerankers.html","ret",0],["Resampling (answers per question)","Answering each question K times and averaging, which shrinks answer-level noise by a factor of K but not the noise from choosing questions.","evals/chapters/04-eval-statistics.html","evl",1],["Research artefact","The paper, repository, weights and benchmark numbers that together support a research claim, built for other researchers rather than for users.","ai-delivery/chapters/16-research-to-product.html","aid",0],["Residual","The actual value minus the model's prediction for one example.","ml/chapters/05-linear-models.html","ml",1],["Residual","What is left of a vector after subtracting its projection; it is orthogonal to the direction projected onto.","ml-foundations/chapters/05-vectors-similarity.html","mlf",1],["Residual compression","Storing each token vector as the id of its nearest centroid plus a coarse low-bit encoding of the difference, to shrink a multi-vector index.","retrieval/chapters/09-late-interaction-sparse.html","ret",0],["Residual connection","A skip path that adds a layer's input to its output, y = x + F(x), giving gradients a direct route backwards.","deep-learning/chapters/03-training-dynamics.html","dl",1],["Residual distribution","The distribution proportional to max(0, p - q) from which a replacement token is drawn when a drafted token is rejected, which makes the overall output exactly p.","llm-training/chapters/21-speculative-decoding.html","llm",0],["Residual risk","The risk that remains after controls are applied, which a named person on the customer's side must accept.","ai-delivery/chapters/15-security-review.html","aid",0],["Residual stream","The running sum of a Transformer's block outputs, which every block reads from and writes to.","deep-learning/chapters/03-training-dynamics.html","dl",1],["Resource indicator","The resource parameter (RFC 8707) by which a client names the MCP server a token is for, so the token is bound to that audience.","agents/chapters/08-mcp-production.html","agt",0],["Resource limit","A cap on CPU time, wall-clock time, memory, disk or processes that a sandbox enforces on running code.","open-ended/chapters/17-self-modification-safety.html","oe",1],["Response format argument","A tool parameter, such as a concise or detailed enum, that lets the agent choose how much detail a result contains.","agents/chapters/05-tool-design.html","agt",1],["REST","An API style using HTTP methods on resources identified by URLs.","networking/chapters/12-apis.html","net",0],["REST / RPC / GraphQL","Three API styles: resources and HTTP verbs; calling remote functions; and clients querying exactly the fields they need.","architecture/chapters/09-api-design.html","arch",0],["Retransmission","Sending data again because no acknowledgement arrived in time.","networking/chapters/08-tcp.html","net",0],["Retrieval","Given a query, returning the most relevant items from a collection in ranked order.","retrieval/chapters/00-start-here.html","ret",0],["Retrieval-augmented generation","Answering a question by searching a document collection at request time and giving the best passages to a language model in its prompt.","retrieval/chapters/13-rag-end-to-end.html","ret",0],["Retrieval-augmented generation (RAG)","Retrieving relevant documents and adding them to a language model's prompt so answers are grounded in them.","design/chapters/20-ml-systems.html","design",0],["Retrieval-augmented generation (RAG)","Searching an index first and putting only the most relevant chunks into the prompt so the model answers from them.","agents/chapters/12-long-context.html","agt",0],["Retrieval-augmented generation (RAG)","Fetching relevant passages first and then asking a language model to write an answer from them, ideally with citations.","retrieval/chapters/00-start-here.html","ret",0],["Retrieval miss","A failure in which the passage that holds the answer is not among the retrieved results at all.","retrieval/chapters/17-rag-failures.html","ret",0],["Retrieval unit","The thing the system returns and judges label: a file, page, section or chunk.","retrieval/chapters/05-test-collections.html","ret",0],["Retry budget","A cap on retries as a fraction of normal traffic, so retries can't multiply load during an outage.","architecture/chapters/17-resilience.html","arch",0],["Return on investment","Total benefit minus total cost, divided by total cost.","ai-delivery/chapters/14-cost-roi.html","aid",0],["Return (reinforcement learning)","The sum of future rewards from a time step, each multiplied by the discount factor raised to its delay.","llm-training/chapters/06-bandits-mdps.html","llm",1],["Reverse-mode autodiff","Differentiation that propagates gradients from the output back to the inputs, giving the effect of all inputs on one output per pass.","ml-foundations/chapters/09-autodiff.html","mlf",1],["Reverse-mode automatic differentiation","Differentiating by one backward sweep over the graph, giving the gradient with respect to every input at a small multiple of the forward cost.","deep-learning/chapters/05-pytorch.html","dl",1],["Reward","A number the environment returns after an action, scoring how good it was; reinforcement learning tries to maximise its accumulated total.","llm-training/chapters/06-bandits-mdps.html","llm",1],["Reward hacking","A policy earning a high score from its reward signal by exploiting flaws in the signal, without doing what the signal was meant to measure.","llm-training/chapters/13-reward-models.html","llm",1],["Reward hacking","Raising a proxy reward in a way that lowers the true reward, usually by exploiting a flaw in how it is computed.","open-ended/chapters/15-evaluator-hacking.html","oe",1],["Reward model","A network that reads a prompt and a response and outputs one number predicting how much people would prefer it, trained on comparisons.","llm-training/chapters/12-preference-optimisation.html","llm",1],["Reward model ensemble","Several reward models trained separately whose disagreement or worst-case score is used to make optimisation more conservative.","llm-training/chapters/13-reward-models.html","llm",1],["Reward over-optimisation","The effect where pushing a policy to maximise a learned reward raises the reward score while true quality peaks and then declines.","llm-training/chapters/08-ppo.html","llm",1],["Reward-to-go","The sum of rewards from a given step onwards, used to weight that step's log-probability gradient because earlier rewards cannot depend on it.","llm-training/chapters/07-policy-gradients.html","llm",1],["RFM","Recency, frequency and monetary value: three classic customer aggregates built from purchase history.","ml/chapters/17-feature-engineering.html","ml",0],["Ridge point","The arithmetic intensity at which a chip's peak FLOP/s and peak memory bandwidth are equally limiting, about 295 FLOP per byte for an H100 in bf16.","llm-training/chapters/04-kernels.html","llm",0],["Ridge point","The arithmetic intensity at which the memory roof meets the compute roof, equal to peak FLOP/s divided by bandwidth.","ml-foundations/chapters/17-compute-costs.html","mlf",0],["Ridge regression","Least squares with a penalty on the sum of squared weights (L2), which shrinks all weights and stabilises correlated features.","ml/chapters/06-regularisation.html","ml",1],["Ridge regression","Least squares with an L2 penalty on the weights, equal to the MAP estimate under Gaussian noise and a Gaussian prior with lambda = sigma^2 / tau^2.","ml-foundations/chapters/13-likelihood-losses.html","mlf",1],["Right altitude (prompting)","Writing instructions specific enough to guide behaviour but flexible enough to give the model heuristics, avoiding both brittle if-then rules and vague guidance.","agents/chapters/10-context-engineering.html","agt",1],["Right to erasure","A person's right under the GDPR to have their personal data deleted, subject to exceptions such as legal claims.","evals/chapters/22-privacy-data.html","evl",0],["Risk acceptance","A written decision by a named, authorised person on the customer's side that they understand a remaining risk, its mitigations and what would trigger a review.","ai-delivery/chapters/15-security-review.html","aid",0],["Risk-coverage curve","A plot of selective risk against coverage as the confidence threshold is lowered, showing the price of answering more questions.","evals/chapters/11-grounding-abstention.html","evl",0],["Risk-coverage curve","A plot of the share of questions answered against the error rate among those answered, as the abstention threshold varies.","retrieval/chapters/16-grounded-citations.html","ret",0],["Riskiest-assumption principle","Test first the assumption that is most likely to be wrong, most costly if wrong and cheapest to check.","ai-delivery/chapters/00-start-here.html","aid",0],["RLHF (reinforcement learning from human feedback)","A three-stage method that fine-tunes a model on demonstrations, trains a reward model on human comparisons, then optimises the model against that reward with a KL penalty.","llm-training/chapters/12-preference-optimisation.html","llm",1],["RLVR (reinforcement learning with verifiable rewards)","Reinforcement learning in which the reward is computed by a program that checks the answer, such as an answer match or unit tests, instead of by a learned reward model.","llm-training/chapters/14-rlvr-grpo.html","llm",1],["RMSE","Root mean squared error, a regression metric in the units of the target whose best constant prediction is the mean.","ml/chapters/02-framing-metrics.html","ml",1],["RMSNorm","A cheaper normalisation that divides by the root mean square of the features and does not subtract the mean.","deep-learning/chapters/03-training-dynamics.html","dl",1],["Robodebt","The Australian automated welfare debt-recovery scheme of 2015 to 2019 that averaged annual income to raise debts and was later found unlawful by courts and a Royal Commission.","ai-delivery/chapters/11-public-sector.html","aid",0],["ROC AUC","The probability that a random positive case scores higher than a random negative case, summarising ranking quality across all thresholds.","ml/chapters/02-framing-metrics.html","ml",1],["Rogan-Gladen correction","An estimate of the true pass rate from a judge's observed rate and its true positive and negative rates.","evals/chapters/03-llm-judges.html","evl",1],["Role","The label on a message saying who spoke, normally user (everything coming in) or assistant (what the model said).","agents/chapters/01-model-apis.html","agt",1],["Rolling buffer cache","A KV cache of fixed size W that overwrites slot position mod W, valid because tokens older than the window are never read again.","deep-learning/chapters/19-efficient-attention.html","dl",0],["Rolling-origin backtest","Evaluating a forecasting method by repeatedly fitting on data before an origin, forecasting the next horizon and moving the origin forward.","ml/chapters/18-time-series.html","ml",0],["Rollout","A fast simulation from a tree leaf to the end of the game, used to estimate how good the leaf is.","open-ended/chapters/01-tree-search.html","oe",1],["Roofline model","A plot of achievable FLOP/s against arithmetic intensity, bounded by a memory-bandwidth slope and a flat compute ceiling.","llm-training/chapters/04-kernels.html","llm",0],["Roofline model","A chart of attainable FLOP/s against arithmetic intensity, bounded by a sloped memory roof and a flat compute roof.","ml-foundations/chapters/17-compute-costs.html","mlf",0],["Root","The first node of a tree, which asks the first question about the whole training set.","ml/chapters/08-decision-trees.html","ml",0],["RoPE base","The constant (10,000 in the original paper) that sets the spread of rotation frequencies across dimension pairs and hence the longest wavelength.","deep-learning/chapters/11-positions.html","dl",1],["Rotary position embedding (RoPE)","A scheme that rotates each pair of query and key dimensions by an angle proportional to position, so that attention scores depend only on the distance between tokens.","deep-learning/chapters/11-positions.html","dl",1],["Round-trip time (RTT)","Time for a message to go there and for the reply to come back.","networking/chapters/01-bits-and-signals.html","net",0],["Router","A device that forwards packets between networks based on their destination IP address.","networking/chapters/05-routing.html","net",0],["Router","The small linear layer that scores every expert for a token and selects the top k.","deep-learning/chapters/20-mixture-of-experts.html","dl",0],["Routing","Classifying an input and sending it down a specialised path, with its own prompt, tools or model, plus a fallback for low confidence.","agents/chapters/13-workflow-patterns.html","agt",1],["Routing collapse","A failure in which a few experts receive nearly all tokens and the rest are rarely trained or used.","deep-learning/chapters/20-mixture-of-experts.html","dl",0],["Routing table","A router's list of destination prefixes and where to send packets for each.","networking/chapters/05-routing.html","net",0],["Row-level security","Database-enforced filtering so each query only sees rows belonging to the current tenant or user.","security/chapters/15-multi-tenancy.html","sec",0],["Row-major order","A memory layout in which the last axis varies fastest, so each row of a matrix is contiguous; also called C order.","ml-foundations/chapters/02-numpy-arrays.html","mlf",1],["RPC","Remote Procedure Call: calling a function that runs on another machine.","networking/chapters/12-apis.html","net",0],["RPO","Recovery point objective: how much data, measured in time, you can afford to lose in a disaster.","reliability/chapters/18-disaster-recovery.html","ops",0],["RRF constant (k)","The number added to each rank in reciprocal rank fusion, usually 60, which sets how quickly the weight falls down a list.","retrieval/chapters/10-hybrid-search.html","ret",0],["R-squared","One minus the ratio of a model's squared error to that of always predicting the mean, so zero means no better than the mean baseline.","ml/chapters/04-baselines.html","ml",1],["RTO","Recovery time objective: how long you can afford to be down before service is restored.","reliability/chapters/18-disaster-recovery.html","ops",0],["Rubric","A list of observable criteria, each with a few anchored levels, that lets different people or a model score the same output consistently.","ai-delivery/chapters/03-expert-knowledge.html","aid",0],["Rubric","The written definition of a criterion, including what counts as PASS and FAIL, that a judge applies.","evals/chapters/03-llm-judges.html","evl",1],["Rug pull","A tool server changing a tool's definition after the user approved it, so earlier approval no longer reflects what the model sees.","agents/chapters/19-agent-security.html","agt",1],["Rule of three","The approximation that with zero successes in n independent tries, the 95% upper bound on the true rate is about 3 divided by n.","ai-delivery/chapters/15-security-review.html","aid",0],["Rule of three","After zero successes in n independent trials, the 95% upper bound on the success rate is about 3 divided by n.","evals/chapters/16-red-teaming.html","evl",0],["Rules of engagement","The agreed limits of a red-team exercise: what is in scope, what is off limits and when to stop and report.","evals/chapters/16-red-teaming.html","evl",0],["Runbook","Step-by-step guidance for responding to a specific alert or failure.","reliability/chapters/07-alerting-oncall.html","ops",0],["Runtime","The part of a framework that executes a loop or graph of steps and keeps its state, as opposed to only calling a model API.","agents/chapters/21-frameworks.html","agt",0],["Safeguard model","A language model fine-tuned to classify prompts and responses against a list of safety categories, such as Llama Guard.","evals/chapters/15-guardrails.html","evl",0],["Safe Harbor de-identification","The HIPAA method of removing 18 listed kinds of identifier from health data, provided nothing else is known that could identify the person.","ai-delivery/chapters/09-healthcare.html","aid",0],["Safetensors","A model-weight file format that stores a length, a JSON header and raw numbers, so that loading it cannot execute code.","ai-delivery/chapters/13-restricted-environments.html","aid",0],["Safety property","\"Nothing bad ever happens\", such as two nodes never deciding different values. Violated by a finite execution.","distributed/chapters/01-system-models.html","dist",0],["Saga","A business transaction across services made of local transactions, each with a compensating action if a later step fails.","architecture/chapters/15-sagas.html","arch",0],["Salt","A random value stored with a password hash so identical passwords hash differently and precomputed tables fail.","security/chapters/05-authentication.html","sec",0],["Same-origin policy","The browser rule that scripts from one origin (scheme, host, port) cannot read responses from another.","security/chapters/10-web-security.html","sec",0],["SameSite cookie","A cookie attribute that limits when browsers send it on cross-site requests, a main defence against CSRF.","security/chapters/06-sessions-tokens.html","sec",0],["Sample efficiency","How much improvement a search obtains per model call or evaluation spent, which depends on what is counted as a sample.","open-ended/chapters/10-evolution-frameworks.html","oe",1],["Sample ratio mismatch","A split of units between experiment arms that differs from the intended ratio by more than chance allows, signalling a bug in assignment or logging.","ml/chapters/21-model-to-value.html","ml",0],["Sample ratio mismatch","A split of users between experiment arms that differs from the planned ratio by more than chance allows, signalling broken assignment or logging.","ml-foundations/chapters/15-statistics.html","mlf",1],["Sampling profiler","A profiler that records the call stack at regular intervals, giving a cheap statistical picture of where time goes.","systems/chapters/22-performance-engineering.html","sys",0],["Sampling weight","The inverse of the probability that a trace was kept, used to compute unbiased rates from a non-uniform sample.","evals/chapters/17-observability.html","evl",0],["Sandbox","An enforced boundary, applied by the operating system, a hypervisor or a proxy, around running code that limits what it can reach.","agents/chapters/20-sandboxing.html","agt",1],["Sanity baseline","A check on the pipeline rather than the problem, such as training on shuffled labels and expecting chance-level results.","ml/chapters/04-baselines.html","ml",1],["Saturation","The flat ends of an activation such as sigmoid or tanh, where the slope is near zero and gradients cannot pass.","deep-learning/chapters/01-neurons-layers.html","dl",1],["Saturation","The state in which the best systems score so close to a benchmark's ceiling that differences among them are smaller than its noise.","evals/chapters/07-contamination.html","evl",1],["Saturation","The property that each extra occurrence of a term adds less to a score, up to a ceiling of k1 plus 1 in BM25.","retrieval/chapters/02-bm25.html","ret",0],["SBOM","Software bill of materials: an inventory of every component and version in a piece of software.","security/chapters/12-memory-supply-chain.html","sec",0],["Scaffold (leaderboard context)","The prompts, tools, loop and limits wrapped around a model, which belong to the score of an agent benchmark as much as the model does.","evals/chapters/09-leaderboards.html","evl",0],["Scalar quantisation","Storing each number of a vector in fewer bits, such as 8, to cut memory at a small cost in accuracy.","retrieval/chapters/11-ann-indexes.html","ret",1],["Scaled dot-product attention","The function softmax(QK^T / sqrt(d_k)) V, where the scaling keeps the score variance at one whatever the key width.","deep-learning/chapters/09-attention.html","dl",1],["Scale (quantisation)","The step size between neighbouring quantised levels, chosen so the largest value in a group maps to the largest integer.","llm-training/chapters/19-quantisation.html","llm",0],["Scaling law","An empirical power-law relationship between a model's loss and its parameters, training data or compute, which lets small runs predict larger ones.","deep-learning/chapters/18-scaling-laws.html","dl",0],["Scanned PDF","A PDF whose pages are images of paper and which contains no characters unless an OCR text layer has been added.","retrieval/chapters/18-pdf-layout.html","ret",0],["Scatter-gather","Sending a query to many shards in parallel and merging their partial results.","design/chapters/11-search-typeahead.html","design",0],["Scatter-gather","A pattern where a request fans out to several backends in parallel and the results are merged, so latency is set by the slowest one.","retrieval/chapters/10-hybrid-search.html","ret",0],["Scheduler","The part of the kernel that decides which runnable thread gets each CPU core next, and for how long.","systems/chapters/07-scheduling.html","sys",0],["Schema (extraction)","A specification of the fields an extraction must produce, with their types, which are required and the rules that relate them.","retrieval/chapters/20-tables-forms.html","ret",0],["Schema-on-read","No fixed structure is enforced on write; the code that reads the data interprets it. The opposite is schema-on-write.","data/chapters/01-data-models.html","data",0],["Score function","The gradient of the log-probability of an action with respect to the policy parameters; for a softmax over logits it is the one-hot vector of the action minus the probabilities.","llm-training/chapters/07-policy-gradients.html","llm",1],["Score normalisation","Rescaling each retriever's scores for a query to a common range so that they can be combined.","retrieval/chapters/10-hybrid-search.html","ret",0],["Scorer","Code or a model that decides whether an attack attempt reached its goal, preferably by checking observable effects.","evals/chapters/16-red-teaming.html","evl",0],["Scratchpad","Text the model writes inside its own window, such as a plan or to-do list, to organise a long task; it disappears with the window.","agents/chapters/11-memory.html","agt",1],["Scree plot","A plot of the variance explained by each principal component in order, used to decide how many to keep.","ml/chapters/11-dimensionality-reduction.html","ml",0],["Scripted model","A stand-in model that replays replies written in advance so that example code and lab checks run offline with identical output every time.","agents/chapters/00-start-here.html","agt",0],["Script (writing system)","A writing system such as Latin, Arabic, Han or Thai, which Unicode records for every character.","retrieval/chapters/22-multilingual.html","ret",0],["Seam","A place where you can change a program's behaviour without editing it, for example by injecting a dependency.","architecture/chapters/07-testability.html","arch",0],["Search-and-replace edit","An edit expressed as exact old text and new text, which fails loudly if the old text is missing or appears more than once.","agents/chapters/18-coding-agents.html","agt",1],["Search (as a method)","Finding a good answer by generating candidates, testing them and using the results to choose the next candidates, instead of computing the answer directly.","open-ended/chapters/00-start-here.html","oe",1],["Search (product)","The product a person uses to type a query and read a ranked list of results.","retrieval/chapters/00-start-here.html","ret",0],["Search set","The data a search loop scores candidates on to choose parents; its scores are optimistic for the survivors.","open-ended/chapters/16-held-out-evaluation.html","oe",1],["Search set versus held-out test set","The data an optimiser is allowed to score candidates on, kept separate from the data used once at the end to report the final result, because search overfits its own score.","llm-training/chapters/16-model-merging.html","llm",1],["Search space (agent design)","The set of agents a method can represent at all, which limits the best possible result before any search begins.","open-ended/chapters/12-meta-agent-search.html","oe",1],["Seasonality","A pattern in a series that repeats with a fixed calendar period, such as weekly or yearly.","ml/chapters/18-time-series.html","ml",0],["Seasonal naive forecast","A forecast that repeats the value from one season ago, such as next Tuesday equal to last Tuesday.","ml/chapters/18-time-series.html","ml",0],["Seatbelt and bubblewrap","The macOS and Linux operating-system facilities used to start a process with file-system and network restrictions it cannot lift.","agents/chapters/20-sandboxing.html","agt",1],["Seat hold","A temporary reservation of inventory with an expiry time, released if checkout does not complete.","design/chapters/15-ticketing.html","design",0],["Secondary index","An extra sorted structure on a non-key column, pointing back to the rows, so lookups by that column avoid a full scan.","data/chapters/07-indexes.html","data",0],["Sectioning","A parallelisation variant in which independent subtasks of one job run at the same time and their results are combined in code.","agents/chapters/13-workflow-patterns.html","agt",1],["Secure design review","Examining a design for security problems before it is built, using a threat model and a checklist.","security/chapters/19-secure-design-review.html","sec",0],["Security group","A stateful, allow-only firewall attached to cloud instances or interfaces.","networking/chapters/22-cloud-networking.html","net",0],["Security policy (agent)","A rule written in code that allows, denies or asks a person about a tool call, given its arguments and their provenance.","evals/chapters/14-architectural-defences.html","evl",0],["Security review","A customer's process for deciding whether a supplier's system may handle their data and connect to their environment.","ai-delivery/chapters/15-security-review.html","aid",0],["Security trimming","Removing from search results every document the caller is not allowed to read, before the results or any text derived from them are shown.","retrieval/chapters/12-filters-permissions.html","ret",0],["Seed","The starting value of a pseudorandom number generator; the same seed gives the same sequence.","ml-foundations/chapters/04-reproducible-experiments.html","mlf",1],["Selection bias","The optimism in the best of many noisy validation scores, caused by choosing the winner on the same rows used to score it.","ml/chapters/13-cross-validation.html","ml",1],["Selection bias (winner's curse)","The optimism that comes from reporting the best score among many noisy candidates on the same data.","ml/chapters/01-generalisation.html","ml",1],["Selection pressure","How strongly an evolutionary algorithm favours the fittest individuals when choosing parents.","open-ended/chapters/02-evolutionary-algorithms.html","oe",1],["Selection set","Fresh data used to choose among a small shortlist of finalists.","open-ended/chapters/16-held-out-evaluation.html","oe",1],["Selective batching","Flattening all tokens of a step into one matrix for the per-token layers while computing attention separately for each request.","llm-training/chapters/20-serving-engines.html","llm",0],["Selective disclosure","Testing many private variants and publishing only the best result, which inflates the published score without any dishonest measurement.","evals/chapters/09-leaderboards.html","evl",0],["Selective labels","A problem in which past decisions determine which outcomes are observed, so only some cases ever receive a label.","ml/chapters/21-model-to-value.html","ml",0],["Selective recomputation","Recomputing only the memory-heavy but cheap parts of a layer, such as attention scores, instead of the whole layer.","llm-training/chapters/02-gpu-memory.html","llm",0],["Selective risk","The error rate among only the questions a system answers, ignoring those it declines.","evals/chapters/11-grounding-abstention.html","evl",0],["Selectivity","Making a state-space layer's update depend on the current input, so it can choose what to write into its state and what to ignore.","deep-learning/chapters/22-beyond-attention.html","dl",0],["Selectivity","The fraction of a collection that passes a filter, which decides whether pre-filtering, filtered traversal or post-filtering is cheapest.","retrieval/chapters/12-filters-permissions.html","ret",0],["Self-adaptive model","A model that changes part of its own weights at inference time in response to the task it is given, without a new training run.","llm-training/chapters/17-adapters-on-demand.html","llm",0],["Self-attention","Attention in which the queries, keys and values are all computed from the same sequence.","deep-learning/chapters/09-attention.html","dl",1],["Self-consistency","Sampling several reasoning paths and returning the most common final answer.","open-ended/chapters/08-inference-time-search.html","oe",1],["Self-enhancement bias","A judge's tendency to prefer answers written by itself or by a model of its own family.","evals/chapters/03-llm-judges.html","evl",1],["Self-modification","An agent editing its own code (tools, prompts, workflow) to produce a new version of itself, with the underlying model's weights left unchanged.","open-ended/chapters/13-self-improving-agents.html","oe",1],["Self-modifying system","A loop in which a candidate's output includes changes to code, prompts or settings that run in the next iteration.","open-ended/chapters/17-self-modification-safety.html","oe",1],["Self-referential improvement","A process whose improvement step is among the things it improves, such as a search that evolves its own mutation operators.","open-ended/chapters/11-evolving-prompts.html","oe",1],["Self-reported score","A benchmark result measured and published by the model's own developer, usually under settings chosen to suit that model.","evals/chapters/09-leaderboards.html","evl",0],["Self-Route","A hybrid that tries retrieval first and falls back to the long context only when the model judges the retrieved chunks insufficient.","agents/chapters/12-long-context.html","agt",0],["Self-verification","Having a separate model call (a critic) judge whether a task was completed and suggest fixes.","open-ended/chapters/07-lifelong-agents.html","oe",1],["Semantic cache","A cache keyed by an embedding of the question that returns an earlier answer to a similar question, with the risk of wrong or leaked answers.","evals/chapters/19-cost-latency-quality.html","evl",0],["Semantic chunking","Cutting where the embedding similarity between neighbouring sentences drops, so chunk size follows topic changes.","retrieval/chapters/14-chunking.html","ret",0],["Semantic conventions","Agreed names for common telemetry attributes, so that different tools describing the same thing use the same key.","evals/chapters/17-observability.html","evl",0],["Semantic entropy","The entropy of a model's sampled answers after grouping them by meaning, high when the model gives arbitrary, changing answers.","evals/chapters/11-grounding-abstention.html","evl",0],["Semantic lock","A status such as PENDING that tells other operations a record is mid-saga.","architecture/chapters/15-sagas.html","arch",0],["Semantic memory","Facts that stay true until changed, such as a customer's preferred channel, stored with one current value per fact.","agents/chapters/11-memory.html","agt",1],["Semaphore","A counter-based lock that lets up to N threads in at once; useful for limiting concurrency.","systems/chapters/12-locks.html","sys",0],["SentencePiece","A library that trains BPE or unigram tokenisers directly on raw text, treating the space as an ordinary symbol.","deep-learning/chapters/13-tokenisation.html","dl",1],["Sentinel value","A special number such as 999 or -1 stored in place of a missing or unknown value.","ml/chapters/03-eda.html","ml",0],["Sentinel value","A special number such as -999 used to mean 'missing' that parses as ordinary data unless it is found and converted.","ml-foundations/chapters/03-data-wrangling.html","mlf",0],["Sequence-level distillation","Distillation by sampling answers from the teacher and fine-tuning the student on that text, which needs no access to the teacher's probabilities.","llm-training/chapters/15-distillation.html","llm",0],["Sequence number","TCP's numbering of bytes so the receiver can put data in order and detect gaps.","networking/chapters/08-tcp.html","net",0],["Sequence parallelism","Splitting activations along the sequence dimension in the parts of a layer that tensor parallelism leaves replicated, to save memory without extra traffic.","llm-training/chapters/03-parallelism.html","llm",0],["Sequential consistency","All operations appear in one order that respects each client's own program order, but not necessarily real time (Lamport, 1979).","distributed/chapters/05-consistency-models.html","dist",0],["Serializable","The strongest isolation: the result is as if transactions ran one at a time, in some order.","data/chapters/11-isolation.html","data",0],["Serialization","Turning data structures into bytes to send or store (JSON, Protocol Buffers).","networking/chapters/12-apis.html","net",0],["Serialization (encoding)","Turning in-memory objects into bytes to store or send, and back again, using formats like JSON, Protobuf or Avro.","data/chapters/03-encoding.html","data",0],["Serious incident (EU AI Act)","An incident or malfunction of a high-risk AI system that leads to defined kinds of serious harm, which providers must report to authorities within set deadlines.","evals/chapters/20-ai-incidents.html","evl",0],["server/discover","The MCP method, required of every server in the 2026-07-28 revision, that returns the supported protocol versions, capabilities and identity of a server.","agents/chapters/08-mcp-production.html","agt",0],["Server-sent events","A long-lived HTTP response in which the server writes named events as they happen, used to stream model output token by token.","agents/chapters/01-model-apis.html","agt",1],["Service contract","The written promise of what a service accepts, what it returns, how it fails and what will not change without notice.","ai-delivery/chapters/16-research-to-product.html","aid",0],["Session guarantees","Per-client promises such as read-your-writes, monotonic reads, monotonic writes and writes-follow-reads (Terry et al., 1994).","distributed/chapters/06-causal-session.html","dist",0],["Set-of-marks","Overlaying numbered marks on the interactive regions of a screenshot so the model answers with a mark number instead of estimating coordinates.","agents/chapters/17-computer-use.html","agt",0],["Shadowing","Observing someone do their real work without directing it, to see what they actually look at, skip, check and ask.","ai-delivery/chapters/03-expert-knowledge.html","aid",0],["Shadow mode","Running a model on real inputs while humans keep deciding, recording its answers without showing or acting on them.","ai-delivery/chapters/12-poc-to-production.html","aid",0],["Shadow mode","Running a candidate on a copy of live traffic and scoring its answers without showing them to users.","evals/chapters/18-improvement-flywheel.html","evl",0],["Shadow mode","Running a model on live traffic without acting on its outputs, to compare them with what actually happens.","ml/chapters/21-model-to-value.html","ml",0],["Shadow mode","Running a new version alongside the current one without acting on its output.","open-ended/chapters/18-search-in-products.html","oe",1],["Shake-up","A large change in participants' ranks between the public and private leaderboards.","ml/chapters/20-competitions.html","ml",0],["SHAP","A framework that explains predictions with Shapley values and has fast algorithms such as TreeSHAP for tree ensembles.","ml/chapters/16-interpretability.html","ml",0],["Shape (array)","The tuple giving the number of elements along each axis of an array, written (rows, columns) for a matrix.","ml-foundations/chapters/02-numpy-arrays.html","mlf",1],["Shape contract","The rule that (m, n) @ (n, p) gives (m, p): the inner sizes must agree and vanish.","ml-foundations/chapters/06-matrices.html","mlf",1],["Shapley value","A feature's average marginal contribution to a prediction over all orders of adding features, borrowed from cooperative game theory.","ml/chapters/16-interpretability.html","ml",0],["Sharded checkpoint","A checkpoint in which each rank writes only the part of the state it owns, in parallel, rather than gathering everything to one writer.","llm-training/chapters/05-long-runs.html","llm",0],["Shard key","The value that decides which shard (partition) a row lives on.","data/chapters/16-sharding.html","data",0],["Shared expert","An expert that every token uses, holding common knowledge so the routed experts can specialise.","deep-learning/chapters/20-mixture-of-experts.html","dl",0],["Shared responsibility model","The split of security duties between a cloud provider (the platform) and the customer (what they build on it).","security/chapters/14-cloud-container.html","sec",0],["Shingle","An overlapping run of n consecutive words (or characters) taken from a document so it can be treated as a set for similarity comparison.","llm-training/chapters/01-pretraining-data.html","llm",0],["ShinkaEvolve","Sakana AI's open-source program-evolution framework, built to find good programs with few model calls.","open-ended/chapters/10-evolution-frameworks.html","oe",1],["Shortlist","A small set of top candidates re-scored on fresh data before a winner is chosen.","open-ended/chapters/16-held-out-evaluation.html","oe",1],["Shortlist filter","Using a public benchmark to choose a few candidates to test on your own data, rather than to make the final decision.","retrieval/chapters/06-retrieval-benchmarks.html","ret",0],["Shrinking","Automatically reducing a failing test case to a smaller one that still fails, to make the bug easier to understand.","distributed/chapters/19-testing.html","dist",0],["Shuffled-label test","Retraining with randomly permuted training labels; any held-out score above chance signals a leak or bug.","ml/chapters/04-baselines.html","ml",1],["Shuffle sharding","Giving each customer a random small combination of workers, so one bad customer rarely shares all its workers with another.","reliability/chapters/15-blast-radius.html","ops",0],["SigLIP","A CLIP variant that replaces the softmax over the batch by an independent sigmoid loss on every image-caption pair.","deep-learning/chapters/21-vision-language.html","dl",0],["Sigmoid","The function 1 / (1 + e^-z) that maps any real number to a probability between 0 and 1.","ml/chapters/05-linear-models.html","ml",1],["Signal","A small asynchronous notification sent to a process, like SIGINT (Ctrl-C), SIGTERM (please stop) or SIGKILL (stop now).","systems/chapters/05-processes.html","sys",0],["Signature","A declaration of what a DSPy module takes in and returns, without the wording of the prompt.","open-ended/chapters/11-evolving-prompts.html","oe",1],["Silent data corruption","A hardware fault that makes a computation return a wrong value without raising any error.","llm-training/chapters/05-long-runs.html","llm",0],["Silhouette score","For each point, the gap between its distance to the nearest other cluster and to its own, scaled to between -1 and +1 and averaged.","ml/chapters/10-clustering.html","ml",0],["Silo, pool and bridge","Tenancy models: separate resources per tenant, fully shared resources, or a mix of the two.","security/chapters/15-multi-tenancy.html","sec",0],["SIMD","Single instruction, multiple data: one instruction applied to a vector of values at once.","systems/chapters/21-parallelism-gpus.html","sys",0],["SimpleQA","A short-form factuality benchmark whose answers are graded correct, incorrect or not attempted.","evals/chapters/10-hallucination.html","evl",0],["Simulated user","A model or script that plays the customer in an agent evaluation, following a hidden instruction and replying to the agent.","evals/chapters/08-agent-evals.html","evl",1],["Simulator","A model of a process used to score candidate policies when replay cannot show what would have happened.","open-ended/chapters/18-search-in-products.html","oe",1],["Single-column scan","Scoring each feature alone by how well it ranks the target, to find columns that are suspiciously predictive.","ml/chapters/14-leakage.html","ml",1],["Singleton rate","The share of training mentions whose fact appears exactly once, which estimates how much probability lies on facts the model cannot tell from unseen ones.","evals/chapters/10-hallucination.html","evl",0],["Single writer","A design rule in which several agents may contribute research or review but only one agent edits the shared artefact, avoiding conflicting writes.","agents/chapters/14-multi-agent.html","agt",0],["Singular matrix","A square matrix with no inverse because it flattens space and loses information.","ml-foundations/chapters/06-matrices.html","mlf",1],["Singular value decomposition","The factorisation A = U Sigma V^T of any matrix into a rotation, an axis-aligned stretch and another rotation.","ml-foundations/chapters/07-decompositions.html","mlf",0],["Singular-value fine-tuning (SVF)","Adapting a weight matrix by learning one scale per singular value while keeping its singular vectors fixed, which needs far fewer parameters than LoRA.","llm-training/chapters/17-adapters-on-demand.html","llm",0],["Singular values","The non-negative diagonal entries of Sigma in the SVD, which measure how much the matrix stretches along each pair of singular vectors.","ml-foundations/chapters/07-decompositions.html","mlf",0],["Sinusoidal positional encoding","A fixed code made of sines and cosines at geometrically spaced frequencies, so that a shift in position is a rotation of the code.","deep-learning/chapters/11-positions.html","dl",1],["Site reliability engineering (SRE)","Running production systems as a software-engineering problem, with explicit reliability targets and a cap on manual operational work.","reliability/chapters/00-start-here.html","ops",0],["Skill","The ability to produce, debug and explain something without help, which is built by effort rather than by receiving an answer.","ml-foundations/chapters/19-ai-assistants.html","mlf",0],["Skill (A2A)","An entry in an agent card describing one capability of the agent, with an id, description, tags and examples.","agents/chapters/09-agent-to-agent.html","agt",0],["Skill library","A collection of reusable procedures, each described briefly, that an agent loads only when a task calls for them.","agents/chapters/11-memory.html","agt",1],["Skill library","A store of verified programs, each indexed by a description, that an agent retrieves and calls when solving new tasks.","open-ended/chapters/07-lifelong-agents.html","oe",1],["SKILL.md","The file at the core of an Agent Skill, with YAML front matter giving a name and description followed by the instructions the agent reads when it chooses the skill.","agents/chapters/11-memory.html","agt",1],["Skip-gram","The word2vec variant in which the centre word is used to predict each word in its context window.","deep-learning/chapters/06-embeddings.html","dl",1],["SLA","Service level agreement: a contract with consequences, usually looser than the internal SLO.","reliability/chapters/02-slos-error-budgets.html","ops",0],["SLERP","Spherical linear interpolation: blending two weight tensors along the arc between them so that their norm is not shrunk in the middle.","llm-training/chapters/16-model-merging.html","llm",1],["SLI","Service level indicator: a measured ratio of good events to valid events, such as requests answered successfully within 300 ms.","reliability/chapters/02-slos-error-budgets.html","ops",0],["SLI","A service-level indicator: a measurement of behaviour, such as the fraction of requests answered within 2.5 seconds.","ai-delivery/chapters/16-research-to-product.html","aid",0],["Slice (evaluation)","A subset of cases sharing a property, such as a document type, reported separately because an overall score can hide a weak slice.","ai-delivery/chapters/18-getting-hired.html","aid",0],["Sliding window","A time-based split that trains on a fixed-length recent stretch of the past instead of all of it.","ml/chapters/13-cross-validation.html","ml",1],["Sliding-window attention","Causal attention in which each token reads only its previous W tokens, so scored pairs grow as T times W instead of T squared.","deep-learning/chapters/19-efficient-attention.html","dl",0],["Sliding window counter","A rate-limiting approximation that weights the previous fixed window's count to estimate a rolling window.","design/chapters/05-rate-limiter.html","design",0],["Sliding-window evaluation","Scoring each token with as much context as the model allows by moving a fixed-length window forward in small strides and scoring only its last positions.","deep-learning/chapters/14-language-modelling.html","dl",1],["Sliding window (reranking)","Ranking a long candidate list in overlapping windows from the back to the front so strong passages move towards the top.","retrieval/chapters/08-rerankers.html","ret",0],["SLO","Service level objective: a target for an SLI over a window, such as 99.9% of requests good over 30 days.","reliability/chapters/02-slos-error-budgets.html","ops",0],["SLO","A service-level objective: a target for an indicator over a period, such as 99% within 2.5 seconds over 30 days.","ai-delivery/chapters/16-research-to-product.html","aid",0],["Sloppy quorum","A quorum that may count stand-in nodes when the usual replicas are unreachable, trading consistency for availability.","networking/cases/case-09-dynamo.html","net",0],["SLSA","Supply-chain Levels for Software Artifacts: a framework of increasing guarantees about how software was built.","security/chapters/12-memory-supply-chain.html","sec",0],["Smoke set","A small, fast subset of the most important test cases, run on every change.","evals/chapters/02-eval-harnesses.html","evl",1],["Smoothing","Adding pseudo-counts to observed counts so unseen events get non-zero probability; add-k smoothing is MAP under a Dirichlet prior.","ml-foundations/chapters/13-likelihood-losses.html","mlf",1],["Smoothing (target encoding)","Blending a category's mean with the overall mean, weighted by the category's row count, so small categories are not trusted too much.","ml/chapters/17-feature-engineering.html","ml",0],["SmoothQuant","A method that divides activation channels by a factor and multiplies the matching weight rows by it, moving quantisation difficulty from activations to weights.","llm-training/chapters/19-quantisation.html","llm",0],["SMOTE","An oversampling method that creates new minority examples by interpolating between a minority row and one of its nearest minority neighbours.","ml/chapters/15-imbalance-calibration.html","ml",0],["Snapshot","A stored, folded copy of state together with the log position it covers, so recovery replays only the events after it.","agents/chapters/15-durable-execution.html","agt",0],["Snapshot (event sourcing)","A saved copy of an aggregate's state at some version, so rebuilding needs only the events after it.","architecture/chapters/16-cqrs-event-sourcing.html","arch",0],["Snapshot isolation","Each transaction reads from a consistent snapshot of the database as of when it started.","data/chapters/11-isolation.html","data",0],["Snowflake ID","A 64-bit, roughly time-ordered identifier built from a timestamp, a worker id and a sequence number.","design/chapters/07-unique-ids.html","design",0],["Socket","A program's endpoint for network communication, identified by protocol, IP address and port.","networking/chapters/07-ports-udp.html","net",0],["Soft attributes","Properties of a model choice that can be improved or traded against each other, such as accuracy, latency and cost, compared after the hard attributes have filtered the list.","ai-delivery/chapters/07-choosing-models.html","aid",0],["Softmax","The function that turns a vector of logits into probabilities by exponentiating each entry and dividing by the sum.","deep-learning/chapters/14-language-modelling.html","dl",1],["Softmax cross-entropy gradient","The gradient of the loss with respect to the logits, equal to the predicted probabilities minus the one-hot true label.","deep-learning/chapters/02-backpropagation.html","dl",1],["Soft targets","The teacher's full probability distribution over answers, used as a training target in place of a single hard label.","llm-training/chapters/15-distillation.html","llm",0],["Soft-threshold","The operator that shrinks a value towards zero by a fixed amount and stops at zero, used in each lasso update.","ml/chapters/06-regularisation.html","ml",1],["Software architecture","The set of decisions about a system's structure that are expensive to change: boundaries, data ownership, communication and deployment.","architecture/chapters/00-start-here.html","arch",0],["Software as a medical device","Software that performs a medical purpose, such as diagnosis or treatment, without being part of a hardware device, and is regulated as a device.","ai-delivery/chapters/09-healthcare.html","aid",0],["Software bill of materials","A machine-readable list of every component in a software bundle, with versions and licences, used to check new vulnerabilities against what was installed.","ai-delivery/chapters/13-restricted-environments.html","aid",0],["Software supply chain attack","Compromising software by tampering with its dependencies, build systems or distribution rather than the product itself.","security/chapters/12-memory-supply-chain.html","sec",0],["Solve rate","The share of systems or attempts that get an item right in a pilot run.","evals/chapters/06-building-benchmarks.html","evl",1],["Source label","A short stable tag such as [S1] attached to each chunk in the prompt so the model can cite it and code can map the citation back.","retrieval/chapters/13-rag-end-to-end.html","ret",0],["Source triage","Deciding which search hits are worth opening by scoring snippets and discounting by source kind, because reading a page costs far more than reading a snippet.","agents/chapters/16-deep-research.html","agt",0],["Span","One timed operation in a trace, with a parent, attributes and events.","reliability/chapters/06-tracing.html","ops",0],["Span","One timed operation within a trace, with a name, attributes, a parent and a status.","evals/chapters/17-observability.html","evl",0],["Sparse reward","A reward that is zero for most steps and arrives only at the end of an episode, as when a whole response is scored once.","llm-training/chapters/06-bandits-mdps.html","llm",1],["Sparse reward","A reward signal that is zero almost everywhere, so an optimiser gets no feedback until it is already close to success.","open-ended/chapters/05-open-ended-algorithms.html","oe",1],["Sparsity regulariser","A training penalty that discourages many non-zero weights so a learned sparse index keeps short posting lists.","retrieval/chapters/09-late-interaction-sparse.html","ret",0],["Special token","A reserved vocabulary entry, such as an end-of-text or end-of-turn marker, that carries control meaning rather than text.","deep-learning/chapters/13-tokenisation.html","dl",1],["Special tokens","Reserved vocabulary entries that mark structure, such as the start and end of a turn, rather than ordinary text.","llm-training/chapters/10-sft.html","llm",1],["Specification gaming","Behaviour that satisfies the literal specification of an objective without achieving the intended outcome.","open-ended/chapters/15-evaluator-hacking.html","oe",1],["Speculative decoding","Letting a cheap draft propose several tokens that the large model verifies in one forward pass, producing the same output distribution in fewer large-model passes.","llm-training/chapters/21-speculative-decoding.html","llm",0],["SPLADE","A learned sparse model that turns a masked-language-model head's word scores into sparse weights with log(1 + ReLU) and max pooling.","retrieval/chapters/09-late-interaction-sparse.html","ret",0],["Split brain","Two machines both believing they are the leader, causing conflicting writes.","networking/chapters/18-replication.html","net",0],["Spotlighting","Marking untrusted text, for example with delimiters or encoding, so the model can tell which tokens are data.","agents/chapters/19-agent-security.html","agt",1],["Spotlighting","Transforming untrusted input so that it carries a signal of its origin, helping a model treat it as data rather than instructions.","evals/chapters/13-prompt-injection.html","evl",0],["SQL injection","Untrusted input changing the structure of a SQL query because it was concatenated into the query text.","security/chapters/09-injection.html","sec",0],["Squared error","The loss (y - f)^2, which is the negative log-likelihood of Gaussian noise up to constants.","ml-foundations/chapters/13-likelihood-losses.html","mlf",1],["SSI","Serializable snapshot isolation: snapshot isolation plus tracking of read-write conflicts, aborting transactions that could break serializability.","data/chapters/12-mvcc-locking.html","data",0],["SSRF","Server-side request forgery: tricking a server into making requests the attacker chooses, often to internal services.","security/chapters/11-ssrf-server-side.html","sec",0],["SSTable","Sorted String Table: an immutable file of key-value pairs sorted by key, the building block of LSM trees.","data/chapters/05-lsm-trees.html","data",0],["Stable softmax","Softmax computed after subtracting the largest logit, which gives the same probabilities but cannot overflow.","ml-foundations/chapters/11-numerics.html","mlf",0],["Stacking","Training a meta-model on the out-of-fold predictions of base models so that it learns how to combine them.","ml/chapters/20-competitions.html","ml",0],["Staged evaluation","Testing a candidate on a few tasks first and spending a larger evaluation budget only on those that clear a bar.","open-ended/chapters/13-self-improving-agents.html","oe",1],["Stage-level evaluation","Scoring retrieval, assembly, generation and citation separately so that a wrong answer can be traced to the stage that caused it.","retrieval/chapters/13-rag-end-to-end.html","ret",0],["Staleness","The state of an index containing superseded, changed or deleted information that the source of truth no longer holds.","retrieval/chapters/17-rag-failures.html","ret",0],["Standalone question","A follow-up message rewritten with its references resolved so that it makes sense without the conversation.","retrieval/chapters/15-agentic-retrieval.html","ret",0],["Standard error","A measure of how much an estimate, such as an eval score, would vary if the sampling of questions were repeated.","evals/chapters/04-eval-statistics.html","evl",1],["Standard error","The standard deviation of an estimate such as a sample mean, equal to sigma divided by the square root of n.","ml-foundations/chapters/12-probability.html","mlf",1],["Stand-in model","A deterministic function used in place of a language model so that examples run offline and give the same output every time.","open-ended/chapters/00-start-here.html","oe",1],["Starvation","A thread that is always runnable but never gets the resource it needs because others keep winning.","systems/chapters/13-deadlock.html","sys",0],["State capacity","The limit on how many independent facts a fixed-size state can hold, roughly its number of entries.","deep-learning/chapters/22-beyond-attention.html","dl",0],["state_dict","A plain dictionary from parameter names to tensors, used to save and restore a model.","deep-learning/chapters/05-pytorch.html","dl",1],["State graph","A description of an agent's flow as nodes (steps) and edges (what follows), with a typed state object saved after each node so a run can pause, resume or replay.","agents/chapters/21-frameworks.html","agt",0],["Stateless API","An API that keeps nothing between calls, so a conversation exists only because the client re-sends the whole message list each time.","agents/chapters/01-model-apis.html","agt",1],["Stateless protocol (MCP 2026-07-28)","A design in which every request carries its protocol version and client capabilities, so any server replica can answer it without remembering earlier requests.","agents/chapters/08-mcp-production.html","agt",0],["Statement of Applicability","A document listing which management-system controls apply to an organisation and why any others are excluded.","evals/chapters/21-governance.html","evl",0],["State space duality","The result that Mamba-style layers and a form of attention are two views of the same structured matrices.","deep-learning/chapters/22-beyond-attention.html","dl",0],["State-space model","A layer that keeps a hidden state updated linearly by each input and reads its output from that state, with constant work per token.","deep-learning/chapters/22-beyond-attention.html","dl",0],["Static embeddings","Word vectors with one fixed vector per word regardless of the sentence it appears in.","deep-learning/chapters/06-embeddings.html","dl",1],["Static stability","Designing a system to keep working without needing to change anything when a dependency, especially a control plane, fails.","reliability/chapters/15-blast-radius.html","ops",0],["Statistical power","The probability that an eval detects a real difference of a given size.","evals/chapters/04-eval-statistics.html","evl",1],["Statistical power","The probability that a test detects an effect of a given size when it is real; sample size scales with one over the effect squared.","ml-foundations/chapters/15-statistics.html","mlf",1],["Statistical reproducibility","Producing a rerun result that falls within the normal run-to-run variation, even if it is not identical.","ml-foundations/chapters/04-reproducible-experiments.html","mlf",1],["Status report","A short, regular document telling the customer where an engagement stands against its plan, what is at risk and what decision is needed.","ai-delivery/chapters/17-writing-for-customers.html","aid",0],["stdio transport","An MCP transport in which the client launches the server as a subprocess and exchanges newline-delimited JSON-RPC messages over its standard input and output.","agents/chapters/07-mcp.html","agt",0],["Stemming","Reducing words to a shared stem by rule-based suffix stripping, so that refunds and refunded can match.","retrieval/chapters/01-text-analysis.html","ret",0],["Step-back question","A more general question asked first so that retrieval can find the underlying principle when the specific query matches nothing.","retrieval/chapters/15-agentic-retrieval.html","ret",0],["Stepping stone","An intermediate discovery that is valuable for what it leads to, even though it may score poorly on the final objective.","open-ended/chapters/03-novelty-search.html","oe",1],["Step-up authorisation","Re-authorising with a larger scope set after a server answers 403 insufficient_scope, keeping the scopes already granted.","agents/chapters/08-mcp-production.html","agt",0],["Stochastic gradient descent","Gradient descent that uses the gradient of a small random batch of rows at each step instead of the whole dataset.","ml/chapters/05-linear-models.html","ml",1],["Stochastic gradient descent","Gradient descent that estimates the gradient from a small random minibatch instead of the whole dataset.","ml-foundations/chapters/10-optimisers.html","mlf",1],["Stop condition","A rule enforced by the harness that ends an agent loop, such as an iteration cap, token budget, timeout or repeated-call detection.","agents/chapters/02-tool-loop.html","agt",1],["Stop reason","The field in a model response that says why generation ended, such as end_turn, max_tokens, stop_sequence or tool_use.","agents/chapters/01-model-apis.html","agt",1],["Stop sequence","A string that ends generation as soon as the model produces it, useful for preventing the model from inventing text such as a tool result.","agents/chapters/01-model-apis.html","agt",1],["Stop words","Very common words such as the and of that some analysers drop before indexing.","retrieval/chapters/01-text-analysis.html","ret",0],["Storage limitation","The principle that personal data should be kept no longer than its purpose requires.","evals/chapters/22-privacy-data.html","evl",0],["Story-based interview","An interview built around a specific recent occasion, so that details can be followed and checked instead of collecting opinions.","ai-delivery/chapters/01-discovery-interviews.html","aid",0],["Straggler","A working but slow GPU, host or link that sets the pace of a synchronous job because everyone waits for it.","llm-training/chapters/05-long-runs.html","llm",0],["Straight-through rate","The share of documents accepted automatically without a person reviewing them.","retrieval/chapters/20-tables-forms.html","ret",0],["Strangler fig","Replacing a legacy system gradually by routing one capability at a time to the new system behind a facade.","architecture/chapters/18-evolving-safely.html","arch",0],["Stratified gold set","A small labelled set drawn deliberately from each kind of case, including awkward ones, rather than sampled at random.","ai-delivery/chapters/18-getting-hired.html","aid",0],["Stratified k-fold","A k-fold split that deals each class out separately so every fold has nearly the same class proportions.","ml/chapters/13-cross-validation.html","ml",1],["Streamable HTTP","An MCP transport using a single HTTP endpoint where each client message is a POST and the server replies with JSON or a Server-Sent Events stream.","agents/chapters/07-mcp.html","agt",0],["Strict mode","A provider option that guarantees tool arguments conform to the declared schema, typically requiring closed objects and all fields listed as required.","agents/chapters/06-function-calling.html","agt",0],["Strict serializability","Transactions appear to run one at a time in an order that respects real time: serializability plus linearizability.","distributed/chapters/05-consistency-models.html","dist",0],["STRIDE","Spoofing, Tampering, Repudiation, Information disclosure, Denial of service, Elevation of privilege: a checklist of threat types.","security/chapters/01-threat-modeling.html","sec",0],["Stride","The number of pixels a filter moves between positions, where larger strides give smaller outputs.","deep-learning/chapters/07-convolutions.html","dl",0],["Strides","The number of bytes to step in memory to move one position along each axis of an array.","ml-foundations/chapters/02-numpy-arrays.html","mlf",1],["Strong eventual consistency","Replicas that have received the same updates are in the same state, without any coordination.","distributed/chapters/15-crdts.html","dist",0],["Structural chunking","Splitting a document along its own divisions such as sections, clauses, slides or functions instead of at fixed lengths.","retrieval/chapters/14-chunking.html","ret",0],["Structured logging","Logging events as key-value records, such as JSON, instead of free text, so they can be queried.","reliability/chapters/05-logs-events.html","ops",0],["Structured note-taking","Having the agent write notes such as decisions, open bugs and next steps to storage outside the window and read them back later.","agents/chapters/10-context-engineering.html","agt",1],["Structured output","Model output in a machine-readable shape such as JSON matching a schema, obtained by prompting and validating, by a forced tool or by constrained decoding.","agents/chapters/01-model-apis.html","agt",1],["STUN / TURN / ICE","NAT traversal tools: STUN discovers your public address, TURN relays traffic when direct paths fail, ICE tries the options in order.","networking/cases/case-04-nat-traversal.html","net",0],["Style control","A regression adjustment for answer length and formatting so that preference ratings reflect substance more than presentation.","evals/chapters/09-leaderboards.html","evl",0],["Sub-agent","An agent loop started by a lead agent for one part of a task, working in its own fresh context and returning a condensed result.","agents/chapters/14-multi-agent.html","agt",0],["Subgradient","A valid slope to use at a kink such as ReLU at zero, where the ordinary derivative does not exist.","ml-foundations/chapters/08-derivatives.html","mlf",1],["Subnet / subnet mask","A range of IP addresses sharing the same network prefix; the mask marks which bits are the network part.","networking/chapters/04-ip-addresses.html","net",0],["Subnormal number","A tiny float below the smallest normal value, stored without the hidden leading 1, giving gradual loss of precision before reaching zero.","ml-foundations/chapters/11-numerics.html","mlf",0],["Sub-processor","A third party, including a model provider, that handles customer data on a supplier's behalf and must be disclosed under the data processing agreement.","ai-delivery/chapters/15-security-review.html","aid",0],["Sub-question","One independently searchable piece of a research question, produced by the planner so that searches can run in parallel.","agents/chapters/16-deep-research.html","agt",0],["Subsampling","Randomly discarding very frequent words while reading a corpus, which speeds training and improves vectors for rarer words.","deep-learning/chapters/06-embeddings.html","dl",1],["Success detector","A program, often written by a model, that decides whether an agent has completed a generated task.","open-ended/chapters/06-interestingness.html","oe",1],["Success metric","A number that can be computed from stated data, with a threshold, a baseline and an owner, that both sides agree decides whether the system worked.","ai-delivery/chapters/02-requirements-ambiguity.html","aid",0],["Superficial alignment hypothesis","The claim, from the LIMA paper, that a model learns nearly all its knowledge in pretraining and that a small instruction set mainly teaches style and format.","llm-training/chapters/10-sft.html","llm",1],["Super-population","The hypothetical, unlimited set of questions from which an eval's questions are treated as a random sample.","evals/chapters/04-eval-statistics.html","evl",1],["Supervised fine-tuning (SFT)","Continuing training on examples of the desired behaviour, such as conversations, using the same next-token loss as pretraining.","llm-training/chapters/00-start-here.html","llm",0],["Supervised learning","Learning a mapping from features to a known label, as in classification and regression.","ml/chapters/00-start-here.html","ml",0],["Support vector machine","A classifier that finds the widest-margin boundary between classes, optionally in a kernel feature space.","ml/chapters/07-neighbours-bayes.html","ml",1],["Support vectors","The training points on or inside the margin, which alone determine a support vector machine's boundary.","ml/chapters/07-neighbours-bayes.html","ml",1],["Surprisal","The negative log probability of a token that actually occurred, in bits or nats: how surprised the model was.","deep-learning/chapters/14-language-modelling.html","dl",1],["Surprise","The information content of an event, -log p, which is large for rare events and adds across independent ones.","ml-foundations/chapters/14-information-theory.html","mlf",1],["Surrogate objective","A stand-in objective, the ratio times the advantage, that can be optimised on data from an older policy and matches the policy gradient at the starting point.","llm-training/chapters/08-ppo.html","llm",1],["Swap test","Judging each pair in both orders and counting a win only when the verdict agrees across orders.","evals/chapters/03-llm-judges.html","evl",1],["SWE-bench","A benchmark of 2,294 real GitHub issues from 12 Python repositories, graded by running the repository's tests on the agent's patch.","agents/chapters/18-coding-agents.html","agt",1],["SWE-bench","A benchmark that gives an agent a real GitHub repository and issue and checks whether its patch makes hidden tests pass.","open-ended/chapters/13-self-improving-agents.html","oe",1],["SWE-bench Verified","A subset of 500 SWE-bench instances that human developers screened for clear issue descriptions and fair tests.","agents/chapters/18-coding-agents.html","agt",1],["SwiGLU","A gated MLP using the SiLU nonlinearity as its gate, with hidden width about 8C/3 to match the parameters of a standard MLP.","deep-learning/chapters/10-transformer-block.html","dl",1],["SWIM","A membership protocol that probes one random member per period, asks others to probe indirectly on timeout, and spreads updates by piggybacking on pings.","distributed/chapters/03-failure-detection.html","dist",0],["Swiss-cheese model","James Reason's picture of accidents as holes in several layers of defence lining up at once.","reliability/chapters/17-postmortems.html","ops",0],["Switch","A layer-2 device that forwards frames to the right port using MAC addresses.","networking/chapters/02-local-networks.html","net",0],["Sycophancy","A model's tendency to tell users what they want to hear, such as agreeing with their stated opinion or abandoning a correct answer when challenged.","llm-training/chapters/13-reward-models.html","llm",1],["Symmetric absmax quantisation","A scheme where the scale is the largest absolute value divided by the largest integer, so zero maps exactly to zero.","llm-training/chapters/19-quantisation.html","llm",0],["Symmetric matrix","A matrix equal to its transpose; it has real eigenvalues and perpendicular eigenvectors.","ml-foundations/chapters/07-decompositions.html","mlf",0],["Symptom-based alerting","Paging on what users experience, such as errors and latency, rather than on internal causes like CPU.","reliability/chapters/07-alerting-oncall.html","ops",0],["Synchronous training","Training in which every rank must finish each step's communication before any rank continues, so one failed or slow rank stops or slows the whole job.","llm-training/chapters/05-long-runs.html","llm",0],["Synthetic data","Training data written or labelled by a model instead of a person, whose quality depends on the checks applied to it.","llm-training/chapters/15-distillation.html","llm",0],["System call","A request from a program to the kernel, like read, write, open or fork. The only way a program can reach the hardware.","systems/chapters/04-kernel-syscalls.html","sys",0],["System model","The assumptions a protocol makes about timing, failures and links. A protocol is only correct relative to its model.","distributed/chapters/01-system-models.html","dist",0],["System prompt","Standing instructions placed outside the turn-by-turn messages that set the role, rules and style for a whole conversation.","agents/chapters/01-model-apis.html","agt",1],["System prompt for an agent","Standing instructions for an agent loop that state its process, its limits, what to do on repeated failure and the style of its replies.","agents/chapters/04-prompting.html","agt",1],["TabArena","A maintained public benchmark and leaderboard for machine learning on small and medium tabular datasets.","ml/chapters/19-tabular-deep-learning.html","ml",0],["Table structure","The arrangement of a table's cells in rows and columns, including merged cells and which cells are headers.","retrieval/chapters/20-tables-forms.html","ret",0],["Table structure recognition","Recovering the grid of rows, columns, spans and header cells of a table from its image or word boxes.","retrieval/chapters/20-tables-forms.html","ret",0],["TabPFN","A transformer pre-trained on synthetic tables that classifies or regresses a new small table in one forward pass by in-context learning.","ml/chapters/19-tabular-deep-learning.html","ml",0],["Tabular foundation model","A large model pre-trained once on many (often synthetic) tables that predicts on a new table without being trained on it.","ml/chapters/19-tabular-deep-learning.html","ml",0],["Tacit knowledge","Skill and judgement a person uses without being able to state it fully, so that asking for the rules yields only part of what they know.","ai-delivery/chapters/03-expert-knowledge.html","aid",0],["Tactical vs strategic programming","Getting the next feature working as fast as possible, versus investing a little extra to keep the design good.","architecture/chapters/01-complexity.html","arch",0],["Tail-based sampling","Deciding whether to keep a trace after it finishes, so slow and failed requests can always be kept.","reliability/chapters/06-tracing.html","ops",0],["Tail latency","The latency of the slowest requests (p99, p99.9), which dominates when many calls are combined.","networking/chapters/13-performance.html","net",0],["Tail sampling","Deciding whether to keep a trace after it has finished, so rules can use errors, latency, scores and feedback.","evals/chapters/17-observability.html","evl",0],["Take-home","A timed exercise done on your own, usually two to six hours, with an incomplete brief, which a reviewer then discusses with you.","ai-delivery/chapters/18-getting-hired.html","aid",0],["Target encoding","Replacing each category by a summary of the target within it, usually the mean, which is powerful for high-cardinality columns and leaks the label unless done out of fold.","ml/chapters/17-feature-engineering.html","ml",0],["Target leakage","Using information in a feature that would not be available at prediction time, producing unrealistically good validation scores.","ml/chapters/03-eda.html","ml",0],["Target model","The large model whose output distribution speculative decoding must reproduce and which verifies the draft's tokens.","llm-training/chapters/21-speculative-decoding.html","llm",0],["Task archive","A store of every task tried, with its description, code and whether it was learned or failed, used to propose and filter new tasks.","open-ended/chapters/06-interestingness.html","oe",1],["Task arithmetic","Adding or subtracting scaled task vectors from a base model to add, combine or remove behaviours.","llm-training/chapters/16-model-merging.html","llm",1],["Task specification","A short document defining what a benchmark measures: the input, output, scoring rule, scope and the decision the score feeds.","evals/chapters/06-building-benchmarks.html","evl",1],["Task state","The lifecycle position of an A2A task: submitted, working, input-required or auth-required while active, and completed, failed, canceled or rejected once finished.","agents/chapters/09-agent-to-agent.html","agt",0],["Task vector","The difference between a fine-tuned model's weights and the weights of the base it started from, describing everything that fine-tuning changed.","llm-training/chapters/16-model-merging.html","llm",1],["tau-bench","A benchmark that grades agents in simulated customer conversations by the database state they leave and reports reliability as pass^k.","evals/chapters/08-agent-evals.html","evl",1],["TCP","Transmission Control Protocol: a reliable, ordered byte stream built on top of IP.","networking/chapters/08-tcp.html","net",0],["TD error","The critic's surprise at one step: reward plus discounted next value minus the current value, used both to train the critic and as a one-step advantage.","llm-training/chapters/09-value-functions.html","llm",1],["Teacher and student","In distillation, the teacher is the large trained model being imitated and the student is the smaller model being trained.","llm-training/chapters/15-distillation.html","llm",0],["Teacher forcing","Training with the true previous tokens as input at every position, rather than the model's own earlier predictions.","deep-learning/chapters/14-language-modelling.html","dl",1],["Technical debt","Shortcuts that make work faster now and slower later, like a loan with interest.","architecture/chapters/01-complexity.html","arch",0],["Technical report","A lab's description of a model or system, usually with less detail about what was tried and discarded than a research paper.","ml-foundations/chapters/16-reading-papers.html","mlf",0],["Technology-assisted review","Document review in which a classifier trained on lawyers' labels ranks or labels the remaining documents for relevance.","ai-delivery/chapters/10-legal.html","aid",0],["TEDS","Tree-edit-distance-based similarity, a table metric that compares predicted and true tables as HTML trees and gives partial credit for small structural damage.","retrieval/chapters/20-tables-forms.html","ret",0],["Temperature","A sampling setting that divides the logits before the softmax, so low values concentrate probability on the top token and high values spread it out.","agents/chapters/01-model-apis.html","agt",1],["Temperature","A number that divides the logits before the softmax: below one it sharpens the distribution and above one it flattens it.","deep-learning/chapters/15-decoding.html","dl",1],["Temperature","A divisor applied to logits before the softmax: below 1 sharpens the distribution toward the largest logit, above 1 flattens it.","ml-foundations/chapters/12-probability.html","mlf",1],["Temperature","A constant that divides similarities before the softmax; small values sharpen the distribution and focus training on the hardest negatives.","retrieval/chapters/07-dense-retrieval.html","ret",1],["Temperature (distillation)","A divisor applied to logits before the softmax; values above 1 flatten the distribution so small probabilities of wrong answers become visible to the loss.","llm-training/chapters/15-distillation.html","llm",0],["Temperature sampling","Choosing each source with probability proportional to its size raised to a power below one, so that small sources are upsampled.","llm-training/chapters/01-pretraining-data.html","llm",0],["Temperature scaling","Recalibration that divides a model's logits by a single number fitted on held-out data.","ml/chapters/15-imbalance-calibration.html","ml",0],["Temporal coupling","Two parts must both be available at the same time for an operation to succeed.","architecture/chapters/13-sync-async.html","arch",0],["Temporal leakage","Leakage from using information dated after the prediction time, for example a rolling window that extends into the future.","ml/chapters/14-leakage.html","ml",1],["Temporal split","Training on data before a date and testing on data after it, to mimic facing the future.","llm-training/chapters/23-evaluating-models.html","llm",0],["Tenant isolation","Ensuring one customer of a shared system can never see or affect another's data or performance.","security/chapters/15-multi-tenancy.html","sec",0],["Tenant isolation","Ensuring that one customer's documents can never appear in another customer's retrieval, by separate indexes or by mandatory tenant predicates.","retrieval/chapters/12-filters-permissions.html","ret",0],["Tensor","An n-dimensional array with a shape, a number format (dtype) and a device, which can also record the operations applied to it.","deep-learning/chapters/05-pytorch.html","dl",1],["Tensor core","A GPU unit that multiplies small matrix tiles in one step at low precision, which is why peak throughput is quoted per number format.","ml-foundations/chapters/17-compute-costs.html","mlf",0],["Tensor parallelism","Splitting each layer's weight matrices across GPUs so that they compute one layer together, at the cost of all-reduces inside every layer.","llm-training/chapters/03-parallelism.html","llm",0],["Term expansion","Giving a text weight on vocabulary words that it does not contain, so queries can match it despite different wording.","retrieval/chapters/09-late-interaction-sparse.html","ret",0],["Term frequency","The number of times a term occurs in a particular document.","retrieval/chapters/02-bm25.html","ret",0],["Terminal state","A task state (completed, failed, canceled or rejected) from which an A2A task cannot be restarted; changes are made in a new task in the same context.","agents/chapters/09-agent-to-agent.html","agt",0],["Term (search index)","The normalised unit stored in an index, such as a stem, number or lowercase word, which need not be a dictionary word.","retrieval/chapters/01-text-analysis.html","ret",0],["Test case","One input together with the checks or reference answer that define correct behaviour for it.","evals/chapters/02-eval-harnesses.html","evl",1],["Test collection","A fixed set of documents, queries and relevance judgements used to compare retrieval systems repeatably (the Cranfield paradigm).","retrieval/chapters/05-test-collections.html","ret",0],["Test double","Any stand-in for a real dependency in a test: dummy, stub, fake, mock or spy.","architecture/chapters/07-testability.html","arch",0],["Test set","Held-out data used once, after all choices are made, to report an honest estimate of generalisation error.","ml/chapters/01-generalisation.html","ml",1],["Test set","Data touched once, after all decisions, to report an unbiased final score.","open-ended/chapters/16-held-out-evaluation.html","oe",1],["Test set (versus development set)","The test set is scored rarely and never used to make choices, while the development set is used repeatedly to select checkpoints and settings.","llm-training/chapters/23-evaluating-models.html","llm",0],["Test-time compute","The computation spent when a model answers a query, as opposed to the computation spent training it.","open-ended/chapters/08-inference-time-search.html","oe",1],["Text detection","Finding where the text is on a page and returning boxes or polygons for lines or words, before any character is read.","retrieval/chapters/19-ocr.html","ret",0],["Text extraction","Pulling the main prose out of a web page's HTML while discarding navigation, adverts and other boilerplate.","llm-training/chapters/01-pretraining-data.html","llm",0],["Text layer","The characters, fonts and positions stored in a born-digital PDF, which can be read exactly without any OCR.","retrieval/chapters/19-ocr.html","ret",0],["Text-to-LoRA","A hypernetwork that generates LoRA matrices for a base model in one forward pass from a natural-language description of the task.","llm-training/chapters/17-adapters-on-demand.html","llm",0],["The AI Scientist","A pipeline from Sakana AI and collaborators that proposes machine-learning research ideas, runs the experiments, writes a paper and reviews it automatically.","open-ended/chapters/14-automated-science.html","oe",1],["Theoretical saturation","The point at which new traces stop revealing new failure kinds or changing existing categories.","evals/chapters/01-error-analysis.html","evl",1],["Think-aloud","An elicitation method in which an expert performs a real task while saying whatever passes through their mind, without explaining or justifying.","ai-delivery/chapters/03-expert-knowledge.html","aid",0],["Thinking budget","A cap on how many tokens a model may spend reasoning before it answers, trading answer quality against cost and latency.","agents/chapters/03-reasoning-planning.html","agt",1],["Thompson sampling","A bandit strategy that samples a plausible value for each action from its posterior distribution and picks the action with the highest sample.","llm-training/chapters/06-bandits-mdps.html","llm",1],["Thompson sampling","A bandit strategy that samples a plausible payout rate for each option from its posterior belief and picks the highest sample.","open-ended/chapters/01-tree-search.html","oe",1],["Thread","An independent flow of execution inside a process, with its own stack and registers but sharing the process's memory.","systems/chapters/10-threads.html","sys",0],["Thread pool","A fixed set of worker threads that take tasks from a queue, instead of creating a thread per task.","systems/chapters/14-queues-backpressure.html","sys",0],["Threat model","A structured description of what you are protecting, from whom, how it could be attacked and what you do about it.","security/chapters/01-threat-modeling.html","sec",0],["Three-pass method","Keshav's way of reading a paper in up to three passes (scan, grasp, re-create), stopping as soon as your question is answered.","ml-foundations/chapters/16-reading-papers.html","mlf",0],["Three-way handshake","SYN, SYN-ACK, ACK: how TCP opens a connection and agrees on starting sequence numbers.","networking/chapters/08-tcp.html","net",0],["Throughput","How much data actually gets through per second, which can be less than the bandwidth.","networking/chapters/13-performance.html","net",0],["Throughput (serving)","The total number of tokens a system generates per second across all concurrent requests.","llm-training/chapters/22-token-economics.html","llm",0],["Tidy data","A table layout with one variable per column, one observation per row and one table per type of observational unit.","ml-foundations/chapters/03-data-wrangling.html","mlf",0],["Tie-out","Checking that every figure in a generated answer matches a value in the cited source, with its page or table.","ai-delivery/chapters/08-finance.html","aid",0],["TIES-Merging","A merge method that trims small task-vector entries, elects a sign for each weight and averages only the entries that agree with it.","llm-training/chapters/16-model-merging.html","llm",1],["Timeout","Giving up on waiting after a chosen time. The only way to suspect a failure in a distributed system.","networking/chapters/16-failure.html","net",0],["Time series","A sequence of measurements of one quantity taken at regular times, such as daily sales.","ml/chapters/18-time-series.html","ml",0],["Timestamp oracle","A service handing out strictly increasing timestamps, used by Percolator for snapshot reads and commits.","distributed/chapters/14-distributed-transactions.html","dist",0],["Time to first token","The delay between sending a request and receiving the first token of the reply, dominated by reading the prompt.","evals/chapters/19-cost-latency-quality.html","evl",0],["Time to first token (TTFT)","The delay between sending a request and receiving the first generated token, set mainly by prefill and so by the prompt length.","llm-training/chapters/18-kv-cache.html","llm",0],["TLA+","Leslie Lamport's specification language for describing systems as states and actions, checked with the TLC model checker.","distributed/chapters/20-formal-methods.html","dist",0],["TLB","Translation lookaside buffer: a small CPU cache of recent virtual-to-physical page translations.","systems/chapters/06-virtual-memory.html","sys",0],["TLS","Transport Layer Security: encryption, integrity and authentication for network connections.","networking/chapters/11-tls.html","net",0],["Toil","Manual, repetitive, automatable operational work that grows with the service and has no lasting value.","reliability/chapters/03-sre-toil.html","ops",0],["Token bucket","A rate limiter: tokens refill at a fixed rate, each request spends one, and bursts are allowed up to the bucket size.","architecture/chapters/17-resilience.html","arch",0],["Tokeniser","A fixed program that converts text into a list of integer ids for the model and converts ids back into text.","deep-learning/chapters/13-tokenisation.html","dl",1],["Tokenising","Cutting a string of text into tokens at word boundaries.","retrieval/chapters/01-text-analysis.html","ret",0],["Tokenization","Replacing sensitive data with a meaningless token and keeping the mapping in a separate, tightly controlled vault.","security/chapters/17-data-protection.html","sec",0],["Token-mean loss","A batch loss averaged over every unmasked token, so long responses carry more total weight than short ones.","llm-training/chapters/10-sft.html","llm",1],["Tokens per parameter","The ratio of training tokens to parameters, about 20 at the compute-optimal point in the Chinchilla analysis and far higher in models built for cheap serving.","deep-learning/chapters/18-scaling-laws.html","dl",0],["Tolerant reader","A consumer that ignores fields it doesn't understand, so producers can add fields safely.","architecture/chapters/10-evolving-contracts.html","arch",0],["Tombstone","A special record meaning \"this key was deleted\", needed because append-only files can't erase in place.","data/chapters/04-log-hash-index.html","data",0],["Tool","A function the surrounding program offers to a model, which the model can request but never runs itself.","agents/chapters/00-start-here.html","agt",0],["tool_choice","A request setting that lets the model decide on tools (auto), requires some tool, requires a named tool, or forbids tools for a turn.","agents/chapters/06-function-calling.html","agt",0],["Tool definition","The name, plain-language description and JSON Schema of a function that a model may request; the model sees this and never the function's code.","agents/chapters/02-tool-loop.html","agt",1],["Tool description","The prose in a tool definition that tells the model what the tool does, when to use it, what its arguments mean and what it does not return.","agents/chapters/05-tool-design.html","agt",1],["Tool linter","A script that checks tool definitions for known weaknesses such as thin descriptions, generic argument names and overlapping tools.","agents/chapters/05-tool-design.html","agt",1],["Tool poisoning","Hiding malicious instructions in a tool description or result so that the model follows them.","agents/chapters/07-mcp.html","agt",0],["tool_result block","A content block in a user message that answers one tool_use request, matched by tool_use_id and flagged with is_error when the tool failed.","agents/chapters/02-tool-loop.html","agt",1],["Tool-result clearing","Replacing old tool outputs in the history with short placeholders while keeping the calls and the model's own messages.","agents/chapters/10-context-engineering.html","agt",1],["Tool shadowing","A malicious tool's description altering how the agent uses a different, trusted tool.","agents/chapters/19-agent-security.html","agt",1],["tool_use block","A content block in an assistant message in which the model requests a tool by name, with an id and an input object.","agents/chapters/02-tool-loop.html","agt",1],["Top-k sampling","Sampling only from the k most probable tokens after renormalising.","deep-learning/chapters/15-decoding.html","dl",1],["Top-p sampling","Sampling only from the smallest set of top tokens whose probabilities add up to p, after renormalising them.","agents/chapters/01-model-apis.html","agt",1],["Top-p sampling","Also called nucleus sampling: sampling only from the smallest set of tokens whose probabilities sum to at least p.","deep-learning/chapters/15-decoding.html","dl",1],["torch.compile","PyTorch 2's compiler entry point, which captures a model as a graph and generates fused kernels, using Triton on GPUs.","llm-training/chapters/04-kernels.html","llm",0],["Torn write","A write that was only partly saved when a crash happened, leaving a mix of old and new bytes.","systems/chapters/09-durability.html","sys",0],["Total cost of ownership","Everything the customer pays over the life of a system: building, running, supporting, changing it and the labour that works alongside it.","ai-delivery/chapters/14-cost-roi.html","aid",0],["Total order broadcast","Delivering every message to every node in the same order. Equivalent in power to consensus.","distributed/chapters/08-consensus-smr.html","dist",0],["Total parameters","Every weight in a mixture-of-experts model, counting all experts; this sets the memory needed.","deep-learning/chapters/20-mixture-of-experts.html","dl",0],["TOTP","Time-based one-time password: a six-digit code derived from a shared secret and the current time (RFC 6238).","security/chapters/05-authentication.html","sec",0],["ToUnicode map","A table in a PDF font that says which Unicode character each glyph code stands for; without it, extracted text may be gibberish.","retrieval/chapters/18-pdf-layout.html","ret",0],["Tournament selection","Choosing a parent by drawing k individuals at random and taking the fittest of them.","open-ended/chapters/02-evolutionary-algorithms.html","oe",1],["Trace","The full record of one request: input, prompts, model and tool calls, retrieved documents and final output, in order.","evals/chapters/00-start-here.html","evl",0],["Traceability matrix","A table linking each risk to the control that addresses it and the document that proves the control exists, so that gaps show as empty cells.","ai-delivery/chapters/15-security-review.html","aid",0],["Trace context propagation","Passing trace and span ids with every call, for example in the W3C traceparent header, so spans join into one trace.","reliability/chapters/06-tracing.html","ops",0],["Training","The step in which an algorithm adjusts a model's parameters to fit the training examples; also called fitting.","ml/chapters/00-start-here.html","ml",0],["Training set","The part of the labelled data used to fit a model's parameters.","ml/chapters/01-generalisation.html","ml",1],["Training window","A run of T consecutive tokens used as input, paired with the same run shifted by one token as the targets, so it supplies T prediction problems at once.","deep-learning/chapters/12-building-gpt.html","dl",1],["Train/serve skew","A difference between how a feature is computed in training and how it is computed in production.","ml/chapters/14-leakage.html","ml",1],["Train-test contamination","Leakage caused by the same or near-identical examples appearing in both the training and the evaluation data.","ml/chapters/14-leakage.html","ml",1],["Trajectory","One complete sequence of states and actions from a start to an end, such as a prompt and the response sampled for it.","llm-training/chapters/07-policy-gradients.html","llm",1],["Trajectory metrics","Cheap automatic measures of a run, such as steps, tool errors, repeated calls and cap hits, used to find trials worth reading.","evals/chapters/08-agent-evals.html","evl",1],["Transaction","A group of reads and writes the database treats as one unit: all of it happens, or none of it does.","data/chapters/10-acid.html","data",0],["Transactional outbox","Writing an event to an outbox table in the same transaction as the data change, then publishing it separately.","data/chapters/19-streams-cdc.html","data",0],["Transcoding","Converting a video into the formats, resolutions and bitrates needed for playback.","design/chapters/13-video-streaming.html","design",0],["Transcript (agent evaluation)","The complete record of a trial: messages, tool calls, results and reasoning, also called a trace or trajectory.","evals/chapters/08-agent-evals.html","evl",1],["Transfer (POET)","Testing an agent from one environment on another and adopting it if it scores higher there, so skills spread between challenges.","open-ended/chapters/05-open-ended-algorithms.html","oe",1],["Transfer (research to product)","Whether a method that works on a paper's benchmark still works on a different distribution such as a customer's own documents.","ai-delivery/chapters/16-research-to-product.html","aid",0],["Transformer","A neural network architecture, introduced in 2017, in which every position in a sequence attends directly to every other and all positions are processed in parallel.","deep-learning/chapters/00-start-here.html","dl",0],["Transformer block","The repeating unit of a Transformer: an attention sublayer and an MLP sublayer, each with a normalisation and a residual connection.","deep-learning/chapters/10-transformer-block.html","dl",1],["Transit gateway","A cloud network hub that connects many VPCs and on-premises networks through one routed attachment each.","networking/chapters/22-cloud-networking.html","net",0],["Translation equivariance","The property that shifting the input shifts the output feature map by the same amount.","deep-learning/chapters/07-convolutions.html","dl",0],["Transpose","The matrix with rows and columns swapped; it reverses the order of products, (AB)^T = B^T A^T.","ml-foundations/chapters/06-matrices.html","mlf",1],["Trap function","A small deceptive test problem whose score rises toward a poor optimum and hides a single better optimum at the far end.","open-ended/chapters/03-novelty-search.html","oe",1],["Tree of Thoughts","A prompting and search method in which the model proposes and evaluates partial reasoning steps while a search procedure decides which to extend.","open-ended/chapters/08-inference-time-search.html","oe",1],["Trend","The slow underlying direction of a series, such as steady growth or decline.","ml/chapters/18-time-series.html","ml",0],["Trial","One attempt by an agent at a task; agent evals run several trials per task because outputs vary.","evals/chapters/08-agent-evals.html","evl",1],["Trie","A prefix tree, used for typeahead by storing the top completions at each prefix node.","design/chapters/11-search-typeahead.html","design",0],["Triple","A fact written as subject, relation and object, such as (Priya Nair, reports_to, Chen Wu).","retrieval/chapters/15-agentic-retrieval.html","ret",0],["Triton","A Python-syntax language and compiler for writing GPU kernels in terms of blocks of values, with the compiler handling threads and shared memory.","llm-training/chapters/04-kernels.html","llm",0],["True negative rate","Of the outputs humans label FAIL, the fraction the judge also fails.","evals/chapters/03-llm-judges.html","evl",1],["True positive rate","Of the outputs humans label PASS, the fraction the judge also passes.","evals/chapters/03-llm-judges.html","evl",1],["TrueTime","Google Spanner's clock API, which returns a time interval guaranteed to contain the true time.","networking/cases/case-10-ordering-at-scale.html","net",0],["Truncated BPTT","Backpropagation through time over chunks of a long sequence, passing the state between chunks but stopping gradients at their boundaries.","deep-learning/chapters/08-sequences-rnns.html","dl",0],["Truncated SVD","The sum of the first k terms of the SVD, which is the best rank-k approximation of a matrix.","ml-foundations/chapters/07-decompositions.html","mlf",0],["Truncation (sampling)","Removing the unlikely tail of the next-token distribution before drawing, using top-k, top-p or min-p.","deep-learning/chapters/15-decoding.html","dl",1],["Truncation with guidance","Cutting an oversized tool result and telling the model that it was cut and how to narrow the next request.","agents/chapters/05-tool-design.html","agt",1],["Trunk-based development","Everyone integrating small changes into one main branch at least daily, using feature flags for unfinished work.","architecture/chapters/21-engineering-practice.html","arch",0],["Trust boundary","A line in a system where data or control passes between parts with different levels of trust; most attacks happen at one.","security/chapters/01-threat-modeling.html","sec",0],["Trusted computing base","The set of components that must be correct for the system to be secure; smaller is better.","security/chapters/02-principles.html","sec",0],["Trusted core","The evaluator, selection rule, limits, lineage writer and guard, kept outside the loop's reach.","open-ended/chapters/17-self-modification-safety.html","oe",1],["Trust region","The neighbourhood of the current policy, usually defined by a KL limit, within which a local approximation of the objective is trusted.","llm-training/chapters/08-ppo.html","llm",1],["Trust-then-verify gap","The failure of accepting a plausible-looking implementation that has not been checked against edge cases or the real requirement.","agents/chapters/22-ai-coding-tools.html","agt",0],["t-SNE","A non-linear embedding that places points in two dimensions so that neighbour probabilities match those in the original space, preserving local structure.","ml/chapters/11-dimensionality-reduction.html","ml",0],["TTL (DNS)","How long a DNS answer may be cached before it must be looked up again.","networking/chapters/09-dns.html","net",0],["TTL (IP)","Time To Live: a hop counter in the IP header, decremented by each router; the packet is dropped at zero.","networking/chapters/05-routing.html","net",0],["Tukey's fence","A rule that flags values beyond 1.5 interquartile ranges outside the first or third quartile.","ml/chapters/12-anomaly-detection.html","ml",0],["Two Generals problem","A thought experiment showing that agreement over an unreliable channel can never be guaranteed with certainty.","networking/chapters/16-failure.html","net",0],["Two-pass inference","A scheme in which a first pass identifies the task and chooses a blend of expert vectors, and a second pass generates the answer with the adapted weights.","llm-training/chapters/17-adapters-on-demand.html","llm",0],["Two-phase commit (2PC)","A coordinator asks participants to prepare and vote, then tells all of them the decision. It blocks if the coordinator fails after votes are cast.","distributed/chapters/13-atomic-commit.html","dist",0],["Two-phase locking (2PL)","Transactions take locks as they go and release them only at the end, which makes them serializable but makes readers and writers wait.","data/chapters/12-mvcc-locking.html","data",0],["Two-stage retrieval","A pipeline where a fast, recall-oriented retriever proposes candidates and a slower, precision-oriented model reorders them.","retrieval/chapters/08-rerankers.html","ret",0],["Type I and Type II errors","A Type I error is a false positive (rejecting a true null); a Type II error is a false negative (missing a real effect).","ml-foundations/chapters/15-statistics.html","mlf",1],["Type promotion","The rules that decide the dtype of a result when operands have different dtypes.","ml-foundations/chapters/02-numpy-arrays.html","mlf",1],["Ubiquitous language","Using the same precise business vocabulary in conversation, code and documentation.","architecture/chapters/06-ddd.html","arch",0],["UCB1","A bandit rule that picks the option with the highest average reward plus an optimism bonus that is larger for rarely tried options.","open-ended/chapters/01-tree-search.html","oe",1],["UCT","Upper confidence bounds applied to trees: choosing the move at every tree node with the UCB1 rule.","open-ended/chapters/01-tree-search.html","oe",1],["UDP","User Datagram Protocol: minimal, connectionless, unreliable transport with an 8-byte header.","networking/chapters/07-ports-udp.html","net",0],["UMAP","A non-linear embedding that builds a fuzzy nearest-neighbour graph and finds a low-dimensional layout with a matching graph, faster than t-SNE and able to transform new points.","ml/chapters/11-dimensionality-reduction.html","ml",0],["Unanswerable question","A test question whose answer is not in the supplied material, used to check that a system abstains instead of guessing.","evals/chapters/11-grounding-abstention.html","evl",0],["Underfitting","Using a model too rigid to capture the real pattern, so error is high on both training and new data.","ml/chapters/01-generalisation.html","ml",1],["Underflow","A result smaller than the format's smallest representable value, which becomes zero.","ml-foundations/chapters/11-numerics.html","mlf",0],["Undersampling","Discarding some of the majority-class rows before training to make the classes more even.","ml/chapters/15-imbalance-calibration.html","ml",0],["Under-stemming","A stemming error that fails to merge related word forms.","retrieval/chapters/01-text-analysis.html","ret",0],["Unicode normalisation","Converting different encodings of the same visible text, such as a precomposed é and e plus a combining accent, into one form.","retrieval/chapters/01-text-analysis.html","ret",0],["Unigram language model tokeniser","A subword method that starts from a large candidate vocabulary and prunes the pieces whose removal costs least, allowing several segmentations of one word.","deep-learning/chapters/13-tokenisation.html","dl",1],["Unit economics","The cost of serving one unit of value, such as a request or a user, used to reason about efficiency.","reliability/chapters/20-cost-efficiency.html","ops",0],["Unit economics","What it costs to complete one unit of work from end to end, including every model call, tool, retry and human step that touches it.","ai-delivery/chapters/14-cost-roi.html","aid",0],["Unit vector","A vector of length 1, obtained by dividing a vector by its norm so that only its direction remains.","ml-foundations/chapters/05-vectors-similarity.html","mlf",1],["Universal approximation theorem","The result that a network with one hidden non-linear layer and enough units can approximate any reasonable continuous function on a bounded region.","deep-learning/chapters/01-neurons-layers.html","dl",1],["Universal Scalability Law","Neil Gunther's model of throughput as concurrency grows, including contention and coherency costs that can make it fall.","reliability/chapters/08-queueing-theory.html","ops",0],["Unjudged document","A retrieved document that no judge labelled, conventionally scored as non-relevant, which can under-score systems that retrieve differently.","retrieval/chapters/04-relevance-metrics.html","ret",0],["Unknown token","A placeholder used by word-level vocabularies for any word they have never seen, which loses the word's identity.","deep-learning/chapters/13-tokenisation.html","dl",1],["Unsafe deserialization","Loading attacker-controlled data with a format, such as pickle, that can create arbitrary objects or run code.","security/chapters/09-injection.html","sec",0],["Unsupervised learning","Looking for structure in data without labels, as in clustering and dimensionality reduction.","ml/chapters/00-start-here.html","ml",0],["Uplift model","A model that estimates how much an action changes an individual's outcome, rather than how likely the outcome is.","ml/chapters/21-model-to-value.html","ml",0],["Upper confidence bound","A bandit strategy that adds to each action's average an optimism bonus that shrinks as the action is tried more often.","llm-training/chapters/06-bandits-mdps.html","llm",1],["Upstream gradient","The gradient of the loss with respect to a layer's output, handed backwards to that layer by the one above it.","deep-learning/chapters/02-backpropagation.html","dl",1],["Uptraining","Converting an existing multi-head checkpoint to grouped-query attention with a small fraction of the original training compute.","deep-learning/chapters/19-efficient-attention.html","dl",0],["URL","Uniform Resource Locator: scheme, host, port, path and query identifying a resource on the web.","networking/chapters/10-http.html","net",0],["URL frontier","A web crawler's prioritised, per-host queue of URLs waiting to be fetched.","design/chapters/18-web-crawler.html","design",0],["USE method","Utilization, Saturation and Errors: the three things to check for every resource (Brendan Gregg).","reliability/chapters/04-metrics.html","ops",0],["User mode / kernel mode","CPU privilege levels. Normal programs run in user mode and can't touch hardware; the kernel runs in kernel mode and can.","systems/chapters/04-kernel-syscalls.html","sys",0],["UTF-8","The encoding that turns any Unicode text into a sequence of one to four bytes per character.","deep-learning/chapters/13-tokenisation.html","dl",1],["Utilisation","The share of time a GPU is doing useful work; idle time is billed but produces no tokens.","llm-training/chapters/22-token-economics.html","llm",0],["Utilization","The fraction of time a server is busy: arrival rate divided by service rate.","reliability/chapters/08-queueing-theory.html","ops",0],["UUIDv7","A UUID whose leading bits are a millisecond timestamp, so identifiers sort roughly by creation time (RFC 9562).","design/chapters/07-unique-ids.html","design",0],["Vacuous truth","A statement about an empty set that holds automatically, such as 'no tests failed' when the test list has been emptied.","open-ended/chapters/15-evaluator-hacking.html","oe",1],["Validation loss","The loss on held-out text the model never trains on, used to judge whether it has learned something general.","deep-learning/chapters/12-building-gpt.html","dl",1],["Validation set","The held-out part of the labelled data used to compare candidates and choose hyperparameters.","ml/chapters/01-generalisation.html","ml",1],["Value (attention)","The vector attached to each position that is passed on, in proportion to its attention weight, when the position is read.","deep-learning/chapters/09-attention.html","dl",1],["Value function","The expected return from a state (or state and action) when following a given policy.","llm-training/chapters/06-bandits-mdps.html","llm",1],["Value head","A linear layer on a language model's hidden states that outputs one predicted return per token position instead of vocabulary logits.","llm-training/chapters/09-value-functions.html","llm",1],["Value object","An immutable object defined only by its values, like Money(10, 'EUR'), with no identity of its own.","architecture/chapters/06-ddd.html","arch",0],["Value target","The regression target for the critic in PPO, equal to the GAE advantage plus the value predicted when the data was collected.","llm-training/chapters/09-value-functions.html","llm",1],["Vanishing gradient","The shrinking of gradients towards zero as they are multiplied through many steps, so early inputs get almost no learning signal.","deep-learning/chapters/08-sequences-rnns.html","dl",0],["Vanishing gradient","The collapse of a gradient towards zero when it passes back through many layers whose local derivatives are below one.","ml-foundations/chapters/08-derivatives.html","mlf",1],["Vanishing gradients","Gradients that shrink exponentially towards the early layers of a deep network until they carry no usable signal.","deep-learning/chapters/03-training-dynamics.html","dl",1],["Variance","The part of prediction error caused by the fitted model changing from one training sample to the next.","ml/chapters/06-regularisation.html","ml",1],["Variance","The expected squared distance from the mean, measuring spread; it adds for independent variables.","ml-foundations/chapters/12-probability.html","mlf",1],["Vector","An ordered list of numbers that can also be drawn as an arrow from the origin; the basic object of linear algebra.","ml-foundations/chapters/05-vectors-similarity.html","mlf",1],["Vector clock","A list of counters, one per process, that can tell whether two events are ordered or concurrent.","networking/chapters/17-time.html","net",0],["Vectorising","Rewriting a per-element loop as one operation on a whole array so that compiled code runs the loop.","ml-foundations/chapters/01-python-numerics.html","mlf",1],["Vector-Jacobian product","The product of an incoming gradient with a layer's Jacobian, which backpropagation computes without ever forming the Jacobian.","deep-learning/chapters/02-backpropagation.html","dl",1],["Vector-Jacobian product","The backward rule of a tensor operation: from the gradient at its output, compute the gradient at its inputs without building the Jacobian.","ml-foundations/chapters/09-autodiff.html","mlf",1],["Vector search","Finding the items whose embedding vectors are nearest to a query vector, usually approximately.","data/chapters/17-specialised-stores.html","data",0],["Vendor lock-in","Dependence on one supplier that makes leaving costly, reduced by contract terms on data and model portability, ownership and exit plans.","ai-delivery/chapters/11-public-sector.html","aid",0],["Verbosity bias","A judge's tendency to prefer longer answers even when the extra length adds nothing.","evals/chapters/03-llm-judges.html","evl",1],["Verifiable reward","A reward obtained by running a checker against ground truth, such as comparing a final answer or running tests, so it cannot be flattered the way a learned model can.","llm-training/chapters/14-rlvr-grpo.html","llm",1],["Verification loop","A cycle in which an agent edits, runs a check such as tests or a build, reads the result and iterates until the check passes, instead of stopping when its work looks done.","agents/chapters/22-ai-coding-tools.html","agt",0],["Verifier","A deterministic check run on a model's output before it is returned, such as confirming that every number in a summary appears in the source.","ai-delivery/chapters/16-research-to-product.html","aid",0],["Verifier","A checker, exact or learned, that decides whether a candidate answer is correct or how good it is.","open-ended/chapters/08-inference-time-search.html","oe",1],["ViDoRe","A benchmark of page-level retrieval over visually rich documents, introduced with ColPali and extended in later versions.","retrieval/chapters/21-visual-retrieval.html","ret",0],["View (array)","An array that describes the same memory as another array, so writing through one changes the other.","ml-foundations/chapters/02-numpy-arrays.html","mlf",1],["Virtual environment","A directory with its own Python interpreter link and installed packages, keeping one project's dependencies separate from others.","ml-foundations/chapters/04-reproducible-experiments.html","mlf",1],["Virtual loss","A temporary pessimistic visit added to a node so that parallel search workers spread out instead of choosing the same leaf.","open-ended/chapters/01-tree-search.html","oe",1],["Virtual memory","Giving each process its own private address space, which the hardware and kernel map onto real RAM page by page.","systems/chapters/06-virtual-memory.html","sys",0],["Virtual waiting room","A queue in front of a contended sale that admits users at a rate the backend can handle.","design/chapters/15-ticketing.html","design",0],["Vision-language model","A model that takes images and text together and produces text, usually a language model that reads image tokens placed in its context.","deep-learning/chapters/21-vision-language.html","dl",0],["Vision Transformer","A Transformer that treats the patches of an image as its input sequence, with bidirectional attention.","deep-learning/chapters/21-vision-language.html","dl",0],["Visual document retrieval","Retrieving document pages by embedding their images directly, without first extracting text.","retrieval/chapters/21-visual-retrieval.html","ret",0],["Visual instruction tuning","Fine-tuning a vision-language model on conversations about images, with the loss on the answer tokens only.","deep-learning/chapters/21-vision-language.html","dl",0],["Vocabulary mismatch","The failure of a word-matching search when a document uses different words from the query, such as spent against spending.","agents/chapters/16-deep-research.html","agt",0],["Vocabulary mismatch","The failure where a query and a relevant document describe the same idea in different words, so word matching finds nothing.","retrieval/chapters/00-start-here.html","ret",0],["Voting","A parallelisation variant in which the same task runs several times and the answers are combined, usually by majority, to raise confidence.","agents/chapters/13-workflow-patterns.html","agt",1],["Voyager","A Minecraft agent that uses a language model to set its own tasks, write code for them, verify the code, and store working programs in a skill library.","open-ended/chapters/07-lifelong-agents.html","oe",1],["VPC","Virtual private cloud: an isolated, software-defined network you define inside a cloud provider.","networking/chapters/22-cloud-networking.html","net",0],["Warmup","A short initial phase in which the learning rate rises from near zero to its peak so early steps are not destabilising.","ml-foundations/chapters/10-optimisers.html","mlf",1],["Watch","A one-time notification a coordination-service client registers to learn when a key or node changes.","distributed/chapters/11-coordination-services.html","dist",0],["Watermelon report","A status report that is green on the outside and red on the inside, hiding real problems behind an optimistic rating.","ai-delivery/chapters/17-writing-for-customers.html","aid",0],["Weight","A learned number that scales one input of a neuron, setting how much and in which direction it matters.","deep-learning/chapters/01-neurons-layers.html","dl",1],["Weight decay","Multiplying the weights by a factor slightly below one at every step, so that only weights the data keeps pushing stay large.","deep-learning/chapters/04-deep-regularisation.html","dl",1],["Weight decay","Shrinking every weight by a small fraction at each step to discourage large weights.","ml-foundations/chapters/10-optimisers.html","mlf",1],["Weighted kappa","A kappa for graded labels in which disagreements between nearby grades count as less serious than distant ones.","retrieval/chapters/05-test-collections.html","ret",0],["Weight-only quantisation","Quantising only the weights while activations stay in 16 bits, with weights dequantised inside the matrix-multiply kernel.","llm-training/chapters/19-quantisation.html","llm",0],["Weight sharing","Reusing the same weights at every position of the input, so the parameter count does not grow with the input size.","deep-learning/chapters/07-convolutions.html","dl",0],["Weight tying","Reusing the input embedding matrix, transposed, as the output layer of a language model to save parameters.","deep-learning/chapters/06-embeddings.html","dl",1],["Wide and long format","Two layouts of the same data: wide has one column per value of a variable (such as month), long has one row per observation.","ml-foundations/chapters/03-data-wrangling.html","mlf",0],["Wide event","One rich structured record per request with many fields, from which metrics and investigations can be derived later.","reliability/chapters/05-logs-events.html","ops",0],["Wi-Fi","Wireless local networking over radio, sharing the air between devices.","networking/chapters/02-local-networks.html","net",0],["Wilson interval","A confidence interval for a proportion that behaves well at small sample sizes and near 0% or 100%.","ai-delivery/chapters/17-writing-for-customers.html","aid",0],["Wilson interval","A confidence interval for a proportion that behaves sensibly for small samples and scores near 0 or 100 percent.","evals/chapters/04-eval-statistics.html","evl",1],["Wilson interval","A confidence interval for a proportion that stays inside 0 and 1 and covers near the stated rate even for small samples and extreme rates.","ml-foundations/chapters/15-statistics.html","mlf",1],["Windowed file viewer","A file-reading tool that shows a fixed number of numbered lines at a time, keeping each observation small.","agents/chapters/18-coding-agents.html","agt",1],["Window function","A SQL function that computes a value over a set of related rows without collapsing them into one row.","ml-foundations/chapters/03-data-wrangling.html","mlf",0],["Winner's curse","The upward bias in the best of several noisy measurements, because luck as well as quality put it on top.","evals/chapters/09-leaderboards.html","evl",0],["Winner's curse","The tendency of the best score among many candidates measured on the same data to overstate how good the best candidate really is.","ml/chapters/20-competitions.html","ml",0],["Winner's curse","The exaggeration of effect sizes among results that pass a significance filter in underpowered experiments.","ml-foundations/chapters/15-statistics.html","mlf",1],["Winner's curse","The upward bias in the score of the best of many noisy measurements, which grows with the number of candidates and shrinks with the size of the evaluation set.","open-ended/chapters/12-meta-agent-search.html","oe",1],["Wizard of Oz prototype","A prototype that looks like a finished system to its users while a person behind the scenes produces the outputs, used to learn about behaviour before automating.","ai-delivery/chapters/05-riskiest-assumption.html","aid",0],["word2vec","A family of small models that learn word vectors by predicting words from their neighbours or neighbours from words.","deep-learning/chapters/06-embeddings.html","dl",1],["Word error rate","The same edit-distance measure as character error rate, computed over words instead of characters.","retrieval/chapters/19-ocr.html","ret",0],["WordPiece","A subword method used by BERT that grows its vocabulary by merges chosen to raise the likelihood of the training text and marks word-internal pieces with a prefix.","deep-learning/chapters/13-tokenisation.html","dl",1],["Workaround","A makeshift routine, file or habit people build to cope with a problem, and among the strongest signs that the problem is real.","ai-delivery/chapters/01-discovery-interviews.html","aid",0],["Workflow","A system in which the programmer fixes the sequence of steps in code, and the model only fills in individual steps such as writing a summary.","agents/chapters/00-start-here.html","agt",0],["Working memory","The context window itself: the current task, recent messages and tool results, fast and exact but lost when the run ends or the window is cleared.","agents/chapters/11-memory.html","agt",1],["Workload identity","Giving a running service short-lived credentials from its platform identity instead of long-lived keys.","security/chapters/14-cloud-container.html","sec",0],["Work-product protection","Protection against disclosure of materials a lawyer prepares in anticipation of litigation.","ai-delivery/chapters/10-legal.html","aid",0],["Write-ahead log (WAL)","Recording each change durably in an append-only log before applying it, so a crash can be recovered by replaying the log.","systems/chapters/09-durability.html","sys",0],["Write amplification","How many bytes the storage engine writes to disk for each byte of data the application writes.","data/chapters/05-lsm-trees.html","data",0],["Writer and reviewer pattern","Using one session to implement a change and a separate fresh-context session to review it, so the reviewer is not anchored on the author's reasoning.","agents/chapters/22-ai-coding-tools.html","agt",0],["Write skew","Two transactions each read the same data, make decisions, and write different rows, together breaking a rule neither broke alone.","data/chapters/11-isolation.html","data",0],["Write-through / write-behind","Writing to the cache and the database together (write-through), or to the cache first and the database later (write-behind).","data/chapters/14-caching.html","data",0],["Wrong chunk","A passage that looks relevant to the retriever, is ranked above the right one, and leads the model to a wrong answer.","retrieval/chapters/17-rag-failures.html","ret",0],["Xavier initialisation","Drawing weights with variance 2 divided by fan-in plus fan-out, chosen to keep signal scale constant for tanh-like activations.","deep-learning/chapters/03-training-dynamics.html","dl",1],["XGBoost","A regularised, second-order gradient-boosting library with sparsity-aware splits and a fast, scalable implementation.","ml/chapters/09-ensembles-boosting.html","ml",0],["XSS","Cross-site scripting: attacker-controlled script running in a victim's browser in your site's origin.","security/chapters/10-web-security.html","sec",0],["XY-cut","A top-down reading-order method that repeatedly splits a page on its widest horizontal or vertical band of whitespace and recurses on the parts.","retrieval/chapters/18-pdf-layout.html","ret",0],["YaRN","A context-extension method that scales rotary frequencies unevenly across dimensions and adds a temperature correction to attention.","deep-learning/chapters/11-positions.html","dl",1],["Young-Daly interval","The checkpoint interval that minimises wasted time, approximately the square root of twice the checkpoint cost times the mean time between failures.","llm-training/chapters/05-long-runs.html","llm",0],["ZeRO","The Zero Redundancy Optimizer: data parallelism that shards optimiser state, then gradients, then weights across GPUs instead of replicating them.","llm-training/chapters/03-parallelism.html","llm",0],["Zero data retention","A contractual commitment by a model provider not to keep prompts and outputs beyond processing the request.","ai-delivery/chapters/07-choosing-models.html","aid",0],["Zero point","An integer offset in asymmetric quantisation that lets the integer range cover any interval, not only one centred on zero.","llm-training/chapters/19-quantisation.html","llm",0],["Zero-shot adapter generation","Producing an adapter for a task the generator was not trained on, from its description alone and without task data.","llm-training/chapters/17-adapters-on-demand.html","llm",0],["Zero-shot evaluation","Testing a model on data it was not trained on, to estimate how it will behave on a new corpus.","retrieval/chapters/06-retrieval-benchmarks.html","ret",0],["Zero-shot generalisation","Solving tasks in a new environment without further training, here by reusing a skill library built elsewhere.","open-ended/chapters/07-lifelong-agents.html","oe",1],["Zero-shot prompting","Asking a model to do a task with instructions alone and no worked examples.","agents/chapters/04-prompting.html","agt",1],["Zero trust","Granting access per request from verified identity, device state and context, instead of trusting anything inside a network perimeter.","security/chapters/13-zero-trust.html","sec",0],["Zipf's law","The pattern in which the frequency of the r-th most common item is roughly proportional to 1/r.","retrieval/chapters/03-query-understanding.html","ret",0],["z-loss","An auxiliary loss on the log of the softmax denominator that keeps the output logits close to log-probabilities and helps stability.","deep-learning/chapters/17-training-stability.html","dl",0],["Zombie process","A process that has finished but whose parent hasn't yet collected its exit status with wait.","systems/chapters/05-processes.html","sys",0],["Z-score normalisation","Rescaling scores by subtracting the list's mean and dividing by its standard deviation.","retrieval/chapters/10-hybrid-search.html","ret",0]];
